			if not Character or not HumanoidRootPart or not Humanoid then
				return
			end

			local Ryu_tweenSpeedResolved = Ryu_getTweenSpeed()

			Ryu_setTargetWalkSpeed(Character, Ryu_tweenSpeedResolved * HEADROOM)

			if not Ryu_updateIntegritySpoof(Humanoid, HumanoidRootPart, Ryu_tweenSpeedResolved) then
				Ryu_installIntegritySpoof(Humanoid, HumanoidRootPart, Ryu_tweenSpeedResolved)
			end

			Ryu_applyArrivalHold()
		end)
	end

	local function Ryu_stopMovementLoop()
		if connection3 then
			pcall(connection3.Disconnect, connection3)
			connection3 = nil
		end

		Ryu_resetStateConfig()
		Ryu_clearIntegritySpoof()
	end

	genv.__oxioTweenRuntimeCleanup = function()
		Ryu_cleanupAllState()
		Ryu_stopMovementLoop()
	end
end

