do
	local connection
	local connection2

	local function Ryu_healthPinSetup(character)
		if not character then
			return
		end

		local Humanoid = character:WaitForChild("Humanoid", 5) or character:FindFirstChildOfClass("Humanoid")

		if not character:WaitForChild("HumanoidRootPart", 5) then
			character:FindFirstChild("HumanoidRootPart")
		end

		if not Humanoid then
			return
		end

		local health = math.max(Humanoid.MaxHealth, 100)
		local Ryu_healthPinSetup_var2 = false
		local Ryu_healthPinSetup_var1 = 0

		local function Ryu_healthPinCallback()
			if Ryu_healthPinSetup_var2 or not Humanoid.Parent then
				return
			end

			local now = os.clock()

			if now - Ryu_healthPinSetup_var1 < 0.1 then
				if Humanoid.Health > 0 then
					if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then
						return
					end
				end
			end

			Ryu_healthPinSetup_var1 = now
			Ryu_healthPinSetup_var2 = true
			pcall(function()
				Humanoid.BreakJointsOnDeath = false
				Humanoid.RequiresNeck = false
				Humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
				Humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
				Humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)

				if Humanoid.Health <= 0 then
					Humanoid.Health = health
				end

				if Humanoid:GetState() == Enum.HumanoidStateType.Dead then
					Humanoid:ChangeState(Enum.HumanoidStateType.Running)
				end
			end)
			Ryu_healthPinSetup_var2 = false
		end

		Ryu_healthPinCallback()

		if connection then
			pcall(connection.Disconnect, connection)
		end

		if connection2 then
			pcall(connection2.Disconnect, connection2)
		end

		connection = Humanoid.HealthChanged:Connect(function(health2)
			if health2 <= 0 or health2 < health then
				Ryu_healthPinCallback()
			end
		end)
		connection2 = RunService.Heartbeat:Connect(Ryu_healthPinCallback)
	end

	task.spawn(function()
		Ryu_healthPinSetup(LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait())
	end)
	LocalPlayer.CharacterAdded:Connect(function(character)
		Ryu_healthPinSetup(character)
	end)
end

