	return math.clamp(math.floor((tonumber(senaV4Config.TweenSpeedMultiplier) or Ryu_CONFIG.DEF_INPUT) + 0.5), Ryu_CONFIG.MIN_INPUT, Ryu_CONFIG.MAX_INPUT) * Ryu_CONFIG.MULTIPLIER
