senaV4Config.applyStealValueInput = function(cfgTable, inputValue)
	local lower = string.lower
	local tostring_ = tostring
	local Ryu_cleanedInputValue = lower(tostring_(inputValue or "")):gsub("[%s,]", "")

	if Ryu_cleanedInputValue == "" then
		cfgTable.StealMinValue = 0

		return true
	end

	local Ryu_parsedNumber, Ryu_parsedUnit = string.match(Ryu_cleanedInputValue, "^([%d]+%.?[%d]*)([kmb]?)$")
	local Ryu_parsedNumberValue = tonumber(Ryu_parsedNumber)

	if not Ryu_parsedNumberValue then
		return false
	end

	local Ryu_getTweenSpeed_var1 = 1

	if Ryu_parsedUnit == "k" then
		Ryu_getTweenSpeed_var1 = 1000
	elseif Ryu_parsedUnit == "m" then
		Ryu_getTweenSpeed_var1 = 1000000
	elseif Ryu_parsedUnit == "b" then
		Ryu_getTweenSpeed_var1 = 1e9
	end

	cfgTable.StealMinValue = Ryu_parsedNumberValue * Ryu_getTweenSpeed_var1

	return true
end
senaV4Config.getAreaEggValue = function(runtime, record)
	if not runtime._assetGenerationUtil then
