	return false
end

do
	local Ryu_isNightPhase_var1 = 0
	local Ryu_isNightPhase_var2 = false

	local function Ryu_checkHighTierEggs()
		if Ryu_isNightPhase() then
			return false
		end

		local now = os.clock()

		if now - Ryu_isNightPhase_var1 < 0.35 then
			return Ryu_isNightPhase_var2
		end

		Ryu_isNightPhase_var1 = now

		local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
		local Ryu_checkHighTierEggs_var1 = require(ReplicatedStorage2.Client.EggState).GetAreaEggSnapshot()
		local Directory = require(ReplicatedStorage2.Data.Assets).Directory
		local pairs_ = pairs
		local Records = Ryu_checkHighTierEggs_var1 and Ryu_checkHighTierEggs_var1.Records or {}

		for _, Record in pairs_(Records) do
			if Record.State ~= "Slot" and Record.State ~= "Dropped" or not Record.BottomCFrame then
				continue
			end

			local Ryu_assetDirectory = Directory[Record.AssetCategory]
			local Rarity = Ryu_assetDirectory and Ryu_assetDirectory.Rarity
			local DisplayName = Rarity and (Rarity.DisplayName or Rarity._id)

			if DisplayName ~= "Eternal" and DisplayName ~= "Divine" then
				continue
			end

			Ryu_isNightPhase_var2 = true

			return true
		end

		Ryu_isNightPhase_var2 = false

		return false
	end
end

local function Ryu_isSafeToSteal()
	if senaV4Config.IsStealing then
		return false
	end

	local __oxioDronesWantCharacter = genv.__oxioDronesWantCharacter

	if __oxioDronesWantCharacter and __oxioDronesWantCharacter() then
		return false
	end

	if senaV4Config.IsPlacing == true then
		return false
	end

	if senaV4Config.AutoSteal then
		return os.clock() >= (senaV4Config.StealPriorityUntil or 0)
	end

	return true
end

do
	local function Ryu_logDisconnect(logMessage)
		pcall(function()
			if typeof(writefile) ~= "function" then
				return
			end

			local Ryu_logDisconnect_var1 = ""

			if typeof(readfile) == "function" and typeof(isfile) == "function" and isfile("Sena_Disconnect_Log.txt") then
				Ryu_logDisconnect_var1 = readfile("Sena_Disconnect_Log.txt") or ""
			end

			local Ryu_logBuffer = {}

			for match in Ryu_logDisconnect_var1:gmatch("[^\r\n]+") do
				table.insert(Ryu_logBuffer, match)
			end

			local Ryu_logDisconnect_var2 = "] " .. logMessage

			table.insert(Ryu_logBuffer, "[" .. os.date("%Y-%m-%d %H:%M:%S") .. Ryu_logDisconnect_var2)

			while #Ryu_logBuffer > 50 do
				table.remove(Ryu_logBuffer, 1)
			end

			writefile("Sena_Disconnect_Log.txt", table.concat(Ryu_logBuffer, "\n"))
		end)
	end
end

local function Ryu_logDisconnect_var3(valueObject)
	if not valueObject or type(valueObject.GetValue) ~= "function" then
		return nil
	end

	local ok, result = pcall(function()
		return valueObject:GetValue()
	end)

	if not ok then
		return nil
	end

	if type(result) ~= "table" then
		if type(result) == "string" then
			return { result }
		end

		return nil
	end

	local Ryu_logLines = {}

	for k, v in pairs(result) do
		if type(k) == "number" then
			table.insert(Ryu_logLines, v)
		elseif type(k) == "string" and v == true then
			table.insert(Ryu_logLines, k)
		end
	end

	return Ryu_logLines
end
local function Ryu_isFilterMatch(eggName, eggRarity, nameList, rarityList)
	if senaV4Config.SellAll then
		return true
	end

	if type(nameList) ~= "table" or type(rarityList) ~= "table" then
		return false
	end

	local Ryu_isFilterMatch_var1 = false

	if not (#nameList == 0 or table.find(nameList, "None")) then
		if table.find(nameList, "All") then
			Ryu_isFilterMatch_var1 = true
		else
			Ryu_isFilterMatch_var1 = table.find(nameList, eggName) ~= nil
		end
	end

	local Ryu_isFilterMatch_var2 = false

	if #rarityList ~= 0 and not table.find(rarityList, "None") then
		if table.find(rarityList, "All") then
			Ryu_isFilterMatch_var2 = true
		else
			Ryu_isFilterMatch_var2 = table.find(rarityList, eggRarity) ~= nil
		end
	end

	return Ryu_isFilterMatch_var1 or Ryu_isFilterMatch_var2
end
local function Ryu_isRarityInList(nameInput, listInput)
	if type(listInput) ~= "table" then
		return false
