local function Ryu_glideRootLegacy(rootPart, targetCFrame, timeout, cancelCheck)
	local Ryu_glideDeadline = os.clock() + timeout
	local now
	local Ryu_glideRootLegacy_var1 = 0
	local Ryu_glideRootLegacy_var2 = 0.1

	pcall(function()
		Ryu_glideRootLegacy_var2 = LocalPlayer:GetNetworkPing()
	end)

	local Ryu_settleThreshold = math.clamp(Ryu_glideRootLegacy_var2 * 2 + 0.2, 0.4, 1)

	while true do
		if not (os.clock() < Ryu_glideDeadline) then
			return false
		end

		if cancelCheck and cancelCheck() then
			break
		end

		rootPart.AssemblyLinearVelocity = Vector3.zero
		rootPart.AssemblyAngularVelocity = Vector3.zero
		RunService.Heartbeat:Wait()

		if not ((rootPart.Parent and (rootPart.Position - targetCFrame.Position).Magnitude or math.huge) <= 1.5) then
			now = nil
			Ryu_glideRootLegacy_var1 = 0

			continue
		end

		rootPart.CFrame = targetCFrame
		now = now or os.clock()
		Ryu_glideRootLegacy_var1 += 1

		if not (Ryu_glideRootLegacy_var1 >= 3) or not (Ryu_settleThreshold <= os.clock() - now) then
			continue
		end

		return true
	end

	return false
end

local Ryu_activeTweens = {}

local function Ryu_glideTo(rootPart, humanoid, targetCFrame, cancelCheck, onArrival, onEarlyCarry, allowAerial)
	if not rootPart or not humanoid or typeof(targetCFrame) ~= "CFrame" then
		return false
	end

	if cancelCheck and cancelCheck() then
		return false
	end

	local Ryu_previousTweenHandle = Ryu_activeTweens[rootPart]

	if Ryu_previousTweenHandle then
		Ryu_previousTweenHandle.cancelled = true
		Ryu_activeTweens[rootPart] = nil
	end

	local Parent = rootPart.Parent

	if not Parent then
		return false
	end

	Ryu_clearCharacterState()
	Ryu_purgeTrapsOnCharacter(Parent)
	Ryu_startMovementLoop()

	local CurrentCamera = workspace.CurrentCamera

	if CurrentCamera and CurrentCamera.CameraSubject ~= humanoid then
		pcall(function()
			CurrentCamera.CameraSubject = humanoid
		end)
	end

	local AutoRotate = humanoid.AutoRotate

	humanoid.AutoRotate = false

	local Ryu_forcedY = allowAerial and math.max(rootPart.Position.Y, targetCFrame.Position.Y + 5, vector3.Y + 5) or nil
	local Ryu_targetCF = Ryu_forcedY and cFrameNew(targetCFrame.Position.X, Ryu_forcedY, targetCFrame.Position.Z) * targetCFrame.Rotation or targetCFrame
	local Ryu_glideSpeed = math.clamp(Ryu_getTweenSpeed(), Ryu_CONFIG.MIN_SPEED, genv.__oxioAdminBoost == true and 3000 or Ryu_CONFIG.MAX_SPEED)

	Ryu_setTargetWalkSpeed(Parent, Ryu_glideSpeed * Ryu_CONFIG.HEADROOM)

	local Ryu_tweenState = {
		cancelled = false
	}

	Ryu_activeTweens[rootPart] = Ryu_tweenState
	Ryu_ensureHoverPad()

	local now
	local Ryu_previousDistance
	local Ryu_glideTo_var1 = 0
	local Ryu_flightPhase = Ryu_forcedY and (math.abs(rootPart.Position.Y - Ryu_forcedY) > 0.35 and "takeoff" or "cruise") or nil
	local Magnitude = (Ryu_targetCF.Position - rootPart.Position).Magnitude
	local Ryu_glideTimeout = os.clock() + math.max(Magnitude / Ryu_glideSpeed, 0.08) * 3 + 8
	local Ryu_arrivedSafely = false
	local Ryu_earlyCarryFired = false

	while not Ryu_tweenState.cancelled and (not cancelCheck or not cancelCheck()) and rootPart.Parent and not (Ryu_glideTimeout <= os.clock()) do
		local Ryu_frameDelta = math.max(math.min(RunService.Heartbeat:Wait(), 0.15), 0.0041666666666666666)
		local Ryu_currentSpeed = math.clamp(Ryu_getTweenSpeed(), Ryu_CONFIG.MIN_SPEED, genv.__oxioAdminBoost == true and 3000 or Ryu_CONFIG.MAX_SPEED)

		Ryu_setTargetWalkSpeed(Parent, Ryu_currentSpeed * Ryu_CONFIG.HEADROOM)

		local Ryu_stealIntegrityState = Ryu_getEnv()[Ryu_CONFIG.INTEGRITY_KEY]
		local State = type(Ryu_stealIntegrityState) == "table" and Ryu_stealIntegrityState.State or nil

		if Ryu_isOwnStateChecked(State, humanoid, rootPart) then
			local Position = rootPart.Position
			local Ryu_deltaVector = Ryu_targetCF.Position - Position
			local Magnitude2 = Ryu_deltaVector.Magnitude
			local vector32 = Vector3.new(Ryu_deltaVector.X, 0, Ryu_deltaVector.Z)

			if Ryu_forcedY and Ryu_flightPhase == "takeoff" and math.abs(Position.Y - Ryu_forcedY) <= 0.35 then
				Ryu_flightPhase = "cruise"
			end

			local Ryu_stepVector = (Ryu_forcedY and Ryu_flightPhase == "takeoff" and Vector3.new(Position.X, Ryu_forcedY, Position.Z) or Ryu_targetCF.Position) - Position
			local Magnitude3 = Ryu_stepVector.Magnitude
			local Magnitude4 = Ryu_forcedY and vector32.Magnitude or Magnitude2

			if Ryu_previousDistance and Ryu_previousDistance + 2 < Magnitude4 then
				Ryu_glideTo_var1 = os.clock() + 0.5
			end

			Ryu_previousDistance = Magnitude4

			local Ryu_stepDistance = (os.clock() < Ryu_glideTo_var1 and math.max(Ryu_CONFIG.MIN_SPEED, Ryu_currentSpeed * 0.45) or Ryu_currentSpeed) * Ryu_frameDelta

			if onEarlyCarry and not Ryu_earlyCarryFired and Magnitude2 <= Ryu_carryTimings.EarlyCarryDistance then
				Ryu_earlyCarryFired = true
				task.spawn(onEarlyCarry)
			end

			local vector33 = Vector3.new(rootPart.CFrame.LookVector.X, 0, rootPart.CFrame.LookVector.Z)
			local Unit = vector32.Magnitude > 0.001 and vector32.Unit or vector33.Magnitude > 0.001 and vector33.Unit or Vector3.new(0, 0, -1)

			if (not Ryu_forcedY or Ryu_flightPhase == "cruise") and Magnitude2 <= math.max(Ryu_stepDistance, 0.05) then
				if Magnitude2 > 0.5 then
					now = nil
				end

				Ryu_syncHoverPad(Ryu_targetCF.Position)
				rootPart.CFrame = lookAt(Ryu_targetCF.Position, Ryu_targetCF.Position + Unit)
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
				Ryu_syncHoverPad(Ryu_targetCF.Position)
				Ryu_updateIntegritySpoof(humanoid, rootPart, Ryu_currentSpeed, Vector3.zero)
				now = now or os.clock()

				if os.clock() - now >= 0.4 then
					Ryu_arrivedSafely = true

					break
				end
			else
				now = nil

				if Magnitude3 <= 0.001 then
					rootPart.AssemblyLinearVelocity = Vector3.zero
					rootPart.AssemblyAngularVelocity = Vector3.zero
					Ryu_syncHoverPad(Position)
				else
					local Ryu_nextPosition = Position + Ryu_stepVector.Unit * math.min(Ryu_stepDistance, Magnitude3)
					local Ryu_velocity = (Ryu_nextPosition - Position) / Ryu_frameDelta

					Ryu_syncHoverPad(Ryu_nextPosition)
					rootPart.CFrame = lookAt(Ryu_nextPosition, Ryu_nextPosition + Unit)
					rootPart.AssemblyLinearVelocity = Vector3.zero
					Ryu_syncHoverPad(Ryu_nextPosition)

					if not Ryu_updateIntegritySpoof(humanoid, rootPart, Ryu_currentSpeed, Ryu_velocity) then
						Ryu_installIntegritySpoof(humanoid, rootPart, Ryu_currentSpeed)
						Ryu_updateIntegritySpoof(humanoid, rootPart, Ryu_currentSpeed, Ryu_velocity)
					end
				end
			end
		else
			Ryu_previousDistance = nil
			now = nil
			rootPart.AssemblyLinearVelocity = Vector3.zero
			rootPart.AssemblyAngularVelocity = Vector3.zero
			Ryu_syncHoverPad(rootPart.Position)

			if Ryu_isOwnState(State, humanoid, rootPart) then
				Ryu_applyWalkSpeedToState(State, Ryu_currentSpeed * Ryu_CONFIG.HEADROOM, Vector3.zero)
			else
				Ryu_installIntegritySpoof(humanoid, rootPart, Ryu_currentSpeed)
			end
		end
	end

	if humanoid.Parent and AutoRotate ~= nil then
		humanoid.AutoRotate = AutoRotate
	end

	rootPart.AssemblyLinearVelocity = Vector3.zero
	rootPart.AssemblyAngularVelocity = Vector3.zero

	if Ryu_arrivedSafely and onArrival then
		Ryu_setArrivalHold(rootPart, Ryu_targetCF)
	else
		Ryu_destroyHoverPad()
	end

	local Ryu_glideSuccess = Ryu_arrivedSafely and not Ryu_tweenState.cancelled

	return Ryu_glideSuccess
end
local function Ryu_glideToTarget(rootPart, humanoid, targetCFrame, cancelCheck)
	return Ryu_glideTo(rootPart, humanoid, targetCFrame, cancelCheck, false, nil, true)
end
local function Ryu_teleportCharacterRoot(rootPart, targetCFrame)
	if rootPart then
		if typeof(targetCFrame) == "CFrame" then
			if not pcall(function()
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
				rootPart.CFrame = targetCFrame
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
			end) then
				return false
			end

			Ryu_syncHoverPad(targetCFrame.Position)

			local Parent = rootPart.Parent
			local Humanoid = Parent and Parent:FindFirstChildOfClass("Humanoid")

			if Humanoid then
				local Ryu_targetSpeed = math.clamp(Ryu_getTweenSpeed(), Ryu_CONFIG.MIN_SPEED, genv.__oxioAdminBoost == true and 3000 or Ryu_CONFIG.MAX_SPEED)

				Ryu_setTargetWalkSpeed(Parent, Ryu_targetSpeed * Ryu_CONFIG.HEADROOM)

				if not Ryu_updateIntegritySpoof(Humanoid, rootPart, Ryu_targetSpeed, Vector3.zero) then
					Ryu_installIntegritySpoof(Humanoid, rootPart, Ryu_targetSpeed)
					Ryu_updateIntegritySpoof(Humanoid, rootPart, Ryu_targetSpeed, Vector3.zero)
				end
			end

			return true
		end
	end

	return false
end

