local function Ryu_destroyForeignTrap(trapInstance)
	if trapInstance and trapInstance.Name == "PlayerTrap" then
		pcall(function()
			trapInstance:Destroy()
		end)
	end
end

task.spawn(function()
	local function Ryu_watchTraps(folder)
		if not folder then
			return
		end

		local Ryu_transientChildren, Ryu_transientChildrenIter, Ryu_transientChildrenState = ipairs(folder:GetChildren())
		local Ryu_transientIterator = geniter(Ryu_transientChildren, Ryu_transientChildrenIter, Ryu_transientChildrenState)
		local Ryu_transientFirstPack = table.pack(Ryu_transientIterator())

		if Ryu_transientFirstPack[1] then
			local Ryu_transientChild = Ryu_transientFirstPack[3]

			while true do
				Ryu_destroyForeignTrap(Ryu_transientChild)

				local Ryu_transientNextPack = table.pack(Ryu_transientIterator())

				if Ryu_transientNextPack[1] then
					Ryu_transientChild = Ryu_transientNextPack[3]
				else
					break
				end
			end
		end

		folder.ChildAdded:Connect(function(child)
			Ryu_destroyForeignTrap(child)
		end)
	end

	local Transient = workspace:FindFirstChild("Transient")

	if Transient then
		Ryu_watchTraps(Transient)
	end

	local __DEBRIS = workspace:FindFirstChild("__DEBRIS")

	if __DEBRIS then
		Ryu_watchTraps(__DEBRIS)
	end

	workspace.ChildAdded:Connect(function(child)
		if child.Name == "Transient" or child.Name == "__DEBRIS" then
			Ryu_watchTraps(child)
		elseif child.Name == "PlayerTrap" then
			Ryu_destroyForeignTrap(child)

			return
		elseif child.Name:lower():find("trap") then
			Ryu_destroyForeignTrap(child)
		end
	end)
	task.spawn(function()
		while Ryu_isCurrentSession() do
			for _, v in ipairs({
				workspace:FindFirstChild("Transient"),
				workspace:FindFirstChild("__DEBRIS")
			}) do
				if v then
					for _, child in ipairs(v:GetChildren()) do
						Ryu_destroyForeignTrap(child)
					end
				end
			end

			task.wait(1.5)
		end
	end)
end)

