local function Ryu_checkTreadmillSnapshot()
	local ok, result = pcall(function()
		return require(game:GetService("ReplicatedStorage").Shared.Remotes).Treadmill.AskRenderSnapshot:InvokeServer()
	end)

	if ok then
		if type(result) == "table" then
			return table.find(result, LocalPlayer.UserId) ~= nil
		end
	end

	return nil
end
local function Ryu_unequipTreadmill()
	local ok, result, result2 = pcall(function()
		return require(game:GetService("ReplicatedStorage").Shared.Remotes).Treadmill.AskDoff:InvokeServer()
	end)

	if not ok then
		return false, tostring(result)
	end

	if result ~= true then
		return false, tostring(result2)
	end

	return true
end
local function Ryu_getTreadmillStandCF()
	local ok, result = pcall(function()
		local PlotState2 = require(ReplicatedStorage.Client.PlotState)
		local Ryu_localPlotSlot = type(PlotState2.ResolveLocalSlot) == "function" and PlotState2.ResolveLocalSlot() or PlotState2.GetMySlot()
		local Ryu_plotsFolder = type(PlotState2.ResolveFolder) == "function" and PlotState2.ResolveFolder() or PlotState2.GetPlotsFolder()
		local Ryu_localPlotFolder = Ryu_plotsFolder and Ryu_localPlotSlot

		Ryu_localPlotFolder = Ryu_localPlotFolder and Ryu_plotsFolder:FindFirstChild(tostring(Ryu_localPlotSlot))

		local TreadmillBottom = Ryu_localPlotFolder and Ryu_localPlotFolder:FindFirstChild("TreadmillBottom")

		if not TreadmillBottom or not TreadmillBottom:IsA("BasePart") then
			return nil
		end

		local Character = LocalPlayer.Character
		local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
		local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

		if HumanoidRootPart and Humanoid then
			return TreadmillBottom.CFrame * cFrameNew(0, TreadmillBottom.Size.Y * 0.5 + (Humanoid.RigType == Enum.HumanoidRigType.R15 and HumanoidRootPart.Size.Y * 0.5 + math.max(Humanoid.HipHeight, 0.5) or HumanoidRootPart.Size.Y * 0.5 + 2) + 0.05, 0)
		end

		return nil
	end)
	local Ryu_treadmillPrepareResult = ok and result or nil

	return Ryu_treadmillPrepareResult
end

local Ryu_TreadmillHelpers = {
	HoldSeconds = 0.3,
	ConfirmStableSeconds = 0.3,
	ConfirmTimeout = 2.5,
	PollSeconds = 0.05,
	ArrivalSettle = 0.5,
	DecoyName = "__oxioTweenTreadmillDecoy",
	destroyTrail = function(trailInstance)
