Ryu_TreadmillHelpers.purgeStealPopups = function()
	local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")

	if not PlayerGui then
		return
	end

	for _, descendant in ipairs(PlayerGui:GetDescendants()) do
		Ryu_TreadmillHelpers.destroyStealPopup(descendant)
	end
end
Ryu_TreadmillHelpers.guiConnection = LocalPlayer:WaitForChild("PlayerGui").DescendantAdded:Connect(function(descendant)
	Ryu_TreadmillHelpers.destroyStealPopup(descendant)
end)
Ryu_TreadmillHelpers.removeDecoy = function()
	if Ryu_TreadmillHelpers.cameraConnection then
		pcall(Ryu_TreadmillHelpers.cameraConnection.Disconnect, Ryu_TreadmillHelpers.cameraConnection)
		Ryu_TreadmillHelpers.cameraConnection = nil
	end

	if Ryu_TreadmillHelpers.characterConnection then
		pcall(Ryu_TreadmillHelpers.characterConnection.Disconnect, Ryu_TreadmillHelpers.characterConnection)
		Ryu_TreadmillHelpers.characterConnection = nil
	end

	local pairs_ = pairs
	local transparency = Ryu_TreadmillHelpers.transparency or {}

	for k, v in pairs_(transparency) do
		if typeof(k) == "Instance" and k.Parent then
			pcall(function()
				k.LocalTransparencyModifier = v
			end)
		end
	end

	Ryu_TreadmillHelpers.transparency = nil

	local Character = LocalPlayer.Character
	local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
	local CurrentCamera = workspace.CurrentCamera

	if CurrentCamera then
		pcall(function()
			CurrentCamera.CameraSubject = Humanoid or Ryu_TreadmillHelpers.cameraSubject
		end)
	end

	Ryu_TreadmillHelpers.cameraSubject = nil

	if Ryu_TreadmillHelpers.decoy then
		pcall(Ryu_TreadmillHelpers.decoy.Destroy, Ryu_TreadmillHelpers.decoy)
	end

	Ryu_TreadmillHelpers.decoy = nil
end
Ryu_TreadmillHelpers.spawnDecoy = function(targetCFrame)
	Ryu_TreadmillHelpers.removeDecoy()

	local Character = LocalPlayer.Character

	if not Character then
		return false
	end

	local Archivable = Character.Archivable

	Character.Archivable = true

	local ok, decoy = pcall(Character.Clone, Character)

	Character.Archivable = Archivable

	if not ok or not decoy or typeof(decoy) ~= "Instance" then
		return false
	end

	decoy.Name = Ryu_TreadmillHelpers.DecoyName

	for _, descendant in ipairs(decoy:GetDescendants()) do
		if not descendant:IsA("Script") then
			if not descendant:IsA("LocalScript") and not descendant:IsA("BillboardGui") and not descendant:IsA("Sound") and not descendant:IsA("Trail") then
				if not descendant:IsA("BasePart") then
					continue
				end

				descendant.LocalTransparencyModifier = 0
				descendant.Anchored = true
				descendant.CanCollide = false
				descendant.CanQuery = false
				descendant.CanTouch = false

				continue
			end
		end

		pcall(descendant.Destroy, descendant)
	end

	local Humanoid = decoy:FindFirstChildOfClass("Humanoid")

	if not Humanoid then
		decoy:Destroy()

		return false
	end

	pcall(function()
		Humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		Humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
	end)
	decoy.Parent = workspace
	decoy:PivotTo(targetCFrame)
	Ryu_TreadmillHelpers.decoy = decoy

	local transparency = setmetatable({}, {
		__mode = "k"
	})

	local function Ryu_hideLocalPart(part)
		if not part or not part:IsA("BasePart") or not part:IsDescendantOf(Character) then
			return
		end

		if transparency[part] == nil then
			transparency[part] = part.LocalTransparencyModifier
		end

		part.LocalTransparencyModifier = 1
	end

	for _, descendant in ipairs(Character:GetDescendants()) do
		Ryu_hideLocalPart(descendant)
		Ryu_TreadmillHelpers.destroyTrail(descendant)
	end

	Ryu_TreadmillHelpers.transparency = transparency
	Ryu_TreadmillHelpers.characterConnection = Character.DescendantAdded:Connect(function(descendant)
		if Ryu_TreadmillHelpers.decoy == decoy then
			pcall(Ryu_hideLocalPart, descendant)
			Ryu_TreadmillHelpers.destroyTrail(descendant)
		end
	end)

	local CurrentCamera = workspace.CurrentCamera

	if CurrentCamera then
		Ryu_TreadmillHelpers.cameraSubject = CurrentCamera.CameraSubject
		CurrentCamera.CameraSubject = Humanoid
	end

	Ryu_TreadmillHelpers.cameraConnection = RunService.RenderStepped:Connect(function()
		if Ryu_TreadmillHelpers.decoy == decoy then
			if decoy.Parent and Humanoid.Parent then
				for k in pairs(transparency) do
					if k.Parent and k.LocalTransparencyModifier ~= 1 then
						k.LocalTransparencyModifier = 1
					end
				end

				local CurrentCamera2 = workspace.CurrentCamera

				if CurrentCamera2 and CurrentCamera2.CameraSubject ~= Humanoid then
					CurrentCamera2.CameraSubject = Humanoid
				end

				return
			end
		end
	end)

	return true
end
Ryu_TreadmillHelpers.requestEquip = function()
	local ok, result, result2 = pcall(function()
		return require(ReplicatedStorage.Shared.Remotes).Treadmill.AskWearStill:InvokeServer()
	end)

	if ok then
		if result ~= false then
			return true
		end
	end

	local Ryu_treadmillUnequipFalse = false
	local tostring_ = tostring
	local Ryu_treadmillUnequipMsg = result2 or result

	return Ryu_treadmillUnequipFalse, tostring_(Ryu_treadmillUnequipMsg)
end
Ryu_TreadmillHelpers.prepare = function(targetCFrame, cancelCheck)
	local Character = LocalPlayer.Character
	local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
	local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

	if HumanoidRootPart then
		if Humanoid and typeof(targetCFrame) == "CFrame" then
			local function Ryu_cancelCheck()
				return cancelCheck ~= nil and cancelCheck()
			end
			local function Ryu_cleanupDecoy()
				local Character2 = LocalPlayer.Character
				local HumanoidRootPart2 = Character2 and Character2:FindFirstChild("HumanoidRootPart")

				if HumanoidRootPart2 then
					Ryu_teleportCharacterRoot(HumanoidRootPart2, targetCFrame)
					task.wait(0.1)
				end

				Ryu_TreadmillHelpers.removeDecoy()
			end

			Ryu_TreadmillHelpers.purgeStealPopups()
			Ryu_clearCharacterState()
			Ryu_destroyHoverPad()

			if not Ryu_TreadmillHelpers.spawnDecoy(targetCFrame) then
				return false
			end

			local Ryu_treadmillStandCF = Ryu_getTreadmillStandCF()

			if not Ryu_treadmillStandCF or Ryu_cancelCheck() or not Ryu_teleportCharacterRoot(HumanoidRootPart, Ryu_treadmillStandCF) then
				Ryu_unequipTreadmill()
				Ryu_cleanupDecoy()

				return false
			end

			task.wait(Ryu_TreadmillHelpers.ArrivalSettle)

			if Ryu_cancelCheck() then
				Ryu_unequipTreadmill()
				Ryu_cleanupDecoy()

				return false
			end

			if not Ryu_TreadmillHelpers.requestEquip() then
				Ryu_unequipTreadmill()
				Ryu_cleanupDecoy()

				return false
			end

			local Ryu_confirmDeadline = os.clock() + Ryu_TreadmillHelpers.ConfirmTimeout
			local Ryu_equipConfirmed = false
			local now

			while not Ryu_cancelCheck() do
				if not (os.clock() < Ryu_confirmDeadline) then
					break
				end

				if Ryu_checkTreadmillSnapshot() == true then
					now = now or os.clock()

					if not (Ryu_TreadmillHelpers.ConfirmStableSeconds <= os.clock() - now) then
						task.wait(Ryu_TreadmillHelpers.PollSeconds)

						continue
					end

					Ryu_equipConfirmed = true

					break
				end

				now = nil
				task.wait(Ryu_TreadmillHelpers.PollSeconds)
			end

			if not Ryu_equipConfirmed or Ryu_cancelCheck() then
				Ryu_unequipTreadmill()
				Ryu_cleanupDecoy()

				return false
			end

			local Ryu_holdDeadline = os.clock() + Ryu_TreadmillHelpers.HoldSeconds

			while not Ryu_cancelCheck() and os.clock() < Ryu_holdDeadline do
				task.wait(Ryu_TreadmillHelpers.PollSeconds)
			end

			local Ryu_doffDeadline = os.clock() + Ryu_TreadmillHelpers.ConfirmTimeout
			local Ryu_doffSucceeded = false

			while not Ryu_cancelCheck() and os.clock() < Ryu_doffDeadline do
				Ryu_unequipTreadmill()
				task.wait(Ryu_TreadmillHelpers.PollSeconds)

				if Ryu_checkTreadmillSnapshot() == false then
					Ryu_watchTraps_var1 = nil
					Ryu_doffSucceeded = true

					break
				end
			end

			Ryu_cleanupDecoy()

			local Ryu_treadmillPrepareDone = Ryu_doffSucceeded and not Ryu_cancelCheck()

			return Ryu_treadmillPrepareDone
		end
	end

	return false
end
