	local Ryu_declutterTargets = {
		{
			name = "ProximityPrompts",
			restore = true
		},
		{
			name = "AreaGui",
			restore = false
		}
	}
	local Ryu_playWake_var1 = false
	local Ryu_declutterConnections = {}

	local function Ryu_isLayerCollector(guiObject)
		return guiObject and (guiObject:IsA("ScreenGui") or guiObject:IsA("LayerCollector"))
	end
	local function Ryu_disableLayerCollector(guiObject)
		if not Ryu_isLayerCollector(guiObject) then
			return
		end

		pcall(function()
			guiObject.Enabled = false
		end)
		table.insert(Ryu_declutterConnections, guiObject:GetPropertyChangedSignal("Enabled"):Connect(function()
			if Ryu_playWake_var1 then
				if guiObject.Enabled then
					pcall(function()
						guiObject.Enabled = false
					end)
				end
			end
		end))
	end
	local function Ryu_findDeclutterTargets(callback)
		local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")

		if not PlayerGui then
			return
		end

		for _, v in ipairs(Ryu_declutterTargets) do
			local VName = PlayerGui:FindFirstChild(v.name)

			if VName then
				callback(VName, v)
			end
		end
	end
	local function Ryu_watchDeclutter()
		local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")

		if not PlayerGui then
			return
		end

		Ryu_findDeclutterTargets(function(guiObject)
			Ryu_disableLayerCollector(guiObject)
		end)
		table.insert(Ryu_declutterConnections, PlayerGui.ChildAdded:Connect(function(child)
			if not Ryu_playWake_var1 then
				return
			end

			for _, v in ipairs(Ryu_declutterTargets) do
				if child.Name == v.name then
					Ryu_disableLayerCollector(child)

					break
				end
			end
		end))
	end
	local function Ryu_restoreDeclutter()
		for _, v in ipairs(Ryu_declutterConnections) do
			pcall(function()
				v:Disconnect()
			end)
		end

		table.clear(Ryu_declutterConnections)
		Ryu_findDeclutterTargets(function(guiObject, entry)
			pcall(function()
				guiObject.Enabled = entry.restore
			end)
		end)
	end

	genv.__oxioSetStealDeclutter = function(enabled)
		local Ryu_declutterWanted = enabled == true

		if Ryu_declutterWanted == Ryu_playWake_var1 then
			return
		end

		Ryu_playWake_var1 = Ryu_declutterWanted

		if Ryu_declutterWanted then
			Ryu_watchDeclutter()
		else
			Ryu_restoreDeclutter()
		end
	end
	genv.__oxioStealDeclutterCleanup = function()
		Ryu_playWake_var1 = false
		Ryu_restoreDeclutter()
	end
end

do
	local function Ryu_leftTreadmillCheck()
		local Ryu_treadmillSnapshot = Ryu_checkTreadmillSnapshot()

		if Ryu_treadmillSnapshot == false then
			Ryu_watchTraps_var1 = nil

			return true
		end

		if Ryu_treadmillSnapshot == nil and Ryu_watchTraps_var1 == nil then
			return true
		end

		Ryu_watchTraps_var1 = Ryu_watchTraps_var1 or "server"

		local Ryu_doffOk, Ryu_doffError = Ryu_unequipTreadmill()

		if not Ryu_doffOk then
			warn("[Treadmill] Gagal minta lepas dari treadmill sebelum steal:", Ryu_doffError)

			return false
		end

		local Ryu_doffDeadline = os.clock() + 1.5

		while Ryu_watchTraps_var1 ~= nil and os.clock() < Ryu_doffDeadline do
			task.wait(0.05)

			if not senaV4Config.AutoSteal then
				return false
			end

			if Ryu_checkTreadmillSnapshot() == false then
				Ryu_watchTraps_var1 = nil

				break
			end
		end

		if Ryu_watchTraps_var1 ~= nil then
			warn("[Treadmill] Lepas treadmill gak kekonfirmasi dalam 1.5s, steal dilanjut apa adanya.")

			return false
		end

		task.wait(0.12)

		return true
	end
end

