	local Ryu_watchFpsBoost_var1 = false

	Ryu_leftTreadmillCheck_var2 = function()
		if Ryu_watchFpsBoost_var1 then
			return
		end

		Ryu_watchFpsBoost_var1 = true

		local Lighting = game:GetService("Lighting")

