					for k, pref in pairs(snapshot.prefs) do
						Preferences.Set(k, pref)
					end
				end)
			end
		end

		local Ryu_v390_var1 = 0

		for k, part in pairs(Ryu_FpsBoost.parts) do
			if k.Parent then
				pcall(function()
					k.Material = part[1]
					k.CastShadow = part[2]

					if part[3] ~= nil and k:IsA("MeshPart") then
						k.RenderFidelity = part[3]
					end
				end)
			end

			Ryu_v390_var1 += 1

			if Ryu_v390_var1 % 400 == 0 then
				task.wait()
			end
		end

		for k, decal in pairs(Ryu_FpsBoost.decals) do
			if k.Parent then
