	local Ryu_v390_var2 = false

	local function Ryu_hideOtherPlayerEggs(model)
		if not model or not model:IsA("Model") then
			return
		end

		local match = model.Name:match("^(%d+)_")
		local Ryu_otherPlayerId = match and tonumber(match)

		if not Ryu_otherPlayerId or Ryu_otherPlayerId == LocalPlayer.UserId then
			return
		end

		for _, descendant in ipairs(model:GetDescendants()) do
			if descendant:IsA("BasePart") then
				descendant.Transparency = 1
				descendant.CanCollide = false
			elseif descendant:IsA("Decal") or descendant:IsA("Texture") then
				descendant.Transparency = 1
			elseif descendant:IsA("ParticleEmitter") or descendant:IsA("Trail") or descendant:IsA("Beam") then
				descendant.Enabled = false
			elseif descendant:IsA("BillboardGui") or descendant:IsA("SurfaceGui") then
				descendant.Enabled = false
			end
		end
	end
	local function Ryu_prepareFpsEggHiding()
		if senaV4Config._fpsEggsReady then
			return true
		end

		local Ryu_prepareFpsEggHiding_var1 = false
		local ok, result = pcall(function()
			local Ryu_placedEggRenderer = require(game:GetService("ReplicatedStorage").Shared.Eggs.PlacedEggRenderer).GetRenderFolder()

			if not Ryu_placedEggRenderer then
				return
			end

			local children = Ryu_placedEggRenderer:GetChildren()

			for _, child in ipairs(children) do
				Ryu_hideOtherPlayerEggs(child)
			end

			Ryu_placedEggRenderer.ChildAdded:Connect(function(child)
				task.defer(Ryu_hideOtherPlayerEggs, child)
			end)
			Ryu_prepareFpsEggHiding_var1 = true
		end)

		if not ok then
			warn("[FPSBoost] Gagal hide egg pemain lain:", result)

			return false
		end

		return Ryu_prepareFpsEggHiding_var1
	end
	local function Ryu_hideClientAsset(instance)
		if not instance then
			return
		end

		pcall(function()
			instance.Parent = nil
		end)
	end
	local function Ryu_prepareFpsPetHiding()
		if senaV4Config._fpsPetsReady then
			return true
		end

		local IsOn
		local ok, result = pcall(function()
			local Shared = game:GetService("ReplicatedStorage").Shared
			local Preferences = Shared:FindFirstChild("Preferences")

			if Preferences then
