	local color3 = Color3.fromRGB(120, 120, 120)

	local function Ryu_flattenPartMaterial(part)
		if not part or not part:IsA("BasePart") then
			return
		end

		part.Material = Enum.Material.SmoothPlastic
		part.Color = color3
		part.CastShadow = false
	end
	local function Ryu_disableVisualEffects(instance)
		if instance:IsA("ParticleEmitter") then
			instance.Enabled = false
			instance.Rate = 0
			pcall(function()
				instance:Clear()
			end)
		elseif instance:IsA("Trail") or instance:IsA("Beam") or instance:IsA("Smoke") or instance:IsA("Fire") or instance:IsA("Sparkles") or instance:IsA("PostEffect") or instance:IsA("Light") or instance:IsA("Highlight") or instance:IsA("Clouds") then
			instance.Enabled = false
		elseif instance:IsA("Atmosphere") then
			instance.Density = 0
			instance.Haze = 0
			instance.Glare = 0
		elseif instance:IsA("Explosion") then
			pcall(function()
				instance.Visible = false
			end)
		end
	end
	local function Ryu_prepareFpsWorld()
		if senaV4Config._fpsWorldReady then
			return true
		end

		local Ryu_prepareFpsWorld_var1 = false
		local Ryu_fpsListenersList = {}
		local ok, result = pcall(function()
			local function Ryu_applyFpsWorldToDescendant(descendant)
				if Ryu_isVisualTool(descendant) then
					return
				end

				Ryu_flattenPartMaterial(descendant)
				Ryu_disableVisualEffects(descendant)
			end

			local Ryu_fpsRoots = {
				workspace,
				game:GetService("Lighting")
			}

			for _, v in ipairs(Ryu_fpsRoots) do
				table.insert(Ryu_fpsListenersList, v.DescendantAdded:Connect(function(descendant)
					task.defer(Ryu_applyFpsWorldToDescendant, descendant)
				end))
			end

			local Ryu_fpsNodeList = {}

			for _, v in ipairs(Ryu_fpsRoots) do
				for _, child in ipairs(v:GetChildren()) do
					table.insert(Ryu_fpsNodeList, child)
				end
			end

			local Ryu_applyFpsWorldToDescendant_var1 = 0

			while #Ryu_fpsNodeList > 0 do
				local Ryu_fpsNode = table.remove(Ryu_fpsNodeList)

				Ryu_applyFpsWorldToDescendant(Ryu_fpsNode)

				for _, child in ipairs(Ryu_fpsNode:GetChildren()) do
					table.insert(Ryu_fpsNodeList, child)
				end

				Ryu_applyFpsWorldToDescendant_var1 += 1

				if Ryu_applyFpsWorldToDescendant_var1 >= 250 and #Ryu_fpsNodeList > 0 then
					Ryu_applyFpsWorldToDescendant_var1 = 0
					RunService.Heartbeat:Wait()
				end
			end

			Ryu_prepareFpsWorld_var1 = true
		end)

		if ok then
			return Ryu_prepareFpsWorld_var1
		end

		for _, v in ipairs(Ryu_fpsListenersList) do
			v:Disconnect()
		end

		warn("[FPSBoost] Gagal flatten material workspace:", result)

		return false
	end
	local function Ryu_prepareFpsAreas()
		if senaV4Config._fpsAreasReady then
			return true
		end

		local Ryu_worldRoot = Ryu_getWorkspaceWorld()
		local Areas = Ryu_worldRoot and Ryu_worldRoot:FindFirstChild("Areas")
		local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
		local Build = Ryu_worldRoot and Ryu_worldRoot:FindFirstChild("Build")

		if not GuardAreas or not Build then
			return false
		end

		for _, child in ipairs(GuardAreas:GetChildren()) do
			local RequiredSpeedSign = child:FindFirstChild("RequiredSpeedSign")

			if RequiredSpeedSign then
				pcall(function()
					RequiredSpeedSign:Destroy()
				end)
			end
		end

		local MainMap = Build:FindFirstChild("MainMap")
		local Bases = MainMap and MainMap:FindFirstChild("Bases")

		local function Ryu_isFpsKeepPart(part)
			if Bases and part:IsDescendantOf(Bases) then
				return part.Size.Y <= 5 and not string.find(string.upper(part.Name), "WALL", 1, true)
			end

			local Parent = part

			while true do
				if not Parent or Parent == Build then
					return false
				end

				if not string.find(string.upper(Parent.Name), "BOTTOM", 1, true) then
					Parent = Parent.Parent

					continue
				end

				break
			end

			return true
		end

		local Ryu_fpsAreaKeywords = {
			"ENCHANTED",
			"FUSEBIOME",
			"WISP",
			"BUTTERFLY",
			"MARKERS",
			"PORTAL",
			"TRIGGER"
		}

		local function Ryu_isFpsKeywordPart(part)
			if part:FindFirstChildOfClass("TouchTransmitter") or part:FindFirstChildWhichIsA("ProximityPrompt", true) then
				return true
			end

			local Parent = part

			while true do
				if not Parent then
					return false
				end

				if Parent == Build then
					return false
				end

				local Ryu_upperParentName = string.upper(Parent.Name)

				for _, v in ipairs(Ryu_fpsAreaKeywords) do
					if string.find(Ryu_upperParentName, v, 1, true) then
						return true
					end
				end

				Parent = Parent.Parent
			end
		end
		local function Ryu_applyFpsAreaFilter(part)
			if not part:IsA("BasePart") then
				return
			end

			if Ryu_isFpsKeywordPart(part) then
				return
			end

			if Ryu_isFpsKeepPart(part) then
				Ryu_flattenPartMaterial(part)
			else
				pcall(function()
					part:Destroy()
				end)
			end
		end

		local connection = Build.DescendantAdded:Connect(function(descendant)
			task.defer(Ryu_applyFpsAreaFilter, descendant)
		end)
		local Ryu_applyFpsAreaFilter_var1 = 0
		local fpsAreaDeleted = 0

		for _, descendant in ipairs(Build:GetDescendants()) do
			local Ryu_hadParentBeforeFilter = descendant.Parent ~= nil

			Ryu_applyFpsAreaFilter(descendant)

			if Ryu_hadParentBeforeFilter and descendant.Parent == nil then
				fpsAreaDeleted += 1
			end

			Ryu_applyFpsAreaFilter_var1 += 1

			if Ryu_applyFpsAreaFilter_var1 >= 250 then
				Ryu_applyFpsAreaFilter_var1 = 0
				RunService.Heartbeat:Wait()
			end
		end

		senaV4Config._fpsAreaListener = connection
		senaV4Config._fpsAreaDeleted = fpsAreaDeleted
		senaV4Config._fpsAreasReady = true

		return true
	end
	local function Ryu_prepareFpsPlots()
		if senaV4Config._fpsPlotsReady then
			return true
		end

		local Ryu_prepareFpsPlots_var1 = false
		local ok, result = pcall(function()
			local PlotState2 = require(game:GetService("ReplicatedStorage").Client.PlotState)

			if PlotState2.GetMySlot() == nil then
				warn("[FPSBoost] Slot plot kita belum ke-resolve, skip delete plot dulu (biar aman).")

				return
			end

			local function Ryu_isLocalPlot(plotChild)
				local Ryu_localPlotSlotId = PlotState2.GetMySlot()

				return Ryu_localPlotSlotId ~= nil and plotChild.Name == tostring(Ryu_localPlotSlotId)
			end

			local Plots = PlotState2.GetPlotsFolder() or workspace:WaitForChild("Plots", 10)

			if not Plots then
				warn("[FPSBoost] workspace.Plots gak ketemu sama sekali.")

				return
			end

			local children = Plots:GetChildren()
			local Ryu_isLocalPlot_var1 = 0

			for _, child in ipairs(children) do
				if not Ryu_isLocalPlot(child) and pcall(function()
					child:Destroy()
				end) then
					Ryu_isLocalPlot_var1 += 1
				end
			end

			Plots.ChildAdded:Connect(function(child)
				task.defer(function()
					if child.Parent then
						if not Ryu_isLocalPlot(child) then
							pcall(function()
								child:Destroy()
							end)
						end
					end
				end)
			end)
			Ryu_prepareFpsPlots_var1 = true
		end)

		if ok then
			return Ryu_prepareFpsPlots_var1
		end

		warn("[FPSBoost] Gagal delete plot pemain lain:", result)

		return false
	end
	local function Ryu_prepareFpsTreadmills()
		if senaV4Config._fpsTreadmillsReady then
