				if Ryu_localTreadmillRender then
					return Ryu_localTreadmillRender
				end

				local Peek = Ryu_prepareFpsTreadmills_var2 and (Ryu_prepareFpsTreadmills_var2.Peek or Ryu_prepareFpsTreadmills_var2.Get)

				if not Peek then
					return nil
				end

				local ok, result = pcall(Peek, "TreadmillPlotRender", tostring(Ryu_localTreadmillSlot))

