				local ok2, result2 = pcall(PlotState2.IsWorldPositionWithinLocalPlotBounds, result)
				local Ryu_localPointInsidePlot = ok2 and result2

				return Ryu_localPointInsidePlot
			end

			local children = __ClientTreadmillRenders:GetChildren()
			local Ryu_isLocalTreadmillRender_var1 = 0

			for _, child in ipairs(children) do
				if child:IsA("Model") and not Ryu_isLocalTreadmillRender(child) and pcall(function()
					child:Destroy()
				end) then
					Ryu_isLocalTreadmillRender_var1 += 1
				end
			end

			__ClientTreadmillRenders.ChildAdded:Connect(function(child)
				task.defer(function()
					if child.Parent and child:IsA("Model") and not Ryu_isLocalTreadmillRender(child) then
						pcall(function()
							child:Destroy()
						end)
					end
				end)
			end)
			Ryu_prepareFpsTreadmills_var1 = true
		end)

		if ok then
			return Ryu_prepareFpsTreadmills_var1
		end

		warn("[FPSBoost] Gagal delete treadmill pemain lain:", result)

		return false
	end

	Ryu_leftTreadmillCheck_var3 = function()
		if Ryu_v390_var2 or senaV4Config._fpsBoostApplying then
