local function Ryu_hasLineOfSight(startPos, endPos, characterFilter)
	local Ryu_hasLineOfSight_var1 = true

	pcall(function()
		local filterDescendantsInstances = { characterFilter }
		local raycastParams = RaycastParams.new()

		raycastParams.FilterType = Enum.RaycastFilterType.Exclude

		local Ryu_rayStartPos = startPos

		for i = 1, 8 do
			raycastParams.FilterDescendantsInstances = filterDescendantsInstances

			local Ryu_rayDirection = endPos - Ryu_rayStartPos

			if Ryu_rayDirection.Magnitude < 1 then
				break
			end

			local hit = workspace:Raycast(Ryu_rayStartPos, Ryu_rayDirection, raycastParams)

			if not hit then
				break
			end

			if not hit.Instance.CanCollide then
				table.insert(filterDescendantsInstances, hit.Instance)
				Ryu_rayStartPos = hit.Position + Ryu_rayDirection.Unit * 0.1

				continue
			end

			Ryu_hasLineOfSight_var1 = false

			break
		end
	end)

	return Ryu_hasLineOfSight_var1
end

local Ryu_AutoLoops = {}
local ProximityPromptService = game:GetService("ProximityPromptService")
local Ryu_Blocker = {
	TITLES = {
		auto_steal = "Auto Steal",
		race = "Race Rally",
		mech_boss = "Mech Boss",
		butterfly = "Butterfly Bloom",
		auto_place = "Auto Place",
		treadmill = "Treadmill"
	},
	ORDER = {
		"auto_steal",
		"race",
		"mech_boss",
		"butterfly",
		"auto_place",
		"treadmill"
	}
}

-- Registry task (sama seperti vlx.register di Sena terbaru): tiap task mendaftarkan wants/active/enabled/status
do
	local Ryu_taskRegistry = {}

	Ryu_Blocker.register = function(name, handlers)
		Ryu_taskRegistry[name] = handlers
	end

	local function Ryu_queryTask(name, key)
		local registered = Ryu_taskRegistry[name]
		local handler = registered and registered[key]

		if type(handler) ~= "function" then
			return nil
		end

		local ok, value = pcall(handler)

		if ok then
			return value
		end

		return nil
	end

	Ryu_Blocker.wants = function(name)
		return Ryu_queryTask(name, "wants") == true
	end
	Ryu_Blocker.active = function(name)
		return Ryu_queryTask(name, "active") == true
	end
	Ryu_Blocker.enabled = function(name)
		return Ryu_queryTask(name, "enabled") == true
	end
end

do
	local function Ryu_isAutoStealBlocked(operation)
		if operation == "auto_steal" then
			local __oxioStealWantsCharacter = genv.__oxioStealWantsCharacter

			return __oxioStealWantsCharacter ~= nil and __oxioStealWantsCharacter() == true
		end

		if operation == "race" then
			return Ryu_Blocker.wants("race")
		end

		if operation ~= "mech_boss" then
			if operation == "butterfly" then
				local __oxioButterflyRuntime = genv.__oxioButterflyRuntime

				return __oxioButterflyRuntime ~= nil and __oxioButterflyRuntime.wantsCharacter == true
			end

			if operation == "auto_place" then
				return senaV4Config.IsPlacing == true
			end

			return false
		end

		if LocalPlayer:GetAttribute("InScrambleArena") == true then
			return true
		end

		if senaV4Config.ScrambleBossAuto ~= true then
			return false
		end

		local ScrambleArena = workspace:FindFirstChild("ScrambleArena")
		local Ryu_scramblePortalPresent = workspace:FindFirstChild("ScrambleArenaPortal") ~= nil

		if not Ryu_scramblePortalPresent then
			Ryu_scramblePortalPresent = ScrambleArena ~= nil

			if Ryu_scramblePortalPresent then
				Ryu_scramblePortalPresent = tostring(ScrambleArena:GetAttribute("Phase") or "") ~= ""
			end

			Ryu_scramblePortalPresent = Ryu_scramblePortalPresent and ScrambleArena:GetAttribute("Phase") ~= "Defeated"
		end

		return Ryu_scramblePortalPresent
	end
	local function Ryu_isAutoStealRunning(operation)
		if operation == "auto_steal" then
			local __oxioEggRuntime = genv.__oxioEggRuntime

			return __oxioEggRuntime ~= nil and __oxioEggRuntime.enabled == true and (__oxioEggRuntime.running == true or __oxioEggRuntime.carry ~= nil and __oxioEggRuntime.carry.active == true)
		end

		if operation == "race" then
			return Ryu_Blocker.active("race")
		end

		if operation == "mech_boss" then
			return LocalPlayer:GetAttribute("InScrambleArena") == true
		end

		if operation ~= "butterfly" then
			if operation == "auto_place" then
				return senaV4Config.IsPlacing == true
			end

			return false
		end

		local __oxioButterflyRuntime = genv.__oxioButterflyRuntime

		return __oxioButterflyRuntime ~= nil and __oxioButterflyRuntime.active == true
	end

	Ryu_Blocker.blocker = function(operation)
		if operation ~= "mech_boss" and LocalPlayer:GetAttribute("InScrambleArena") == true then
			return "mech_boss"
		end
		-- FIX: RaceId dulu langsung return "mech_boss" yang blok semua operasi termasuk auto_steal
		-- Sekarang: RaceId hanya blok kalau operation bukan "auto_steal" dan bukan "race"
		-- Supaya auto_steal tetap jalan selama belum masuk race aktif
		if operation ~= "mech_boss" and operation ~= "auto_steal" and operation ~= "race" then
			if type(LocalPlayer:GetAttribute("RaceId")) == "string" then
				return "mech_boss"
			end
		end

		for _, v in ipairs(Ryu_Blocker.ORDER) do
			if v == operation then
				return nil
			end

			if Ryu_isAutoStealBlocked(v) then
				return v
			end
		end

		return nil
	end
	Ryu_Blocker.holder = function(operation)
		for _, v in ipairs(Ryu_Blocker.ORDER) do
			if v ~= operation and v ~= "treadmill" then
				if Ryu_isAutoStealRunning(v) then
					return v
				end
			end
		end

		return nil
	end
end

local Ryu_catalog, Ryu_eggRuntime, Ryu_treadmillManager, Ryu_antiGuard, Ryu_godMode

do
	local function Ryu_CoordinatorFactory()
		local Ryu_Coordinator = {}

		Ryu_Coordinator.__index = Ryu_Coordinator

		local Ryu_foregroundOps = {
			auto_place = true,
			auto_fuse = true,
			equip_best = true
		}
		local Ryu_operationPriority = {
			auto_steal = 100,
			auto_hatch = 80,
			auto_place = 70,
			auto_fuse = 50,
			equip_best = 40,
			rewards = 20
		}

		local function Ryu_cloneTable(sourceTable)
			local Ryu_clonedTable = {}

			for k, v in pairs(sourceTable) do
				Ryu_clonedTable[k] = v
			end

			return Ryu_clonedTable
		end

		Ryu_Coordinator.new = function()
			local obj = setmetatable({}, Ryu_Coordinator)

			obj.destroyed = false
			obj.active = nil
			obj.background = nil
			obj.reservations = {}
			obj.listeners = {}
			obj.backgroundListeners = {}
			obj.serial = 0

			return obj
		end
		Ryu_Coordinator._snapshot = function(self)
			local active = self.active

			return {
				busy = active ~= nil,
				operation = active and active.owner or nil,
				priority = active and active.priority or 0,
				reservedCount = active and #active.uids or 0,
				reservations = Ryu_cloneTable(self.reservations)
			}
		end
		Ryu_Coordinator._emit = function(self)
			local Ryu_coordinatorSnapshot = self:_snapshot()

			for k in pairs(self.listeners) do
				local ok, result = pcall(k, Ryu_coordinatorSnapshot)

				if not ok then
					warn("[StealAnEgg] Coordinator listener failed:", result)
				end
			end
		end
		Ryu_Coordinator._emitBackground = function(self)
			local background = self.background
			local Ryu_bgState = {
				busy = background ~= nil
			}
			local owner = background and background.owner

			Ryu_bgState.operation = owner or nil

			for k in pairs(self.backgroundListeners) do
				local ok, result = pcall(k, Ryu_bgState)

				if not ok then
					warn("[StealAnEgg] Background coordinator listener failed:", result)
				end
			end
		end
		Ryu_Coordinator.subscribe = function(self, listener)
			self.listeners[listener] = true
			pcall(listener, self:_snapshot())

			local function Ryu_unsubscribe()
				self.listeners[listener] = nil
			end

			return Ryu_unsubscribe
		end
		Ryu_Coordinator.subscribeBackground = function(self, listener)
			self.backgroundListeners[listener] = true
			pcall(listener, {
				busy = self.background ~= nil,
				operation = self.background and self.background.owner or nil
			})

			local function Ryu_unsubscribeBackground()
				self.backgroundListeners[listener] = nil
			end

			return Ryu_unsubscribeBackground
		end
		Ryu_Coordinator.getSnapshot = function(self)
			return self:_snapshot()
		end
		Ryu_Coordinator.isBackgroundBusy = function(self)
			return self.background ~= nil
		end
		Ryu_Coordinator.isReserved = function(self, uid, owner)
			local Ryu_reservedBy = self.reservations[uid]

			return Ryu_reservedBy ~= nil and Ryu_reservedBy ~= owner
		end
		Ryu_Coordinator.tryAcquire = function(self, owner, uids, priority)
			if self.destroyed then
				return nil, "Coordinator destroyed"
			end

			if type(owner) ~= "string" or owner == "" then
				return nil, "Invalid operation owner"
			end

			if self.active then
				return nil, "Busy: " .. self.active.owner
			end

			if self.background and Ryu_foregroundOps[owner] then
				return nil, "Busy: background " .. self.background.owner
			end

			local Ryu_fgUids = {}
			local Ryu_fgUniqueUids = {}
