		local function Ryu_applySpeedToState(state, walkSpeed, travelVelocity)
			if type(state) ~= "table" then
				return false
			end

			local value = rawget(state, "RootPart")
			local CFrame_2 = value and value.Parent and value.CFrame

			CFrame_2 = CFrame_2 or nil

			local Position = CFrame_2 and CFrame_2.Position or nil
			local vector33 = typeof(travelVelocity) == "Vector3" and travelVelocity or Vector3.zero

			local function Ryu_applyValuesToSamples(sample)
				if type(sample) == "table" then
					rawset(sample, "WalkSpeed", walkSpeed)

					if CFrame_2 then
						rawset(sample, "CFrame", CFrame_2)
						rawset(sample, "Position", Position)
						rawset(sample, "LinearVelocity", vector33)
						rawset(sample, "AngularVelocity", Vector3.zero)
					end
				end
			end

			for _, v in ipairs(Ryu_integritySampleFields) do
				Ryu_applyValuesToSamples(rawget(state, v))
			end

			local pairs_ = pairs
			local Ryu_sampleHistory = rawget(state, "SampleHistory") or {}

			for _, v in pairs_(Ryu_sampleHistory) do
				Ryu_applyValuesToSamples(v)
			end

			local pairs_2 = pairs
			local Ryu_safeGroundCheckpoints = rawget(state, "SafeGroundCheckpoints") or {}

			for _, v in pairs_2(Ryu_safeGroundCheckpoints) do
				Ryu_applyValuesToSamples(v)
			end

			local value2 = rawget(state, "Evidence")

			if type(value2) == "table" then
				value2.Speed = 0
				value2.Teleport = 0
				value2.Flight = 0
			end

			local value3 = rawget(state, "ImpulseContext")

			if type(value3) == "table" then
				local maxHorizontalSpeed = math.max(tonumber(value3.MaxHorizontalSpeed) or 0, walkSpeed)
				local Ryu_impulseDuration = math.max((tonumber(value3.ExpiresAt) or 0) - (tonumber(value3.StartedAt) or 0), 0.15)

				value3.MaxHorizontalSpeed = maxHorizontalSpeed

				if Position then
					value3.OriginPosition = Position
				end

				value3.MaxHorizontalDistance = math.max(tonumber(value3.MaxHorizontalDistance) or 0, maxHorizontalSpeed * Ryu_impulseDuration + 48)
				Ryu_applyValuesToSamples(value3.PreMovementSafeSample)
			end

			if rawget(state, "CorrectionContext") == nil then
				rawset(state, "FirstSuspiciousAt", nil)

				if rawget(state, "ThreatLevel") == "Observing" then
					rawset(state, "ThreatLevel", "Trusted")
				end
			end

			return true
		end
