		local function Ryu_installSpoofFromCharacter(humanoid, rootPart, walkSpeed)
			local Ryu_spoofState2 = Ryu_getIntegrityState2()
			local State = Ryu_spoofState2.State

			if not Ryu_isOwnStateA(State, humanoid, rootPart) then
				local now = os.clock()

				if now < (Ryu_spoofState2.NextSearchAt or 0) then
					return false
				end

				Ryu_spoofState2.NextSearchAt = now + 0.2
				State = Ryu_findStateViaGcSweep(LocalPlayer2, humanoid, rootPart)
			end

			if not State then
				return false
			end

			if not Ryu_isOwnStateB(State, humanoid, rootPart) then
				Ryu_spoofState2.Enabled = false
				Ryu_spoofState2.Humanoid = humanoid
				Ryu_spoofState2.RootPart = rootPart
				Ryu_spoofState2.State = State

				return false
			end

			Ryu_spoofState2.NextSearchAt = 0
			Ryu_spoofState2.Enabled = true
			Ryu_spoofState2.Humanoid = humanoid
			Ryu_spoofState2.RootPart = rootPart
			Ryu_spoofState2.State = State
			Ryu_spoofState2.WalkSpeed = math.clamp(walkSpeed * 1.35, 200, 1350)
			Ryu_spoofState2.TravelVelocity = Vector3.zero
			Ryu_applySpeedToState(State, Ryu_spoofState2.WalkSpeed, Ryu_spoofState2.TravelVelocity)

			return true
		end
		local function Ryu_updateSpoofSpeed(humanoid, rootPart, walkSpeed, travelVelocity)
			local __oxioStealAnEggIntegritySpoof = Ryu_getGenv().__oxioStealAnEggIntegritySpoof

			if type(__oxioStealAnEggIntegritySpoof) ~= "table" or not __oxioStealAnEggIntegritySpoof.Enabled or __oxioStealAnEggIntegritySpoof.Humanoid ~= humanoid or __oxioStealAnEggIntegritySpoof.RootPart ~= rootPart or not Ryu_isOwnStateB(__oxioStealAnEggIntegritySpoof.State, humanoid, rootPart) then
				return false
