			__oxioStealAnEggIntegritySpoof.WalkSpeed = math.clamp(walkSpeed * 1.35, 200, 1350)

			if typeof(travelVelocity) == "Vector3" then
				__oxioStealAnEggIntegritySpoof.TravelVelocity = travelVelocity
			elseif typeof(__oxioStealAnEggIntegritySpoof.TravelVelocity) ~= "Vector3" then
				__oxioStealAnEggIntegritySpoof.TravelVelocity = Vector3.zero
			end

			return Ryu_applySpeedToState(__oxioStealAnEggIntegritySpoof.State, __oxioStealAnEggIntegritySpoof.WalkSpeed, __oxioStealAnEggIntegritySpoof.TravelVelocity)
