				if now - (obj._espLastTick or 0) < 0.4 then
					return
				end

				obj._espLastTick = now

				local ok2, result2 = pcall(function()
					obj:_updateEsp()
				end)

				if not ok2 then
					if now - (obj._espErrLast or 0) > 5 then
						obj._espErrLast = now
						warn("[SAE][esp] update error: " .. tostring(result2))
					end
				end
			end, obj.connections)
