						end
					end
				else
					minValuePerSec = config.minValuePerSec or 0

					if minValuePerSec > 0 then
						Ryu_unsubscribeUI_var2 = Ryu_computeRatePerSec(record)

						if not Ryu_unsubscribeUI_var2 or Ryu_unsubscribeUI_var2 < config.minValuePerSec then
							return false
						end
					end
				end
			else
				if (config.minWeightKg or 0) > 0 then
					Ryu_weightKg = self:_resolveWeightKg(record)

					if not Ryu_weightKg or Ryu_weightKg < config.minWeightKg then
						return false
					end

					minValuePerSec = config.minValuePerSec or 0

					if minValuePerSec > 0 then
						Ryu_unsubscribeUI_var2 = Ryu_computeRatePerSec(record)

						if not Ryu_unsubscribeUI_var2 or Ryu_unsubscribeUI_var2 < config.minValuePerSec then
							return false
						end
					end
				else
					if (config.minValuePerSec or 0) > 0 then
						Ryu_unsubscribeUI_var2 = Ryu_computeRatePerSec(record)

						if not Ryu_unsubscribeUI_var2 or Ryu_unsubscribeUI_var2 < config.minValuePerSec then
							return false
						end
					end
				end
			end

			return true
		end
		Ryu_EggRuntime._matches = function(self, record)
			if record.State ~= AreaEggs.States.Slot and record.State ~= AreaEggs.States.Dropped then
				return false
			end

			if self.riftWants[record.AssetCategory] then
				return true
			end

			if self.indexObjectiveEnabled and self:_isIndexObjective(record) then
				return true
			end

			if self.wispObjective and self:_isWispObjective(record) then
				return true
			end

			if self.userStealEnabled and not self.riftOnly and self:_matchesNormalFilter(record) then
				return true
			end

			return false
		end
		Ryu_EggRuntime.setScrambleWants = function(self, uidList, riftOnly)
			local riftWants = {}
			local ipairs_ = ipairs
			local Ryu_riftUidList = type(uidList) == "table" and uidList or {}

			for _, v in ipairs_(Ryu_riftUidList) do
				if type(v) == "string" and v ~= "" then
					riftWants[v] = true
				end
			end

			local riftOnly = riftOnly == true
			local Ryu_riftChanged = riftOnly ~= self.riftOnly

			for k in pairs(riftWants) do
				if not self.riftWants[k] then
					Ryu_riftChanged = true
				end
			end

			for k in pairs(self.riftWants) do
				if not riftWants[k] then
					Ryu_riftChanged = true
				end
			end

			if not Ryu_riftChanged then
				return
			end

			self.riftWants = riftWants
			self.riftOnly = riftOnly
			self:_reconcileRunningState()
		end
		Ryu_EggRuntime._refreshCounts = function(self)
			local available = 0
			local matching = 0

			for _, record in pairs(self.records) do
				if record.State == AreaEggs.States.Slot then
					available += 1

					if self:_matches(record) then
						matching += 1
					end
				end
			end

			self.stats.available = available
			self.stats.matching = matching
			self:_notify()
		end
		Ryu_EggRuntime.hasPriorityRareEgg = function(self)
			local Character = LocalPlayer2.Character

			Character = Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

			local Ryu_bestPriorityRecord
			local Ryu_bestRank
			local Ryu_bestDistance
			local pairs_ = pairs
			local records = self.records or {}

			for _, record in pairs_(records) do
				if (record.State == AreaEggs.States.Slot or record.State == AreaEggs.States.Dropped) and record.BottomCFrame and not self:isSkippedEgg(record.Uid) and self:_matchesNormalFilter(record) then
					local Ryu_bestPriorityEgg = self.catalog.resolve(record)

					if Ryu_priorityRarities[Ryu_bestPriorityEgg.rarity] then
						local Magnitude = Character and (record.BottomCFrame.Position - Character.Position).Magnitude or 0
						local rarityRank = Ryu_bestPriorityEgg.rarityRank or 0

						if not Ryu_bestPriorityRecord or Ryu_bestRank < rarityRank or rarityRank == Ryu_bestRank and Magnitude < Ryu_bestDistance then
							Ryu_bestPriorityRecord = record
							Ryu_bestRank = rarityRank
							Ryu_bestDistance = Magnitude
						end
					end
				end
			end

			return Ryu_bestPriorityRecord ~= nil, Ryu_bestPriorityRecord
		end
		Ryu_EggRuntime.isSkippedEgg = function(self, uid)
			if uid ~= nil then
				if uid == workspace:GetAttribute("Event_CaptureTheEggUid") then
					if not self.captureObjectiveEnabled then
						return true
					end
				end
			end

			local Ryu_skipUntil = uid and self.skippedEggs[uid]

			if not Ryu_skipUntil then
				return false
			end

			if os.clock() < Ryu_skipUntil then
				return true
			end

			self.skippedEggs[uid] = nil

			return false
		end

		do
			Ryu_EggRuntime._isCaptureEgg = function(self, eggUid)
				return eggUid ~= nil and eggUid == workspace:GetAttribute("Event_CaptureTheEggUid")
			end
		end

		Ryu_EggRuntime.setCaptureObjective = function(self, enabled)
			local Ryu_captureObjectiveFlag = enabled == true

			if self.captureObjectiveEnabled == Ryu_captureObjectiveFlag then
				return
			end

			if Ryu_captureObjectiveFlag then
				self._modeBeforeCapture = {
					self.config.stealMode,
					self.config.flyAerial,
					self.config.flyZigzag
				}
				self:setStealMode("Instant", false, false)
				self.captureObjectiveEnabled = true
			else
				self.captureObjectiveEnabled = false

				local _modeBeforeCapture = self._modeBeforeCapture

				self._modeBeforeCapture = nil

				if _modeBeforeCapture then
					self:setStealMode(_modeBeforeCapture[1], _modeBeforeCapture[2], _modeBeforeCapture[3])
				end
			end

			self:_reconcileRunningState()
		end
		Ryu_EggRuntime._captureHold = function(self, uid)
			if self._captureHoldUid == uid then
				return
			end

			self._captureHoldUid = uid

			local function Ryu_stillCapturing()
				local Ryu_captureEggRecord = EggState2.ReadFieldEgg(uid)

				return Ryu_captureEggRecord ~= nil and Ryu_captureEggRecord.State == AreaEggs.States.Carried and Ryu_captureEggRecord.CarrierUserId == LocalPlayer2.UserId
			end
			local function Ryu_captureNotDone()
				return not self.destroyed and self.enabled and self.captureObjectiveEnabled and Ryu_stillCapturing()
			end

			task.spawn(function()
				self:_clearArrivalHold(uid)
				self:_hideTreadmillDecoy()
				pcall(function()
					self:_stopHoverPad()
				end)
				self.stats.lastResult = "Holding capture egg"
				self:_setStatus("Holding capture egg")

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local cFrame2 = HumanoidRootPart and cFrameNew(HumanoidRootPart.Position.X, 110, HumanoidRootPart.Position.Z) * HumanoidRootPart.CFrame.Rotation

				if cFrame2 then
					self:_glideRoot(cFrame2, function()
						return not Ryu_captureNotDone()
					end)
				end

				while Ryu_captureNotDone() do
					local Character2 = LocalPlayer2.Character
					local HumanoidRootPart2 = Character2 and Character2:FindFirstChild("HumanoidRootPart")
					local Humanoid = Character2 and Character2:FindFirstChildOfClass("Humanoid")

					if HumanoidRootPart2 and Humanoid and cFrame2 then
						pcall(function()
							HumanoidRootPart2.CFrame = cFrame2
							HumanoidRootPart2.AssemblyLinearVelocity = Vector3.zero
							HumanoidRootPart2.AssemblyAngularVelocity = Vector3.zero
						end)
						self:_syncHoverPad(cFrame2.Position)

						local Ryu_captureSpeed = math.clamp(self.config.speed or 600, 200, Ryu_getMaxSpeedClamp())

						pcall(function()
							Ryu_applySpoofWalkSpeed(Character2, Ryu_captureSpeed * 1.35)
							Ryu_updateSpoofSpeed(Humanoid, HumanoidRootPart2, Ryu_captureSpeed, Vector3.zero)
						end)
					end

					task.wait(0.1)
				end

				pcall(function()
					self:_stopHoverPad()
				end)

				if self._captureHoldUid == uid then
					self._captureHoldUid = nil
				end

				if self.destroyed or not self.enabled then
					return
				end

				self:_finish(self.captureObjectiveEnabled and "Capture egg lost — re-grabbing" or "Capture stopped")
			end)
		end
		Ryu_EggRuntime._chooseTarget = function(self)
			local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

			if not HumanoidRootPart then
				return nil
			end

			if self.captureObjectiveEnabled then
				local attribute = workspace:GetAttribute("Event_CaptureTheEggUid")
				local Ryu_captureRecordData = attribute and (EggState2.ReadFieldEgg(attribute) or self.records[attribute])

				if type(Ryu_captureRecordData) == "table" and Ryu_captureRecordData.BottomCFrame and (Ryu_captureRecordData.State == AreaEggs.States.Slot or Ryu_captureRecordData.State == AreaEggs.States.Dropped) then
					return Ryu_captureRecordData
				end
			end

			if self.manualObjectiveEnabled then
				local Ryu_manualTarget = self:_takeManualTarget()

				if Ryu_manualTarget then
					return Ryu_manualTarget
				end
			end

			if self.userStealEnabled and not self.riftOnly then
				local Ryu_hasPriority, Ryu_priorityEgg = self:hasPriorityRareEgg()

				if Ryu_hasPriority and Ryu_priorityEgg then
					return Ryu_priorityEgg
				end
			end

			local Ryu_riftRecord
			local Ryu_riftDistance
			local Ryu_indexRecord
			local Ryu_indexDistance
			local Ryu_wispRecord
			local Ryu_wispDistance

			for _, record in pairs(self.records) do
				if (record.State == AreaEggs.States.Slot or record.State == AreaEggs.States.Dropped) and record.BottomCFrame and not self:isSkippedEgg(record.Uid) then
					local Magnitude = (record.BottomCFrame.Position - HumanoidRootPart.Position).Magnitude

					if not self.riftWants[record.AssetCategory] then
						if not self.wispObjective or not self:_isWispObjective(record) then
							if self.indexObjectiveEnabled and self:_isIndexObjective(record) and (not Ryu_indexRecord or Magnitude < Ryu_indexDistance) then
								Ryu_indexRecord = record
								Ryu_indexDistance = Magnitude
							end
						elseif not Ryu_wispRecord or Magnitude < Ryu_wispDistance then
							Ryu_wispRecord = record
							Ryu_wispDistance = Magnitude
						end
					elseif not Ryu_riftRecord or Magnitude < Ryu_riftDistance then
						Ryu_riftRecord = record
						Ryu_riftDistance = Magnitude
					end
				end
			end

			if Ryu_riftRecord or Ryu_wispRecord or Ryu_indexRecord then
				return Ryu_riftRecord or Ryu_wispRecord or Ryu_indexRecord
			end

			if self.userStealEnabled and not self.riftOnly then
				local Ryu_filterMatchRecord
				local Ryu_filterMatchRank
				local Ryu_filterMatchDistance

				for _, record in pairs(self.records) do
					if record.State == AreaEggs.States.Slot or record.State == AreaEggs.States.Dropped then
						if not self:isSkippedEgg(record.Uid) and self:_matchesNormalFilter(record) then
							local Magnitude = (record.BottomCFrame.Position - HumanoidRootPart.Position).Magnitude
							local Ryu_eggResolved = self.catalog.resolve(record)
							local Ryu_eggPriorityScore

							if self.config.highestValueFirst then
								Ryu_eggPriorityScore = Ryu_computeRatePerSec(record) or -math.huge
							elseif self.config.heaviestFirst then
								Ryu_eggPriorityScore = self:_resolveWeightKg(record) or -math.huge
							else
								Ryu_eggPriorityScore = Ryu_eggResolved.rarityRank or 0
							end

							if not Ryu_filterMatchRecord or Ryu_filterMatchRank < Ryu_eggPriorityScore or Ryu_eggPriorityScore == Ryu_filterMatchRank and Magnitude < Ryu_filterMatchDistance then
								Ryu_filterMatchRecord = record
								Ryu_filterMatchRank = Ryu_eggPriorityScore
								Ryu_filterMatchDistance = Magnitude
							end
						end
					end
				end

				if Ryu_filterMatchRecord then
					return Ryu_filterMatchRecord
				end
			end

			return nil
		end
		Ryu_EggRuntime._takeManualTarget = function(self)
			local Ryu_manualRemaining = {}
			local manualOrder = {}

			for _, v in ipairs(self.manualOrder) do
				local Ryu_manualEggRecord = self.records[v]

				if Ryu_manualEggRecord and (Ryu_manualEggRecord.State == AreaEggs.States.Slot or Ryu_manualEggRecord.State == AreaEggs.States.Dropped) then
					manualOrder[#manualOrder + 1] = v
					Ryu_manualRemaining[v] = true
				end
			end

			self.manualOrder = manualOrder

			for k in pairs(self.manualQueue) do
				if not Ryu_manualRemaining[k] then
					self.manualQueue[k] = nil
				end
			end

			if #manualOrder ~= 0 then
				return self.records[manualOrder[1]]
			end

			if self.manualObjectiveEnabled then
				self.manualObjectiveEnabled = false
				task.defer(function()
					if not self.destroyed then
						self:_reconcileRunningState()
					end
				end)
			end

			return nil
		end
		Ryu_EggRuntime.queueManual = function(self, uidList)
			if type(uidList) ~= "table" then
				return 0
			end

			for _, v in ipairs(uidList) do
				local Ryu_manualQueueKey = v

				if Ryu_manualQueueKey ~= nil and not self.manualQueue[Ryu_manualQueueKey] then
					self.manualQueue[Ryu_manualQueueKey] = true
					self.manualOrder[#self.manualOrder + 1] = Ryu_manualQueueKey
				end
			end

			local Ryu_manualPendingCount = #self.manualOrder

			if Ryu_manualPendingCount > 0 then
				self.manualObjectiveEnabled = true
			end

			self:_reconcileRunningState()

			return Ryu_manualPendingCount
		end

		do
			Ryu_EggRuntime.clearManual = function(self)
				self.manualQueue = {}
				self.manualOrder = {}
				self.manualObjectiveEnabled = false
				self:_reconcileRunningState()
			end
		end

		Ryu_EggRuntime.manualPending = function(self)
			return #self.manualOrder
		end
		Ryu_EggRuntime.setTreadmillManager = function(self, treadmillManager)
			self.treadmillManager = treadmillManager
		end
		Ryu_EggRuntime.getStealMode = function(self)
			return self.config.stealMode == "Fly" and "Fly" or "Instant"
		end

		do
			Ryu_EggRuntime.setStealMode = function(self, mode, flyAerial, flyZigzag)
				local stealMode = mode == "Fly" and "Fly" or "Instant"
				local flyAerial = stealMode == "Fly" and flyAerial == true
				local flyZigzag = stealMode == "Fly" and flyZigzag == true and not flyAerial

				if self.config.stealMode ~= stealMode or self.config.flyAerial ~= flyAerial or self.config.flyZigzag ~= flyZigzag then
					self.config.stealMode = stealMode
					self.config.flyAerial = flyAerial
					self.config.flyZigzag = flyZigzag

					if self.enabled then
						self:_installGuardHitDistanceBoost()
						self:_finish("Mode changed")
					end
				end

				return stealMode
			end
		end

		do
			local ResolveHitDistance

			Ryu_EggRuntime._installGuardHitDistanceBoost = function(self)
				if not self.guardHitBoostInstalled then
					pcall(function()
						local GuardChasePolicy = require(ReplicatedStorage2.Shared.Modules.GuardAreas.GuardChasePolicy)

						if GuardChasePolicy and type(GuardChasePolicy.ResolveHitDistance) == "function" then
							ResolveHitDistance = ResolveHitDistance or GuardChasePolicy.ResolveHitDistance

							local Ryu_thisRuntime = self

							GuardChasePolicy.ResolveHitDistance = function(guardLevel)
								if Ryu_thisRuntime.enabled and Ryu_thisRuntime.instantPhase == "priming" then
									return 25
								end

								if Ryu_thisRuntime.enabled or Ryu_thisRuntime._recalling then
									return -math.huge
								end

								local ok = not ResolveHitDistance
								local Ryu_originalHitDistance

								if not ok then
									Ryu_originalHitDistance = ResolveHitDistance(guardLevel)
									ok = not Ryu_originalHitDistance
								end

								if ok then
									Ryu_originalHitDistance = guardLevel or 10
								end

								return Ryu_originalHitDistance
							end
							self.guardHitBoostInstalled = true
						end
					end)

					return
				end
			end
			Ryu_EggRuntime._removeGuardHitDistanceBoost = function(self)
				if not self.guardHitBoostInstalled then
					return
				end

				pcall(function()
					local GuardChasePolicy = require(ReplicatedStorage2.Shared.Modules.GuardAreas.GuardChasePolicy)

					if GuardChasePolicy and ResolveHitDistance then
						GuardChasePolicy.ResolveHitDistance = ResolveHitDistance
						self.guardHitBoostInstalled = false
					end
				end)
			end
		end

		Ryu_EggRuntime._setInstantAnchored = function(self, anchored)
			pcall(function()
				local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

				if HumanoidRootPart then
					if HumanoidRootPart.Anchored ~= anchored then
						HumanoidRootPart.Anchored = anchored
					end
				end
			end)
		end

		do
			Ryu_EggRuntime._kbCancelTimer = function(self)
				if self.hitTimer then
					pcall(task.cancel, self.hitTimer)
					self.hitTimer = nil
				end
			end
		end

		Ryu_EggRuntime._isPrimerEgg = function(self, uid)
			if uid == nil then
				return false
			end

			if uid == self.primerUid then
				return true
			end

			local primerUids = self.primerUids and self.primerUids[uid]

			if primerUids then
				if os.clock() < primerUids then
					return true
				end
			end

			if primerUids then
				self.primerUids[uid] = nil
			end

			return false
		end
		Ryu_EggRuntime._cleanupInstantSteal = function(self)
			self.instantPhase = nil
			self.primerUid = nil
			self.targetUid = nil
			self._flyDeparting = false
			self:_stopGuardStick()
			self:_kbCancelTimer()
			self:_setInstantAnchored(false)
			self:_hideTreadmillDecoy()
		end
		Ryu_EggRuntime._choosePrimerEgg = function(self, uid)
			local Ryu_guardHitDistance = Ryu_getWorkspaceWorld()
			local Areas = Ryu_guardHitDistance and Ryu_guardHitDistance:FindFirstChild("Areas")
			local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
			local Forest = GuardAreas and GuardAreas:FindFirstChild("Forest")
			local Guard = Forest and Forest:FindFirstChild("Guard")
			local HumanoidRootPart = Guard and Guard:FindFirstChild("HumanoidRootPart")
			local Position = HumanoidRootPart and HumanoidRootPart.Position
			local Ryu_primerEggCandidate
			local Ryu_primerEggScore

			for _, record in pairs(self.records) do
				if record.State == AreaEggs.States.Slot and record.AreaId == "Forest" and record.Uid ~= uid and not self:_isCaptureEgg(record.Uid) then
					local Ryu_primerEggPriority = -(Position and (record.BottomCFrame.Position - Position).Magnitude or LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart") and (record.BottomCFrame.Position - LocalPlayer2.Character.HumanoidRootPart.Position).Magnitude or math.huge) - (self.catalog.resolve(record).rarityRank or 0) * 100

					if not Ryu_primerEggCandidate or Ryu_primerEggScore < Ryu_primerEggPriority then
						Ryu_primerEggCandidate = record
						Ryu_primerEggScore = Ryu_primerEggPriority
					end
				end
			end

			return Ryu_primerEggCandidate
		end
		Ryu_EggRuntime._stopGuardStick = function(self)
			if self.guardStickConnection then
				pcall(self.guardStickConnection.Disconnect, self.guardStickConnection)
				self.guardStickConnection = nil
			end
		end
		Ryu_EggRuntime._startGuardStick = function(self)
			self:_stopGuardStick()

			local function Ryu_getForestGuard()
				local Ryu_worldRef = Ryu_getWorkspaceWorld()
				local Areas = Ryu_worldRef and Ryu_worldRef:FindFirstChild("Areas")
				local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
				local Forest = GuardAreas and GuardAreas:FindFirstChild("Forest")
				local Guard = Forest and Forest:FindFirstChild("Guard")

				return Guard and Guard:FindFirstChild("HumanoidRootPart")
			end

			self.guardStickConnection = RunService2.PreSimulation:Connect(function()
				if self.destroyed or not self.enabled or self.instantPhase ~= "priming" then
					self:_stopGuardStick()

					return
				end

				local Ryu_forestGuardRoot = Ryu_getForestGuard()
				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")

				if not Ryu_forestGuardRoot or not HumanoidRootPart then
					return
				end

				local Position = Ryu_forestGuardRoot.Position
				local Ryu_guardForwardOffset = Ryu_forestGuardRoot.CFrame.LookVector * 2.5
				local Ryu_guardFrontPos = Vector3.new(Position.X + Ryu_guardForwardOffset.X, HumanoidRootPart.Position.Y, Position.Z + Ryu_guardForwardOffset.Z) - HumanoidRootPart.Position

				if Ryu_guardFrontPos.Magnitude > 40 then
					Ryu_guardFrontPos = Ryu_guardFrontPos.Unit * 40
				end

				local Ryu_guardStrikeAnchor = HumanoidRootPart.Position + Ryu_guardFrontPos

				HumanoidRootPart.CFrame = lookAt(Ryu_guardStrikeAnchor, Vector3.new(Position.X, Ryu_guardStrikeAnchor.Y, Position.Z))
				HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
				HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				self:_syncHoverPad(Ryu_guardStrikeAnchor)
			end)
		end
		Ryu_EggRuntime._forestGuardModel = function()
			local Ryu_worldRef2 = Ryu_getWorkspaceWorld()
			local Areas = Ryu_worldRef2 and Ryu_worldRef2:FindFirstChild("Areas")
			local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
			local Forest = GuardAreas and GuardAreas:FindFirstChild("Forest")

			return Forest and Forest:FindFirstChild("Guard")
		end
		Ryu_EggRuntime._triggerGuardHit = function(self)
			local Ryu_forestGuard = self:_forestGuardModel()
			local HumanoidRootPart = Ryu_forestGuard and Ryu_forestGuard:FindFirstChild("HumanoidRootPart")

			if not HumanoidRootPart then
				return
			end

			local Character = LocalPlayer2.Character
			local HumanoidRootPart2 = Character and Character:FindFirstChild("HumanoidRootPart")

			if not HumanoidRootPart2 then
				return
			end

			local Position = HumanoidRootPart.Position
			local Ryu_guardForward2 = HumanoidRootPart.CFrame.LookVector * 2.5
			local vector33 = Vector3.new(Position.X + Ryu_guardForward2.X, HumanoidRootPart2.Position.Y, Position.Z + Ryu_guardForward2.Z)

			self.guardStrikeAnchor = vector33
			HumanoidRootPart2.CFrame = lookAt(vector33, Vector3.new(Position.X, vector33.Y, Position.Z))
			HumanoidRootPart2.AssemblyLinearVelocity = Vector3.zero

			local Collider = Ryu_forestGuard:FindFirstChild("Collider") or HumanoidRootPart

			if firetouchinterest then
				pcall(function()
					firetouchinterest(HumanoidRootPart2, Collider, 0)
					firetouchinterest(HumanoidRootPart2, Collider, 1)
				end)
			end

			pcall(function()
				local ForestStrike = Remotes.GuardPatrol and Remotes.GuardPatrol.ForestStrike

				if ForestStrike then
					ForestStrike:FireServer({
						EggUid = self.primerUid,
						GuardCFrame = HumanoidRootPart.CFrame
					})
				end
			end)
		end
		Ryu_EggRuntime._stopGuardStrike = function(self)
			self.guardStrikeGeneration = (self.guardStrikeGeneration or 0) + 1
		end
		Ryu_EggRuntime._knockbackLanded = function()
			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not HumanoidRootPart or not Humanoid then
				return false
			end

			if Humanoid.PlatformStand or Humanoid.Sit then
				return true
			end

			local state = Humanoid:GetState()

			if state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.FallingDown or state == Enum.HumanoidStateType.PlatformStanding then
				return true
			end

			return HumanoidRootPart.AssemblyLinearVelocity.Magnitude > 18
		end
		Ryu_EggRuntime._settleAfterKnockback = function(self)
			local guardStrikeAnchor = self.guardStrikeAnchor
			local Ryu_knockbackSettleDeadline = os.clock() + 0.35

			while true do
				if not (os.clock() < Ryu_knockbackSettleDeadline) or self.destroyed then
					return
				end

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")

				if not HumanoidRootPart then
					break
				end

				local Humanoid = Character:FindFirstChildOfClass("Humanoid")

				if Humanoid then
					pcall(function()
						Humanoid.PlatformStand = false
						Humanoid.Sit = false
						Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					end)
				end

				if guardStrikeAnchor then
					HumanoidRootPart.CFrame = cFrameNew(guardStrikeAnchor)
				end

				HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
				HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				self:_syncHoverPad(guardStrikeAnchor or HumanoidRootPart.Position)
				RunService2.Heartbeat:Wait()
			end
		end
		Ryu_EggRuntime._startGuardStrike = function(self)
			self:_stopGuardStrike()

			local guardStrikeGeneration = self.guardStrikeGeneration

			task.spawn(function()
				local Ryu_guardStrikeDeadline = os.clock() + 1.5

				while not self.destroyed and self.enabled and self.instantPhase == "priming" and self.guardStrikeGeneration == guardStrikeGeneration and os.clock() < Ryu_guardStrikeDeadline do
					self:_triggerGuardHit()

					local Ryu_knockbackCheckDeadline = os.clock() + 0.05
					local Ryu_knockbackLanded = false

					while os.clock() < Ryu_knockbackCheckDeadline do
						if self:_knockbackLanded() then
							Ryu_knockbackLanded = true

							break
						else
							RunService2.Heartbeat:Wait()
						end
					end

					if Ryu_knockbackLanded then
						break
					end
				end

				if self.guardStrikeGeneration == guardStrikeGeneration then
					self:_stopGuardStick()
					self:_settleAfterKnockback()
				end
			end)
		end
		Ryu_EggRuntime._enterBaitWait = function(self)
			self:_setInstantAnchored(false)
			self:_setStatus("Preparing steal")
			self:_startGuardStick()
			self:_startGuardStrike()

			if self.hitTimer then
				return
			end

			self.hitTimer = task.delay(1.8, function()
				self.hitTimer = nil

				if self.destroyed or not self.enabled then
					return
				end

				if self.instantPhase ~= "priming" then
					return
				end

				self:_stopGuardStick()
				self:_stopGuardStrike()

				if self.carry.active and self:_isPrimerEgg(self.carry.uid) then
					pcall(EggState2.DropFieldEgg, "PlayerRequest")
				end

				self:_finish("Steal timed out — retrying")
			end)
		end

		local function Ryu_computeSettleSeconds(areaName, holdLevel)
			local Ryu_areaName = tostring(areaName or ""):lower()
			local Ryu_computeSettleSeconds_var1 = 8
			local Ryu_computeSettleSeconds_var2 = 3.5

			if Ryu_areaName:find("enchanted") then
				Ryu_computeSettleSeconds_var1 = 18
				Ryu_computeSettleSeconds_var2 = 12
			elseif Ryu_areaName:find("light") or Ryu_areaName:find("dark") then
				Ryu_computeSettleSeconds_var1 = 16
				Ryu_computeSettleSeconds_var2 = 10
			elseif Ryu_areaName:find("titan") then
				Ryu_computeSettleSeconds_var1 = 10
				Ryu_computeSettleSeconds_var2 = 8
			end

			return math.max(Ryu_computeSettleSeconds_var2, Ryu_computeSettleSeconds_var1 * ((11 - math.clamp(holdLevel, 1, 10)) / 6))
		end

		do
			Ryu_EggRuntime._resolveSettleSeconds = function(self, record)
				local Ryu_stealHoldSeconds = math.clamp(tonumber(senaV4Config.StealHoldSeconds) or 5, 1, 10)
				local Ryu_settleBonusData = self.settleBonus and type(record) == "table" and self.settleBonus[record.Uid]
				local seconds = Ryu_settleBonusData and Ryu_settleBonusData.untilAt > os.clock() and Ryu_settleBonusData.seconds or 0

				return Ryu_computeSettleSeconds(type(record) == "table" and record.AreaId, Ryu_stealHoldSeconds) + seconds
			end
		end

		Ryu_EggRuntime._startPrimerTargetHunt = function(self)
			if self.instantPhase ~= "priming" then
				return
			end

			self:_stopGuardStick()
			self:_stopGuardStrike()
			pcall(function()
				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

				if Humanoid then
					Humanoid.PlatformStand = false
					Humanoid.Sit = false
				end

				if HumanoidRootPart then
					if self.guardStrikeAnchor then
						HumanoidRootPart.CFrame = cFrameNew(self.guardStrikeAnchor)
					end

					HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
					HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				end
			end)
			self:_kbCancelTimer()
			self:_setInstantAnchored(false)
			self.instantPhase = "hunting"
			self:_clearArrivalHold()

			local carry = self.carry

			carry.generation += 1
			self:_invalidateCarryWorker()
			self.carry.active = false
			self.carry.uid = nil

			local targetUid = self.targetUid

			self.targetUid = nil

			if not targetUid then
				self:_finish("No target egg")

				return
			end

			local Ryu_targetRecordData = EggState2.ReadFieldEgg(targetUid) or self.records[targetUid]

			if not Ryu_targetRecordData or Ryu_targetRecordData.State ~= AreaEggs.States.Slot and Ryu_targetRecordData.State ~= AreaEggs.States.Dropped then
				self:_finish("Target egg no longer available")

				return
			end

			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not HumanoidRootPart or not Humanoid then
				self:_finish("Character unavailable")

				return
			end

			self.activeTarget = Ryu_targetRecordData

			local Ryu_eggDestinationCF = self:_resolveEggDestination(Ryu_targetRecordData, HumanoidRootPart, Humanoid)

			if not Ryu_eggDestinationCF then
				self:_finish("Target destination unavailable")

				return
			end

			if self.config.stealMode ~= "Fly" then
				if self.config.stealMode == "Instant" and not self.lowFpsPrime then
					local Uid = Ryu_targetRecordData.Uid

					local function Ryu_huntCancelled()
						return self.destroyed or not self.enabled or self.instantPhase ~= "hunting" or not self.activeTarget or self.activeTarget.Uid ~= Uid
					end

					local cFrame2 = Ryu_eggDestinationCF + Vector3.new(0, 14, 0)

					self:_setStatus("Heading to target egg")

					if not self:_glideRoot(cFrame2, Ryu_huntCancelled) then
						if not Ryu_huntCancelled() then
							self:_finish("Could not reach the egg — retrying")
						end

						return
					end

					task.spawn(function()
						local Ryu_settleSeconds = self:_resolveSettleSeconds(Ryu_targetRecordData)
						local Ryu_settleDeadline = os.clock() + Ryu_settleSeconds

						if os.clock() < Ryu_settleDeadline then
							local exitTo

							while not Ryu_huntCancelled() do
								self:_setStatus(string.format("Securing target egg (%.1fs)", math.max(0, Ryu_settleDeadline - os.clock())))

								local Character2 = LocalPlayer2.Character
								local HumanoidRootPart2 = Character2 and Character2:FindFirstChild("HumanoidRootPart")
								local Humanoid2 = Character2 and Character2:FindFirstChildOfClass("Humanoid")

								if HumanoidRootPart2 and Humanoid2 then
									pcall(function()
										HumanoidRootPart2.CFrame = cFrame2
										HumanoidRootPart2.AssemblyLinearVelocity = Vector3.zero
										HumanoidRootPart2.AssemblyAngularVelocity = Vector3.zero
									end)
									self:_syncHoverPad(cFrame2.Position)

									local Ryu_huntSpeed = math.clamp(self.config.speed or 600, 200, Ryu_getMaxSpeedClamp())

									pcall(function()
										Ryu_applySpoofWalkSpeed(Character2, Ryu_huntSpeed * 1.35)
										Ryu_updateSpoofSpeed(Humanoid2, HumanoidRootPart2, Ryu_huntSpeed, Vector3.zero)
									end)
								end

								task.wait(0.1)

								if not (os.clock() < Ryu_settleDeadline) then
									exitTo = 1

									break
								end
							end

							if exitTo ~= 1 then
								return
							end

							if not Ryu_huntCancelled() then
								self:_glideRoot(Ryu_eggDestinationCF, Ryu_huntCancelled)

								if Ryu_huntCancelled() then
									return
								end

								self:_setArrivalHold(Ryu_eggDestinationCF, Uid)
								self:_setStatus("Securing target egg")
								self:_requestCarry(Ryu_targetRecordData, true)

								return
							end
						elseif not Ryu_huntCancelled() then
							self:_glideRoot(Ryu_eggDestinationCF, Ryu_huntCancelled)

							if Ryu_huntCancelled() then
								return
							end

							self:_setArrivalHold(Ryu_eggDestinationCF, Uid)
							self:_setStatus("Securing target egg")
							self:_requestCarry(Ryu_targetRecordData, true)

							return
						end
					end)

					return
				end

				self:_setStatus("Heading to target egg")
				self:_tweenRoot(Ryu_eggDestinationCF, function()
					if self.instantPhase == "hunting" and self.activeTarget and self.activeTarget.Uid == Ryu_targetRecordData.Uid then
						self:_requestCarry(Ryu_targetRecordData, false)
					end
				end, nil, {
					holdAfterArrival = true,
					holdUid = Ryu_targetRecordData.Uid,
					flightProfile = true,
					carryTarget = Ryu_targetRecordData
				})

				return
			end

			local Uid = Ryu_targetRecordData.Uid

			local function Ryu_flyHuntCancelled()
				return self.destroyed or not self.enabled or self.instantPhase ~= "hunting" or not self.activeTarget or self.activeTarget.Uid ~= Uid
			end

			if self.config.flyAerial then
				self:_setStatus("Heading to target egg")
				self:_startFlyGrounding()

				local Ryu_flyHuntSuccess = self:_flyWalkTo(Ryu_eggDestinationCF, Ryu_flyHuntCancelled, 8, 110)

				self:_stopFlyGrounding()

				if not Ryu_flyHuntSuccess then
					if not Ryu_flyHuntCancelled() then
						self:_finish("Could not reach the egg — retrying")
					end

					return
				end
			elseif self.config.flyZigzag then
				self:_setStatus("Heading to target egg")

				if not self:_walkToZigzag(Ryu_eggDestinationCF, Ryu_flyHuntCancelled) then
					if not Ryu_flyHuntCancelled() then
						self:_finish("Zig-zag walk to target failed")
					end

					return
				end
			else
				self:_setStatus("Heading to target egg")

				if not self:_walkTo(Ryu_eggDestinationCF, Ryu_flyHuntCancelled) then
					if not Ryu_flyHuntCancelled() then
						self:_finish("Walk to target failed")
					end

					return
				end
			end

			if Ryu_flyHuntCancelled() then
				return
			end

			self:_glideRoot(Ryu_eggDestinationCF, Ryu_flyHuntCancelled, self:_legitWalkSpeed())

			if Ryu_flyHuntCancelled() then
				return
			end

			self:_setArrivalHold(Ryu_eggDestinationCF, Uid)
			self:_setStatus("Securing target egg")
			self:_requestCarry(Ryu_targetRecordData, true)
		end

		do
			Ryu_EggRuntime._wallOpen = function(self)
				if self.resetBlocked or AreaEggResetWall3.IsSealed() or os.clock() < self.gateOpenAt then
					return false
				end

				local Ryu_worldRef3 = Ryu_getWorkspaceWorld()
				local Areas = Ryu_worldRef3 and Ryu_worldRef3:FindFirstChild("Areas")
				local WallStartCollision = Areas and Areas:FindFirstChild("WallStartCollision")

				if WallStartCollision and WallStartCollision:IsA("BasePart") and WallStartCollision.CanCollide then
					return false
				end

				return true
			end
		end

		Ryu_EggRuntime._closeGate = function(self, reason)
			self.resetBlocked = true
			self.gateOpenAt = math.huge
			self.safeStarting = false

			if not self.activeTween then
				self:_cancelTween(reason)
			elseif not self.activeTween.sharedTravel then
				self:_cancelTween(reason)
				self:_setStatus(reason)

				return
			end

			self:_setStatus(reason)
		end
		Ryu_EggRuntime._releaseOperation = function(self)
			local operationToken = self.operationToken

			self.operationToken = nil

			if operationToken and self.coordinator then
				self.coordinator:release(operationToken)
			end
		end

		do
			Ryu_EggRuntime._acquireOperation = function(self)
				if self.operationToken or not self.coordinator then
					return true
				end

				local autoSteal, Ryu_acquireError = self.coordinator:tryAcquire("auto_steal", {})

				if not autoSteal then
					return false, Ryu_acquireError
				end

				self.operationToken = autoSteal

				return true
			end
		end

		Ryu_EggRuntime._cancelTween = function(self, reason, alreadyReleased)
			self:_cleanupInstantSteal()
			self.carryAttemptToken = nil
			self:_clearArrivalHold()
			self.safeStarting = false

			if self.activeTween then
				pcall(self.activeTween.Cancel, self.activeTween)
				self.activeTween = nil
			end

			if not self.activeTween and not self.arrivalHold then
				self:_stopHoverPad()
			end

			if self.running then
				self.running = false
				self.activeTarget = nil
				self.stats.lastResult = reason
				self:_notify()
			end

			if not alreadyReleased then
				self:_releaseOperation()
			end
		end
		Ryu_EggRuntime._groundYAt = function(self, x, z, character)
			local Character = character or LocalPlayer2.Character
			local vector33 = Vector3.new(x, (Character and Character:FindFirstChild("HumanoidRootPart") and Character.HumanoidRootPart.Position.Y or vector32.Y) + 60, z)
			local filterDescendantsInstances = {}

			if Character then
				table.insert(filterDescendantsInstances, Character)
			end

			if self.hoverPad then
				table.insert(filterDescendantsInstances, self.hoverPad)
			end

			if self.treadmillDecoy then
				table.insert(filterDescendantsInstances, self.treadmillDecoy)
			end

			for _, child in ipairs(workspace:GetChildren()) do
				if child.Name == "__oxioHoverPad" or child.Name == "__oxioTreadmillDecoy" then
					table.insert(filterDescendantsInstances, child)
				end
			end

			for i = 1, 10 do
				local raycastParams = RaycastParams.new()

				raycastParams.FilterType = Enum.RaycastFilterType.Exclude
				raycastParams.FilterDescendantsInstances = filterDescendantsInstances
				raycastParams.IgnoreWater = true

				local hit = workspace:Raycast(vector33, Vector3.new(0, -300, 0), raycastParams)

				if not hit then
					return nil
				end

				if hit.Instance.CanCollide then
					return hit.Position.Y
				end

				table.insert(filterDescendantsInstances, hit.Instance)
			end

			return nil
		end

		do
			Ryu_EggRuntime._resolveSafeCFrame = function(self, rootPart)
				if not rootPart then
					return nil
				end

				local X = vector32.X
				local Z = vector32.Z
				local Y = vector32.Y
				local Ryu_groundYValue = self:_groundYAt(X, Z, rootPart.Parent)

				if Ryu_groundYValue then
					Y = Ryu_groundYValue + 3.2
				end

				return cFrameNew(X, Y, Z) * rootPart.CFrame.Rotation
			end
		end

		Ryu_EggRuntime._groundSnap = function(self)
			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not HumanoidRootPart or not Humanoid then
				return false
			end

			local Position = HumanoidRootPart.Position
			local Ryu_groundYSnap = self:_groundYAt(Position.X, Position.Z, Character)

			if not Ryu_groundYSnap then
				return false
			end

			local Ryu_groundYWithFeet = Ryu_groundYSnap + self:_feetOffset(HumanoidRootPart, Humanoid)

			if not (Position.Y < Ryu_groundYWithFeet - 0.25) and not (Ryu_groundYWithFeet + 8 < Position.Y) then
				return false
			end

			pcall(function()
				self:_syncHoverPad(Vector3.new(Position.X, Ryu_groundYWithFeet, Position.Z))
				HumanoidRootPart.CFrame = cFrameNew(Position.X, Ryu_groundYWithFeet, Position.Z) * HumanoidRootPart.CFrame.Rotation
				HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
				HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
			end)

			return true
		end

		do
			local function Ryu_destroyTrails(instance)
				if typeof(instance) == "Instance" and instance:IsA("Trail") then
					pcall(instance.Destroy, instance)
				end
			end
			local function Ryu_destroyStealPopups(instance)
				if typeof(instance) == "Instance" then
					if instance.Name == "SpeedGainPopup" or instance.Name == "PlusOne" then
						pcall(instance.Destroy, instance)
					end
				end
			end

			Ryu_EggRuntime._showTreadmillDecoy = function(self)
				if self.treadmillDecoy and self.treadmillDecoy.Parent then
					return true
				end

				self:_hideTreadmillDecoy()

				local Character = LocalPlayer2.Character

				if not Character then
					return false
				end

				local Archivable = Character.Archivable

				Character.Archivable = true

				local ok, treadmillDecoy = pcall(Character.Clone, Character)

				Character.Archivable = Archivable

				if not ok or not treadmillDecoy or typeof(treadmillDecoy) ~= "Instance" then
					return false
				end

				treadmillDecoy.Name = "__oxioTreadmillDecoy"

				for _, descendant in ipairs(treadmillDecoy:GetDescendants()) do
					if Ryu_decoyDestroyFilter[descendant.ClassName] or descendant:IsA("Trail") then
						pcall(descendant.Destroy, descendant)
					elseif descendant:IsA("BasePart") then
						descendant.LocalTransparencyModifier = 0
						descendant.Anchored = true
						descendant.CanCollide = false
						descendant.CanQuery = false
						descendant.CanTouch = false
					end
				end

				local HumanoidRootPart = treadmillDecoy:FindFirstChild("HumanoidRootPart")
				local Humanoid = treadmillDecoy:FindFirstChildOfClass("Humanoid")

				if not HumanoidRootPart or not Humanoid then
					treadmillDecoy:Destroy()

					return false
				end

				pcall(function()
					Humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
					Humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
				end)
				treadmillDecoy.Parent = workspace
				treadmillDecoy:PivotTo(cFrameNew(vector32))
				self.treadmillDecoy = treadmillDecoy

				local PlayerGui = LocalPlayer2:FindFirstChildOfClass("PlayerGui")

				if PlayerGui then
					for _, descendant in ipairs(PlayerGui:GetDescendants()) do
						if descendant.Name == "SpeedGainPopup" or descendant.Name == "PlusOne" then
							Ryu_destroyStealPopups(descendant)
						end
					end

					self.treadmillPopupConnection = PlayerGui.DescendantAdded:Connect(function(descendant)
						if self.treadmillDecoy == treadmillDecoy then
							Ryu_destroyStealPopups(descendant)
						end
					end)
				end

				local treadmillDecoyRealTransparency = setmetatable({}, {
					__mode = "k"
				})

				local function Ryu_hideCharacterPart(part)
					if not part or not part:IsA("BasePart") or not part:IsDescendantOf(Character) then
						return
					end

					if treadmillDecoyRealTransparency[part] == nil then
						treadmillDecoyRealTransparency[part] = part.LocalTransparencyModifier
					end

					part.LocalTransparencyModifier = 1
				end

				for _, descendant in ipairs(Character:GetDescendants()) do
					Ryu_hideCharacterPart(descendant)
					Ryu_destroyTrails(descendant)
				end

				self.treadmillDecoyRealTransparency = treadmillDecoyRealTransparency
				self.treadmillDecoyCharacterConnection = Character.DescendantAdded:Connect(function(descendant)
					if self.treadmillDecoy == treadmillDecoy then
						pcall(Ryu_hideCharacterPart, descendant)
						Ryu_destroyTrails(descendant)
					end
				end)

				local CurrentCamera = workspace.CurrentCamera

				if CurrentCamera then
					self.treadmillDecoyCamera = CurrentCamera.CameraSubject
					CurrentCamera.CameraSubject = Humanoid
				end

				self.treadmillDecoyCameraConnection = RunService2.RenderStepped:Connect(function()
					if self.treadmillDecoy ~= treadmillDecoy or not treadmillDecoy.Parent or not Humanoid.Parent then
						return
					end

					for k in pairs(treadmillDecoyRealTransparency) do
						if k.Parent and k.LocalTransparencyModifier ~= 1 then
							k.LocalTransparencyModifier = 1
						end
					end

					local CurrentCamera2 = workspace.CurrentCamera

					if CurrentCamera2 and CurrentCamera2.CameraSubject ~= Humanoid then
						CurrentCamera2.CameraSubject = Humanoid
					end
				end)

				return true
			end
		end

		Ryu_EggRuntime._hideTreadmillDecoy = function(self, forceRestore)
			if self._recalling and not forceRestore then
				return
			end

			if self.treadmillDecoyCameraConnection then
				pcall(self.treadmillDecoyCameraConnection.Disconnect, self.treadmillDecoyCameraConnection)
				self.treadmillDecoyCameraConnection = nil
			end

			if self.treadmillDecoyCharacterConnection then
				pcall(self.treadmillDecoyCharacterConnection.Disconnect, self.treadmillDecoyCharacterConnection)
				self.treadmillDecoyCharacterConnection = nil
			end

			if self.treadmillPopupConnection then
				pcall(self.treadmillPopupConnection.Disconnect, self.treadmillPopupConnection)
				self.treadmillPopupConnection = nil
			end

			local pairs_ = pairs
			local treadmillDecoyRealTransparency = self.treadmillDecoyRealTransparency or {}

			for k, v in pairs_(treadmillDecoyRealTransparency) do
				if typeof(k) == "Instance" and k.Parent then
					pcall(function()
						k.LocalTransparencyModifier = v
					end)
				end
			end

			self.treadmillDecoyRealTransparency = nil

			local Character = LocalPlayer2.Character
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
			local CurrentCamera = workspace.CurrentCamera

			if CurrentCamera then
				pcall(function()
					CurrentCamera.CameraSubject = Humanoid or self.treadmillDecoyCamera
				end)
			end

			self.treadmillDecoyCamera = nil

			if self.treadmillDecoy then
				pcall(self.treadmillDecoy.Destroy, self.treadmillDecoy)
			end

			self.treadmillDecoy = nil
		end

		do
			Ryu_EggRuntime._restoreTreadmillVisualAtSafe = function(self)
				if not self.treadmillDecoy then
					self:_hideTreadmillDecoy()

					return true
