				end

				if cancelCheck and cancelCheck() then
					break
				end

				if self.destroyed or not self.enabled then
					return false
				end

				local Character2 = LocalPlayer2.Character
				local HumanoidRootPart2 = Character2 and Character2:FindFirstChild("HumanoidRootPart")

				Humanoid = Character2 and Character2:FindFirstChildOfClass("Humanoid")

				if not HumanoidRootPart2 or not Humanoid then
					return false
				end

				local Position2 = HumanoidRootPart2.Position
				local vector33 = Vector3.new(Position.X - Position2.X, 0, Position.Z - Position2.Z)
				local Magnitude2 = vector33.Magnitude

				if Magnitude2 <= Ryu_zigzagBrakeDist then
					return self:_walkLeg(Position, cancelCheck, Ryu_zigzagArriveDist, true, Ryu_zigzagDeadline)
				end

				local Unit = vector33.Unit
				local vector34 = Vector3.new(-Unit.Z, 0, Unit.X)
				local Ryu_zigzagStepDist = math.max(Magnitude2 - Ryu_zigzagBrakeDist * 0.5, 4)
				local Ryu_zigzagForwardDist = math.min(60 + math.random() * 40, Ryu_zigzagStepDist)
				local Ryu_zigzagSideDist = math.min(38, Ryu_zigzagForwardDist * 0.4)
				local Ryu_zigzagTargetPos = Position2 + Unit * Ryu_zigzagForwardDist + vector34 * ((math.random() * 2 - 1) * Ryu_zigzagSideDist)
				local Z = Ryu_zigzagTargetPos.Z

				if Ryu_zigzagLaneMin and Ryu_zigzagLaneMax then
					Z = math.clamp(Z, Ryu_zigzagLaneMin + 2, Ryu_zigzagLaneMax - 2)
				end

				if self:_walkLeg(Vector3.new(Ryu_zigzagTargetPos.X, Position2.Y, Z), cancelCheck, 10, false, Ryu_zigzagDeadline) then
					continue
				end

				return false
			end

			return false
		end
		Ryu_EggRuntime._flyWalkTo = function(self, targetCFrame, cancelCheck, arriveDist, hoverHeight)
			if typeof(targetCFrame) ~= "CFrame" then
				return false
			end

			local Ryu_flyWalkArriveDist = arriveDist or 8
			local hoverPadHeightOverride = tonumber(hoverHeight) or 110
			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not HumanoidRootPart or not Humanoid then
				return false
			end

			pcall(function()
				Humanoid.AutoRotate = true
			end)

			local function Ryu_stopAnimations()
				pcall(function()
					local Humanoid2 = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChildOfClass("Humanoid")
					local Animator = Humanoid2 and Humanoid2:FindFirstChildWhichIsA("Animator")

					if Animator then
						for _, v in ipairs(Animator:GetPlayingAnimationTracks()) do
							v:Stop(0)
						end
					end
				end)
			end
			local function Ryu_toggleAnimate(disabled)
				local Character2 = LocalPlayer2.Character
				local Animate = Character2 and Character2:FindFirstChild("Animate")

				if Animate then
					pcall(function()
						Animate.Disabled = disabled
					end)
				end
			end

			Ryu_toggleAnimate(true)
			Ryu_stopAnimations()

			local Position = targetCFrame.Position

			self.hoverPadHeightOverride = hoverPadHeightOverride
			self:_startHoverPad()
			pcall(function()
				HumanoidRootPart.CFrame = cFrameNew(HumanoidRootPart.Position.X, hoverPadHeightOverride, HumanoidRootPart.Position.Z) * HumanoidRootPart.CFrame.Rotation
				HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
				HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
			end)
			self:_syncHoverPad()

			local WalkSpeed = Humanoid.WalkSpeed

			if not WalkSpeed or WalkSpeed < 1 then
				WalkSpeed = 16
			end

			local Magnitude = Vector3.new(Position.X - HumanoidRootPart.Position.X, 0, Position.Z - HumanoidRootPart.Position.Z).Magnitude
			local Ryu_flyWalkSuccess = self:_walkLeg(Position, cancelCheck, Ryu_flyWalkArriveDist, true, os.clock() + math.clamp(Magnitude / WalkSpeed * 2 + 10, 12, 120), Ryu_stopAnimations)

			Ryu_toggleAnimate(false)
			self.hoverPadHeightOverride = nil

			if not Ryu_flyWalkSuccess then
				return false
			end

			if cancelCheck and cancelCheck() then
				return false
			end

			self:_glideRoot(targetCFrame, cancelCheck, self:_legitWalkSpeed())

			local Ryu_flyWalkCancelled = cancelCheck and cancelCheck()

			return not Ryu_flyWalkCancelled
		end
		Ryu_EggRuntime._isInSafeArea = function(self, rootPart)
			if not rootPart then
				return false
			end

			local Ryu_deltaFromSafe = rootPart.Position - vector32

			return Vector2.new(Ryu_deltaFromSafe.X, Ryu_deltaFromSafe.Z).Magnitude <= 30 and math.abs(Ryu_deltaFromSafe.Y) <= 18
		end
		Ryu_EggRuntime._isInField = function(self, rootPart)
			local Ryu_worldRef5 = Ryu_getWorkspaceWorld()
			local Areas = Ryu_worldRef5 and Ryu_worldRef5:FindFirstChild("Areas")
			local WallStartCollision = Areas and Areas:FindFirstChild("WallStartCollision")

			if WallStartCollision and WallStartCollision:IsA("BasePart") then
				return rootPart.Position.X >= WallStartCollision.Position.X + 3
			end

			return true
		end
		Ryu_EggRuntime._needsSafeZoneHop = function(self, rootPart)
			if self:_isInField(rootPart) or self:_isInSafeArea(rootPart) then
				return false, nil
			end

			return true, self:_resolveSafeCFrame(rootPart)
		end
		Ryu_EggRuntime._invalidateCarryWorker = function(self)
			self.carryWorker = nil
		end
		Ryu_EggRuntime._claimCarryWorker = function(self, kind, uid)
			local generation = self.carry.generation
			local carryWorker = self.carryWorker

			if carryWorker then
				if carryWorker.generation == generation then
					return nil
				end
			end

			local carryWorker2 = {
				kind = kind,
				uid = uid,
				generation = generation,
				token = {}
			}

			self.carryWorker = carryWorker2

			return carryWorker2
		end

		do
			Ryu_EggRuntime._isCarryWorkerCurrent = function(self, worker)
				return type(worker) == "table" and self.carryWorker == worker and self.carry.generation == worker.generation and not self.destroyed and (self.enabled or self._externalDeliver)
			end
		end

		Ryu_EggRuntime._releaseCarryWorker = function(self, worker)
			if self.carryWorker == worker then
				self.carryWorker = nil
			end
		end
		Ryu_EggRuntime.ownsCarryRecovery = function(self, uid)
			if self.destroyed or not self.enabled then
				return false
			end

			if self.carry.uid == uid then
				return true
			end

			return self.running and self.activeTarget ~= nil and (uid == nil or self.activeTarget.Uid == uid)
		end
		Ryu_EggRuntime.requestCarryRecovery = function(self, uid)
			if self.destroyed or not self.enabled or type(uid) ~= "string" or uid == "" then
				return false
			end

			if self:isSkippedEgg(uid) then
				return true
			end

			if self.tweenRecoveryUid == uid then
				self:_scheduleMovementRetry()

				return true
			end

			if self.carry.active and self.carry.uid == uid then
				return true
			end

			local Ryu_recoveryTargetRecord = EggState2.ReadFieldEgg(uid) or self.records[uid]

			if type(Ryu_recoveryTargetRecord) ~= "table" or Ryu_recoveryTargetRecord.State ~= AreaEggs.States.Dropped and Ryu_recoveryTargetRecord.State ~= AreaEggs.States.Slot then
				return false
			end

			local carryWorker = self.carryWorker

			if (not carryWorker or carryWorker.kind ~= "re-steal" or carryWorker.uid ~= uid) and (not self.activeTween or not self.activeTarget or self.activeTarget.Uid ~= uid) then
				if not self.carryAttemptToken or not self.activeTarget or self.activeTarget.Uid ~= uid then
					local carry = self.carry

					carry.generation += 1
					self:_invalidateCarryWorker()
					self.carryAttemptToken = nil
					self.running = true
					self.activeTarget = Ryu_recoveryTargetRecord
					task.defer(function()
						if not self.destroyed and self.enabled and not self.carry.active then
							self:_reStealDroppedEgg(uid)
						end
					end)

					return true
				end
			end

			return true
		end
		Ryu_EggRuntime._hasConfirmedCarry = function(self, uid)
			if not self.carry.active then
				return false
			end

			if uid == nil or self.carry.uid == nil then
				return true
			end

			return self.carry.uid == uid
		end
		Ryu_EggRuntime._adoptCarryFromRecord = function(self, uid)
			if self.carry.active and self.carry.uid == uid then
				return
			end

			if self.carryTimeouts then
				self.carryTimeouts[uid] = nil
			end

			if self.instantPhase == "priming" and uid == self.primerUid then
				self.carry.active = true
				self.carry.uid = uid

				return
			end

			local carry = self.carry

			carry.generation += 1
			self:_invalidateCarryWorker()
			self:_clearArrivalHold(uid)

			local activeTarget = self.activeTarget

			self.claimPresentationSuppression = {
				assetCategory = activeTarget and activeTarget.AssetCategory,
				expiresAt = os.clock() + 8
			}
			self.carry.active = true
			self.carry.uid = uid
			self.carryStartTime = os.clock()

			local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

			self.carryStartPos = activeTarget and activeTarget.BottomCFrame and activeTarget.BottomCFrame.Position or HumanoidRootPart and HumanoidRootPart.Position

			if self.tweenRecoveryUid == uid then
				self.tweenRecoveryUid = nil
			end

			self.stats.lastResult = "Carry confirmed"
			self:_notify()
		end
		Ryu_EggRuntime._recordShowsCarried = function(self, uid)
			if type(uid) ~= "string" or uid == "" then
				return false
			end

			local Ryu_recordShowsCarried = EggState2.ReadFieldEgg(uid) or self.records[uid]

			return type(Ryu_recordShowsCarried) == "table" and Ryu_recordShowsCarried.State == AreaEggs.States.Carried and Ryu_recordShowsCarried.CarrierUserId == LocalPlayer2.UserId
		end
		Ryu_EggRuntime._recordShowsForeignCarry = function(self, uid)
			if type(uid) ~= "string" or uid == "" then
				return false
			end

			local Ryu_recordShowsForeign = EggState2.ReadFieldEgg(uid) or self.records[uid]

			return type(Ryu_recordShowsForeign) == "table" and Ryu_recordShowsForeign.State == AreaEggs.States.Carried and Ryu_recordShowsForeign.CarrierUserId ~= nil and Ryu_recordShowsForeign.CarrierUserId ~= LocalPlayer2.UserId
		end
		Ryu_EggRuntime._resolveMovementSpeed = function(self, humanoid)
			if not humanoid.Parent or humanoid.Health <= 0 then
				return nil
			end

			return math.clamp(self.config.speed, 200, Ryu_getMaxSpeedClamp())
		end
		Ryu_EggRuntime._isAreaSafe = function()
			return true
		end
		Ryu_EggRuntime._feetOffset = function(self, rootPart, humanoid)
			if humanoid.RigType == Enum.HumanoidRigType.R15 then
				return rootPart.Size.Y * 0.5 + math.max(humanoid.HipHeight, 0.5)
			end

			return rootPart.Size.Y * 0.5 + 2
		end
		Ryu_EggRuntime.setAntiTrap = function(self, enabled)
			self.config.antiTrap = enabled == true

			if self.config.antiTrap then
				self:_purgeTraps()
			end
		end
		Ryu_EggRuntime._isForeignTrap = function(self, instance)
			if instance.Name == "PlayerTrap" and instance:IsA("BasePart") then
				local attribute = instance:GetAttribute("Owner")

				return type(attribute) ~= "string" or attribute ~= LocalPlayer2.Name
			end

			return instance:IsA("Model") and instance.Name == "Trap" and instance:FindFirstChild("Hitbox") ~= nil
		end
		Ryu_EggRuntime._purgeTrap = function(self, instance)
			if self.config.antiTrap and instance then
				if instance.Parent then
					if self:_isForeignTrap(instance) then
						pcall(instance.Destroy, instance)
					end

					return
				end
			end
		end
		Ryu_EggRuntime._purgeTraps = function(self)
			for _, v in ipairs({
				"Transient",
				"__DEBRIS"
			}) do
				local Ryu_trapFolder = workspace:FindFirstChild(v)

				if Ryu_trapFolder then
					for _, descendant in ipairs(Ryu_trapFolder:GetDescendants()) do
						self:_purgeTrap(descendant)
					end
				end
			end
		end

		do
			Ryu_EggRuntime._syncHoverPad = function(self, position)
				local hoverPad = self.hoverPad

				if not hoverPad or not hoverPad.Parent or hoverPad:GetAttribute("oxioRuntimeOwner") ~= self.hoverPadOwnerId then
					return false
				end

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

				if not HumanoidRootPart or not Humanoid then
					return false
				end

				local Position = typeof(position) == "Vector3" and position or HumanoidRootPart.Position
				local Y = Position.Y

				if self.hoverPadHeightOverride ~= nil and typeof(position) ~= "Vector3" then
					Y = self.hoverPadHeightOverride
				end

				local Ryu_toggleAnimate_var1 = 8

				if self.hoverPadHeightOverride ~= nil then
					Ryu_toggleAnimate_var1 = math.max(8, Humanoid.WalkSpeed * 2 / 15)
				end

				if math.abs(hoverPad.Size.X - Ryu_toggleAnimate_var1) > 0.5 then
					hoverPad.Size = Vector3.new(Ryu_toggleAnimate_var1, 1, Ryu_toggleAnimate_var1)
				end

				hoverPad.CFrame = cFrameNew(Position.X, Y - self:_feetOffset(HumanoidRootPart, Humanoid) - 0.5 - 0.05, Position.Z)

				return true
			end
		end

		do
			Ryu_EggRuntime._setArrivalHold = function(self, targetCFrame, uid)
				if typeof(targetCFrame) ~= "CFrame" then
					return
				end

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")

				if not Character or not HumanoidRootPart then
					return
				end

				self.arrivalHold = {
					Character = Character,
					RootPart = HumanoidRootPart,
					CFrame = targetCFrame,
					Uid = uid
				}
			end
		end

		Ryu_EggRuntime._clearArrivalHold = function(self, uid)
			local arrivalHold = self.arrivalHold

			if not arrivalHold or uid == nil or arrivalHold.Uid == nil or arrivalHold.Uid == uid then
				self.arrivalHold = nil
			end
		end
		Ryu_EggRuntime._enforceArrivalHold = function(self)
			local arrivalHold = self.arrivalHold

			if type(arrivalHold) ~= "table" or typeof(arrivalHold.CFrame) ~= "CFrame" then
				return false
			end

			if LocalPlayer2.Character ~= arrivalHold.Character or not arrivalHold.RootPart or not arrivalHold.RootPart.Parent then
				self.arrivalHold = nil

				return false
			end

			self:_startHoverPad()
			pcall(function()
				arrivalHold.RootPart.AssemblyLinearVelocity = Vector3.zero
				arrivalHold.RootPart.AssemblyAngularVelocity = Vector3.zero
				self:_syncHoverPad(arrivalHold.CFrame.Position)
				arrivalHold.RootPart.CFrame = arrivalHold.CFrame
			end)
			self:_syncHoverPad(arrivalHold.CFrame.Position)

			return true
		end
		Ryu_EggRuntime._purgeOrphanHoverPads = function(self)
			for _, child in ipairs(workspace:GetChildren()) do
				if child.Name == "__oxioHoverPad" and child ~= self.hoverPad then
					pcall(child.Destroy, child)
				end
			end
		end
		Ryu_EggRuntime._startHoverPad = function(self)
			local hoverPad = self.hoverPad

			if not hoverPad or not hoverPad.Parent or hoverPad:GetAttribute("oxioRuntimeOwner") ~= self.hoverPadOwnerId then
				self:_purgeOrphanHoverPads()

				if hoverPad and hoverPad.Parent then
					pcall(hoverPad.Destroy, hoverPad)
				end

				local Part = Instance.new("Part")

				Part.Name = "__oxioHoverPad"
				Part:SetAttribute("oxioRuntimeOwner", self.hoverPadOwnerId)
				Part.Anchored = true
				Part.CanCollide = true
				Part.CanQuery = true
				Part.CanTouch = false
				Part.CastShadow = false
				Part.Transparency = 1
				Part.Material = Enum.Material.SmoothPlastic
				Part.Size = Vector3.new(8, 1, 8)
				self.hoverPad = Part
				Part.Parent = workspace
			end

			self:_syncHoverPad()

			if not self.hoverPadConnection then
				self.hoverPadConnection = RunService2.PreSimulation:Connect(function()
					if not self:_syncHoverPad() then
						self:_startHoverPad()
					end
				end)
			end

			if not self.hoverPadPostConnection then
				self.hoverPadPostConnection = RunService2.PostSimulation:Connect(function()
					if self.activeTween or self.arrivalHold then
						self:_syncHoverPad()
					end
				end)
			end
		end

		do
			Ryu_EggRuntime._stopHoverPad = function(self)
				self.hoverPadHeightOverride = nil

				if self.hoverPadConnection then
					pcall(self.hoverPadConnection.Disconnect, self.hoverPadConnection)
					self.hoverPadConnection = nil
				end

				if self.hoverPadPostConnection then
					pcall(self.hoverPadPostConnection.Disconnect, self.hoverPadPostConnection)
					self.hoverPadPostConnection = nil
				end

				if self.hoverPad then
					pcall(self.hoverPad.Destroy, self.hoverPad)
					self.hoverPad = nil
				end

				self:_purgeOrphanHoverPads()
			end
		end

		do
			Ryu_EggRuntime._startMovementProtection = function(self)
				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

				if not Character or not HumanoidRootPart or not Humanoid then
					return false
				end

				local Ryu_protectionSpeed = math.clamp(self.config.speed or 600, 200, Ryu_getMaxSpeedClamp())

				self.protectionCharacter = Character
				self.protectionHumanoid = Humanoid
				self.protectionRoot = HumanoidRootPart
				Ryu_applySpoofWalkSpeed(Character, Ryu_protectionSpeed * 1.35)
				Ryu_installSpoofFromCharacter(Humanoid, HumanoidRootPart, Ryu_protectionSpeed)

				if not self.integritySpoofConnection then
					self.integritySpoofConnection = RunService2.PreSimulation:Connect(function()
						local Character2 = LocalPlayer2.Character
						local HumanoidRootPart2 = Character2 and Character2:FindFirstChild("HumanoidRootPart")
						local Humanoid2 = Character2 and Character2:FindFirstChildOfClass("Humanoid")

						if not Character2 or not HumanoidRootPart2 or not Humanoid2 then
							return
						end

						local Ryu_protectionSpeed2 = math.clamp(self.config.speed or 600, 200, Ryu_getMaxSpeedClamp())

						self.protectionCharacter = Character2
						self.protectionHumanoid = Humanoid2
						self.protectionRoot = HumanoidRootPart2
						Ryu_applySpoofWalkSpeed(Character2, Ryu_protectionSpeed2 * 1.35)

						if not Ryu_updateSpoofSpeed(Humanoid2, HumanoidRootPart2, Ryu_protectionSpeed2) then
							Ryu_installSpoofFromCharacter(Humanoid2, HumanoidRootPart2, Ryu_protectionSpeed2)
						end

						self:_enforceArrivalHold()
					end)
				end

				if not self.arrivalHoldConnection then
					self.arrivalHoldConnection = RunService2.Heartbeat:Connect(function()
						self:_enforceArrivalHold()
					end)
				end

				return true
			end
		end

		Ryu_EggRuntime._startFlyGrounding = function(self)
			self:_stopFlyGrounding()

			local Ryu_integrityState3 = Ryu_getIntegrityState2()

			self._flyGroundConn = RunService2.PreSimulation:Connect(function()
				if self.destroyed then
					return
				end

				local State = Ryu_integrityState3 and Ryu_integrityState3.State

				if type(State) ~= "table" or rawget(State, "CorrectionContext") ~= nil then
					return
				end

				rawset(State, "IsSupportedNow", true)
				rawset(State, "UnsupportedStartedAt", nil)

				if rawget(State, "MovementMode") ~= "Correcting" then
					rawset(State, "MovementMode", "Grounded")
				end

				local value = rawget(State, "Evidence")

				if type(value) == "table" then
					value.Flight = 0
					value.Teleport = 0
					value.Speed = 0
				end
			end)
		end
		Ryu_EggRuntime._stopFlyGrounding = function(self)
			if self._flyGroundConn then
				pcall(self._flyGroundConn.Disconnect, self._flyGroundConn)
				self._flyGroundConn = nil
			end
		end
		Ryu_EggRuntime._stopMovementProtection = function(self)
			self:_stopFlyGrounding()

			if self.integritySpoofConnection then
				pcall(self.integritySpoofConnection.Disconnect, self.integritySpoofConnection)
				self.integritySpoofConnection = nil
			end

			if self.arrivalHoldConnection then
				pcall(self.arrivalHoldConnection.Disconnect, self.arrivalHoldConnection)
				self.arrivalHoldConnection = nil
			end

			self:_clearArrivalHold()
			self:_stopHoverPad()
			Ryu_clearSpoofState()
			Ryu_clearSpoofHumanoid(self.protectionHumanoid)
			self.protectionCharacter = nil
			self.protectionHumanoid = nil
			self.protectionRoot = nil
		end
		Ryu_EggRuntime.travelAndWait = function(self, targetCFrame, options)
			local Ryu_travelOptions = options or {}

			if self.destroyed then
				return false
			end

			if self.travelBusy then
				if os.clock() < (self.travelBusyUntil or 0) then
					return false
				end
			end

			if self.activeTween and not self.running and (not self.activeTween.sharedTravel or Ryu_travelOptions.preempt == true) then
				pcall(self.activeTween.Cancel, self.activeTween)

				local Ryu_cancelWaitDeadline = os.clock() + 0.5

				while self.activeTween and os.clock() < Ryu_cancelWaitDeadline do
					task.wait(0.05)
				end
			end

			if self.activeTween then
				return false
			end

			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")

			if not HumanoidRootPart then
				return false
			end

			self.travelBusy = true
			self.travelBusyUntil = os.clock() + 45

			local ok, result = pcall(function()
				local Ryu_toggleAnimate_var2
				local now = os.clock()
				local Ryu_lastProgressTime = now
				local Magnitude = (targetCFrame.Position - HumanoidRootPart.Position).Magnitude
				local Ryu_travelAbsoluteDeadline = now + Magnitude / math.max(tonumber(Ryu_travelOptions.speed) or self.config.speed or 600, 200) + 6

				self.travelBusyUntil = Ryu_travelAbsoluteDeadline + 2
				self:_tweenRoot(targetCFrame, nil, Ryu_travelOptions.speed, {
					silent = true,
					sharedTravel = true,
					abort = function()
						return self.destroyed or Ryu_travelOptions.abort ~= nil and Ryu_travelOptions.abort()
					end,
					onDone = function(success)
						Ryu_toggleAnimate_var2 = success == true
					end
				})

				while Ryu_toggleAnimate_var2 == nil do
					local now2 = os.clock()
					local HumanoidRootPart2 = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")
					local Magnitude2 = HumanoidRootPart2 and (targetCFrame.Position - HumanoidRootPart2.Position).Magnitude or math.huge

					if Magnitude2 < Magnitude - 0.5 then
						Magnitude = Magnitude2
						Ryu_lastProgressTime = now2
					end

					if self.destroyed or Ryu_travelOptions.abort ~= nil and Ryu_travelOptions.abort() or now2 - Ryu_lastProgressTime >= 1.5 or Ryu_travelAbsoluteDeadline <= now2 then
						if self.activeTween and self.activeTween.Cancel then
							pcall(self.activeTween.Cancel)
						end

						Ryu_toggleAnimate_var2 = false

						break
					else
						task.wait(0.05)
					end
				end

				return Ryu_toggleAnimate_var2
			end)

			self.travelBusy = false

			if ok then
				return result == true
			end

			if self.activeTween and self.activeTween.sharedTravel and self.activeTween.Cancel then
				pcall(self.activeTween.Cancel)
			end

			return false
		end

		do
			Ryu_EggRuntime._tweenRoot = function(self, targetCFrame, onSuccess, speedOverride, options)
				self:_clearArrivalHold()

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
				local Ryu_tweenOptions = options or {}

				if not HumanoidRootPart or not Humanoid then
					self.safeStarting = false

					if not Ryu_tweenOptions.silent then
						self:_finish("Character unavailable")

						return
					end

					if Ryu_tweenOptions.onDone then
						pcall(Ryu_tweenOptions.onDone, false)
					end

					return
				end

				local Ryu_resolvedMoveSpeed = speedOverride or self:_resolveMovementSpeed(Humanoid)

				if not Ryu_resolvedMoveSpeed then
					self.safeStarting = false

					if not Ryu_tweenOptions.silent then
						self:_finish("Movement unavailable")

						return
					end

					if Ryu_tweenOptions.onDone then
						pcall(Ryu_tweenOptions.onDone, false)
					end

					return
				end

				local Ryu_clampedMoveSpeed = math.clamp(Ryu_resolvedMoveSpeed, 200, Ryu_getMaxSpeedClamp())

				self:_startMovementProtection()
				pcall(Ryu_getDebugSource_var1, Character)

				local CurrentCamera = workspace.CurrentCamera

				if CurrentCamera and CurrentCamera.CameraSubject ~= Humanoid then
					pcall(function()
						CurrentCamera.CameraSubject = Humanoid
					end)
				end

				local AutoRotate = Humanoid.AutoRotate

				Humanoid.AutoRotate = false

				local Ryu_routeCruiseY = Ryu_tweenOptions.flightProfile == true and self:_resolveRouteCruiseY(HumanoidRootPart, targetCFrame) or nil
				local activeTween = {
					sharedTravel = Ryu_tweenOptions.sharedTravel == true,
					routeCruiseY = Ryu_routeCruiseY,
					travelPhase = Ryu_routeCruiseY and "takeoff" or nil,
					zigzag = self.config.stealMode == "Zig-Zag",
					zigT = 0,
					zigLast = 0
				}

				self.activeTween = activeTween
				self:_startHoverPad()

				local Ryu_onDone_var2 = false
				local connection
				local now
				local Ryu_onDone_var3
				local Ryu_onDone_var1 = 0

				local function Ryu_finishTween(success)
					if Ryu_onDone_var2 then
						return
					end

					Ryu_onDone_var2 = true
					now = nil

					if Humanoid.Parent ~= nil then
						Humanoid.AutoRotate = AutoRotate
					end

					if success and Ryu_tweenOptions.holdAfterArrival then
						self:_setArrivalHold(targetCFrame, Ryu_tweenOptions.holdUid)
					end

					if Ryu_tweenOptions.onDone then
						pcall(Ryu_tweenOptions.onDone, success == true)
					end

					if connection then
						connection:Disconnect()
						connection = nil
					end

					if self.activeTween == activeTween then
						self.activeTween = nil
					end

					if not self.arrivalHold then
						self:_stopHoverPad()
					end

					if not self.enabled then
						self:_stopMovementProtection()
					end

					pcall(function()
						if LocalPlayer2.Character == Character and HumanoidRootPart.Parent then
							HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
						end
					end)

					if success and LocalPlayer2.Character == Character and Humanoid.Parent ~= nil and onSuccess then
						onSuccess()
					end
				end

				activeTween.Cancel = function()
					Ryu_finishTween(false)
				end
				connection = RunService2.Heartbeat:Connect(function(dt)
					if Ryu_tweenOptions.abort and Ryu_tweenOptions.abort() then
						Ryu_finishTween(false)

						return
					end

					if self.destroyed or self.activeTween ~= activeTween then
						Ryu_finishTween(false)

						return
					end

					if Ryu_tweenOptions.carryTarget then
						if (activeTween.nextTargetCheck or 0) <= os.clock() then
							activeTween.nextTargetCheck = os.clock() + 0.1

							local Uid = Ryu_tweenOptions.carryTarget.Uid
							local Ryu_eggStateRecord = EggState2.ReadFieldEgg(Uid)
							local State = Ryu_eggStateRecord and Ryu_eggStateRecord.State

							if State ~= AreaEggs.States.Slot and State ~= AreaEggs.States.Dropped and State ~= "GuardCarried" and (not Ryu_eggStateRecord or Ryu_eggStateRecord.CarrierUserId ~= LocalPlayer2.UserId) and not self:_hasConfirmedCarry(Uid) then
								Ryu_finishTween(false)

								local __oxioPlayerSteal = genv.__oxioPlayerSteal

								self:_finish(State == "Carried" and __oxioPlayerSteal ~= nil and __oxioPlayerSteal:intercept(Uid) and "Target taken - chasing the carrier" or "Target taken by someone else")

								return
							end
						end
					end

					pcall(function()
						local Ryu_tweenSpeedValue = math.clamp(speedOverride or self.config.speed or Ryu_clampedMoveSpeed, 200, Ryu_getMaxSpeedClamp())

						Ryu_applySpoofWalkSpeed(Character, Ryu_tweenSpeedValue * 1.35)

						local __oxioStealAnEggIntegritySpoof = Ryu_getGenv().__oxioStealAnEggIntegritySpoof
						local State = type(__oxioStealAnEggIntegritySpoof) == "table" and __oxioStealAnEggIntegritySpoof.State or nil

						if not Ryu_isOwnStateB(State, Humanoid, HumanoidRootPart) then
							Ryu_onDone_var3 = nil
							now = nil
							HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
							HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
							self:_syncHoverPad(HumanoidRootPart.Position)

							if Ryu_isOwnStateA(State, Humanoid, HumanoidRootPart) then
								Ryu_applySpeedToState(State, Ryu_tweenSpeedValue * 1.35, Vector3.zero)
							else
								Ryu_installSpoofFromCharacter(Humanoid, HumanoidRootPart, Ryu_tweenSpeedValue)
							end

							return
						end

						local Position = HumanoidRootPart.Position
						local Ryu_tweenDelta = targetCFrame.Position - Position
						local Magnitude = Ryu_tweenDelta.Magnitude
						local vector33 = Vector3.new(Ryu_tweenDelta.X, 0, Ryu_tweenDelta.Z)
						local Magnitude2 = vector33.Magnitude
						local Position2 = targetCFrame.Position

						if activeTween.routeCruiseY then
							if activeTween.travelPhase == "takeoff" then
								if activeTween.routeCruiseY - 0.5 <= Position.Y then
									activeTween.travelPhase = "cruise"
								else
									Position2 = Vector3.new(Position.X, activeTween.routeCruiseY, Position.Z)
								end
							end

							if activeTween.travelPhase == "cruise" then
								if Magnitude2 <= 4 then
									activeTween.travelPhase = "descend"
								else
									Position2 = Vector3.new(targetCFrame.Position.X, activeTween.routeCruiseY, targetCFrame.Position.Z)
								end
							end

							if activeTween.travelPhase == "descend" then
								Position2 = targetCFrame.Position
							end
						end

						local Ryu_positionDelta = Position2 - Position
						local Magnitude3 = Ryu_positionDelta.Magnitude
						local routeCruiseY = activeTween.routeCruiseY and Magnitude2 or Magnitude

						if Ryu_onDone_var3 and Ryu_onDone_var3 + 2 < routeCruiseY then
							Ryu_onDone_var1 = os.clock() + 0.5
						end

						Ryu_onDone_var3 = routeCruiseY

						local Ryu_tweenFrameSpeed = os.clock() < Ryu_onDone_var1 and math.max(200, Ryu_tweenSpeedValue * 0.45) or Ryu_tweenSpeedValue

						if Ryu_tweenOptions.carryTarget and not activeTween.__earlyCarrySpam and Magnitude <= 30 then
							activeTween.__earlyCarrySpam = true

							local carryTarget = Ryu_tweenOptions.carryTarget
							local Uid = carryTarget.Uid
							local Ryu_slotKey = AreaEggSlotIdentity.LooksLikeFirstAreaUid(Uid) and AreaEggSlotIdentity.SlotKey(carryTarget.AreaId, carryTarget.NestId) or nil

							task.spawn(function()
								while not self.destroyed and self.enabled and self.activeTween == activeTween and not self:_hasConfirmedCarry(Uid) do
									pcall(Ryu_getMaxSpeedClamp_var1, Uid, Ryu_slotKey)
									task.wait(0.08)
								end
							end)
						end

						local Ryu_tweenFrameDelta = math.max(math.min(dt, 0.15), 0.0041666666666666666)
						local Ryu_tweenStepDist = Ryu_tweenFrameSpeed * Ryu_tweenFrameDelta
						local Ryu_tweenDirVector = vector33
						local vector34 = Vector3.new(HumanoidRootPart.CFrame.LookVector.X, 0, HumanoidRootPart.CFrame.LookVector.Z)
						local Unit = Ryu_tweenDirVector.Magnitude > 0.001 and Ryu_tweenDirVector.Unit or vector34.Magnitude > 0.001 and vector34.Unit or Vector3.new(0, 0, -1)

						if (not activeTween.routeCruiseY or activeTween.travelPhase == "descend") and Magnitude <= math.max(Ryu_tweenStepDist, 0.05) then
							if Magnitude > 0.5 then
								now = nil
							end

							self:_syncHoverPad(targetCFrame.Position)
							HumanoidRootPart.CFrame = lookAt(targetCFrame.Position, targetCFrame.Position + Unit)
							HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
							self:_syncHoverPad(targetCFrame.Position)
							Ryu_updateSpoofSpeed(Humanoid, HumanoidRootPart, Ryu_tweenSpeedValue, Vector3.zero)
							now = now or os.clock()

							if os.clock() - now >= 0.4 then
								Ryu_finishTween(true)
							end

							return
						end

						now = nil

						if Magnitude3 <= 0.001 then
							HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
							HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
							self:_syncHoverPad(Position)

							return
						end

						if not self.hoverPad or not self.hoverPad.Parent then
							self:_startHoverPad()
						end

						local Ryu_tweenClampedStep = math.min(Ryu_tweenStepDist, Magnitude3)
						local Ryu_tweenNextPos = Position + Ryu_positionDelta.Unit * Ryu_tweenClampedStep

						if Ryu_tweenFrameDelta >= 0.033333333333333333 and (not activeTween.routeCruiseY or activeTween.travelPhase ~= "cruise") then
							local Ryu_tweenGroundY = self:_groundYAt(Ryu_tweenNextPos.X, Ryu_tweenNextPos.Z, Character)

							if Ryu_tweenGroundY then
								local Ryu_tweenGroundYFeet = Ryu_tweenGroundY + self:_feetOffset(HumanoidRootPart, Humanoid)

								if Ryu_tweenNextPos.Y < Ryu_tweenGroundYFeet then
									Ryu_tweenNextPos = Vector3.new(Ryu_tweenNextPos.X, Ryu_tweenGroundYFeet, Ryu_tweenNextPos.Z)
								end
							end
						end

						if activeTween.zigzag and (not activeTween.routeCruiseY or activeTween.travelPhase == "cruise") then
							local vector35 = Vector3.new(Ryu_positionDelta.X, 0, Ryu_positionDelta.Z)

							if vector35.Magnitude > 1 and Magnitude2 > 12 then
								local Unit2 = vector35.Unit
								local vector36 = Vector3.new(-Unit2.Z, 0, Unit2.X)
								local Ryu_zigzagAmplitude = math.min(30, Magnitude2 * 0.3)

								if Magnitude2 < 120 then
									Ryu_zigzagAmplitude *= Magnitude2 / 120
								end

								activeTween.zigT = (activeTween.zigT or 0) + Ryu_tweenClampedStep

								local zigLast = Ryu_zigzagAmplitude * math.sin(activeTween.zigT / 900 * 3.1415926535897931 * 2)
								local zigLast2 = activeTween.zigLast or 0

								activeTween.zigLast = zigLast
								Ryu_tweenNextPos += vector36 * (zigLast - zigLast2)

								if not activeTween.zigLaneMin then
									local Ryu_zigzagBoundsMin, Ryu_zigzagBoundsMax = Ryu_getEggCarryBoundsZ()

									activeTween.zigLaneMin = Ryu_zigzagBoundsMin
									activeTween.zigLaneMax = Ryu_zigzagBoundsMax
								end

								local Ryu_zigzagClampedZ = math.clamp(Ryu_tweenNextPos.Z, activeTween.zigLaneMin, activeTween.zigLaneMax)

								if Ryu_zigzagClampedZ ~= Ryu_tweenNextPos.Z then
									Ryu_tweenNextPos = Vector3.new(Ryu_tweenNextPos.X, Ryu_tweenNextPos.Y, Ryu_zigzagClampedZ)
								end
							else
								activeTween.zigLast = 0
							end
						end

						local Ryu_tweenVelocity = (Ryu_tweenNextPos - Position) / Ryu_tweenFrameDelta

						self:_syncHoverPad(Ryu_tweenNextPos)
						HumanoidRootPart.CFrame = lookAt(Ryu_tweenNextPos, Ryu_tweenNextPos + Unit)
						HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
						self:_syncHoverPad(Ryu_tweenNextPos)

						if not Ryu_updateSpoofSpeed(Humanoid, HumanoidRootPart, Ryu_tweenSpeedValue, Ryu_tweenVelocity) then
							Ryu_installSpoofFromCharacter(Humanoid, HumanoidRootPart, Ryu_tweenSpeedValue)
							Ryu_updateSpoofSpeed(Humanoid, HumanoidRootPart, Ryu_tweenSpeedValue, Ryu_tweenVelocity)
						end
					end)
				end)
			end
		end

		Ryu_EggRuntime._reStealDroppedEgg = function(self, uid)
			if type(uid) ~= "string" or uid == "" then
				self:_finish("Egg lost — retrying")

				return
			end

			if self:isSkippedEgg(uid) then
				return
			end

			if self.tweenRecoveryUid == uid then
				self.running = false
				self.activeTarget = nil
				self:_releaseOperation()
				self:_scheduleMovementRetry()

				return
			end

			local Ryu_reStealWorker = self:_claimCarryWorker("re-steal", uid)

			if not Ryu_reStealWorker then
				return
			end

			if genv.__oxioGodMode then
				genv.__oxioGodMode:startDefend(uid)
			end

			local Ryu_reStealRecord
			local Ryu_reStealDeadline = os.clock() + 5

			self:_setStatus("Re-stealing dropped egg")

			while self:_isCarryWorkerCurrent(Ryu_reStealWorker) and os.clock() < Ryu_reStealDeadline do
				local Ryu_reStealFieldEgg = EggState2.ReadFieldEgg(uid) or self.records[uid]

				if Ryu_reStealFieldEgg and (Ryu_reStealFieldEgg.State == AreaEggs.States.Dropped or Ryu_reStealFieldEgg.State == AreaEggs.States.Slot) then
					Ryu_reStealRecord = Ryu_reStealFieldEgg

					break
				else
					task.wait(0.03)
				end
			end

			if not self:_isCarryWorkerCurrent(Ryu_reStealWorker) then
				return
			end

			if not Ryu_reStealRecord or not self:_wallOpen() then
				self:_releaseCarryWorker(Ryu_reStealWorker)
				self:_finish("Egg lost — retrying")

				return
			end

			self:_cancelTween("Re-stealing dropped egg", true)

			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
			local Ryu_reStealDestination = self:_resolveEggDestination(Ryu_reStealRecord, HumanoidRootPart, Humanoid)
			local Ryu_reStealElevatedDest = Ryu_reStealDestination and self:_resolveElevatedDestination(HumanoidRootPart, Ryu_reStealDestination) or nil

			if not Ryu_reStealElevatedDest then
				self:_releaseCarryWorker(Ryu_reStealWorker)
				self:_finish("Character unavailable")

				return
			end

			self.running = true
			self.activeTarget = Ryu_reStealRecord
			self:_setStatus("Bringing egg home")

			if self:_regrabBurst(Ryu_reStealWorker, Ryu_reStealRecord.Uid, 3.5) or not self:_isCarryWorkerCurrent(Ryu_reStealWorker) then
				return
			end

			self:_setStatus("Re-stealing egg")

			if not self:_teleportRoot(HumanoidRootPart, Humanoid, Ryu_reStealElevatedDest) then
				self:_releaseCarryWorker(Ryu_reStealWorker)
				self:_finish("Re-steal failed — retrying")

				return
			end

			self:_setArrivalHold(Ryu_reStealElevatedDest, Ryu_reStealRecord.Uid)
			self:_setStatus("Re-stealing egg")

			if self:_isCarryWorkerCurrent(Ryu_reStealWorker) then
				self:_requestCarry(Ryu_reStealRecord, true)
			end
		end

		do
			Ryu_EggRuntime._regrabBurst = function(self, worker, uid, duration)
				local function Ryu_isReStealDone()
					local Ryu_reStealEggCarried = EggState2.ReadFieldEgg(uid)

					return Ryu_reStealEggCarried ~= nil and Ryu_reStealEggCarried.State == AreaEggs.States.Carried and Ryu_reStealEggCarried.CarrierUserId == LocalPlayer2.UserId
				end

				local RagdollJoints

				pcall(function()
					RagdollJoints = require(ReplicatedStorage2.Shared.Modules.RagdollJoints)
				end)

				local Ryu_isReStealDone_var1 = false
				local Ryu_isReStealDone_var2 = false
				local Ryu_regrabDeadline = os.clock() + duration

				while true do
					if not (os.clock() < Ryu_regrabDeadline) or self.destroyed or not self.enabled and not self._externalDeliver then
						return Ryu_isReStealDone()
					end

					if Ryu_isReStealDone() then
						break
					end

					if not self:_isCarryWorkerCurrent(worker) then
						return Ryu_isReStealDone()
					end

					local Ryu_regrabRecord = EggState2.ReadFieldEgg(uid)

					if not Ryu_regrabRecord or Ryu_regrabRecord.State ~= AreaEggs.States.Dropped and Ryu_regrabRecord.State ~= AreaEggs.States.Slot then
						return false
					end

					local Character = LocalPlayer2.Character
					local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
					local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

					if not HumanoidRootPart or not Humanoid then
						return false
					end

					pcall(function()
						if RagdollJoints and RagdollJoints.Release then
							RagdollJoints.Release(Character)
						end

						Humanoid.PlatformStand = false
						Humanoid.Sit = false

						if Humanoid:GetState() ~= Enum.HumanoidStateType.Running then
							Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
						end
					end)

					local Ryu_regrabDestination = self:_resolveEggDestination(Ryu_regrabRecord, HumanoidRootPart, Humanoid)

					if Ryu_regrabDestination then
						HumanoidRootPart.CFrame = Ryu_regrabDestination
						HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
						HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
						self:_syncHoverPad(Ryu_regrabDestination.Position)
					end

					if not Ryu_isReStealDone_var1 then
						Ryu_isReStealDone_var1 = true
						task.spawn(function()
							pcall(function()
								EggWorld.AskFieldEggCarry:InvokeServer({
									Uid = uid
								})
							end)
							Ryu_isReStealDone_var1 = false
						end)
					end

					if not Ryu_isReStealDone_var2 then
						Ryu_isReStealDone_var2 = true
						task.spawn(function()
							pcall(EggState2.CarryFieldEgg, uid)
							Ryu_isReStealDone_var2 = false
						end)
					end

					pcall(function()
						local AreaEggSlotsClient = workspace:FindFirstChild("AreaEggSlotsClient")
						local Ryu_areaEggSlotClient = AreaEggSlotsClient and AreaEggSlotsClient:FindFirstChild(tostring(uid))
						local CarryAreaEgg = Ryu_areaEggSlotClient and (Ryu_areaEggSlotClient:FindFirstChild("CarryAreaEgg", true) or Ryu_areaEggSlotClient:FindFirstChildWhichIsA("ProximityPrompt", true))

						if CarryAreaEgg and CarryAreaEgg.Enabled and type(fireproximityprompt) == "function" then
							CarryAreaEgg.HoldDuration = 0
							CarryAreaEgg.RequiresLineOfSight = false
							fireproximityprompt(CarryAreaEgg, 0)
						end
					end)
					task.wait(0.06)
				end

				return true
			end
		end

		Ryu_EggRuntime._recoverCarryConfirmationTimeout = function(self, expectedWorker, uid)
			if self.destroyed or not self.enabled or self.carryAttemptToken ~= expectedWorker or self:_hasConfirmedCarry(uid) then
				return false
			end

			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Ryu_carryTimeoutSafeCF = HumanoidRootPart and self:_resolveSafeCFrame(HumanoidRootPart)
			local Ryu_carryTimeoutElevatedCF = Ryu_carryTimeoutSafeCF and self:_resolveElevatedDestination(HumanoidRootPart, Ryu_carryTimeoutSafeCF) or nil

			self.carryTimeouts = self.carryTimeouts or {}

			local Ryu_carryTimeoutAttempts = (self.carryTimeouts[uid] or 0) + 1
			local Ryu_carryTimeoutSkip = Ryu_carryTimeoutAttempts >= 2

			if Ryu_carryTimeoutSkip then
				self.carryTimeouts[uid] = nil
				self.skippedEggs[uid] = os.clock() + 45
				self.tweenRecoveryUid = nil
			else
				self.carryTimeouts[uid] = Ryu_carryTimeoutAttempts
				self.tweenRecoveryUid = not self:_isPrimerEgg(uid) and uid or nil
			end

			local lastCarryReject = self.stats.lastCarryReject
			local Ryu_timeoutRecord = self.records[uid] or EggState2.ReadFieldEgg(uid)
			local Ryu_timeoutIsForest = self.config.stealMode == "Instant" and (uid == self.primerUid or type(Ryu_timeoutRecord) == "table" and Ryu_timeoutRecord.AreaId == "Forest")
			local carry = self.carry

			carry.generation += 1
			self:_invalidateCarryWorker()
			self.carryAttemptToken = nil
			self:_clearArrivalHold(uid)

			if self.activeTween and self.activeTween.Cancel then
				pcall(self.activeTween.Cancel, self.activeTween)
			end

			self.activeTween = nil
			self.running = true
			self.activeTarget = nil
			self.stats.lastResult = "Carry confirmation timeout"

			if HumanoidRootPart and Ryu_carryTimeoutElevatedCF then
				pcall(function()
					HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
					HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				end)
				self:_setStatus("Carry timeout - returning to safe area")
				pcall(self._glideRoot, self, Ryu_carryTimeoutElevatedCF, function()
					return self.destroyed or not self.enabled
				end)

				if Ryu_carryTimeoutSkip then
					self:_setStatus(lastCarryReject and "Carry refused (" .. lastCarryReject .. ") — skipping egg" or "Carry timed out twice — skipping egg")
				else
					self:_setStatus("Carry timeout — retrying")
				end
			else
				self:_setStatus("Carry timeout — safe area unavailable")
			end

			self.running = false
			self:_releaseOperation()

			if Ryu_timeoutIsForest then
				self.running = true
			end

			task.delay(0.35, function()
				if Ryu_timeoutIsForest then
					if not self.destroyed and self.enabled then
						self:_setStatus("Retrying steal")
						pcall(self._treadmillReset, self, function()
							return self.destroyed or not self.enabled
						end)
					end

					self.running = false
				end

				if not self.destroyed and self.enabled and self.carryAttemptToken == nil then
					self:_schedule()
				end
			end)

			return true
		end
		-- Tunggu maksimal `seconds`, tapi berhenti lebih awal begitu carry sudah terkonfirmasi,
		-- record sudah menunjukkan carried, atau percobaan ini dibatalkan. Jumlah request carry
		-- tetap sama (tiap 0.25s); yang lebih cepat hanya deteksi konfirmasinya.
		local function Ryu_waitCarryTick(self, uid, token, seconds)
			local untilAt = os.clock() + seconds

			while true do
				task.wait(0.03) -- selalu yield sekali dulu supaya tidak pernah busy-loop

				if os.clock() >= untilAt then
					return
				end

				if self.destroyed or not self.enabled or self.carryAttemptToken ~= token then
					return
				end

				if self:_hasConfirmedCarry(uid) or self:_recordShowsCarried(uid) then
					return
				end
			end
		end

		Ryu_EggRuntime._requestCarry = function(self, record, skipReapproach)
			if not self:_wallOpen() then
				self:_finish("Wall closed before carry")

				return
			end

			local Uid = record.Uid
			local carryAttemptToken = {}
			local Ryu_isReStealDone_var3

			self.stats.lastCarryReject = nil

			local Ryu_carryConfirmWindow = self.instantPhase == "priming" and Uid == self.primerUid and 5 or math.max(5, self:_resolveSettleSeconds(record) + 3)

			self.carryAttemptToken = carryAttemptToken
			self.stats.lastResult = "Carry requested"
			self:_setStatus("Securing egg")

			local Character = LocalPlayer2.Character
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if Humanoid then
				pcall(Humanoid.UnequipTools, Humanoid)
			end

			if self.coordinator then
				local Ryu_backgroundWaitDeadline = os.clock() + 0.35

				while self.coordinator:isBackgroundBusy() and not self.destroyed and self.enabled and self.carryAttemptToken == carryAttemptToken and os.clock() < Ryu_backgroundWaitDeadline do
					task.wait(0.02)
				end

				if Humanoid and Humanoid.Parent then
					pcall(Humanoid.UnequipTools, Humanoid)
				end
			end

			task.spawn(function()
				while not self.destroyed and self.enabled and self.running and self.carryAttemptToken == carryAttemptToken and self.activeTarget and self.activeTarget.Uid == Uid do
					if not self:_hasConfirmedCarry(Uid) and self:_recordShowsCarried(Uid) then
						self:_adoptCarryFromRecord(Uid)
					end

					if self:_hasConfirmedCarry(Uid) then
						if not self:_recordShowsCarried(Uid) then
							self:_setStatus("Confirming carry record")
							task.wait(0.1)

							continue
						end

						self:_clearArrivalHold(Uid)
						self.carryAttemptToken = nil

						if self.activeTween then
							pcall(self.activeTween.Cancel, self.activeTween)
							self.activeTween = nil
						end

						if self.instantPhase == "priming" and Uid == self.primerUid then
							self.carry.active = true
							self.carry.uid = Uid
							self.stats.lastResult = "Preparing steal"
							self:_enterBaitWait()

							return
						end

						self.carry.active = true
						self.carry.uid = Uid
						self.stats.lastResult = "Carry confirmed"
						self:_setStatus("Carry confirmed")
						task.defer(function()
							if not self.destroyed and self.enabled and self:_hasConfirmedCarry(Uid) then
								self:_returnToSafe()
							end
						end)

						return
					end

					if Ryu_isReStealDone_var3 and Ryu_isReStealDone_var3 <= os.clock() then
						self:_recoverCarryConfirmationTimeout(carryAttemptToken, Uid)

						return
					end

					if not self:_wallOpen() then
						self:_finish("Wall closed before carry")

						return
					end

					local Ryu_carryRequestRecord = EggState2.ReadFieldEgg(Uid) or self.records[Uid]

					if not Ryu_carryRequestRecord then
						self:_finish("Target unavailable")

						return
					end

					if Ryu_carryRequestRecord.State == AreaEggs.States.Carried then
						if Ryu_carryRequestRecord.CarrierUserId == LocalPlayer2.UserId then
							self:_setStatus("Confirming carry state")
							task.wait(0.1)

							continue
						end

						self:_finish("Egg carried by another player")

						return
					end

					if Ryu_carryRequestRecord.State ~= AreaEggs.States.Slot and Ryu_carryRequestRecord.State ~= AreaEggs.States.Dropped then
						self:_finish("Target changed")

						return
					end

					local Character2 = LocalPlayer2.Character
					local HumanoidRootPart = Character2 and Character2:FindFirstChild("HumanoidRootPart")

					if not HumanoidRootPart then
						self:_finish("Character unavailable")

						return
					end

					local Humanoid2 = Character2 and Character2:FindFirstChildOfClass("Humanoid")

					if not Humanoid2 then
						self:_finish("Character unavailable")

						return
					end

					local Ryu_carryRequestDest = self:_resolveEggDestination(Ryu_carryRequestRecord, HumanoidRootPart, Humanoid2)
					local Ryu_carryRequestElevatedDest = Ryu_carryRequestDest and self:_resolveElevatedDestination(HumanoidRootPart, Ryu_carryRequestDest) or nil

					if not Ryu_carryRequestElevatedDest then
						self:_finish("Character unavailable")

						return
					end

					if (HumanoidRootPart.Position - Ryu_carryRequestElevatedDest.Position).Magnitude > 10 then
						if not skipReapproach then
							self:_setStatus("Re-approaching egg")

							local Ryu_isReStealDone_var4 = false

							self:_tweenRoot(Ryu_carryRequestDest, function()
								Ryu_isReStealDone_var4 = true

								if self.carryAttemptToken == carryAttemptToken and not self:_hasConfirmedCarry(Uid) then
									self:_setStatus("Securing egg")
								end
							end, nil, {
								holdAfterArrival = true,
								holdUid = Uid,
								flightProfile = true
							})

							while not self.destroyed and self.enabled and self.carryAttemptToken == carryAttemptToken and not self:_hasConfirmedCarry(Uid) and not Ryu_isReStealDone_var4 do
								task.wait(0.05)
							end

							continue
						end

						self:_setStatus("Re-stealing egg")

						if not self:_teleportRoot(HumanoidRootPart, Humanoid2, Ryu_carryRequestElevatedDest) then
							self:_finish("Re-steal failed — retrying")

							return
						end

						self:_setArrivalHold(Ryu_carryRequestElevatedDest, Uid)
						self:_setStatus("Re-stealing egg")
					end

					local ok, result, lastCarryReject = pcall(Ryu_getMaxSpeedClamp_var1, Ryu_carryRequestRecord.Uid, AreaEggSlotIdentity.LooksLikeFirstAreaUid(Ryu_carryRequestRecord.Uid) and AreaEggSlotIdentity.SlotKey(Ryu_carryRequestRecord.AreaId, Ryu_carryRequestRecord.NestId) or nil)

					if not ok then
						lastCarryReject = tostring(result)
					elseif result == true then
						lastCarryReject = nil
					end

					if lastCarryReject then
						self.stats.lastCarryReject = lastCarryReject

						if lastCarryReject ~= self._lastCarryRejectLogged then
							self._lastCarryRejectLogged = lastCarryReject
							warn("[oxio Steal] carry refused: " .. lastCarryReject)
						end
					end

					Ryu_isReStealDone_var3 = Ryu_isReStealDone_var3 or os.clock() + Ryu_carryConfirmWindow
					self.stats.lastResult = "Carry requested"
					self:_setStatus(lastCarryReject and "Waiting for carry · " .. lastCarryReject or "Waiting for carry confirmation")
					Ryu_waitCarryTick(self, Uid, carryAttemptToken, 0.25)
				end
			end)
		end
		Ryu_EggRuntime._burstHold = function(self, targetCFrame, cancelCheck)
			if typeof(targetCFrame) ~= "CFrame" then
				return false
			end

			local Position = targetCFrame.Position

			local function Ryu_getCarryRoot()
				local Character = LocalPlayer2.Character

				return Character and Character:FindFirstChild("HumanoidRootPart")
			end
			local function Ryu_holdRootCFrame(rootPart)
				rootPart.CFrame = targetCFrame
				rootPart.AssemblyLinearVelocity = Vector3.zero
				rootPart.AssemblyAngularVelocity = Vector3.zero
			end

			local Ryu_burstHoldDeadline = os.clock() + 0.7

			while true do
				if os.clock() < Ryu_burstHoldDeadline then
					if cancelCheck and cancelCheck() then
						break
					end

					local Ryu_burstHoldRoot = Ryu_getCarryRoot()

					if not Ryu_burstHoldRoot or not Ryu_burstHoldRoot.Parent then
						return false
					end

					pcall(Ryu_holdRootCFrame, Ryu_burstHoldRoot)
					RunService2.Heartbeat:Wait()

					continue
				end

				local Ryu_burstHoldSettleDeadline = os.clock() + 3
				local now

				while true do
					if not (os.clock() < Ryu_burstHoldSettleDeadline) then
						local Ryu_burstHoldRoot2 = Ryu_getCarryRoot()
						local Ryu_burstHoldInRange = Ryu_burstHoldRoot2 ~= nil and (Ryu_burstHoldRoot2.Position - Position).Magnitude <= 6

						return Ryu_burstHoldInRange
					end

					if cancelCheck and cancelCheck() then
						break
					end

					local Ryu_burstHoldRoot3 = Ryu_getCarryRoot()

					if not Ryu_burstHoldRoot3 or not Ryu_burstHoldRoot3.Parent then
						return false
					end

					if (Ryu_burstHoldRoot3.Position - Position).Magnitude > 6 then
						now = nil
					elseif not now then
						now = os.clock()
					elseif os.clock() - now >= 0.45 then
						return true
					end

					pcall(Ryu_holdRootCFrame, Ryu_burstHoldRoot3)
					RunService2.Heartbeat:Wait()
				end

				return false
			end

			return false
		end
		Ryu_EggRuntime._isStealPrompt = function(self, prompt)
			if typeof(prompt) ~= "Instance" then
				return false
			end

			if prompt.Name == "EnchantedTreePrompt" then
				return true
			end

			local AreaEggSlotsClient = workspace:FindFirstChild("AreaEggSlotsClient")

			if AreaEggSlotsClient and prompt:IsDescendantOf(AreaEggSlotsClient) then
				return true
			end

			if prompt:FindFirstAncestor("FuseBiomeLanePortals") or prompt:FindFirstAncestor("FuseBiomeZone") then
				return true
			end

			return false
		end
		Ryu_EggRuntime._installPromptFilter = function(self)
			if self._promptFilter or type(getconnections) ~= "function" then
				return
			end

			local promptFilter = {
				muted = {},
				forwarders = {}
			}

			self._promptFilter = promptFilter

			local function Ryu_shouldMutePrompt()
				return not self.destroyed and (self.enabled or self._externalDeliver or self._recalling or self._treeFxMuted ~= nil)
			end

			for _, v in ipairs({
				ProximityPromptService.PromptShown,
				ProximityPromptService.PromptHidden
			}) do
				local ok, result = pcall(getconnections, v)
				local ipairs_ = ipairs
				local Ryu_promptConnections = ok and type(result) == "table" and result or {}

				for _, Ryu_item in ipairs_(Ryu_promptConnections) do
					local Function = Ryu_item.Function
					local Ryu_debugInfoOk = false
					local result2

					if type(Function) == "function" then
						Ryu_debugInfoOk, result2 = pcall(debug.info, Function, "s")
					end

					if Ryu_debugInfoOk then
						if tostring(result2):find("ProximityPromptScriptController", 1, true) and type(Ryu_item.Disable) == "function" and pcall(Ryu_item.Disable, Ryu_item) then
							table.insert(promptFilter.muted, Ryu_item)
							table.insert(promptFilter.forwarders, v:Connect(function(prompt, ...)
								if Ryu_shouldMutePrompt() then
									if self:_isStealPrompt(prompt) then
										return
									end
								end

								Function(prompt, ...)
							end))
						end
					end
				end
			end
		end
		Ryu_EggRuntime._removePromptFilter = function(self)
			local _promptFilter = self._promptFilter

			if not _promptFilter then
				return
			end

			self._promptFilter = nil

			for _, forwarder in ipairs(_promptFilter.forwarders) do
				pcall(forwarder.Disconnect, forwarder)
			end

			for _, v in ipairs(_promptFilter.muted) do
				pcall(v.Enable, v)
			end
		end
		Ryu_EggRuntime._treadmillReset = function(self, cancelCheck)
			self._treadmillResetting = true

			local ok, result = pcall(self._treadmillResetInner, self, cancelCheck)

			self._treadmillResetting = false

			return ok and result
		end
		Ryu_EggRuntime._treadmillResetInner = function(self, cancelCheck)
			local function Ryu_treadmillResetCancelled()
				return cancelCheck ~= nil and cancelCheck()
			end

			local Treadmill = Remotes and Remotes.Treadmill

			if not Treadmill or Ryu_treadmillResetCancelled() then
				return false
			end

			local function Ryu_treadmillRenderSnapshot()
				local ok, result = pcall(function()
					return Treadmill.AskRenderSnapshot:InvokeServer()
				end)

				if ok and type(result) == "table" then
					return table.find(result, LocalPlayer2.UserId) ~= nil
				end

				return nil
			end
			local function Ryu_getTreadmillStandCF2()
				local ok, result = pcall(function()
					local Ryu_localPlotSlot2 = type(PlotState2.ResolveLocalSlot) == "function" and PlotState2.ResolveLocalSlot() or PlotState2.GetMySlot()
					local Ryu_plotsFolder2 = type(PlotState2.ResolveFolder) == "function" and PlotState2.ResolveFolder() or PlotState2.GetPlotsFolder()
					local Ryu_localPlotFolder2 = Ryu_plotsFolder2 and Ryu_localPlotSlot2 and Ryu_plotsFolder2:FindFirstChild(tostring(Ryu_localPlotSlot2))
					local TreadmillBottom = Ryu_localPlotFolder2 and Ryu_localPlotFolder2:FindFirstChild("TreadmillBottom")

					if not TreadmillBottom or not TreadmillBottom:IsA("BasePart") then
						return nil
					end

					local Character = LocalPlayer2.Character
					local HumanoidRootPart = Character
					local Humanoid, Ryu_feetOffset

					if HumanoidRootPart then
						HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")

						if Character then
							Humanoid = Character:FindFirstChildOfClass("Humanoid")

							if HumanoidRootPart and Humanoid then
								if Humanoid.RigType == Enum.HumanoidRigType.R15 then
									Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + math.max(Humanoid.HipHeight, 0.5)

									if not Ryu_feetOffset then
										Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + 2

										return TreadmillBottom.CFrame * cFrameNew(0, TreadmillBottom.Size.Y * 0.5 + Ryu_feetOffset + 0.05, 0)
									end
								else
									Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + 2
								end

								return TreadmillBottom.CFrame * cFrameNew(0, TreadmillBottom.Size.Y * 0.5 + Ryu_feetOffset + 0.05, 0)
							end
						end
					elseif Character then
						Humanoid = Character:FindFirstChildOfClass("Humanoid")

						if HumanoidRootPart and Humanoid then
							if Humanoid.RigType == Enum.HumanoidRigType.R15 then
								Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + math.max(Humanoid.HipHeight, 0.5)

								if not Ryu_feetOffset then
									Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + 2

									return TreadmillBottom.CFrame * cFrameNew(0, TreadmillBottom.Size.Y * 0.5 + Ryu_feetOffset + 0.05, 0)
								end
							else
								Ryu_feetOffset = HumanoidRootPart.Size.Y * 0.5 + 2
							end

							return TreadmillBottom.CFrame * cFrameNew(0, TreadmillBottom.Size.Y * 0.5 + Ryu_feetOffset + 0.05, 0)
						end
					end

					return nil
				end)
				local Ryu_treadmillStandCF3 = ok and result or nil

				return Ryu_treadmillStandCF3
			end

			local Ryu_treadmillStandCF4 = Ryu_getTreadmillStandCF2()

			if not Ryu_treadmillStandCF4 or Ryu_treadmillResetCancelled() then
				return false
			end

			self:_glideRoot(Ryu_treadmillStandCF4, function()
				return Ryu_treadmillResetCancelled()
			end)

			if Ryu_treadmillResetCancelled() then
				return false
			end

			local Ryu_treadmillWearOk = false
			local Ryu_treadmillWearDeadline = os.clock() + 0.7

			if not Ryu_treadmillResetCancelled() and os.clock() < Ryu_treadmillWearDeadline then
				while true do
					pcall(function()
						Treadmill.AskWearStill:InvokeServer()
					end)
					task.wait(0.08)

					if Ryu_treadmillRenderSnapshot() == true then
						Ryu_treadmillWearOk = true

						break
					elseif Ryu_treadmillResetCancelled() or not (os.clock() < Ryu_treadmillWearDeadline) then
						break
					end
				end

				if Ryu_treadmillWearOk then
					local Ryu_treadmillWearSettle = os.clock() + 0.25

					while not Ryu_treadmillResetCancelled() do
						if not (os.clock() < Ryu_treadmillWearSettle) then
							break
						end

						task.wait(0.05)
					end
				end
			end

			local Ryu_treadmillDoffOk = false
			local Ryu_treadmillDoffDeadline = os.clock() + 0.7

			while not Ryu_treadmillResetCancelled() and os.clock() < Ryu_treadmillDoffDeadline do
				pcall(function()
					Treadmill.AskDoff:InvokeServer()
				end)
				task.wait(0.08)

				if Ryu_treadmillRenderSnapshot() == false then
					Ryu_treadmillDoffOk = true

					break
				end
			end

			local Ryu_treadmillResetDone = Ryu_treadmillWearOk and Ryu_treadmillDoffOk

			return Ryu_treadmillResetDone
		end
		Ryu_EggRuntime._instantReturn = function(self, uid)
			if self._instantReturnToken ~= nil then
				return
			end

			local instantReturnToken = {}

			self._instantReturnToken = instantReturnToken
			self._flyDeparting = false

			if self.config.stealMode == "Fly" then
				self:_showTreadmillDecoy()
			end

			task.spawn(function()
				local function Ryu_isStillActive()
					return not self.destroyed and (self.enabled or self._externalDeliver) and self._instantReturnToken == instantReturnToken
				end
				local function Ryu_getCarryState()
					local Character = LocalPlayer2.Character

					return Character and Character:FindFirstChild("HumanoidRootPart"), Character and Character:FindFirstChildOfClass("Humanoid")
				end
				local function Ryu_getFieldEggState()
					return EggState2.ReadFieldEgg(uid)
				end
				local function Ryu_isFieldEggCarried()
					local Ryu_isFieldEggCarried2 = Ryu_getFieldEggState()

					return Ryu_isFieldEggCarried2 ~= nil and Ryu_isFieldEggCarried2.State == AreaEggs.States.Carried and Ryu_isFieldEggCarried2.CarrierUserId == LocalPlayer2.UserId
				end
				local function Ryu_isFieldEggClaimed()
					local Ryu_fieldEggState = Ryu_getFieldEggState()

					if Ryu_fieldEggState then
						return Ryu_fieldEggState.State == AreaEggs.States.Claimed
					end

					return true
				end
				local function Ryu_moveCarryToSafe(targetCFrame, statusText)
					local Ryu_carryRoot, Ryu_carryHumanoid = Ryu_getCarryState()

					if Ryu_carryRoot and Ryu_carryHumanoid and typeof(targetCFrame) == "CFrame" then
						if statusText then
							self:_setStatus(statusText)
						end

						self:_teleportRoot(Ryu_carryRoot, Ryu_carryHumanoid, targetCFrame)
					end
				end
				local function Ryu_getSafeCFrame()
					local Ryu_getSafeCFrame2 = Ryu_getCarryState()

					return Ryu_getSafeCFrame2 and self:_resolveSafeCFrame(Ryu_getSafeCFrame2) or nil
				end
				local function Ryu_setSettleBonus(isComplete)
					self.settleBonus = self.settleBonus or {}

					if isComplete then
						self.settleBonus[uid] = nil
					elseif self.config.stealMode == "Instant" and self.boostedUid ~= uid then
						self.settleBonus[uid] = {
							seconds = 2,
							untilAt = os.clock() + 300
						}
					end
				end
				local function Ryu_finishReturn(reason)
					if self._instantReturnToken ~= instantReturnToken then
						return
					end

					Ryu_setSettleBonus(reason == nil or reason == "Safe return complete")
					self._instantReturnToken = nil
					self._forestDropInProgress = nil

					local _externalDeliver = self._externalDeliver

					self._externalDeliver = nil

					if self.destroyed then
						return
					end

					if self.enabled then
						self:_reportStolen()
						self:_finish(reason or "Safe return complete")
					elseif _externalDeliver then
						self:_reportStolen()
						self.carry.active = false
						self.carry.uid = nil
						self.activeTarget = nil
						self:_hideTreadmillDecoy()
					end
				end

				self:_clearArrivalHold(uid)

				local treeRegrabMode = self.treeBoostedUid == uid and (self.treeRegrabMode or "walk") or "glide"

				local function Ryu_inSafeZone()
					local Ryu_inSafeZone2 = Ryu_getCarryState()

					return Ryu_inSafeZone2 ~= nil and self:_isInSafeArea(Ryu_inSafeZone2)
				end
				local function Ryu_walkToSafe(targetCFrame, cancelCheck, arriveDist)
					return self:_walkTo(targetCFrame, cancelCheck, arriveDist or 4)
				end
				local function Ryu_routeCarryStep(targetCFrame, cancelCheck, arriveDist, phase)
					local Ryu_treeRegrabMode = treeRegrabMode == "walk" or phase == "egg" and (treeRegrabMode == "glideSafe" or treeRegrabMode == "skipSafe") or phase == "safe" and treeRegrabMode == "glideEgg"

					if Ryu_treeRegrabMode and phase == "safe" then
						local Ryu_walkSelf2 = self
						local _walkTo = self._walkTo
						local Ryu_walkTargetPos2 = targetCFrame

						local function Ryu_walkCancelCheck2()
							return cancelCheck() or Ryu_inSafeZone()
						end

						local Ryu_walkArriveDist2 = arriveDist or 4

						return _walkTo(Ryu_walkSelf2, Ryu_walkTargetPos2, Ryu_walkCancelCheck2, Ryu_walkArriveDist2)
					end

					if not Ryu_treeRegrabMode then
						return self:_glideRoot(targetCFrame, cancelCheck)
					end

					local Ryu_walkSelf3 = self
					local _walkTo = self._walkTo
					local Ryu_walkTargetPos3 = targetCFrame
					local Ryu_walkCancelCheck3 = cancelCheck
					local Ryu_walkArriveDist3 = arriveDist or 4

					return _walkTo(Ryu_walkSelf3, Ryu_walkTargetPos3, Ryu_walkCancelCheck3, Ryu_walkArriveDist3)
				end

				local Ryu_isFlyMode = self.config.stealMode == "Fly" or self.boostedUid == uid and not senaV4Config.HelpFriend
				local Ryu_settleShort = Ryu_isFlyMode and 0.15 or 0.4
				local Ryu_settleLong = Ryu_isFlyMode and 0.45 or 0.85
				local Ryu_carryConfirmed = Ryu_isFieldEggCarried()

				if not Ryu_carryConfirmed then
					self:_setStatus("Confirming carry record")

					local Ryu_carryConfirmDeadline2 = os.clock() + 2.5

					while Ryu_isStillActive() and os.clock() < Ryu_carryConfirmDeadline2 do
						Ryu_carryConfirmed = Ryu_isFieldEggCarried()

						if not Ryu_carryConfirmed then
							local Ryu_carryClaimedState = Ryu_getFieldEggState()

							if not Ryu_carryClaimedState or Ryu_carryClaimedState.State ~= AreaEggs.States.Claimed then
								RunService2.Heartbeat:Wait()

								continue
							end
						end

						break
					end

					if not Ryu_isStillActive() then
						return
					end
				end

				if Ryu_carryConfirmed then
					self._forestDropInProgress = uid
					self:_setStatus("Bringing egg home")
					self:_glideRoot(cFrame, function()
						return not Ryu_isStillActive() or not Ryu_isFieldEggCarried()
					end)

