						self._instantReturnToken = nil
						self.carry.active = false
						self.carry.uid = nil
					end
				end)

				return true
			end

			self._externalDeliver = nil
			self.carry.active = false
			self.carry.uid = nil

			return false
		end
		Ryu_EggRuntime._adminSteal = function(self, record)
