							Position = HumanoidRootPart and HumanoidRootPart.Position
							Ryu_watchdogLastStatus = Ryu_watchdogStatus
							now3 = os.clock()
						elseif os.clock() - now3 > 12 then
							Ryu_watchdogLastStatus = nil
							Position = nil
							now3 = nil
							Ryu_watchdogLastKey = nil
							self.stats.watchdogResets = (self.stats.watchdogResets or 0) + 1
							pcall(function()
								self:_invalidateCarryWorker()
							end)
							self:_finish("Stuck - retrying")
							self:_releaseOperation()
						end

						if not self.enabled or self._captureHoldUid then
							Ryu_watchdogLastKey = nil
							now2 = nil
						elseif self.running then
							now2 = nil

							local Ryu_watchdogTargetKey = tostring(self.activeTarget and self.activeTarget.Uid) .. "|" .. tostring(self.carry.active)

							if Ryu_watchdogTargetKey ~= Ryu_watchdogLastKey then
								Ryu_watchdogLastKey = Ryu_watchdogTargetKey
								now = os.clock()
							elseif os.clock() - now > 60 then
								Ryu_watchdogLastKey = nil
								self.stats.watchdogResets = (self.stats.watchdogResets or 0) + 1

								local Uid = self.activeTarget and self.activeTarget.Uid

								if Uid and not self.carry.active then
									self.skippedEggs[Uid] = os.clock() + 45

									if self.tweenRecoveryUid == Uid then
										self.tweenRecoveryUid = nil
									end
								end

								pcall(function()
									self:_invalidateCarryWorker()
								end)
								self:_finish("Stuck — retrying")
							end
						else
							Ryu_watchdogLastKey = nil

							local ok, result = pcall(self._chooseTarget, self)

							if self:_wallOpen() and ok and result ~= nil then
								now2 = now2 or os.clock()

								if os.clock() - now2 > 6 then
									now2 = nil
									self.stats.watchdogResets = (self.stats.watchdogResets or 0) + 1
									self:_releaseOperation()
									self:_schedule()
								end
							else
								now2 = nil
							end
						end
					end

					self.watchdogRunning = false
				end)
			end
		end

		Ryu_EggRuntime._finalizeReturn = function(self, worker)
			if not self:_isCarryWorkerCurrent(worker) then
				return
			end

			if not self.carry.active then
				self:_releaseCarryWorker(worker)
				self:_reportStolen()
				self:_finish("Safe return complete")

				return
			end

			self:_setStatus("Validating safe arrival")

			local now = os.clock()
			local Ryu_finalizeDeadline = os.clock() + 6

			while true do
				if not self:_isCarryWorkerCurrent(worker) or not self.carry.active or not (os.clock() < Ryu_finalizeDeadline) then
					if not self:_isCarryWorkerCurrent(worker) then
						return
					end

					if not self.carry.active then
						self:_releaseCarryWorker(worker)
						self:_reportStolen()
						self:_finish("Safe return complete")

						return
					end

					self:_setStatus("Deposit pending — validating again")
					task.defer(function()
						if self:_isCarryWorkerCurrent(worker) and self.carry.active then
							self:_finalizeReturn(worker)
						end
					end)

					return
				end

				local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

				if not HumanoidRootPart then
					self:_releaseCarryWorker(worker)
					self:_finish("Character unavailable")

					return
				end

				if not self:_isInSafeArea(HumanoidRootPart) then
					break
				end

				if os.clock() - now >= 0.35 then
					self:_setStatus("Waiting for deposit")
				end

				task.wait(0.08)
			end

			self:_setStatus("Rollback detected — returning again")
			self:_releaseCarryWorker(worker)
			task.defer(function()
				if not self.destroyed and self.enabled and self.carry.active then
					self:_returnToSafe()
				end
			end)
		end
		Ryu_EggRuntime._finish = function(self, reason)
			self:_noteLowSpeedOutcome(reason)
			self:_hideTreadmillDecoy()
			self._forestDropInProgress = nil
			self._instantReturnToken = nil
			self.boostedUid = nil
			self:_invalidateCarryWorker()
			self.planGeneration += 1
			self:_cancelTween(reason, self.enabled)
			self:_setStatus(self.enabled and "Searching" or "Idle")

			if self.enabled then
				task.delay(0.05, function()
					if self.destroyed or not self.enabled then
						self:_releaseOperation()

						return
					end

					self:_schedule()
				end)
			end
		end
		Ryu_EggRuntime._scheduleMovementRetry = function(self)
			if self.movementRetryPending or self.destroyed or not self.enabled then
				return
			end

			self.movementRetryPending = true
			task.delay(0.2, function()
				self.movementRetryPending = false

				if not self.destroyed and self.enabled then
					self:_schedule()
				end
			end)
		end
		Ryu_EggRuntime._schedule = function(self)
			if not self.running then
				self.safeStarting = false
			end

			if self.destroyed or not self.enabled or self.running then
				return
			end

			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not HumanoidRootPart or not Humanoid then
				self:_releaseOperation()
				self:_setStatus("Character unavailable")

				return
			end

			self:_startMovementProtection()

			if self.carry.active and self.carry.uid ~= nil then
				if self.instantPhase == "priming" and self.carry.uid == self.primerUid then
					return
				end

				if self:_isPrimerEgg(self.carry.uid) then
					self:_setStatus("Dropping primer egg")
					self.skippedEggs[self.carry.uid] = os.clock() + 30
					pcall(EggState2.DropFieldEgg, "PlayerRequest")
					task.delay(0.5, function()
						if not self.destroyed and self.enabled then
							self:_schedule()
						end
					end)

					return
				end

				local Ryu_reconcileTarget = self.records[self.carry.uid] or EggState2.ReadFieldEgg(self.carry.uid)
				local captureObjectiveEnabled = type(Ryu_reconcileTarget) == "table" and (self.riftWants[Ryu_reconcileTarget.AssetCategory] or self.captureObjectiveEnabled and self:_isCaptureEgg(Ryu_reconcileTarget.Uid) or self.indexObjectiveEnabled and self:_isIndexObjective(Ryu_reconcileTarget) or self.wispObjective and self:_isWispObjective(Ryu_reconcileTarget) or self.userStealEnabled and not self.riftOnly and self:_matchesNormalFilter(Ryu_reconcileTarget))

				if type(Ryu_reconcileTarget) ~= "table" or captureObjectiveEnabled then
					self:_returnToSafe()

					return
				end

				self:_setStatus("Dropping unwanted egg")
				self.skippedEggs[self.carry.uid] = os.clock() + 30
				pcall(EggState2.DropFieldEgg, "PlayerRequest")
				task.delay(0.5, function()
					if not self.destroyed and self.enabled then
						self:_schedule()
					end
				end)

				return
			end

			if not self:_wallOpen() then
				self:_releaseOperation()
				self:_setStatus("Waiting for reset wall")

				return
			end

			local __oxioPlayerSteal = genv.__oxioPlayerSteal
			local autoSteal = Ryu_Blocker.blocker("auto_steal")
			local autoSteal2 = not autoSteal and Ryu_Blocker.holder("auto_steal") or nil

			if autoSteal or autoSteal2 or __oxioPlayerSteal and __oxioPlayerSteal.running then
				self:_releaseOperation()
				self:_setStatus(autoSteal and "Yielding to " .. Ryu_Blocker.TITLES[autoSteal] or autoSteal2 and "Waiting for " .. Ryu_Blocker.TITLES[autoSteal2] .. " to hand over" or "Yielding to Steal Players")

				if self._yieldRetryPending then
					return
				end

				self._yieldRetryPending = true
				task.delay((autoSteal or autoSteal2) and 1 or 0.5, function()
					self._yieldRetryPending = nil

					if not self.destroyed and self.enabled then
						self:_schedule()
					end
				end)

				return
			end

			local tweenRecoveryUid = self.tweenRecoveryUid
			local Ryu_recoveryRecord = tweenRecoveryUid and (EggState2.ReadFieldEgg(tweenRecoveryUid) or self.records[tweenRecoveryUid]) or nil

			if tweenRecoveryUid then
				if type(Ryu_recoveryRecord) ~= "table" or Ryu_recoveryRecord.State ~= AreaEggs.States.Slot and Ryu_recoveryRecord.State ~= AreaEggs.States.Dropped then
					self.tweenRecoveryUid = nil
					tweenRecoveryUid = nil
					Ryu_recoveryRecord = nil
				end
			end

			Ryu_recoveryRecord = Ryu_recoveryRecord or self:_chooseTarget()

			if not Ryu_recoveryRecord then
				if self.stats.matching == 0 and self.stats.available > 0 then
					if (self.config.minWeightKg or 0) > 0 then
						self:_setStatus(string.format("No eggs ≥ %dKg", self.config.minWeightKg))
					else
						self:_setStatus("No matching eggs")
					end
				else
					self:_setStatus("No matching eggs")
				end

				self:_releaseOperation()

				if not self.activeTween and self:_isInField(HumanoidRootPart) and not self:_isInSafeArea(HumanoidRootPart) then
					local Ryu_reconcileSafeCF = self:_resolveSafeCFrame(HumanoidRootPart)

					if Ryu_reconcileSafeCF then
						self:_tweenRoot(Ryu_reconcileSafeCF, nil, nil, {
							silent = true,
							flightProfile = true,
							abort = function()
								return not self.enabled or self.running
							end
						})
					end
				end

				return
			end

			if self.treadmillManager then
				if self.treadmillManager:isEngaged() then
					self.treadmillManager:_cancelIdle(true)
				end
			end

			local planGeneration = self.planGeneration
			local Ryu_opAcquired, Ryu_opAcquireError = self:_acquireOperation()

			if not Ryu_opAcquired then
				self:_setStatus("Waiting · " .. tostring(Ryu_opAcquireError or "another operation"))
				task.delay(0.5, function()
					if not self.destroyed and self.enabled and self.planGeneration == planGeneration then
						self:_schedule()
					end
				end)

				return
			end

			self.safeStarting = true
			self.running = true
			self.activeTarget = Ryu_recoveryRecord

			local Ryu_resolvedTargetCatalog = self.catalog.resolve(Ryu_recoveryRecord)

			self.stats.lastTarget = string.format("%s · %s · %s", Ryu_resolvedTargetCatalog.rarity, Ryu_resolvedTargetCatalog.name, Ryu_recoveryRecord.AreaId)

			if tweenRecoveryUid then
				self.safeStarting = false
				self.stats.lastResult = "Recovering with tween"

				local Ryu_recoveryDest = self:_resolveEggDestination(Ryu_recoveryRecord, HumanoidRootPart, Humanoid)

				if not Ryu_recoveryDest then
					self.tweenRecoveryUid = nil
					self:_finish("Recovery destination unavailable")

					return
				end

				self:_setStatus("Returning to egg")
				self:_tweenRoot(Ryu_recoveryDest, function()
					if self.tweenRecoveryUid == Ryu_recoveryRecord.Uid then
						self:_requestCarry(Ryu_recoveryRecord, false)
					end
				end, nil, {
					holdAfterArrival = true,
					holdUid = Ryu_recoveryRecord.Uid,
					flightProfile = true,
					carryTarget = Ryu_recoveryRecord
				})

				return
			end

			if not self:_leftTreadmill(HumanoidRootPart) then
				self.running = false
				self.safeStarting = false
				self.activeTarget = nil
				self:_releaseOperation()
				self:_setStatus("Preparing steal")
				task.delay(0.3, function()
					if not self.destroyed and self.enabled and self.planGeneration == planGeneration then
						self:_schedule()
					end
				end)

				return
			end

			if genv.__oxioAdminBoost == true and (not self.captureObjectiveEnabled or not self:_isCaptureEgg(Ryu_recoveryRecord.Uid)) then
				self.safeStarting = false
				task.spawn(self._adminSteal, self, Ryu_recoveryRecord)

				return
			end

			local Ryu_deltaFromSafe2 = HumanoidRootPart.Position - vector32
			local Magnitude = Vector2.new(Ryu_deltaFromSafe2.X, Ryu_deltaFromSafe2.Z).Magnitude
			local Ryu_isNearEggFirst = false

			if self.config.stealMode == "Fly" then
				local BottomCFrame = Ryu_recoveryRecord.BottomCFrame or Ryu_recoveryRecord.BoundsCFrame

				if BottomCFrame then
					local Ryu_deltaToEgg = BottomCFrame.Position - HumanoidRootPart.Position

					if Vector2.new(Ryu_deltaToEgg.X, Ryu_deltaToEgg.Z).Magnitude < Magnitude then
						Ryu_isNearEggFirst = true
					end
				end
			end

			if not Ryu_isNearEggFirst and Magnitude > 3 then
				if os.clock() - (self.lastSafeRepositionAt or 0) > 5 then
					local Ryu_repositionSafeCF = self:_resolveSafeCFrame(HumanoidRootPart)

					if Ryu_repositionSafeCF then
						self.safeStarting = true
						self.running = true
						self.lastSafeRepositionAt = os.clock()
						self:_setStatus("Repositioning to safe area")
						self:_tweenRoot(Ryu_repositionSafeCF, function()
							self:_groundSnap()
							self.safeStarting = false
							self.running = false
							task.delay(0.15, function()
								if not self.destroyed and self.enabled and self.planGeneration == planGeneration then
									self:_schedule()
								end
							end)
						end, nil, {
							flightProfile = true
						})

						return
					end
				end
			end

			self.safeStarting = false

			if self.config.stealMode == "Fly" then
				self.instantPhase = "priming"
				self.primerUid = nil
				self.targetUid = Ryu_recoveryRecord.Uid
				self.activeTarget = Ryu_recoveryRecord
				self._flyDeparting = false
				self.lowFpsPrime = false
				self:_installGuardHitDistanceBoost()
				self:_startMovementProtection()
				self.stats.lastResult = "High Speed departing"
				self:_startPrimerTargetHunt()

				return
			end

			local Ryu_primerEggSelected = self:_choosePrimerEgg(Ryu_recoveryRecord.Uid)

			if not Ryu_primerEggSelected then
				self.running = false
				self.activeTarget = nil
				self:_releaseOperation()
				self:_setStatus("Preparing steal")
				task.delay(0.25, function()
					if not self.destroyed and self.enabled and self.planGeneration == planGeneration then
						self:_schedule()
					end
				end)

				return
			end

			self.instantPhase = "priming"
			self.primerUid = Ryu_primerEggSelected.Uid
			self.primerUids[Ryu_primerEggSelected.Uid] = os.clock() + 120
			self.skippedEggs[Ryu_primerEggSelected.Uid] = os.clock() + 30
			self.targetUid = Ryu_recoveryRecord.Uid
			self.activeTarget = Ryu_primerEggSelected
			self._flyDeparting = self.config.stealMode == "Fly"

			if self.config.stealMode == "Instant" then
				self:_showTreadmillDecoy()
			end

			self:_installGuardHitDistanceBoost()
			self.stats.lastResult = self.config.stealMode .. " priming"
			self.lowFpsPrime = Ryu_getFps() < 30

			local Ryu_primerEggDest = self:_resolveEggDestination(Ryu_primerEggSelected, HumanoidRootPart, Humanoid)

			if not Ryu_primerEggDest then
				self:_finish("Steal unavailable — retrying")

				return
			end

			if self.lowFpsPrime then
				self:_setStatus("Preparing steal")
				self:_tweenRoot(Ryu_primerEggDest, function()
					if self.instantPhase == "priming" and self.primerUid == Ryu_primerEggSelected.Uid then
						self:_requestCarry(Ryu_primerEggSelected, false)
					end
				end, nil, {
					holdAfterArrival = true,
					holdUid = Ryu_primerEggSelected.Uid,
					flightProfile = true,
					carryTarget = Ryu_primerEggSelected
				})

				return
			end

			if self.config.stealMode == "Fly" then
				self:_setStatus("Preparing steal")

				if not self:_glideRoot(Ryu_primerEggDest, function()
					return self.destroyed or not self.enabled or self.instantPhase ~= "priming" or self.primerUid ~= Ryu_primerEggSelected.Uid
				end) then
					if self.instantPhase == "priming" and self.primerUid == Ryu_primerEggSelected.Uid then
						self:_finish("Steal unavailable — retrying")
					end

					return
				end

				self:_setArrivalHold(Ryu_primerEggDest, Ryu_primerEggSelected.Uid)
				self:_requestCarry(Ryu_primerEggSelected, true)

				return
			end

			self:_setStatus("Preparing steal")

			if not self:_teleportRoot(HumanoidRootPart, Humanoid, Ryu_primerEggDest) then
				self:_finish("Steal unavailable — retrying")

				return
			end

			self:_setArrivalHold(Ryu_primerEggDest, Ryu_primerEggSelected.Uid)
			self:_requestCarry(Ryu_primerEggSelected, true)
		end
		Ryu_EggRuntime._leftTreadmill = function(self, rootPart)
			local treadmillManager = self.treadmillManager

			if not treadmillManager or treadmillManager.destroyed then
				return true
			end

			if not (treadmillManager.activeTreadmill ~= nil or treadmillManager.treadmillEquipPending == true or treadmillManager.travelingToTreadmill == true or rootPart ~= nil and rootPart.Anchored) then
				self.treadmillLeaveAt = nil

				return true
			end

			local now = os.clock()

			self.treadmillLeaveAt = self.treadmillLeaveAt or now
			treadmillManager.idleGeneration += 1

			if not self.treadmillDoffBusy then
				if now - (self.treadmillDoffAt or 0) > 0.6 then
					self.treadmillDoffBusy = true
					self.treadmillDoffAt = now
					task.spawn(function()
						pcall(treadmillManager._requestUnequip, treadmillManager)
						pcall(treadmillManager._syncActiveTreadmillSnapshot, treadmillManager)
						self.treadmillDoffBusy = false
					end)
				end
			end

			if rootPart and rootPart.Anchored and now - self.treadmillLeaveAt > 1 then
				pcall(function()
					rootPart.Anchored = false
				end)
			end

			if not (now - self.treadmillLeaveAt > 8) then
				return false
			end

			self.treadmillLeaveAt = nil

			return true
		end

		do
			Ryu_EggRuntime._reconcileRunningState = function(self)
				local enabled = self.userStealEnabled == true or next(self.riftWants) ~= nil or self.indexObjectiveEnabled == true or self.wispObjective ~= nil or self.manualObjectiveEnabled == true or self.captureObjectiveEnabled == true

				if self.enabled == enabled then
					if self.enabled then
						self:_refreshCounts()
						self:_schedule()
					end

					return
				end

				self.enabled = enabled

				if self.enabled then
					if LocalPlayer2.Character then
						Ryu_getDebugSource_var1(LocalPlayer2.Character)
						Ryu_installHealthPin(self, LocalPlayer2.Character)
					end

					self:_installGuardHitDistanceBoost()
					self:_startMovementProtection()
					pcall(self._installPromptFilter, self)
					self:_setStatus("Searching")
					self:_schedule()
				else
					if self._instantReturnToken ~= nil and self.carry.uid ~= nil and not self._externalDeliver then
						self._externalDeliver = true
						self.planGeneration += 1
						self.running = false
						self:_setStatus("Finishing target egg")
						task.spawn(function()
							local Ryu_instantFinishDeadline = os.clock() + 45

							while self._instantReturnToken ~= nil and os.clock() < Ryu_instantFinishDeadline and not self.destroyed do
								task.wait(0.2)
							end

							if self.destroyed or self.enabled then
								return
							end

							self._externalDeliver = nil
							self._instantReturnToken = nil
							self.carry.active = false
							self.carry.uid = nil
							self.activeTarget = nil
							self:_cleanupInstantSteal()
							self:_removeGuardHitDistanceBoost()
							self:_restoreTreadmillVisualAtSafe()
							self:_stopMovementProtection()
							Ryu_clearHealthPin(self)
							self:_setStatus("Idle")
						end)
						self:_refreshCounts()

						return
					end

					self.planGeneration += 1

					local carry = self.carry

					carry.generation += 1
					self:_cleanupInstantSteal()
					self:_removeGuardHitDistanceBoost()
					self:_invalidateCarryWorker()
					self._forestDropInProgress = nil
					self._instantReturnToken = nil
					self.carry.active = false
					self.carry.uid = nil
					self.tweenRecoveryUid = nil
					self.claimPresentationSuppression = nil
					self.safeStarting = false
					self.movementRetryPending = false
					self:_cancelTween("Disabled")
					self:_releaseOperation()
					self:_restoreTreadmillVisualAtSafe()
					self:_stopMovementProtection()
					Ryu_clearHealthPin(self)
					self.activeTarget = nil
					self.running = false
					self:_setStatus("Idle")
				end

				self:_refreshCounts()
			end
		end

		Ryu_EggRuntime.setEnabled = function(self, enabled)
			self.userStealEnabled = enabled == true
			self:_reconcileRunningState()

			if self.userStealEnabled then
				self:_startWatchdog()
			end

			self:_reconcileScramblePortal()
		end

		do
			Ryu_EggRuntime._neutralizeScramblePortal = function(self, portal)
				if typeof(portal) ~= "Instance" or portal.Name ~= "ScrambleArenaPortal" then
					return
				end

				self.scramblePortalOriginals = self.scramblePortalOriginals or {}

				for _, descendant in ipairs(portal:GetDescendants()) do
					if descendant:IsA("BasePart") then
						if self.scramblePortalOriginals[descendant] == nil then
							local attribute = descendant:GetAttribute("oxioPortalOrig")

							if type(attribute) == "string" then
								self.scramblePortalOriginals[descendant] = {
									CanCollide = attribute:sub(1, 1) == "1",
									CanTouch = attribute:sub(2, 2) == "1"
								}
							else
								self.scramblePortalOriginals[descendant] = {
									CanCollide = descendant.CanCollide,
									CanTouch = descendant.CanTouch
								}
								pcall(descendant.SetAttribute, descendant, "oxioPortalOrig", (descendant.CanCollide and "1" or "0") .. (descendant.CanTouch and "1" or "0"))
							end
						end

						pcall(function()
							descendant.CanCollide = false
							descendant.CanTouch = false
						end)
					end
				end
			end
		end

		Ryu_EggRuntime._startScramblePortalBypass = function(self)
			local ScrambleArenaPortal = workspace:FindFirstChild("ScrambleArenaPortal")

			if ScrambleArenaPortal then
				self:_neutralizeScramblePortal(ScrambleArenaPortal)
			end

			if not self.scramblePortalConn then
				self.scramblePortalConn = workspace.ChildAdded:Connect(function(child)
					if self.destroyed or not self.userStealEnabled or self._scramblePortalHold or senaV4Config.ScrambleBossAuto == true then
						return
					end

					if child.Name ~= "ScrambleArenaPortal" then
						return
					end

					for _, v in ipairs({
						0,
						0.15,
						0.4,
						0.8
					}) do
						task.delay(v, function()
							if not self.destroyed and self.userStealEnabled and not self._scramblePortalHold then
								if senaV4Config.ScrambleBossAuto ~= true and child.Parent then
									self:_neutralizeScramblePortal(child)
								end
							end
						end)
					end
				end)
			end
		end
		Ryu_EggRuntime._stopScramblePortalBypass = function(self)
			if self.scramblePortalConn then
				pcall(self.scramblePortalConn.Disconnect, self.scramblePortalConn)
				self.scramblePortalConn = nil
			end

			if self.scramblePortalOriginals then
				for k, scramblePortalOriginal in pairs(self.scramblePortalOriginals) do
					if typeof(k) == "Instance" and k.Parent then
						pcall(function()
							k.CanCollide = scramblePortalOriginal.CanCollide
							k.CanTouch = scramblePortalOriginal.CanTouch
							k:SetAttribute("oxioPortalOrig", nil)
						end)
					end
				end

				self.scramblePortalOriginals = nil
			end
		end

		do
			Ryu_EggRuntime._setScramblePortalHold = function(self, holdState)
				local scramblePortalHold = holdState == true

