			end

			self:_schedule()
		end

		do
			local Ryu_espDetailFields = {
				rarity = true,
				name = true,
				kg = true,
				mutation = true,
				value = true,
				placed = true,
				icon = true
			}

			Ryu_computeRatePerSec = function(record)
				if type(record) ~= "table" then
					return nil
				end

				local Category = record.Category or record.AssetCategory
				local Ryu_computeRatePerSec_var2 = tonumber(record.Scale or record.AssetScale)

				if type(Category) ~= "string" or not Ryu_computeRatePerSec_var2 or Ryu_computeRatePerSec_var2 <= 0 then
					return nil
				end

				local ok, result = pcall(AssetEarnings.MutationOnlyRatePerSecond, {
					Category = Category,
					Scale = Ryu_computeRatePerSec_var2,
					Mutations = type(record.Mutations) == "table" and table.clone(record.Mutations) or {},
					BaseMutation = type(record.BaseMutation) == "string" and record.BaseMutation or nil
				})

				return ok and type(result) == "number" and result or nil
			end

			local Ryu_computeRatePerSec_var1

			local function Ryu_formatCompactNumber(value)
				if type(Ryu_computeRatePerSec_var1) ~= "table" then
					local ok, result = pcall(require, ReplicatedStorage2.Packages.FormatNumber.Simple)

					if ok and type(result.FormatCompact) == "function" then
						Ryu_computeRatePerSec_var1 = result
					end
				end

				if Ryu_computeRatePerSec_var1 then
					local ok, result = pcall(Ryu_computeRatePerSec_var1.FormatCompact, value, ".#")

					if ok and type(result) == "string" then
						return result
					end
				end

				local Ryu_absCompactValue = math.abs(value)

				if Ryu_absCompactValue >= 1e12 then
					return string.format("%.2fT", value / 1e12)
				end

				if Ryu_absCompactValue >= 1e9 then
					return string.format("%.2fB", value / 1e9)
				end

				if Ryu_absCompactValue >= 1000000 then
					return string.format("%.1fM", value / 1000000)
				end

				if Ryu_absCompactValue >= 1000 then
					return string.format("%.1fK", value / 1000)
				end

				return string.format("%d", math.floor(value + 0.5))
			end

			local Ryu_lowSpeedFailures = {
				["Carry not confirmed — retrying"] = true,
				["Carry refused — next egg"] = true,
				["Carry lost — retrying"] = true,
				["Drop failed — retrying"] = true,
				["Egg lost — retrying"] = true,
				["Re-steal failed — retrying"] = true,
				["Steal timed out — retrying"] = true
			}
			local Ryu_guardExitCache = {}

			local function Ryu_getGuardExitXMap()
				if next(Ryu_guardExitCache) then
					return Ryu_guardExitCache
				end

				local Ryu_worldRef6 = Ryu_getWorkspaceWorld()
				local Areas = Ryu_worldRef6 and Ryu_worldRef6:FindFirstChild("Areas")
				local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
				local ipairs_ = ipairs
				local children = GuardAreas and GuardAreas:GetChildren() or {}

				for _, child in ipairs_(children) do
					local ClosestExitPoint = child:FindFirstChild("ClosestExitPoint")

					if ClosestExitPoint and ClosestExitPoint:IsA("BasePart") then
						Ryu_guardExitCache[child.Name] = ClosestExitPoint.Position.X
					end
				end

				return Ryu_guardExitCache
			end

			Ryu_EggRuntime.settleNeed = function(self, areaId, walkSpeed)
				return 2 + math.max(0, (Ryu_getGuardExitXMap()[areaId] or 597) - 597) / (3.2 * math.max(walkSpeed, 16))
			end
			Ryu_EggRuntime.recommendLowSpeedLevel = function(self, projectedSpeed)
				local Ryu_currentProjectedSpeed = projectedSpeed or Ryu_getLegitSpeedFromTreadmill()
				local Ryu_settleAreas = {}

				if self.config.areaEnabled and #self.config.areas > 0 then
					Ryu_settleAreas = self.config.areas
				else
					for k in pairs(Ryu_getGuardExitXMap()) do
						Ryu_settleAreas[#Ryu_settleAreas + 1] = k
					end
				end

				local Ryu_getGuardExitXMap_var1 = 10
				local Ryu_getGuardExitXMap_var2 = 10
				local Ryu_settleWorstArea

				for _, v in ipairs(Ryu_settleAreas) do
					local Ryu_settleRequired = self:settleNeed(v, Ryu_currentProjectedSpeed)
					local Ryu_getGuardExitXMap_var3 = 1
					local Ryu_getGuardExitXMap_var4 = 1

					for i = 10, 1, -1 do
						if Ryu_settleRequired <= Ryu_computeSettleSeconds(v, i) then
							Ryu_getGuardExitXMap_var3 = i

							break
						end
					end

					for i = 10, 1, -1 do
						if Ryu_settleRequired * 1.25 <= Ryu_computeSettleSeconds(v, i) then
							Ryu_getGuardExitXMap_var4 = i

							break
						end
					end

					if Ryu_getGuardExitXMap_var3 < Ryu_getGuardExitXMap_var2 then
						Ryu_getGuardExitXMap_var2 = Ryu_getGuardExitXMap_var3
						Ryu_settleWorstArea = v
					end

					Ryu_getGuardExitXMap_var1 = math.min(Ryu_getGuardExitXMap_var1, Ryu_getGuardExitXMap_var4)
				end

				local lowSpeedFailCap = self.lowSpeedFailCap

				if lowSpeedFailCap then
					Ryu_getGuardExitXMap_var2 = math.min(Ryu_getGuardExitXMap_var2, lowSpeedFailCap)
					Ryu_getGuardExitXMap_var1 = math.min(Ryu_getGuardExitXMap_var1, lowSpeedFailCap)
				end

				return math.min(Ryu_getGuardExitXMap_var1, Ryu_getGuardExitXMap_var2), Ryu_getGuardExitXMap_var2, Ryu_currentProjectedSpeed, Ryu_settleWorstArea
			end
			Ryu_EggRuntime._noteLowSpeedOutcome = function(self, reason)
				local Ryu_untrustedSeen = self._untrustedSeen == true

				self._untrustedSeen = nil

				if self.config.stealMode ~= "Instant" then
					return
				end

				if self.boostedUid ~= nil or self._boostHopUid ~= nil then
					return
				end

				local Ryu_isFailureStatus = Ryu_lowSpeedFailures[tostring(reason)] == true or Ryu_untrustedSeen

				if not Ryu_isFailureStatus and reason ~= "Safe return complete" then
					return
				end

				local Ryu_currentHoldLevel = math.clamp(tonumber(senaV4Config.StealHoldSeconds) or 5, 1, 10)

				self.lowSpeedOutcomes = self.lowSpeedOutcomes or {}

				local Ryu_lowSpeedHistory = self.lowSpeedOutcomes[Ryu_currentHoldLevel] or {}

				self.lowSpeedOutcomes[Ryu_currentHoldLevel] = Ryu_lowSpeedHistory
				Ryu_lowSpeedHistory[#Ryu_lowSpeedHistory + 1] = {
					at = os.clock(),
					failed = Ryu_isFailureStatus
				}

				while #Ryu_lowSpeedHistory > 8 do
					table.remove(Ryu_lowSpeedHistory, 1)
				end

				local Ryu_getGuardExitXMap_var5 = 0
				local Ryu_getGuardExitXMap_var6 = 0

				for _, v in ipairs(Ryu_lowSpeedHistory) do
					if os.clock() - v.at <= 600 then
						Ryu_getGuardExitXMap_var6 += 1

						if v.failed then
							Ryu_getGuardExitXMap_var5 += 1
						end
					end
				end

				if Ryu_currentHoldLevel > 1 then
					if Ryu_getGuardExitXMap_var5 >= 3 and Ryu_getGuardExitXMap_var5 / Ryu_getGuardExitXMap_var6 >= 0.4 then
						local lowSpeedFailCap = Ryu_currentHoldLevel - 1

						if not self.lowSpeedFailCap or lowSpeedFailCap < self.lowSpeedFailCap then
							self.lowSpeedFailCap = lowSpeedFailCap
							self.lowSpeedAdvice = {
								from = Ryu_currentHoldLevel,
								to = lowSpeedFailCap,
								fails = Ryu_getGuardExitXMap_var5,
								total = Ryu_getGuardExitXMap_var6,
								fresh = true
							}
						end
					end
				end
			end
			Ryu_EggRuntime.lowSpeedStatus = function(self)
				local Ryu_getGuardExitXMap_var7

				pcall(function()
					Ryu_getGuardExitXMap_var7 = SpeedPowerProjection.ReadProjected()
				end)

				local Ryu_recommendedSafeLevel, Ryu_recommendedFastLevel, Ryu_currentWalkSpeed = self:recommendLowSpeedLevel()
				local Ryu_holdLevelForAdvice = math.clamp(tonumber(senaV4Config.StealHoldSeconds) or 5, 1, 10)
				local lowSpeedAdvice = self.lowSpeedAdvice

				if lowSpeedAdvice and Ryu_holdLevelForAdvice <= lowSpeedAdvice.to then
					lowSpeedAdvice = nil
				end

				local Ryu_lowSpeedStatus = {
					speedText = type(Ryu_getGuardExitXMap_var7) == "number" and Ryu_formatCompactNumber(Ryu_getGuardExitXMap_var7) or "?",
					walkSpeed = math.floor((Ryu_currentWalkSpeed or 0) + 0.5),
					safe = Ryu_recommendedSafeLevel,
					fast = Ryu_recommendedFastLevel,
					level = Ryu_holdLevelForAdvice,
					advice = lowSpeedAdvice
				}

				return Ryu_lowSpeedStatus
			end
			Ryu_EggRuntime.setEggEsp = function(self, enabled)
				self.config.espEnabled = enabled == true

				if not self.config.espEnabled then
					pcall(function()
						self:_clearEsp()
					end)
				end
			end
			Ryu_EggRuntime.setEspMinRank = function(self, rank)
				self.config.espMinRank = math.max(tonumber(rank) or 0, 0)
			end
			Ryu_EggRuntime.setEspMinValue = function(self, value)
				self.config.espMinValue = math.max(tonumber(value) or 0, 0)
			end
			Ryu_EggRuntime._espPasses = function(self, record, value)
				local config = self.config
				local espMinRank = config.espMinRank

				if (espMinRank or 0) > 0 then
					if (tonumber(record and record.rarityRank) or 0) < config.espMinRank then
						return false
					end
				end

				if (config.espMinValue or 0) > 0 then
					if (tonumber(value) or 0) < config.espMinValue then
						return false
					end
				end

				return true
			end
			Ryu_EggRuntime.setEspOption = function(self, option, enabled)
				if Ryu_espDetailFields[option] then
					self.config["esp" .. option:sub(1, 1):upper() .. option:sub(2)] = enabled == true
				end
			end
			Ryu_EggRuntime._clearEsp = function()
				local AreaEggSlotsClient = workspace:FindFirstChild("AreaEggSlotsClient")

				if not AreaEggSlotsClient then
					return
				end

				for _, child in ipairs(AreaEggSlotsClient:GetChildren()) do
					local __oxioEggEsp = child:FindFirstChild("__oxioEggEsp")

					if __oxioEggEsp then
						__oxioEggEsp:Destroy()
					end

					local __oxioEggHighlight = child:FindFirstChild("__oxioEggHighlight")

					if __oxioEggHighlight then
						__oxioEggHighlight:Destroy()
					end
				end
			end
			Ryu_EggRuntime._updateEsp = function(self)
				local AreaEggSlotsClient = workspace:FindFirstChild("AreaEggSlotsClient")

				if not AreaEggSlotsClient then
					return
				end

				local config = self.config

				for _, child in ipairs(AreaEggSlotsClient:GetChildren()) do
					local Ryu_areaEggRecord = self.records[child.Name]
					local Ryu_espRecordValid = config.espEnabled and Ryu_areaEggRecord ~= nil and (Ryu_areaEggRecord.State == AreaEggs.States.Slot or Ryu_areaEggRecord.State == AreaEggs.States.Dropped)

					if Ryu_espRecordValid and not self:_espPasses(self.catalog.resolve(Ryu_areaEggRecord), Ryu_computeRatePerSec(Ryu_areaEggRecord)) then
						Ryu_espRecordValid = false
					end

					local Hitbox = Ryu_espRecordValid and (child:FindFirstChild("Hitbox") or child:FindFirstChildWhichIsA("BasePart", true))
					local __oxioEggEsp = child:FindFirstChild("__oxioEggEsp")
					local __oxioEggHighlight = child:FindFirstChild("__oxioEggHighlight")

					if Ryu_espRecordValid and Hitbox then
						if __oxioEggEsp and not __oxioEggEsp:FindFirstChild("Icon") then
							__oxioEggEsp:Destroy()
							__oxioEggEsp = nil
						end

						if not __oxioEggEsp then
							__oxioEggEsp = Instance.new("BillboardGui")
							__oxioEggEsp.Name = "__oxioEggEsp"
							__oxioEggEsp.AlwaysOnTop = true
							__oxioEggEsp.Size = UDim2.fromOffset(220, 72)
							__oxioEggEsp.StudsOffset = Vector3.new(0, 4.4, 0)
							__oxioEggEsp.MaxDistance = 1000
							__oxioEggEsp.Adornee = Hitbox

							local ImageLabel = Instance.new("ImageLabel")

							ImageLabel.Name = "Icon"
							ImageLabel.AnchorPoint = Vector2.new(0.5, 1)
							ImageLabel.Position = UDim2.fromScale(0.5, 0.42)
							ImageLabel.Size = UDim2.fromOffset(30, 30)
							ImageLabel.BackgroundTransparency = 1
							ImageLabel.ScaleType = Enum.ScaleType.Fit
							ImageLabel.Visible = false
							ImageLabel.Parent = __oxioEggEsp

							local TextLabel = Instance.new("TextLabel")

							TextLabel.Name = "Text"
							TextLabel.AnchorPoint = Vector2.new(0.5, 0)
							TextLabel.Position = UDim2.fromScale(0.5, 0.45)
							TextLabel.Size = UDim2.new(1, 0, 0.55, 0)
							TextLabel.BackgroundTransparency = 1
							TextLabel.Font = Enum.Font.GothamBold
							TextLabel.TextSize = 13
							TextLabel.TextStrokeTransparency = 0.35
							TextLabel.TextXAlignment = Enum.TextXAlignment.Center
							TextLabel.TextYAlignment = Enum.TextYAlignment.Top
							TextLabel.Parent = __oxioEggEsp
							__oxioEggEsp.Parent = child
						end

						__oxioEggEsp.Adornee = Hitbox

						local Ryu_resolvedEggData = self.catalog.resolve(Ryu_areaEggRecord)
						local Icon = __oxioEggEsp:FindFirstChild("Icon")
						local icon = config.espIcon and type(Ryu_resolvedEggData.icon) == "string" and Ryu_resolvedEggData.icon ~= "" and Ryu_resolvedEggData.icon or nil

						Icon.Image = icon or ""
						Icon.Visible = icon ~= nil

						local rarityColor = typeof(Ryu_resolvedEggData.rarityColor) == "Color3" and Ryu_resolvedEggData.rarityColor or Color3.fromRGB(255, 255, 255)
						local Ryu_espParts = {}

						if config.espRarity then
							Ryu_espParts[#Ryu_espParts + 1] = string.upper(Ryu_resolvedEggData.rarity or "?")
						end

						if config.espName then
							Ryu_espParts[#Ryu_espParts + 1] = tostring(Ryu_resolvedEggData.name)
						end

						if config.espKg then
							local Ryu_resolvedWeightKg = self:_resolveWeightKg(Ryu_areaEggRecord)

							if Ryu_resolvedWeightKg then
								Ryu_espParts[#Ryu_espParts + 1] = string.format("%d Kg", math.floor(Ryu_resolvedWeightKg))
							end
						end

						if config.espMutation and type(Ryu_areaEggRecord.Mutations) == "table" and next(Ryu_areaEggRecord.Mutations) then
							local Ryu_espMutationList = {}

							for _, mutation in pairs(Ryu_areaEggRecord.Mutations) do
								Ryu_espMutationList[#Ryu_espMutationList + 1] = tostring(mutation)
							end

							if #Ryu_espMutationList > 0 then
								table.sort(Ryu_espMutationList)
								Ryu_espParts[#Ryu_espParts + 1] = table.concat(Ryu_espMutationList, ", ")
							end
						end

						if config.espValue then
							local Ryu_resolvedRatePerSec = Ryu_computeRatePerSec(Ryu_areaEggRecord)

							if Ryu_resolvedRatePerSec then
								Ryu_espParts[#Ryu_espParts + 1] = "$" .. Ryu_formatCompactNumber(Ryu_resolvedRatePerSec) .. "/s"
							end
						end

						local Text = __oxioEggEsp:FindFirstChild("Text")

						Text.Text = table.concat(Ryu_espParts, " | ")
						Text.TextColor3 = rarityColor

						if __oxioEggHighlight and not __oxioEggHighlight:IsA("Highlight") then
							__oxioEggHighlight:Destroy()
							__oxioEggHighlight = nil
						end

						if not __oxioEggHighlight then
							__oxioEggHighlight = Instance.new("Highlight")
							__oxioEggHighlight.Name = "__oxioEggHighlight"
							__oxioEggHighlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
							__oxioEggHighlight.Parent = child
						end

						__oxioEggHighlight.Adornee = child
						__oxioEggHighlight.FillColor = rarityColor
						__oxioEggHighlight.FillTransparency = 0.72
						__oxioEggHighlight.OutlineColor = rarityColor
						__oxioEggHighlight.OutlineTransparency = 0
					else
						if __oxioEggEsp then
							__oxioEggEsp:Destroy()
						end

						if __oxioEggHighlight then
							__oxioEggHighlight:Destroy()
						end
					end
				end

				self._placedEspAnchors = self._placedEspAnchors or {}
				os.clock()

				if config.espPlaced then
					local Ryu_saveSnapshot = (Save.Peek or Save.Get)()
					local EggInventory = type(Ryu_saveSnapshot) == "table" and Ryu_saveSnapshot.EggInventory

					EggInventory = EggInventory or nil

					local Ryu_localSlot = PlotState2.ResolveLocalSlot()
					local Ryu_plotsFolder3 = PlotState2.ResolveFolder()
					local Ryu_localPlotFolder = Ryu_plotsFolder3 and Ryu_localSlot and Ryu_plotsFolder3:FindFirstChild(tostring(Ryu_localSlot))
					local CenterPoint = Ryu_localPlotFolder and Ryu_localPlotFolder:FindFirstChild("CenterPoint")

					if CenterPoint and not CenterPoint:IsA("BasePart") then
						CenterPoint = nil
					end

					local Ryu_placedEspKeys = {}

					if type(EggInventory) == "table" and CenterPoint then
						local oxioPlacedEggAnchors = workspace:FindFirstChild("oxioPlacedEggAnchors")

						if not oxioPlacedEggAnchors then
							oxioPlacedEggAnchors = Instance.new("Folder")
							oxioPlacedEggAnchors.Name = "oxioPlacedEggAnchors"
							oxioPlacedEggAnchors.Parent = workspace
						end

						for _, child in ipairs(oxioPlacedEggAnchors:GetChildren()) do
							if child:IsA("Highlight") or child:IsA("BillboardGui") then
								child:Destroy()
							end
						end

						for k, v in pairs(EggInventory) do
							if type(k) == "string" and type(v) == "table" and type(v.Placement) == "table" then
								Ryu_placedEspKeys[k] = true

								local LocalCFrame = v.Placement.LocalCFrame

								if typeof(LocalCFrame) ~= "CFrame" then
									local ok, result = pcall(EggRecords.Decode, v)
									local Placement = ok and type(result) == "table" and result.Placement or nil

									LocalCFrame = type(Placement) == "table" and Placement.LocalCFrame or nil
								end

								if typeof(LocalCFrame) == "CFrame" then
									local ok, result = pcall(EggRecords.Decode, v)
									local Ryu_decodedRecord = ok and type(result) == "table" and result or v
									local Ryu_decodedScale = tonumber(Ryu_decodedRecord.AssetScale) or 1
									local cFrame2 = CenterPoint.CFrame * LocalCFrame + Vector3.new(0, 3 + Ryu_decodedScale * 2, 0)

									self._placedEspAnchors[k] = self._placedEspAnchors[k] or {}

									local Ryu_placedAnchor = self._placedEspAnchors[k]

									if typeof(Ryu_placedAnchor.anchor) ~= "Instance" then
										local Part = Instance.new("Part")

										Part.Name = "oxioPE_" .. k
										Part.Size = Vector3.new(1.5, 1.5, 1.5)
										Part.Transparency = 1
										Part.Anchored = true
										Part.CanCollide = false
										Part.CanQuery = false
										Part.CanTouch = false
										Part.Parent = oxioPlacedEggAnchors
										Ryu_placedAnchor.anchor = Part
									end

									Ryu_placedAnchor.anchor.CFrame = cFrame2

									local Ryu_resolvedPlacedEgg = self.catalog.resolve({
										AssetCategory = Ryu_decodedRecord.AssetCategory
									})
									local rarityColor = typeof(Ryu_resolvedPlacedEgg.rarityColor) == "Color3" and Ryu_resolvedPlacedEgg.rarityColor or Color3.fromRGB(255, 255, 255)
									local Ryu_placedEggRate = Ryu_computeRatePerSec({
										Category = Ryu_decodedRecord.AssetCategory,
										Mutations = type(Ryu_decodedRecord.Mutations) == "table" and Ryu_decodedRecord.Mutations or {},
										Scale = Ryu_decodedScale,
										BaseMutation = type(Ryu_decodedRecord.BaseMutation) == "string" and Ryu_decodedRecord.BaseMutation or nil
									})

									if self:_espPasses(Ryu_resolvedPlacedEgg, Ryu_placedEggRate) then
										local Ryu_placedEspText = {}

										if config.espRarity then
											Ryu_placedEspText[#Ryu_placedEspText + 1] = string.upper(Ryu_resolvedPlacedEgg.rarity or "?")
										end

										if config.espName then
											Ryu_placedEspText[#Ryu_placedEspText + 1] = tostring(Ryu_resolvedPlacedEgg.name)
										end

										if config.espKg then
											local ok2, result2 = pcall(EggRecords.WeightKgForScale, Ryu_decodedRecord.AssetCategory, Ryu_decodedScale)

											if ok2 and type(result2) == "number" then
												Ryu_placedEspText[#Ryu_placedEspText + 1] = string.format("%d Kg", math.floor(result2))
											end
										end

										if config.espValue and Ryu_placedEggRate then
											Ryu_placedEspText[#Ryu_placedEspText + 1] = "$" .. Ryu_formatCompactNumber(Ryu_placedEggRate) .. "/s"
										end

										if type(v.Placement.ReadyAt) == "number" or type(Ryu_decodedRecord.Placement) == "table" and Ryu_decodedRecord.Placement.ReadyAt ~= nil then
											Ryu_placedEspText[#Ryu_placedEspText + 1] = "READY"
										end

										local __oxioEggEsp = Ryu_placedAnchor.anchor:FindFirstChild("__oxioEggEsp")

										if not __oxioEggEsp then
											__oxioEggEsp = Instance.new("BillboardGui")
											__oxioEggEsp.Name = "__oxioEggEsp"
											__oxioEggEsp.AlwaysOnTop = true
											__oxioEggEsp.Size = UDim2.fromOffset(220, 72)
											__oxioEggEsp.StudsOffset = Vector3.new(0, 1.4, 0)
											__oxioEggEsp.MaxDistance = 1000

											local ImageLabel = Instance.new("ImageLabel")

											ImageLabel.Name = "Icon"
											ImageLabel.AnchorPoint = Vector2.new(0.5, 1)
											ImageLabel.Position = UDim2.fromScale(0.5, 0.42)
											ImageLabel.Size = UDim2.fromOffset(34, 34)
											ImageLabel.BackgroundTransparency = 1
											ImageLabel.ScaleType = Enum.ScaleType.Fit
											ImageLabel.Visible = false
											ImageLabel.Parent = __oxioEggEsp

											local TextLabel = Instance.new("TextLabel")

											TextLabel.Name = "Text"
											TextLabel.AnchorPoint = Vector2.new(0.5, 0)
											TextLabel.Position = UDim2.fromScale(0.5, 0.45)
											TextLabel.Size = UDim2.new(1, 0, 0.55, 0)
											TextLabel.BackgroundTransparency = 1
											TextLabel.Font = Enum.Font.GothamBold
											TextLabel.TextSize = 13
											TextLabel.TextStrokeTransparency = 0.35
											TextLabel.TextXAlignment = Enum.TextXAlignment.Center
											TextLabel.TextYAlignment = Enum.TextYAlignment.Top
											TextLabel.Parent = __oxioEggEsp
											__oxioEggEsp.Parent = Ryu_placedAnchor.anchor
										end

										local Icon = __oxioEggEsp:FindFirstChild("Icon")

										if Icon then
											local icon = config.espIcon and type(Ryu_resolvedPlacedEgg.icon) == "string" and Ryu_resolvedPlacedEgg.icon ~= "" and Ryu_resolvedPlacedEgg.icon or nil

											Icon.Image = icon or ""
											Icon.Visible = icon ~= nil
										end

										local Text = __oxioEggEsp:FindFirstChild("Text")

										Text.Text = table.concat(Ryu_placedEspText, " | ")
										Text.TextColor3 = rarityColor

										local __oxioEggHighlight = Ryu_placedAnchor.anchor:FindFirstChild("__oxioEggHighlight")

										if __oxioEggHighlight then
											__oxioEggHighlight:Destroy()
										end
									else
										Ryu_placedEspKeys[k] = nil
									end
								end
							end
						end
					end

					for k, placedEspAnchor in pairs(self._placedEspAnchors) do
						if not Ryu_placedEspKeys[k] then
							if typeof(placedEspAnchor.anchor) == "Instance" then
								placedEspAnchor.anchor:Destroy()
							end

							if typeof(placedEspAnchor.highlight) == "Instance" then
								placedEspAnchor.highlight:Destroy()
							end

							self._placedEspAnchors[k] = nil
						end
					end
				else
					local pairs_ = pairs
					local _placedEspAnchors = self._placedEspAnchors or {}

					for k, _placedEspAnchor in pairs_(_placedEspAnchors) do
						if typeof(_placedEspAnchor.anchor) == "Instance" then
							_placedEspAnchor.anchor:Destroy()
						end

						if typeof(_placedEspAnchor.highlight) == "Instance" then
							_placedEspAnchor.highlight:Destroy()
						end

						self._placedEspAnchors[k] = nil
					end
				end
			end
		end

		Ryu_EggRuntime.setMinWeightKg = function(self, value)
			self.config.minWeightKg = math.max(tonumber(value) or 0, 0)
		end
		Ryu_EggRuntime.setMinValuePerSec = function(self, value)
			self.config.minValuePerSec = math.max(tonumber(value) or 0, 0)
			self:_refreshCounts()
			self:_schedule()
		end
		Ryu_EggRuntime.setSpeed = function(self, speed)
			local Ryu_clampedSpeedInput = math.clamp(math.floor((tonumber(speed) or 60) + 0.5), 20, 100)

			self.config.speed = Ryu_clampedSpeedInput * 10

			if genv.__oxioAdminBoost == true then
				self.config.speed = 3000
			end

			if self.enabled or self.activeTween then
				self:_startMovementProtection()
			end

			return Ryu_clampedSpeedInput
		end

		do
			Ryu_EggRuntime.getDefaultSpeed = function()
				return 60
			end
		end

		do
			Ryu_EggRuntime.setFilterEnabled = function(self, filterName, enabled)
				self.config[filterName .. "Enabled"] = enabled == true
				self:_refreshCounts()
				self:_schedule()
			end
		end

		Ryu_EggRuntime.setFilter = function(self, filterKey, valueList)
			local Ryu_copiedFilterList = type(valueList) == "table" and table.clone(valueList) or {}

			if filterKey == "mutations" and type(self.catalog.resolveMutationId) == "function" then
				local Ryu_mutationResolvedIds = {}

				for _, v in ipairs(Ryu_copiedFilterList) do
					local Ryu_resolvedMutationId = self.catalog.resolveMutationId(v)

					if Ryu_resolvedMutationId then
						table.insert(Ryu_mutationResolvedIds, Ryu_resolvedMutationId)
					end
				end

				Ryu_copiedFilterList = Ryu_mutationResolvedIds
			end

			self.config[filterKey] = Ryu_copiedFilterList
			self:_refreshCounts()
			self:_schedule()
		end
		Ryu_EggRuntime.destroy = function(self)
			if self.destroyed then
				return
			end

			self.destroyed = true
			self.enabled = false
			pcall(self._stopScramblePortalBypass, self)
			pcall(self._removePromptFilter, self)

			if self._relocateConn then
				pcall(self._relocateConn.Disconnect, self._relocateConn)
				self._relocateConn = nil
			end

			self._recalling = nil
			self:_hideTreadmillDecoy()
			self.planGeneration += 1

			local carry = self.carry

			carry.generation += 1
			self:_invalidateCarryWorker()
			self.carry.active = false
			self.carry.uid = nil
			self.tweenRecoveryUid = nil
			self.safeStarting = false
			self:_cancelTween("Destroyed")
			self:_cleanupInstantSteal()
			self:_removeGuardHitDistanceBoost()
			self:_releaseOperation()
			self:_stopMovementProtection()

			if self._healthPinner then
				pcall(self._healthPinner.Disconnect, self._healthPinner)
				self._healthPinner = nil
			end

			if self._healthChangedConnection then
				pcall(self._healthChangedConnection.Disconnect, self._healthChangedConnection)
				self._healthChangedConnection = nil
			end

			self:_restoreClaimPresentationFilter()
			Ryu_restoreDeathStates(LocalPlayer2.Character)
			pcall(function()
				self:_clearEsp()
			end)
			pcall(function()
				local pairs_ = pairs
				local _placedEspAnchors = self._placedEspAnchors or {}

				for _, _placedEspAnchor in pairs_(_placedEspAnchors) do
					if typeof(_placedEspAnchor.anchor) == "Instance" then
						_placedEspAnchor.anchor:Destroy()
					end
				end

				local oxioPlacedEggAnchors = workspace:FindFirstChild("oxioPlacedEggAnchors")

				if oxioPlacedEggAnchors then
					oxioPlacedEggAnchors:Destroy()
				end
			end)
			Ryu_disconnectAll(self.connections)
			table.clear(self.listeners)
			table.clear(self.records)
		end

		return Ryu_EggRuntime
	end

	local Ryu_EggRuntimeClass = Ryu_EggRuntimeFactory()
	local Ryu_rateUnitMult = {
		k = 1000,
		m = 1000000,
		b = 1e9,
		t = 1e12,
		q = 1e15
	}

	local function Ryu_parseCompactNumber(valueInput)
		local match, Ryu_parsedNumberUnit = tostring(valueInput or ""):lower():gsub("%s+", ""):gsub("%$", ""):gsub("/s$", ""):match("^([%d%.]+)([kmbtq]?)$")
		local Ryu_parsedNumberValue = tonumber(match)

		if Ryu_parsedNumberValue then
			return math.max(0, math.floor(Ryu_parsedNumberValue * (Ryu_rateUnitMult[Ryu_parsedNumberUnit] or 1) + 0.5))
		end

		return nil
	end
	local function Ryu_AntiGuardFactory()
		local Players2 = game:GetService("Players")
		local RunService2 = game:GetService("RunService")
		local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
		local LocalPlayer2 = Players2.LocalPlayer
		local Remotes = require(ReplicatedStorage2.Shared.Remotes)
		local EggState2 = require(ReplicatedStorage2.Client.EggState)
		local Ragdoll = require(ReplicatedStorage2.Shared.Modules.Ragdoll)
		local RagdollJoints = require(ReplicatedStorage2.Shared.Modules.RagdollJoints)
		local EggWorld = Remotes.EggWorld
		local Ryu_AntiGuardBody = {}

		Ryu_AntiGuardBody.__index = Ryu_AntiGuardBody

		local function Ryu_disconnectConnection(self)
			if self then
				pcall(self.Disconnect, self)
			end
		end

		Ryu_AntiGuardBody.new = function(eggRuntime)
			local obj = setmetatable({}, Ryu_AntiGuardBody)

			obj.eggRuntime = eggRuntime
			obj.enabled = true
			obj.destroyed = false
			obj.connections = {}
			obj.originalRagdoll = {}
			obj.originalHumanoidStates = setmetatable({}, {
				__mode = "k"
			})
			obj.stats = {
				blockedHits = 0,
				blockedDrops = 0,
				recarriedEggs = 0
			}
			obj.lastHeldEggUid = nil
			obj.lastHeldSlotKey = nil
			obj._installed = false
			obj._stickyToken = 0
			obj._nextBodyRecoveryAt = 0
			obj._nextJointSweepAt = 0
			obj._forestStrikeOldFire = nil

			return obj
		end
		Ryu_AntiGuardBody._liveBody = function()
			local Character = LocalPlayer2.Character
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			return Character, Humanoid, Character and Character:FindFirstChild("HumanoidRootPart")
		end
		Ryu_AntiGuardBody._recoverBody = function(self, force)
			if not self.enabled or self.destroyed then
				return
			end

			local Ryu_antiGuardChar, Ryu_antiGuardHumanoid, Ryu_antiGuardRoot = self:_liveBody()

			if not Ryu_antiGuardChar or not Ryu_antiGuardHumanoid or not Ryu_antiGuardRoot then
				return
			end

			local now = os.clock()

			if not force and now < self._nextBodyRecoveryAt then
				return
			end

			self._nextBodyRecoveryAt = now + 0.03

			if not self.originalHumanoidStates[Ryu_antiGuardHumanoid] then
				self.originalHumanoidStates[Ryu_antiGuardHumanoid] = {
					Physics = Ryu_antiGuardHumanoid:GetStateEnabled(Enum.HumanoidStateType.Physics),
					FallingDown = Ryu_antiGuardHumanoid:GetStateEnabled(Enum.HumanoidStateType.FallingDown),
					Ragdoll = Ryu_antiGuardHumanoid:GetStateEnabled(Enum.HumanoidStateType.Ragdoll)
				}
			end

			local state = Ryu_antiGuardHumanoid:GetState()
			local Ryu_wasInRagdollState = state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.FallingDown

			Ryu_wasInRagdollState = Ryu_wasInRagdollState or state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.PlatformStanding or state == Enum.HumanoidStateType.Seated
			pcall(function()
				Ryu_antiGuardHumanoid.BreakJointsOnDeath = false
				Ryu_antiGuardHumanoid.RequiresNeck = false
				Ryu_antiGuardHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
				Ryu_antiGuardHumanoid:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
				Ryu_antiGuardHumanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
				Ryu_antiGuardHumanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
				Ryu_antiGuardHumanoid.PlatformStand = false
				Ryu_antiGuardHumanoid.Sit = false

				local state2 = Ryu_antiGuardHumanoid:GetState()

				if state2 == Enum.HumanoidStateType.Physics or state2 == Enum.HumanoidStateType.FallingDown or state2 == Enum.HumanoidStateType.Ragdoll or state2 == Enum.HumanoidStateType.PlatformStanding or state2 == Enum.HumanoidStateType.Seated then
					Ryu_antiGuardHumanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					Ryu_antiGuardHumanoid:ChangeState(Enum.HumanoidStateType.Running)
				end
			end)

			for _, descendant in ipairs(Ryu_antiGuardChar:GetDescendants()) do
				if not descendant:IsA("Motor6D") then
					if descendant:IsA("BallSocketConstraint") or descendant:IsA("HingeConstraint") then
						if descendant.Name:find("Ragdoll", 1, true) or descendant:GetAttribute("RagdollConstraint") then
							pcall(descendant.Destroy, descendant)
						end
					end
				elseif not descendant.Enabled then
					descendant.Enabled = true
				end
			end

			local AssemblyLinearVelocity = Ryu_antiGuardRoot.AssemblyLinearVelocity
			local Magnitude = Vector3.new(AssemblyLinearVelocity.X, 0, AssemblyLinearVelocity.Z).Magnitude
			local Ryu_maxAllowedVelocity = math.max(340, (tonumber(Ryu_antiGuardHumanoid.WalkSpeed) or 0) * 1.5)

			if Ryu_wasInRagdollState or Ryu_maxAllowedVelocity < Magnitude or math.abs(AssemblyLinearVelocity.Y) > 240 then
				Ryu_antiGuardRoot.AssemblyLinearVelocity = Vector3.zero
				Ryu_antiGuardRoot.AssemblyAngularVelocity = Vector3.zero
				self.stats.blockedHits += 1
			end
		end
		Ryu_AntiGuardBody._watchCharacter = function(self, character)
			if not character then
				return
			end

			local connection = character.DescendantAdded:Connect(function(descendant)
				if not self.enabled or self.destroyed then
					return
				end

				if not descendant:IsA("BallSocketConstraint") and not descendant:IsA("HingeConstraint") then
					if descendant:IsA("Motor6D") and not descendant.Enabled then
						descendant.Enabled = true
					end
				elseif descendant.Name:find("Ragdoll", 1, true) or descendant:GetAttribute("RagdollConstraint") then
					pcall(descendant.Destroy, descendant)
					self:_recoverBody(true)
				end
			end)

			table.insert(self.connections, connection)
		end
		Ryu_AntiGuardBody._installRagdollHooks = function(self)
			if self._installed then
				return
			end

			self._installed = true
			task.spawn(function()
				task.wait()

				local __oxioForestGate = genv.__oxioForestGate

				if type(__oxioForestGate) == "table" and __oxioForestGate.comp and __oxioForestGate.orig then
					pcall(rawset, __oxioForestGate.comp, "_attackHandler", __oxioForestGate.orig)
					genv.__oxioForestGate = nil
				end

				if type(getgc) ~= "function" then
					return
				end

				local ok, result = pcall(getgc, true)

				if not ok or type(result) ~= "table" then
					return
				end

				for i, v in ipairs(result) do
					if i % 20000 == 0 then
						RunService2.Heartbeat:Wait()
					end

					if self.destroyed then
						return
					end

					if type(v) ~= "table" or rawget(v, "_areaId") ~= "Forest" or type(rawget(v, "_attackHandler")) ~= "function" then
						continue
					end

					local value = rawget(v, "_attackHandler")

					self._forestGate = {
						comp = v,
						orig = value
					}
					genv.__oxioForestGate = self._forestGate
					rawset(v, "_attackHandler", function(...)
						if not self.enabled or self.destroyed or self.eggRuntime and self.eggRuntime.instantPhase == "priming" or genv.__oxioPlayerSteal and genv.__oxioPlayerSteal.running then
							return value(...)
						end

						self.stats.blockedHits += 1
						self:_recoverBody(true)

						if genv.__oxioGodMode then
							genv.__oxioGodMode:startDefend()
						end
					end)

					break
				end
			end)

			for _, v in ipairs({
				"ApplyClientRagdoll",
				"Ragdoll",
				"TimedRagdoll",
				"TimedRagdollAsync"
			}) do
				if type(Ragdoll[v]) == "function" then
					self.originalRagdoll[v] = Ragdoll[v]
					Ragdoll[v] = function(...)
						if self.enabled then
							if not self.destroyed then
								self.stats.blockedHits += 1
								self:_recoverBody(true)

								return
							end
						end

						return self.originalRagdoll[v](...)
					end
				end
			end

			if type(Ragdoll.IsRagdolled) == "function" then
				self.originalRagdoll.IsRagdolled = Ragdoll.IsRagdolled
				Ragdoll.IsRagdolled = function(character)
					if self.enabled then
						if character == LocalPlayer2.Character then
							return false
						end
					end

					return self.originalRagdoll.IsRagdolled(character)
				end
			end
		end
		Ryu_AntiGuardBody._restoreLocalState = function(self)
			for k, originalHumanoidState in pairs(self.originalHumanoidStates) do
				if k.Parent then
					pcall(function()
						k:SetStateEnabled(Enum.HumanoidStateType.Physics, originalHumanoidState.Physics)
						k:SetStateEnabled(Enum.HumanoidStateType.FallingDown, originalHumanoidState.FallingDown)
						k:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, originalHumanoidState.Ragdoll)
					end)
				end
			end

			self.originalHumanoidStates = setmetatable({}, {
				__mode = "k"
			})
			pcall(RagdollJoints.Release, LocalPlayer2.Character)
		end
		Ryu_AntiGuardBody._slotKey = function(self, record)
			if type(record) == "table" and type(record.AreaId) == "string" and type(record.NestId) == "string" then
				return string.format("%s:%s", record.AreaId, record.NestId)
			end

			return nil
		end
		Ryu_AntiGuardBody._requestCarry = function(self, uid, slotKey)
			local Ryu_batCarryRequest = {
				Uid = uid
			}

			if slotKey ~= nil then
				Ryu_batCarryRequest.FirstAreaSlotKey = slotKey
			end

			return EggWorld.AskFieldEggCarry:InvokeServer(Ryu_batCarryRequest)
		end
		Ryu_AntiGuardBody._startSticky = function(self, uid, slotKey)
			if type(uid) ~= "string" or uid == "" then
				return
			end

			self._stickyToken += 1

			local _stickyToken = self._stickyToken

			self.stats.recarriedEggs += 1
			task.spawn(function()
				local Ryu_stickyDeadline = os.clock() + 5

				while not self.destroyed and self.enabled and _stickyToken == self._stickyToken and os.clock() < Ryu_stickyDeadline do
					local Ryu_stickyEggRecord = EggState2.ReadFieldEgg(uid)

					if Ryu_stickyEggRecord and Ryu_stickyEggRecord.State == "Carried" and Ryu_stickyEggRecord.CarrierUserId == LocalPlayer2.UserId then
						self.lastHeldEggUid = uid
						self.lastHeldSlotKey = slotKey or self:_slotKey(Ryu_stickyEggRecord)

						return
					end

					if Ryu_stickyEggRecord and (Ryu_stickyEggRecord.State == "Dropped" or Ryu_stickyEggRecord.State == "Slot") then
						if self.eggRuntime then
							if self.eggRuntime:requestCarryRecovery(uid) then
								return
							end
						end

						local _, _, Ryu_stickyRoot = self:_liveBody()

						if Ryu_stickyRoot and Ryu_stickyEggRecord.BottomCFrame and (Ryu_stickyRoot.Position - Ryu_stickyEggRecord.BottomCFrame.Position).Magnitude <= 10 then
							pcall(self._requestCarry, self, uid, slotKey or self:_slotKey(Ryu_stickyEggRecord))
						end
					end

					task.wait(0.05)
				end
			end)
		end
		Ryu_AntiGuardBody._bindSignals = function(self)
			table.insert(self.connections, EggState2.CarryChanged:Connect(function(carryEvent)
				if not self.enabled then
					return
				end

				if carryEvent.IsCarrying and type(carryEvent.Uid) == "string" then
					self._stickyToken += 1
					self.lastHeldEggUid = carryEvent.Uid

					local Ryu_stickySlotKeySource = EggState2.ReadFieldEgg(carryEvent.Uid)

					self.lastHeldSlotKey = self:_slotKey(Ryu_stickySlotKeySource)

					return
				end

				local __oxioPlayerSteal = genv.__oxioPlayerSteal

				if __oxioPlayerSteal and __oxioPlayerSteal.running then
					return
				end

				local Uid = carryEvent.Uid or self.lastHeldEggUid
				local lastHeldSlotKey = self.lastHeldSlotKey

				if self.eggRuntime then
					if self.eggRuntime:isSkippedEgg(Uid) then
						return
					end
				end

				if Uid then
					self.stats.blockedDrops += 1
					self:_startSticky(Uid, lastHeldSlotKey)

					if genv.__oxioGodMode then
						genv.__oxioGodMode:startDefend(Uid)
					end
				end
			end))
			table.insert(self.connections, LocalPlayer2.CharacterAdded:Connect(function(character)
				self:_watchCharacter(character)
				task.defer(function()
					self:_recoverBody(true)
				end)
			end))

			if LocalPlayer2.Character then
				self:_watchCharacter(LocalPlayer2.Character)
			end

			table.insert(self.connections, RunService2.Stepped:Connect(function()
				self:_recoverBody()
			end))
		end
		Ryu_AntiGuardBody.setEnabled = function(self, enabled)
			local enabled = enabled == true

			if self.enabled == enabled then
				return
			end

			self.enabled = enabled

			if self.enabled then
				self:_recoverBody()
			else
				self._stickyToken += 1
				self:_restoreLocalState()
			end
		end
		Ryu_AntiGuardBody.install = function(self)
			if self.destroyed then
				return false
			end

			getgenv().__oxioAntiGuard = self
			self:_installRagdollHooks()
			self:_bindSignals()
			self:_recoverBody()

			return true
		end

		local Ryu_disconnectConnection_var1 = "destroy"

		local function Ryu_destroyAntiGuardBody(self)
			if self.destroyed then
				return
			end

			self.enabled = false
			self:_restoreLocalState()
			self.destroyed = true
			self._stickyToken += 1

			for _, connection in ipairs(self.connections) do
				Ryu_disconnectConnection(connection)
			end

			table.clear(self.connections)

			for k, v in pairs(self.originalRagdoll) do
				if type(v) == "function" then
					Ragdoll[k] = v
				end
			end

			if self._forestGate then
				pcall(rawset, self._forestGate.comp, "_attackHandler", self._forestGate.orig)

				if genv.__oxioForestGate == self._forestGate then
					genv.__oxioForestGate = nil
				end

				self._forestGate = nil
			end

			self.eggRuntime = nil

			if getgenv().__oxioAntiGuard == self then
				getgenv().__oxioAntiGuard = nil
			end
		end

		Ryu_AntiGuardBody[Ryu_disconnectConnection_var1] = Ryu_destroyAntiGuardBody
		Ryu_AntiGuardBody.getStats = function(self)
			return self.stats
		end

		return Ryu_AntiGuardBody
	end

	local Ryu_AntiGuardClass = Ryu_AntiGuardFactory()

	local function Ryu_GodModeClass()
		local Players2 = game:GetService("Players")

		game:GetService("RunService")

		local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
		local LocalPlayer2 = Players2.LocalPlayer
		local Ryu_AuraBat = {}

		Ryu_AuraBat.__index = Ryu_AuraBat
		Ryu_AuraBat.new = function(eggRuntime)
