			local __oxioIsBatTool = genv.__oxioIsBatTool

			if __oxioIsBatTool and __oxioIsBatTool(tool) then
				return true
			end

			if not __oxioIsBatTool and (tool:GetAttribute("IsBat") == true or tool:GetAttribute("GearName") == "Bat") then
				return true
			end

			local attribute = tool:GetAttribute("ItemType")

			if attribute == nil or attribute == "Gear" then
				return string.find(string.lower(tool.Name), "slap", 1, true) ~= nil
			end

			return false
