				end
			end)

			return nil, false
		end
		Ryu_AuraBat._equipBat = function(self)
			local Character = LocalPlayer2.Character
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not Humanoid or Humanoid.Health <= 0 then
				return nil
			end

			local Ryu_batTool, Ryu_batEquipped = self:_findBat()

			if not Ryu_batTool then
				return nil
			end

			if Ryu_batEquipped and Ryu_batTool.Parent == Character then
				return Ryu_batTool
