			pcall(Humanoid.EquipTool, Humanoid, Ryu_batTool)

			local Ryu_batEquipDeadline = os.clock() + 0.35

			while true do
				if not (os.clock() < Ryu_batEquipDeadline) then
					return Ryu_batTool.Parent == Character and Ryu_batTool or nil
				end

				if Ryu_batTool.Parent == Character then
