		local function Ryu_resolveThumbnail(assetIdInput)
			local match = tostring(assetIdInput or ""):match("%d+")

			if not match then
				return nil
			end

			local Ryu_cachedThumbnail = Ryu_assetIconCache[match]

			if Ryu_cachedThumbnail ~= nil then
				if Ryu_cachedThumbnail == "" then
					return nil
				end

				return Ryu_cachedThumbnail
			end

			local Ryu_preferredThumbnail

			for _, v in ipairs({
				"512x512",
				"150x150"
			}) do
				local imageUrl

				pcall(function()
					local Ryu_thumbnailUrl = "https://thumbnails.roblox.com/Ryu_resolveThumbnail_var1/assets?assetIds=" .. match .. "&size=" .. v .. "&format=Png&isCircular=false"
					local Body

					if http_request_ then
						local Ryu_thumbnailResponse = http_request_({
							Url = Ryu_thumbnailUrl,
							Method = "GET"
						})

						Body = type(Ryu_thumbnailResponse) == "table" and (Ryu_thumbnailResponse.Body or Ryu_thumbnailResponse.body) or nil
					else
						Body = HttpService:GetAsync(Ryu_thumbnailUrl)
					end

					if type(Body) == "string" and Body ~= "" then
						local data = HttpService:JSONDecode(Body)
						local data2 = data and data.data and data.data[1]

						if data2 and data2.state == "Completed" and type(data2.imageUrl) == "string" and data2.imageUrl ~= "" then
							imageUrl = data2.imageUrl
						end
					end
				end)

				if imageUrl then
					Ryu_preferredThumbnail = Ryu_preferredThumbnail or imageUrl

					if imageUrl:find("/Png/", 1, true) then
						Ryu_preferredThumbnail = imageUrl

						break
					else
					end
				else
				end
			end

			Ryu_assetIconCache[match] = Ryu_preferredThumbnail or ""

			return Ryu_preferredThumbnail
		end
		local function Ryu_getWebhookIcon()
			if Ryu_webhookFactory_var2 == nil then
				Ryu_webhookFactory_var2 = Ryu_resolveThumbnail("96240498384290") or false
			end

			return Ryu_webhookFactory_var2 or nil
		end
		local function Ryu_flushWebhookQueue()
			if Ryu_webhookFactory_var1 then
				return
			end

			Ryu_webhookFactory_var1 = true
			task.spawn(function()
				while #Ryu_webhookQueue > 0 do
					local Ryu_webhookQueueItem = table.remove(Ryu_webhookQueue, 1)

					pcall(function()
						if Ryu_webhookQueueItem.thumbAsset then
							local Ryu_webhookEmbed = Ryu_webhookQueueItem.payload.embeds[1]
							local Ryu_resolvedThumbnail = Ryu_resolveThumbnail(Ryu_webhookQueueItem.thumbAsset)

							if Ryu_resolvedThumbnail then
								Ryu_webhookEmbed.thumbnail = {
									url = Ryu_resolvedThumbnail
								}
							end
						end

						local json = HttpService:JSONEncode(Ryu_webhookQueueItem.payload)

						if http_request_ then
							http_request_({
								Url = Ryu_webhookQueueItem.url,
								Method = "POST",
								Headers = {
									["Content-Type"] = "application/json"
								},
								Body = json
							})
						else
							HttpService:PostAsync(Ryu_webhookQueueItem.url, json, Enum.HttpContentType.ApplicationJson)
						end
					end)
					task.wait(0.6)
				end

				Ryu_webhookFactory_var1 = false
			end)
		end
		local function Ryu_colorToDecimal(color)
			if typeof(color) == "Color3" then
