		Ryu_PlayerSteal._passes = function(self, record)
			if not (type(record) == "table" and record.AssetCategory) then
				return false
			end

			local Ryu_resolvedStealEgg = self.catalog.resolve(record)
			local Ryu_playerRaritySet = {}
			local Ryu_hasRarityFilter2 = false
			local ipairs_ = ipairs
			local StealPlayerRarities = senaV4Config.StealPlayerRarities or {}

			for _, StealPlayerRarity in ipairs_(StealPlayerRarities) do
				if StealPlayerRarity ~= "None" and StealPlayerRarity ~= "" then
					Ryu_playerRaritySet[StealPlayerRarity] = true
					Ryu_hasRarityFilter2 = true
				end
			end

			if not Ryu_hasRarityFilter2 then
				local ipairs_2 = ipairs
				local StealRarities = senaV4Config.StealRarities or {}

				for _, StealRarity in ipairs_2(StealRarities) do
					if StealRarity ~= "None" and StealRarity ~= "" then
						Ryu_playerRaritySet[StealRarity] = true
						Ryu_hasRarityFilter2 = true
					end
				end
			end

			if Ryu_hasRarityFilter2 and not Ryu_playerRaritySet[Ryu_resolvedStealEgg.rarity] then
				return false
			end

			local Ryu_playerMinValue = tonumber(senaV4Config.StealPlayerMinValue) or 0

			if Ryu_playerMinValue > 0 then
				if (genv.__oxioWebhook and genv.__oxioWebhook.rateOf(record) or 0) < Ryu_playerMinValue then
					return false
				end
			end

			return true
		end
		Ryu_PlayerSteal.carriers = function(self)
			local Ryu_carriersMap = {}
			local ok, result = pcall(function()
				return EggState2.ReadFieldEggs()
			end)

			if not ok or not result then
				return Ryu_carriersMap
			end

			local ipairs_ = ipairs
			local Records = result.Records or {}

			for _, Record in ipairs_(Records) do
				if (Record.State == "Carried" or AreaEggs and AreaEggs.States and Record.State == AreaEggs.States.Carried) and not self.blacklist[Record.Uid] then
					local Ryu_v2149_var1

					pcall(function()
						Ryu_v2149_var1 = EggState2.ReadFieldEgg(Record.Uid)
					end)
					Ryu_v2149_var1 = Ryu_v2149_var1 or Record

					local CarrierUserId = Ryu_v2149_var1.CarrierUserId

					if CarrierUserId and CarrierUserId ~= LocalPlayer2.UserId then
						local playerByUserId = Players2:GetPlayerByUserId(CarrierUserId)
						local HumanoidRootPart = playerByUserId and playerByUserId.Character and playerByUserId.Character:FindFirstChild("HumanoidRootPart")

						if playerByUserId and HumanoidRootPart then
							table.insert(Ryu_carriersMap, {
								record = Ryu_v2149_var1,
								player = playerByUserId,
								root = HumanoidRootPart
							})
						end
					end
				end
			end

			return Ryu_carriersMap
		end
