		local function Ryu_v2149_var2(color)
			if typeof(color) == "Color3" then
				return string.format("%02x%02x%02x", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
			end

			return "ffffff"
		end

		Ryu_PlayerSteal.listEntries = function(self)
			local Ryu_playerEntriesMap = {}

			for _, v in ipairs(self:carriers()) do
				Ryu_playerEntriesMap[v.player] = v.record
			end

			local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")
			local Ryu_playerListEntries = {}
			local Ryu_playerDistance

			for _, player in ipairs(Players2:GetPlayers()) do
				if player ~= LocalPlayer2 then
					local Ryu_playerCarriedRecord, Ryu_v2183_var1

					if player.Character then
						local HumanoidRootPart2 = player.Character:FindFirstChild("HumanoidRootPart")

						Ryu_playerCarriedRecord = Ryu_playerEntriesMap[player]

						local ok = not (HumanoidRootPart2 and HumanoidRootPart)

						if not ok then
							Ryu_playerDistance = math.floor((HumanoidRootPart2.Position - HumanoidRootPart.Position).Magnitude + 0.5)
							ok = not Ryu_playerDistance
						end

						if ok then
							Ryu_playerDistance = nil
						end

						Ryu_v2183_var1 = "Offline"

						if Ryu_playerCarriedRecord and Ryu_playerCarriedRecord.AreaId then
							Ryu_v2183_var1 = tostring(Ryu_playerCarriedRecord.AreaId)
						elseif HumanoidRootPart2 then
							Ryu_v2183_var1 = HumanoidRootPart2.Position.X <= 552.2 and "Safe Zone" or "Field"
						end
					else
						Ryu_playerCarriedRecord = Ryu_playerEntriesMap[player]
						Ryu_playerDistance = nil
						Ryu_v2183_var1 = "Offline"

						if Ryu_playerCarriedRecord and Ryu_playerCarriedRecord.AreaId then
							Ryu_v2183_var1 = tostring(Ryu_playerCarriedRecord.AreaId)
						end
					end

					local rarityRank
					local Ryu_playerStatusMain, Ryu_playerStatusSub

					if Ryu_playerCarriedRecord then
						local ok, result = pcall(function()
							return self.catalog.resolve(Ryu_playerCarriedRecord)
