						Ryu_playerStatusMain = string.format("<font color=\"#%s\">%s</font>  <font color=\"#A2A2AE\">[%s]</font>", Ryu_v2149_var2(Ryu_playerResolvedRef.rarityColor), tostring(Ryu_playerResolvedRef.name or "Egg"), tostring(Ryu_playerResolvedRef.rarity or "Common"))
						Ryu_playerStatusSub = string.format("Running in %s%s", Ryu_v2183_var1, Ryu_playerDistance and "  -  " .. Ryu_playerDistance .. " studs" or "")
					else
						Ryu_playerStatusMain = "No Egg Carried"
						Ryu_playerStatusSub = string.format("Idle in %s%s", Ryu_v2183_var1, Ryu_playerDistance and "  -  " .. Ryu_playerDistance .. " studs" or "")
					end

					Ryu_playerListEntries[#Ryu_playerListEntries + 1] = {
						id = tostring(player.UserId),
						name = tostring(player.DisplayName or player.Name),
						sub = string.format("<font color=\"#4ADE80\">@%s</font>  <font color=\"#A2A2AE\">[%s]</font>", tostring(player.Name), Ryu_v2183_var1),
						status = Ryu_playerStatusMain,
						statusSub = Ryu_playerStatusSub,
						button = "Steal",
						buttonColor = Ryu_playerCarriedRecord and "accent" or "dim",
						player = player,
						carrying = Ryu_playerCarriedRecord ~= nil,
