				if entryA.carrying ~= entryB.carrying then
					return entryA.carrying
				end

				if not entryA.carrying or entryA.rank == entryB.rank then
					return entryA.distance < entryB.distance
				end

				return entryA.rank > entryB.rank
			end)

			return Ryu_playerListEntries
		end
		Ryu_PlayerSteal._pick = function(self)
			local StealPlayerTarget = senaV4Config.StealPlayerTarget
			local Ryu_bestPlayerTarget
			local Ryu_bestPlayerRank
			local Ryu_carriersIter, Ryu_carriersIterState, Ryu_carriersIterControl = ipairs(self:carriers())
			local Ryu_carriersIterator = geniter(Ryu_carriersIter, Ryu_carriersIterState, Ryu_carriersIterControl)

			while true do
				local Ryu_carriersFirstPack = table.pack(Ryu_carriersIterator())

				if not Ryu_carriersFirstPack[1] then
					break
				end

				local Ryu_playerCarrier = Ryu_carriersFirstPack[3]
				local Ryu_playerMatchesTarget = StealPlayerTarget == nil or StealPlayerTarget == "" or StealPlayerTarget == "Any Player" or Ryu_playerCarrier.player.Name == StealPlayerTarget

				if not (Ryu_playerCarrier.root.Position.X > 672.2) then
					continue
				end

				local exitTo2

				while true do
					local Ryu_playerNotInBoss = Ryu_playerCarrier.player:GetAttribute("InBossArena") ~= true
					local exitTo

					while true do
						if not Ryu_playerMatchesTarget or not Ryu_playerNotInBoss then
							local Ryu_carriersNextPack = table.pack(Ryu_carriersIterator())

							if not Ryu_carriersNextPack[1] then
								break
							end

							Ryu_playerCarrier = Ryu_carriersNextPack[3]
							Ryu_playerMatchesTarget = StealPlayerTarget == nil or StealPlayerTarget == "" or StealPlayerTarget == "Any Player" or Ryu_playerCarrier.player.Name == StealPlayerTarget
							Ryu_playerNotInBoss = Ryu_playerCarrier.root.Position.X > 672.2

							if not Ryu_playerNotInBoss then
								continue
							end

							exitTo = 2

							break
						end

						exitTo = 1

						break
					end

					if exitTo == 1 then
						exitTo2 = 1

						break
					elseif exitTo == 2 then
						continue
					end

					break
				end

				if exitTo2 == 1 then
					if self:_passes(Ryu_playerCarrier.record) then
						local rarityRank = self.catalog.resolve(Ryu_playerCarrier.record).rarityRank or 0

						if not Ryu_bestPlayerRank or Ryu_bestPlayerRank < rarityRank then
							Ryu_bestPlayerTarget = Ryu_playerCarrier
							Ryu_bestPlayerRank = rarityRank
						end
					end

					continue
				end

				break
			end

			return Ryu_bestPlayerTarget
		end
		Ryu_PlayerSteal.strike = function(self, targetPlayer)
			if not targetPlayer or targetPlayer == LocalPlayer2 then
				return false
			end

			for _, v in ipairs(self:carriers()) do
				if v.player == targetPlayer then
					self.forced = true
					task.spawn(function()
						self:_chase(v)
					end)

					return true
				end
			end

			self:_setStatus(targetPlayer.Name .. " is not carrying an egg")

			return false
		end

		local function Ryu_resetRagdollState()
			local Character = LocalPlayer2.Character

			if not Character then
				return
			end

			local Humanoid = Character:FindFirstChildOfClass("Humanoid")
			local HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")

			for _, descendant in ipairs(Character:GetDescendants()) do
				if not descendant:IsA("Motor6D") then
					if not descendant:IsA("BallSocketConstraint") then
						if not descendant:IsA("HingeConstraint") then
							if not descendant:IsA("Attachment") then
								continue
							end

							if not descendant.Name:find("Ragdoll") and not descendant:GetAttribute("RagdollAttachment") then
								continue
							end

							pcall(function()
								descendant:Destroy()
							end)

							continue
						end
					end

					if descendant.Name:find("Ragdoll") or descendant:GetAttribute("RagdollConstraint") then
						pcall(function()
							descendant:Destroy()
						end)
					end
				elseif not descendant.Enabled then
					descendant.Enabled = true
				end
			end

			if Humanoid then
				Humanoid.PlatformStand = false
				Humanoid.Sit = false
				pcall(function()
