			local Position2, Ryu_forestHitConfirmed, Ryu_forestGuardConnections

			if Ryu_findForestBaitEgg_var5 then
				if not Ryu_findForestBaitEgg_var5:FindFirstChild("Collider") then
				end

				Position2 = Ryu_findForestBaitEgg_var6 and Ryu_findForestBaitEgg_var6.Position or Vector3.new(596.6, 69.4, -317.1)
				HumanoidRootPart.CFrame = cFrameNew(Position2.X, Position2.Y + 0.8, Position2.Z)
