		Ryu_PlayerSteal._swingBatAt = function(self, targetPlayer, batTool)
			if not batTool or batTool.Parent ~= LocalPlayer2.Character then
				return false
			end

			self.swingSeq += 1

			local Ryu_batSwingSignature = string.format("%d:%d:%d", LocalPlayer2.UserId, self.swingSeq, math.floor(workspace:GetServerTimeNow() * 1000))

			local function Ryu_fireBatSwing()
