		Ryu_PlayerSteal._returnSafe = function(self)
			local eggRuntime = self.eggRuntime
			local Character = LocalPlayer2.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

			if not eggRuntime or not HumanoidRootPart or not Humanoid or eggRuntime:_isInSafeArea(HumanoidRootPart) then
				return
			end

			local Ryu_strikeReturnCF = eggRuntime:_resolveSafeCFrame(HumanoidRootPart)

			if not Ryu_strikeReturnCF then
				return
			end

			self:_setStatus("Returning to safe zone")
			Ryu_glideTo(HumanoidRootPart, Humanoid, Ryu_strikeReturnCF, function()
				return Humanoid.Health <= 0 or not HumanoidRootPart.Parent
			end, false, nil, true)
		end
		Ryu_PlayerSteal.intercept = function(self, targetUid)
			if self.running then
				return false
			end

			local HumanoidRootPart = LocalPlayer2.Character and LocalPlayer2.Character:FindFirstChild("HumanoidRootPart")

			if not HumanoidRootPart then
				return false
			end

			for _, v in ipairs(self:carriers()) do
				if v.record.Uid == targetUid then
					if v.root.Position.X <= 552.2 or (v.root.Position - HumanoidRootPart.Position).Magnitude > 80 then
						return false
					end

					self.forced = true
					task.spawn(self._chase, self, v, true)

					return self.running
				end
			end

			return false
		end

		local Ryu_fireBatSwing_var1 = "_chase"

		local function Ryu_chasePlayer(self, carrier, instant)
			if self.running then
				return
			end

			self.running = true
			self.attempts += 1

			local record = carrier.record
			local Uid = record.Uid
			local Ryu_chaseResolvedEgg = self.catalog.resolve(record)
			local player = carrier.player
			local DisplayName = player.DisplayName or player.Name

			if self.godMode then
				self.godMode:stopDefend()
			end

			if not instant then
				-- FIX: hapus _returnSafe() di sini — dulu bikin player jalan balik ke base
				-- sebelum mulai ngejar carrier, sekarang langsung prime tanpa pulang dulu
				self:_setStatus(string.format("Priming at Forest Guard for %s", DisplayName))

				local ok, result, result2 = pcall(self._primeForest, self, Uid)
				local Ryu_chasePlayer_var5

				if ok and not result and result2 then
					pcall(function()
						Ryu_chasePlayer_var5 = EggState2.ReadFieldEgg(result2)
					end)
				end

				if Ryu_chasePlayer_var5 and Ryu_chasePlayer_var5.State == "Carried" and Ryu_chasePlayer_var5.CarrierUserId == LocalPlayer2.UserId then
					-- FIX: hanya return safe kalau memang perlu (egg sudah di tangan kita bukan target)
					-- tidak langsung pulang — biarkan loop utama yang handle
					self:_log(DisplayName, Ryu_chaseResolvedEgg.name, "Forest priming failed")
					self:_setStatus(self.enabled and "looking for a carrier" or "idle")
					self.running = false
					self.forced = false

					return
				end
			end

			local godMode = self.godMode and self.godMode:_equipBat()
			local Ryu_chaseDeadline = os.clock() + (instant and 8 or 16)
			local Ryu_outcome = "could not catch them"
			local Ryu_chasePlayer_var1 = 0
			local Ryu_chasePlayer_var2 = 0
			local now
			local Ryu_chasePrevCooldown
			local now2
			local Ryu_positionHistory = {}
			local vector32 = Vector3.zero
			local attribute = player:GetAttribute("RagdollEndTime") or false
			local Ryu_chasePlayer_var3 = 0.1

			pcall(function()
				Ryu_chasePlayer_var3 = math.clamp(LocalPlayer2:GetNetworkPing() or 0.1, 0.03, 0.6)
			end)

			local Ryu_chaseLeadTime = math.clamp(0.14 + Ryu_chasePlayer_var3, 0.14, 0.35)
			local hitIdx = self.hitIdx or self.leadIdx

			self.leadIdx = hitIdx or 1
			self.missStreak = 0

			local connection

			pcall(function()
				connection = RunService.Stepped:Connect(function()
					local Character = LocalPlayer2.Character

					if Character then
						for _, descendant in ipairs(Character:GetDescendants()) do
							if descendant:IsA("BasePart") then
								descendant.CanCollide = false
							end
						end
					end
				end)
			end)
			self:_setStatus(string.format("Chasing %s", DisplayName))

			while os.clock() < Ryu_chaseDeadline do
				local result = RunService.PreSimulation:Wait()

				if not self.enabled and not self.forced then
					Ryu_outcome = "stopped"

					break
				end

				local Ryu_chasePlayer_var6

				pcall(function()
					Ryu_chasePlayer_var6 = EggState2.ReadFieldEgg(Uid)
				end)

				local State = Ryu_chasePlayer_var6 and Ryu_chasePlayer_var6.State

				if not Ryu_chasePlayer_var6 or State == "Slot" or State == "GuardCarried" then
					Ryu_outcome = "egg reset"

					break
				end

				if State == "Claimed" then
					Ryu_outcome = "they banked it"

					break
				end

				if State == "Carried" and Ryu_chasePlayer_var6.CarrierUserId == LocalPlayer2.UserId then
					Ryu_outcome = "taken"

					break
				end

				if State == "Dropped" then
					if now and os.clock() - now <= 1 then
						self.hitIdx = self.leadIdx
					end

					self:_setStatus(string.format("Grabbing dropped egg from %s", DisplayName))
					Ryu_outcome = self:_grab(Ryu_chasePlayer_var6) and "taken" or "someone else grabbed it"

					break
				end

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

				if not HumanoidRootPart or not Humanoid or Humanoid.Health <= 0 then
					Ryu_outcome = "character died"

					break
				end

				local HumanoidRootPart2, now3, Ryu_chaseTrackIndex, AssemblyLinearVelocity, vector33, Magnitude, LookVector, vector34, Unit, Unit2, clamp, Ryu_chaseLeadMultiplier, Ryu_chaseTargetPos, vector35, cFrame, Ryu_chaseDelta, Magnitude2, Ryu_chaseSpeed, Ryu_chaseStepDist, Ryu_chaseVelocity, Ryu_chaseNearThreshold, attribute2, Ryu_chaseCooldownEnd

				if Ryu_chasePlayer_var6.CarrierUserId == player.UserId then
					HumanoidRootPart2 = player.Character and player.Character:FindFirstChild("HumanoidRootPart")

					if not HumanoidRootPart2 then
						Ryu_outcome = "lost sight of them"

						break
					end

					if HumanoidRootPart2.Position.X <= 552.2 then
						Ryu_outcome = "banked"

						break
					end

					now3 = os.clock()
					Ryu_chaseTrackIndex = #Ryu_positionHistory + 1
					Ryu_positionHistory[Ryu_chaseTrackIndex] = {
						t = now3,
						p = HumanoidRootPart2.Position
					}

					while #Ryu_positionHistory > 2 and now3 - Ryu_positionHistory[1].t > 0.4 do
						table.remove(Ryu_positionHistory, 1)
					end

					AssemblyLinearVelocity = HumanoidRootPart2.AssemblyLinearVelocity

					if Vector3.new(AssemblyLinearVelocity.X, 0, AssemblyLinearVelocity.Z).Magnitude > 8 then
						vector32 = AssemblyLinearVelocity
					elseif #Ryu_positionHistory >= 2 and now3 - Ryu_positionHistory[1].t > 0.15 then
						vector32 = (HumanoidRootPart2.Position - Ryu_positionHistory[1].p) / (now3 - Ryu_positionHistory[1].t)
					end

					vector33 = Vector3.new(vector32.X, 0, vector32.Z)
					Magnitude = vector33.Magnitude

					if Magnitude > 6 then
						Unit2 = vector33.Unit
					else
						LookVector = HumanoidRootPart2.CFrame.LookVector
						vector34 = Vector3.new(LookVector.X, 0, LookVector.Z)
						Unit = vector34.Magnitude > 0.05 and vector34.Unit or Vector3.new(-1, 0, 0)
						Unit2 = Unit
					end

					clamp = math.clamp
					Ryu_chaseLeadMultiplier = Ryu_chaseLeads[self.leadIdx] or 1
					Ryu_chaseTargetPos = HumanoidRootPart2.Position + Unit2 * clamp(Ryu_chaseLeadMultiplier * Magnitude * Ryu_chaseLeadTime, 3, 110)

					if Ryu_chaseTargetPos.X < 557.2 then
						Ryu_chaseTargetPos = Vector3.new(557.2, Ryu_chaseTargetPos.Y, Ryu_chaseTargetPos.Z)
					end

					vector35 = Vector3.new(HumanoidRootPart2.Position.X, Ryu_chaseTargetPos.Y, HumanoidRootPart2.Position.Z)

					if (vector35 - Ryu_chaseTargetPos).Magnitude < 0.5 then
						vector35 = Ryu_chaseTargetPos - Unit2
					end

					cFrame = lookAt(Ryu_chaseTargetPos, vector35)
					Ryu_chaseDelta = Ryu_chaseTargetPos - HumanoidRootPart.Position
					Magnitude2 = Ryu_chaseDelta.Magnitude
					Ryu_chaseSpeed = Ryu_getTweenSpeed()
					Ryu_chaseStepDist = Ryu_chaseSpeed * math.min(result, 0.05)
					Ryu_setTargetWalkSpeed(Character, Ryu_chaseSpeed * Ryu_CONFIG.HEADROOM)

					if Ryu_chaseStepDist < Magnitude2 then
						HumanoidRootPart.CFrame = cFrameNew(HumanoidRootPart.Position + Ryu_chaseDelta.Unit * Ryu_chaseStepDist) * cFrame.Rotation
						HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
						Ryu_chaseVelocity = Ryu_chaseDelta.Unit * Ryu_chaseSpeed
					else
						HumanoidRootPart.CFrame = cFrame
						HumanoidRootPart.AssemblyLinearVelocity = HumanoidRootPart2.AssemblyLinearVelocity
						Ryu_chaseVelocity = HumanoidRootPart2.AssemblyLinearVelocity
