		Ryu_PlayerSteal._grab = function(self, record)
			local eggRuntime = self.eggRuntime
			local Uid = record.Uid
			local Ryu_grabDeadline = os.clock() + 3
			local Ryu_chasePlayer_var4 = 0

			while true do
				if not (os.clock() < Ryu_grabDeadline) then
					return false
				end

				local Ryu_chasePlayer_var7

				pcall(function()
					Ryu_chasePlayer_var7 = EggState2.ReadFieldEgg(Uid)
				end)

				local State = Ryu_chasePlayer_var7 and Ryu_chasePlayer_var7.State

				if State == "Carried" then
					if Ryu_chasePlayer_var7.CarrierUserId ~= LocalPlayer2.UserId then
						return false
					end

					if genv.__oxioWebhook then
						local ok, result = pcall(self.catalog.resolve, Ryu_chasePlayer_var7)

						pcall(genv.__oxioWebhook.stolen, Ryu_chasePlayer_var7, ok and result or nil, "player carry")
					end

					return true
				end

				if State ~= "Dropped" then
					return false
				end

				local Character = LocalPlayer2.Character
				local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

				if not HumanoidRootPart or not Humanoid or Humanoid.Health <= 0 then
					break
				end

				local cFrame = eggRuntime and eggRuntime:_resolveEggDestination(Ryu_chasePlayer_var7, HumanoidRootPart, Humanoid)

				if not cFrame then
					local Position = Ryu_chasePlayer_var7.BottomCFrame and Ryu_chasePlayer_var7.BottomCFrame.Position or Ryu_chasePlayer_var7.BoundsCFrame and Ryu_chasePlayer_var7.BoundsCFrame.Position

					cFrame = Position and cFrameNew(Position.X, Position.Y + 2.5, Position.Z)
				end

				if cFrame then
					HumanoidRootPart.CFrame = cFrame
					HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
					HumanoidRootPart.AssemblyAngularVelocity = Vector3.zero
				end

				if Ryu_chasePlayer_var4 <= os.clock() then
					Ryu_chasePlayer_var4 = os.clock() + 0.1
					task.spawn(function()
						pcall(function()
							EggState2.CarryFieldEgg(Uid)
						end)
					end)
					task.spawn(function()
						pcall(function()
							require(ReplicatedStorage2.Shared.Remotes).EggWorld.AskFieldEggCarry:InvokeServer({
								Uid = Uid
							})
						end)
					end)
				end

				RunService.Heartbeat:Wait()
			end

			return false
		end
		Ryu_PlayerSteal._start = function(self)
			if self.loop then
				return
			end

			self.loop = task.spawn(function()
				while true do
					task.wait(0.4)

					if genv.ChloeX_Running == nil and genv.__oxioPlayerSteal ~= self then
						break
