					local eggRuntime = self.eggRuntime
					local __oxioScrambleRuntime = genv.__oxioScrambleRuntime

					if self.enabled and not self.running and (not eggRuntime or not eggRuntime.running and (not eggRuntime.carry or not eggRuntime.carry.active)) and (__oxioScrambleRuntime == nil or __oxioScrambleRuntime.active ~= true) then
