		settle = settle or 0.25
		local deadline = os.clock() + 3
		local stableSince = nil
		while os.clock() < deadline do
			if cancelCheck and cancelCheck() then return false end
			if isDead(lifeChar) then return false end
			local rp = root()
			if not rp then return false end
			local dist = (rp.Position - targetCF.Position).Magnitude
			if dist > 15 then
				pcall(function()
					rp.CFrame = targetCF
					rp.AssemblyLinearVelocity = Vector3.zero
					rp.AssemblyAngularVelocity = Vector3.zero
				end)
				stableSince = nil
			else
				stableSince = stableSince or os.clock()
				if os.clock() - stableSince > settle then
					return true
				end
			end
			RunService.Heartbeat:Wait()
		end
		return false
	end

