				if cancelCheck and cancelCheck() then return false end
				if isDead(lifeChar) then return false end
				rp = root()
				if not rp then return false end
				local d = Vector3.new(walkoutX - rp.Position.X, 0, z - rp.Position.Z)
				if d.Magnitude < 8 then break end
				pcall(function()
					rp.AssemblyLinearVelocity = Vector3.new(0, rp.AssemblyLinearVelocity.Y, 0)
						+ d.Unit * math.min(walkSpeed() * 0.95, d.Magnitude / 0.05)
				end)
				RunService.Heartbeat:Wait()
			end
		end
		rp = root()
		if not rp then return false end
		local curX = rp.Position.X
		local curZ = rp.Position.Z
		while math.abs(targetPos.X - curX) > maxStep do
			curX = curX + math.sign(targetPos.X - curX) * maxStep
			curZ = curZ + (z - curZ) * 0.3
			local yBase
			if curX > 4250 and curX < 4960 then yBase = 118
			elseif curX > 3519 and curX <= 4250 then yBase = 131
			else yBase = 71 end
			local cf = CFrame.new(curX, yBase + 40, curZ)
			local stepEnd = os.clock() + stepGap
			while os.clock() < stepEnd do
				if cancelCheck and cancelCheck() then return false end
				if isDead(lifeChar) then return false end
				local r2 = root()
				if not r2 then return false end
				pcall(function()
					r2.CFrame = cf
					r2.AssemblyLinearVelocity = Vector3.zero
					r2.AssemblyAngularVelocity = Vector3.zero
				end)
				RunService.Heartbeat:Wait()
			end
		end
		return true
	end

	local function v3CamLock()
		if not senaV4Config.InstantHideCamera then return nil end
		local cam = workspace.CurrentCamera
		local char = LocalPlayer.Character
		local rp = root()
		if not cam or not char or not rp then return nil end
		local lock = {
			View = cam.CFrame,
			Name = string.format("%08x", math.random(0, 2147483647)),
			Until = os.clock() + (senaV4Config.InstantCamMax or 30),
			Character = char,
			Subject = char:FindFirstChildOfClass("Humanoid"),
		}
		pcall(function()
			local was = char.Archivable
			char.Archivable = true
			local clone = char:Clone()
			char.Archivable = was
			if not clone then return end
			local cRoot = clone:FindFirstChild("HumanoidRootPart")
			for _, d in ipairs(clone:GetDescendants()) do
				if d:IsA("LuaSourceContainer") or d:IsA("ForceField") or d:IsA("Tool") then
					d:Destroy()
				elseif d:IsA("BasePart") then
					d.Anchored = (d == cRoot)
					d.CanCollide = false
					d.CanQuery = false
					d.CanTouch = false
				end
			end
			local ch = clone:FindFirstChildOfClass("Humanoid")
			if ch then
				ch.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
				ch.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			end
			clone.Name = string.format("%08x", math.random(0, 2147483647))
			clone:PivotTo(rp.CFrame)
			clone.Parent = workspace
			lock.Clone = clone
		end)
		pcall(function()
			RunService:BindToRenderStep(lock.Name, Enum.RenderPriority.Last.Value + 50, function()
				if os.clock() > lock.Until then
					IS.releaseCam(lock)
					return
				end
				local c = workspace.CurrentCamera
				if c then
					c.CameraType = Enum.CameraType.Scriptable
					c.CFrame = lock.View
				end
			end)
		end)
		pcall(function()
			cam.CameraType = Enum.CameraType.Scriptable
			cam.CFrame = lock.View
		end)
		return lock
	end

	IS.releaseCam = function(lock)
		if not lock or lock.Released then return end
		lock.Released = true
		pcall(function() RunService:UnbindFromRenderStep(lock.Name) end)
		if lock.Clone then pcall(function() lock.Clone:Destroy() end) end
		pcall(function()
			local cam = workspace.CurrentCamera
			local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
			if cam then
				cam.CameraType = Enum.CameraType.Custom
				if h then cam.CameraSubject = h end
			end
		end)
		if IS.cam == lock then IS.cam = nil end
	end

	local function v2Prep(cancelCheck, lifeChar)
		local tm = genv.__oxioTreadmillManager
		for i = 1, 3 do
			if cancelCheck and cancelCheck() then return false end
			if isDead(lifeChar) then return false end
			local rp = root()
			if not rp then return false end
			if not rp.Anchored then return true end
			setStatus("Instant Steal V2: getting off the treadmill first")
			if tm and type(tm._requestUnequip) == "function" then
				pcall(tm._requestUnequip, tm)
			end
			pcall(function()
				local doff = Remotes.Treadmill and Remotes.Treadmill.AskDoff
				if doff and doff.InvokeServer then
					doff:InvokeServer()
				end
			end)
			local waitFor = 1.5 + math.clamp(ping(), 0, 1)
			local untilAt = os.clock() + waitFor
			while rp.Parent and rp.Anchored and os.clock() < untilAt do
				if cancelCheck and cancelCheck() then return false end
				RunService.Heartbeat:Wait()
			end
		end
		local rp = root()
		return rp and not rp.Anchored
	end

	local function v3Grab(uid, cancelCheck, lifeChar)
		local deadline = os.clock() + (senaV4Config.InstantGrabTime or 8)
		local tries = 0
		while os.clock() < deadline and tries < 12 do
			if cancelCheck and cancelCheck() then return false end
			if isDead(lifeChar) then return false end
			local egg = genv.__oxioEggRuntime
			if egg and egg.carry and egg.carry.active and egg.carry.uid == uid then
				return true
			end
			tries += 1
			pcall(function()
				if type(EggState.CarryFieldEgg) == "function" then
					EggState.CarryFieldEgg(uid)
				end
			end)
			local stepEnd = os.clock() + 0.4
			while os.clock() < stepEnd do
				local egg2 = genv.__oxioEggRuntime
				if egg2 and egg2.carry and egg2.carry.active and egg2.carry.uid == uid then
					return true
				end
				RunService.Heartbeat:Wait()
			end
		end
		local eggF = genv.__oxioEggRuntime
		return eggF and eggF.carry and eggF.carry.active and eggF.carry.uid == uid
	end

	local function dropEgg()
		pcall(function()
			if type(EggState.DropFieldEgg) == "function" then
				EggState.DropFieldEgg("PlayerRequest")
			end
		end)
		local deadline = os.clock() + 1
		while os.clock() < deadline do
			local egg = genv.__oxioEggRuntime
			if not (egg and egg.carry and egg.carry.active) then return true end
			RunService.Heartbeat:Wait()
		end
		return false
	end

	local function v3PortalTo(record, cancelCheck, lifeChar)
		local eggPos = record.CFrame.Position
		local portal = findFusePortal()
		if not portal then
			setStatus("Instant Steal V3: Fuse portal not found")
			return nil
		end
		if inFuse() then
			setStatus("Instant Steal V3: leaving the Fuse Biome first")
			local deadline = os.clock() + 4
			while os.clock() < deadline and inFuse() do
				local rp = root()
				if rp then touch(rp, portal) end
				task.wait(0.1)
			end
		end
		pcall(function()
			local h = hum()
			if h then h:UnequipTools() end
		end)
		if not v2Prep(cancelCheck, lifeChar) then
			return false
		end
		local rp = root()
		if not rp then return false end
		local home = stealHome()
		if insideBase(rp.Position) and (rp.Position - home).Magnitude > senaV4Config.InstantDirectRadius then
			local safeTarget = home + Vector3.new(0, 3, 0)
			local hopEnd = os.clock() + 15
			local hopSpeed = senaV4Config.InstantSafeSpeed
			while os.clock() < hopEnd do
				if cancelCheck and cancelCheck() then return false end
				if isDead(lifeChar) then return false end
				rp = root()
				if not rp then return false end
				local delta = safeTarget - rp.Position
				if delta.Magnitude <= math.max(senaV4Config.InstantSafeHop, 4) then
					pcall(function()
						rp.CFrame = CFrame.new(safeTarget) * rp.CFrame.Rotation
						rp.AssemblyLinearVelocity = Vector3.zero
					end)
					break
				end
				setStatus(string.format("Instant Steal V2: flying to the safe zone, %d studs",
					math.floor(delta.Magnitude + 0.5)))
				local step = math.min(hopSpeed * 0.016, delta.Magnitude)
				pcall(function()
					rp.CFrame = CFrame.new(rp.Position + delta.Unit * step) * rp.CFrame.Rotation
					rp.AssemblyLinearVelocity = Vector3.zero
					rp.AssemblyAngularVelocity = Vector3.zero
				end)
				RunService.Heartbeat:Wait()
			end
			if isDead(lifeChar) then return false end
			local waitTime = math.clamp(
				senaV4Config.InstantSafeWait + ping(),
				senaV4Config.InstantSafeWait,
				senaV4Config.InstantSafeWaitMax
			)
			local untilAt = os.clock() + waitTime
			setStatus("Instant Steal V2: in the safe zone, letting the server catch up")
			while os.clock() < untilAt do
				if cancelCheck and cancelCheck() then return false end
				local r2 = root()
				if r2 then
					pcall(function()
						r2.CFrame = CFrame.new(safeTarget) * r2.CFrame.Rotation
						r2.AssemblyLinearVelocity = Vector3.zero
					end)
				end
				RunService.Heartbeat:Wait()
			end
		end
		local h = hum()
		for attempt = 1, 2 do
			if cancelCheck and cancelCheck() then return false end
			if isDead(lifeChar) then return false end
			if not v2Prep(cancelCheck, lifeChar) then return false end
			setStatus(attempt == 1
				and "Instant Steal V2: jumping to the egg"
				or "Instant Steal V2: the Fuse put you back, jumping to the egg again")
			pcall(function() if h then h.PlatformStand = true end end)
			local holdTarget = CFrame.new(eggPos + Vector3.new(0, 3, 0))
			if senaV4Config.InstantApproach == "Step" then
				if not v2StepTo(eggPos + Vector3.new(0, 3, 0), cancelCheck, lifeChar) then
					pcall(function() if h then h.PlatformStand = false end end)
					return false
				end
			end
			if not v3Hold(holdTarget, cancelCheck, lifeChar, 0.15) then
				pcall(function() if h then h.PlatformStand = false end end)
				return false
			end
			local waitEnd = os.clock() + (senaV4Config.InstantV3EggWait or 0.05)
			while os.clock() < waitEnd do
				if cancelCheck and cancelCheck() then
					pcall(function() if h then h.PlatformStand = false end end)
					return false
				end
				local rp2 = root()
				if rp2 and (rp2.Position - (eggPos + Vector3.new(0, 3, 0))).Magnitude > 15 then
					pcall(function() rp2.CFrame = CFrame.new(eggPos + Vector3.new(0, 3, 0)) end)
				end
				RunService.Heartbeat:Wait()
			end
			local camLock = v3CamLock()
			IS.cam = camLock
			local enteredFuse = false
			local transConn = nil
			pcall(function()
				local rem = Remotes.FuseBiome and Remotes.FuseBiome.PortalTransition
				if rem and rem.OnClientEvent then
					transConn = rem.OnClientEvent:Connect(function() enteredFuse = true end)
				end
			end)
			setStatus("Instant Steal V2: touching the Fuse portal from the egg")
			local touchEnd = os.clock() + 4
			local nextTouch = 0
			local enteredByY = false
			while os.clock() < touchEnd do
				if cancelCheck and cancelCheck() then break end
				local rp2 = root()
				if rp2 and rp2.Position.Y > 10000 then
					enteredByY = true
					break
				end
				if rp2 then
					local dist = (rp2.Position - (eggPos + Vector3.new(0, 3, 0))).Magnitude
					if dist > 15 then
						pcall(function()
							rp2.CFrame = CFrame.new(eggPos + Vector3.new(0, 3, 0))
							rp2.AssemblyLinearVelocity = Vector3.zero
						end)
					end
					if os.clock() >= nextTouch then
						nextTouch = os.clock() + 0.1
						touch(rp2, portal)
					end
				end
				RunService.Heartbeat:Wait()
			end
			if transConn then pcall(function() transConn:Disconnect() end) end
			pcall(function() if h then h.PlatformStand = false end end)
			if not enteredFuse and not enteredByY then
				IS.releaseCam(camLock)
				setStatus("Instant Steal V2: could not enter the Fuse")
				return nil
			end
			setStatus("Instant Steal V2: in the Fuse Biome, coming back at the egg")
			local inFuseEnd = os.clock() + 8
			while os.clock() < inFuseEnd and inFuse() do
				local rp2 = root()
				if rp2 then touch(rp2, portal) end
				task.wait(0.1)
			end
			IS.releaseCam(camLock)
			rp = root()
			if not rp then return false end
			local dist = (rp.Position - eggPos).Magnitude
			if dist <= 60 then
				break
			end
			if dist <= 600 and not isDead(lifeChar) then
				setStatus(string.format("Instant Steal V2: exit landed %d studs away, walking to egg", math.floor(dist + 0.5)))
				local walkEnd = os.clock() + dist / math.max(walkSpeed() * 0.95, 16) + 2
				while os.clock() < walkEnd do
					if cancelCheck and cancelCheck() then return false end
					if isDead(lifeChar) then return false end
					local r2 = root()
					if not r2 then return false end
					local d = Vector3.new(eggPos.X - r2.Position.X, 0, eggPos.Z - r2.Position.Z)
					if d.Magnitude < 6 then
						pcall(function()
							r2.AssemblyLinearVelocity = Vector3.new(0, r2.AssemblyLinearVelocity.Y, 0)
						end)
						break
					end
					pcall(function()
						r2.AssemblyLinearVelocity = d.Unit * math.max(walkSpeed() * 0.95, 16)
							+ Vector3.new(0, r2.AssemblyLinearVelocity.Y, 0)
					end)
					RunService.Heartbeat:Wait()
				end
				rp = root()
				if rp and (rp.Position - eggPos).Magnitude <= 20 then
					break
				end
			end
		end
		rp = root()
		if not rp or (rp.Position - eggPos).Magnitude > 60 then
			setStatus("Instant Steal V2: the Fuse exit did not land at the egg")
			return false
		end
		task.wait(0.3)
		local fakeCount = senaV4Config.InstantV3FakeGrabs or 2
		for i = 1, fakeCount do
			if cancelCheck and cancelCheck() then return false end
			if isDead(lifeChar) then return false end
			setStatus(string.format("Instant Steal V2: grab and drop %d/%d", i, fakeCount))
			if not v3Grab(record.Uid, cancelCheck, lifeChar) then
				break
			end
			dropEgg()
			task.wait(0.1)
		end
		if cancelCheck and cancelCheck() then return false end
		setStatus("Instant Steal V2: taking the egg for real")
		return v3Grab(record.Uid, cancelCheck, lifeChar)
	end

	local function v3Home(cancelCheck, lifeChar)
		local egg = genv.__oxioEggRuntime
		if not egg or not egg.carry or not egg.carry.active then return false end
		local uid = egg.carry.uid
		if type(uid) ~= "string" then return false end
		local homePos = Vector3.new(
			senaV4Config.InstantHomeX,
			senaV4Config.InstantHomeY,
			senaV4Config.InstantHomeZ
		)
		local homeRot = CFrame.Angles(0, math.pi / 2, 0)
		setStatus("Instant Steal V2: flying the egg home")
		while true do
			if cancelCheck and cancelCheck() then return false end
			local eggR = genv.__oxioEggRuntime
			if not eggR or not eggR.carry or not eggR.carry.active then break end
			if isDead(lifeChar) then return false end
			local rp = root()
			if not rp then return false end
			local px = rp.Position.X
			local dx = homePos.X - px
			if math.abs(dx) < 36 then break end
			local nextX = px + math.sign(dx) * 34
			local nextZ = rp.Position.Z + (homePos.Z - rp.Position.Z) * 0.03
			local yBase
			if nextX > 4250 and nextX < 4960 then yBase = 118
			elseif nextX > 3519 and nextX <= 4250 then yBase = 131
			else yBase = 71 end
			pcall(function()
				rp.CFrame = CFrame.new(nextX, yBase, nextZ) * homeRot
				rp.AssemblyLinearVelocity = Vector3.zero
				rp.AssemblyAngularVelocity = Vector3.zero
			end)
			RunService.Heartbeat:Wait()
		end
		if cancelCheck and cancelCheck() then return false end
		local eggR2 = genv.__oxioEggRuntime
		if not eggR2 or not eggR2.carry or not eggR2.carry.active then
			setStatus("Instant Steal V2: the egg fell on the way home")
			return false
		end
		v3Hold(CFrame.new(homePos) * homeRot, cancelCheck, lifeChar, 0.25)
		task.wait(0.5)
				setStatus("Instant Steal V2: dropping the egg in the Forest")
		dropEgg()
		task.wait(0.9)

		setStatus("Instant Steal V2: picking the egg back up")
		if not v3Grab(uid, cancelCheck, lifeChar) then
			setStatus("Instant Steal V2: could not pick the egg back up")
			return false
		end

		setStatus("Instant Steal V2: crossing the line")
		local rpCross = root()
		if rpCross then
			pcall(function()
				rpCross.CFrame = CFrame.new(
					senaV4Config.InstantLineX,
					senaV4Config.InstantLineY,
					senaV4Config.InstantLineZ
				) * homeRot
				rpCross.AssemblyLinearVelocity = Vector3.zero
			end)
		end

		local crossEnd = os.clock() + 4
		while os.clock() < crossEnd do
			local eggR3 = genv.__oxioEggRuntime
			if not eggR3 or not eggR3.carry or not eggR3.carry.active then
				return true
			end
			RunService.Heartbeat:Wait()
		end
		return false
	end

	local function v2Fallback(record, cancelCheck, lifeChar)
		local eggPos = record.CFrame.Position
		if not v2Prep(cancelCheck, lifeChar) then return false end
		local egg = genv.__oxioEggRuntime
		local rp = root()
		if rp and insideBase(rp.Position) and egg and type(egg._resolveSafeCFrame) == "function" then
			local safeCF = egg:_resolveSafeCFrame(rp)
			if safeCF then
				setStatus("Instant Steal V2: flying to the safe zone")
				local deadline = os.clock() + 20
				while os.clock() < deadline do
					if cancelCheck and cancelCheck() then return false end
					local r2 = root()
					if not r2 then return false end
					local d = (safeCF.Position + Vector3.new(0, 3, 0)) - r2.Position
					if d.Magnitude < 4 then break end
					local step = math.min(senaV4Config.InstantSafeSpeed * 0.016, d.Magnitude)
					pcall(function()
						r2.CFrame = CFrame.new(r2.Position + d.Unit * step) * r2.CFrame.Rotation
						r2.AssemblyLinearVelocity = Vector3.zero
					end)
					RunService.Heartbeat:Wait()
				end
				local waitEnd = os.clock() + math.clamp(
					senaV4Config.InstantSafeWait + ping(),
					senaV4Config.InstantSafeWait,
					senaV4Config.InstantSafeWaitMax
				)
				while os.clock() < waitEnd do
					RunService.Heartbeat:Wait()
				end
			end
		end
		setStatus("Instant Steal V2: flying to the egg")
		local deadline = os.clock() + 20
		while os.clock() < deadline do
			if cancelCheck and cancelCheck() then return false end
			local r2 = root()
			if not r2 then return false end
			local d = (eggPos + Vector3.new(0, 3, 0)) - r2.Position
			if d.Magnitude < 4 then
				pcall(function()
					r2.CFrame = CFrame.new(eggPos + Vector3.new(0, 3, 0)) * r2.CFrame.Rotation
					r2.AssemblyLinearVelocity = Vector3.zero
				end)
				break
			end
			local step = math.min(senaV4Config.InstantSafeSpeed * 0.016, d.Magnitude)
			pcall(function()
				r2.CFrame = CFrame.new(r2.Position + d.Unit * step) * r2.CFrame.Rotation
				r2.AssemblyLinearVelocity = Vector3.zero
			end)
			RunService.Heartbeat:Wait()
		end
		task.wait(0.15)
		local fakeCount = senaV4Config.InstantV3FakeGrabs or 2
		for i = 1, fakeCount do
			if cancelCheck and cancelCheck() then return false end
			if not v3Grab(record.Uid, cancelCheck, lifeChar) then break end
			dropEgg()
			task.wait(0.1)
		end
		return v3Grab(record.Uid, cancelCheck, lifeChar)
	end

	IS.trySteal = function(record, cancelCheck)
		if IS.busy then return false end
		IS.busy = true
		local lifeChar = LocalPlayer.Character
		local ok, result = pcall(function()
			local zone = record.Zone or record.AreaId
			local useV3 = senaV4Config.InstantV3
				and zone
				and senaV4Config.InstantV3Zones[zone] == true
			if useV3 then
				local v3 = v3PortalTo(record, cancelCheck, lifeChar)
				if v3 == nil then
					return v2Fallback(record, cancelCheck, lifeChar)
				end
				if v3 == true then
					return v3Home(cancelCheck, lifeChar)
				end
				return false
			else
				local v2 = v2Fallback(record, cancelCheck, lifeChar)
				if v2 == true then
					return v3Home(cancelCheck, lifeChar)
				end
				return v2
			end
		end)
		IS.busy = false
		if IS.cam then IS.releaseCam(IS.cam) end
		if not ok then
			setStatus("Instant Steal error: " .. tostring(result))
			return false
		end
		if result == true then
			setStatus("Instant Steal V2: delivered")
		elseif result == false then
			setStatus("Instant Steal V2: failed")
		end
		return result == true
	end

	task.spawn(function()
		local hooked = false
		while Ryu_isCurrentSession() do
			local egg = genv.__oxioEggRuntime
			if egg and not hooked and type(egg._requestCarry) == "function" then
				hooked = true
				local orig = egg._requestCarry
				egg._requestCarry = function(self, record, skipReapproach)
					if senaV4Config.InstantStealV2
						and senaV4Config.StealMode == "Instant"
						and record and record.CFrame
					then
						local cancelled = false
						local function cancelCheck()
							if cancelled then return true end
							if self.destroyed or not self.enabled then return true end
							return false
						end
						task.spawn(function()
							local ok = IS.trySteal(record, cancelCheck)
							if ok and not self.destroyed and self.enabled then
	self.carry.active = true
	self.carry.uid = record.Uid
	-- deliver sendiri lewat v3Home (chili style)
	local homeOk = false
	pcall(function()
		homeOk = v3Home(cancelCheck, lifeChar)
	end)
	if not homeOk and type(self._returnToSafe) == "function" then
		pcall(self._returnToSafe, self)
	end
							elseif not ok and type(orig) == "function" then
								orig(self, record, skipReapproach)
							end
						end)
						return
					end
					return orig(self, record, skipReapproach)
				end
			end
			task.wait(1)
		end
	end)

	local prev = genv.__oxioEggRuntimeCleanup
	genv.__oxioEggRuntimeCleanup = function()
		if IS.cam then IS.releaseCam(IS.cam) end
		if type(prev) == "function" then pcall(prev) end
	end
end

