do
	local function Ryu_getGenv2()
		return getgenv and getgenv() or _G
	end
	local function Ryu_getConnectionAPI()
		if type(getconnections) == "function" then
			return getconnections
		end

		if type(get_signal_cons) == "function" then
			return get_signal_cons
		end

		return nil
	end
	local function Ryu_disableIdleConnections(state)
		local LocalPlayer2 = Players.LocalPlayer

		if not LocalPlayer2 then
			state.antiAfkStatus = "LocalPlayer unavailable"

			return false
		end

		local Ryu_connectionAPIName = Ryu_getConnectionAPI()

		if not Ryu_connectionAPIName then
			state.antiAfkStatus = "Native Idled connection API unavailable"

			return false
		end

		local ok, result = pcall(Ryu_connectionAPIName, LocalPlayer2.Idled)

		if not ok or type(result) ~= "table" then
			state.antiAfkStatus = "Idled scan unavailable"

			return false
		end

		local lastDisabledIdleConnections = 0

		for _, v in ipairs(result) do
			local Ryu_connectionDisabled = false

			if type(v) == "table" or type(v) == "userdata" then
				if type(v.Disable) == "function" then
					Ryu_connectionDisabled = pcall(v.Disable, v)
				elseif type(v.Disconnect) == "function" then
					Ryu_connectionDisabled = pcall(v.Disconnect, v)
				end
			end

			if Ryu_connectionDisabled then
				lastDisabledIdleConnections += 1
			end
		end

		state.scanRuns += 1
		state.lastScanAt = os.clock()
		state.lastDisabledIdleConnections = lastDisabledIdleConnections
		state.disabledIdleConnections += lastDisabledIdleConnections
		state.antiAfkStatus = lastDisabledIdleConnections > 0 and "Anti-AFK disabled " .. tostring(lastDisabledIdleConnections) .. " Idled connection(s)" or "Anti-AFK active; Idled connections clear"

		return true
	end

	local Ryu_startupProtection = {
		install = function()
			local Ryu_genvTable3 = Ryu_getGenv2()
			local value = rawget(Ryu_genvTable3, "__FyyStealAnEggStartupProtectionLiteV2")

			if type(value) == "table" and value.installed then
				value.installRuns += 1
				Ryu_disableIdleConnections(value)
				value.status = value.antiAfkStatus

				return value
			end

			local Ryu_startupProtectionLite = {
				installRuns = 1,
				scanRuns = 0,
				disabledIdleConnections = 0,
				lastDisabledIdleConnections = 0,
				lastScanAt = 0,
				installed = false,
				mode = "native-idled-disabler",
				integrityPatcherInstalled = false,
				networkFilterInstalled = false,
				namecallHookInstalled = false
			}

			Ryu_genvTable3.__FyyStealAnEggStartupProtectionLiteV2 = Ryu_startupProtectionLite

			local LocalPlayer2 = Players.LocalPlayer

			if not LocalPlayer2 then
				Ryu_startupProtectionLite.antiAfkInstalled = false
				Ryu_startupProtectionLite.antiAfkStatus = "LocalPlayer unavailable"
				Ryu_startupProtectionLite.status = Ryu_startupProtectionLite.antiAfkStatus
				Ryu_startupProtectionLite.installed = true

				return Ryu_startupProtectionLite
			end

			Ryu_startupProtectionLite.antiAfkInstalled = Ryu_disableIdleConnections(Ryu_startupProtectionLite)
			Ryu_startupProtectionLite.idledConnection = LocalPlayer2.Idled:Connect(function()
				Ryu_disableIdleConnections(Ryu_startupProtectionLite)
			end)
			Ryu_startupProtectionLite.characterConnection = LocalPlayer2.CharacterAdded:Connect(function()
				task.delay(1, function()
					if Ryu_startupProtectionLite.installed then
						Ryu_disableIdleConnections(Ryu_startupProtectionLite)
					end
				end)
			end)
			Ryu_startupProtectionLite.installed = true
			Ryu_startupProtectionLite.status = Ryu_startupProtectionLite.antiAfkStatus

			local function Ryu_antiAfkWatchLoop()
				while Ryu_startupProtectionLite.installed and Ryu_genvTable3.__FyyStealAnEggStartupProtectionLiteV2 == Ryu_startupProtectionLite do
					task.wait(60)

					if Ryu_startupProtectionLite.installed and Ryu_genvTable3.__FyyStealAnEggStartupProtectionLiteV2 == Ryu_startupProtectionLite then
						Ryu_disableIdleConnections(Ryu_startupProtectionLite)
						Ryu_startupProtectionLite.status = Ryu_startupProtectionLite.antiAfkStatus
					end
				end
			end

			task.spawn(Ryu_antiAfkWatchLoop)

			return Ryu_startupProtectionLite
		end,
		uninstall = function()
			local value = rawget(Ryu_getGenv2(), "__FyyStealAnEggStartupProtectionLiteV2")

			if type(value) == "table" then
				value.installed = false

				if value.idledConnection and typeof(value.idledConnection.Disconnect) == "function" then
					pcall(value.idledConnection.Disconnect, value.idledConnection)
					value.idledConnection = nil
				end

				if value.characterConnection and typeof(value.characterConnection.Disconnect) == "function" then
					pcall(value.characterConnection.Disconnect, value.characterConnection)
					value.characterConnection = nil
				end
			end
		end
	}

	local function Ryu_initAntiAfk()
		local genv2 = getgenv and getgenv() or _G

		genv2.__oxioAntiAfkGeneration = (genv2.__oxioAntiAfkGeneration or 0) + 1
		genv2.__oxioAntiAfkEnabled = senaV4Config.AntiAFK
		genv2.__oxioStartupProtection = Ryu_startupProtection
		genv2.__oxioSetAntiAfkEnabled = function(enabled)
			genv2.__oxioAntiAfkEnabled = enabled == true

			if enabled then
				Ryu_startupProtection.install()
			else
				Ryu_startupProtection.uninstall()
			end
		end

		if senaV4Config.AntiAFK then
			genv2.__oxioSetAntiAfkEnabled(true)
		end
	end

	Ryu_initAntiAfk()
end

local Ryu_configRef = senaV4Config
local Ryu_teleportRefs = {
	TeleportService = TeleportService or game:GetService("TeleportService"),
	LP = LocalPlayer or Players.LocalPlayer,
	Players = Players
}

local function Ryu_writeAutoexecFile()
	pcall(function()
		if writefile then
			pcall(function()
				writefile("autoexec/Sena_StealAnEgg.lua", [[repeat task.wait(0.5) until game:IsLoaded()
task.wait(1.5)
if getgenv then getgenv().SNE_AutoExecute = true end
loadstring(game:HttpGet("https://senahub.xyz/raw/saev2"))()
]])
			end)
			pcall(function()
				writefile("autoexecute/Sena_StealAnEgg.lua", [[repeat task.wait(0.5) until game:IsLoaded()
task.wait(1.5)
if getgenv then getgenv().SNE_AutoExecute = true end
loadstring(game:HttpGet("https://senahub.xyz/raw/saev2"))()
]])
			end)
		end
	end)

	local queue_on_teleport_ = queue_on_teleport or syn and syn.queue_on_teleport or fluxus and fluxus.queue_on_teleport

	if queue_on_teleport_ then
		pcall(function()
			queue_on_teleport_([[repeat task.wait(0.5) until game:IsLoaded()
task.wait(1.5)
if getgenv then getgenv().SNE_AutoExecute = true end
loadstring(game:HttpGet("https://senahub.xyz/raw/saev2"))()
]])
		end)
	end
end
local function Ryu_clearAutoexecFile()
	pcall(function()
		if delfile then
			pcall(function()
				delfile("autoexec/Sena_StealAnEgg.lua")
			end)
			pcall(function()
				delfile("autoexecute/Sena_StealAnEgg.lua")
			end)
		elseif writefile then
			pcall(function()
				writefile("autoexec/Sena_StealAnEgg.lua", "")
			end)
			pcall(function()
				writefile("autoexecute/Sena_StealAnEgg.lua", "")
			end)
		end
	end)
end

local Ryu_clearAutoexecFile_var1 = false

local function Ryu_autoReconnectLoop()
	if Ryu_clearAutoexecFile_var1 then
		return
	end

	Ryu_clearAutoexecFile_var1 = true

	if Ryu_configRef.autoExecute or getgenv and getgenv().SNE_AutoExecute then
		pcall(Ryu_writeAutoexecFile)
	end

	task.wait(3)

	local TeleportService2 = Ryu_teleportRefs.TeleportService or game:GetService("TeleportService")
	local PlaceId = game.PlaceId
	local JobId = game.JobId

	while true do
		pcall(function()
			if JobId then
				if not (#JobId > 0) then
					TeleportService2:Teleport(PlaceId, Ryu_teleportRefs.LP)

					return
				end

				TeleportService2:TeleportToPlaceInstance(PlaceId, JobId, Ryu_teleportRefs.LP)
			else
				TeleportService2:Teleport(PlaceId, Ryu_teleportRefs.LP)
			end
		end)
		task.wait(6)
	end
end

pcall(function()
	game:GetService("GuiService").ErrorMessageChanged:Connect(function(errorMessage)
		if Ryu_configRef.autoReconnect and errorMessage and #errorMessage > 0 then
			Ryu_autoReconnectLoop()
		end
	end)
end)
pcall(function()
	local LP = Ryu_teleportRefs.LP or LocalPlayer

	LP = LP or Players.LocalPlayer

	if LP and LP.OnTeleport then
		LP.OnTeleport:Connect(function()
			if Ryu_configRef.autoExecute or getgenv and getgenv().SNE_AutoExecute then
				pcall(Ryu_writeAutoexecFile)
			end
		end)
	end
end)
task.spawn(function()
	while true do
		task.wait(2)

		if Ryu_configRef.autoReconnect then
			pcall(function()
				local RobloxPromptGui = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
				local promptOverlay = RobloxPromptGui and RobloxPromptGui:FindFirstChild("promptOverlay")
				local ErrorPrompt = promptOverlay and promptOverlay:FindFirstChild("ErrorPrompt")

				if ErrorPrompt and ErrorPrompt.Visible then
					Ryu_autoReconnectLoop()
				end
			end)
		end
	end
end)

local function Ryu_petBarnFactory()
	local Remotes = require(ReplicatedStorage.Shared.Remotes)

	local function Ryu_findFusablePair(speciesFilter, nameFilter, rarityFilter)
		local Ryu_saveDataSnapshot = (require(ReplicatedStorage.Shared.Save).Peek or require(ReplicatedStorage.Shared.Save).Get)()

		if not Ryu_saveDataSnapshot or type(Ryu_saveDataSnapshot.Inventory) ~= "table" then
			return nil
		end

		local AssetItems = require(ReplicatedStorage.Shared.Util.AssetItems)
		local Directory = require(ReplicatedStorage.Data.Assets).Directory
		local Ryu_equippedSet = {}
		local ipairs_ = ipairs
		local EquippedAssets = Ryu_saveDataSnapshot.EquippedAssets or {}

		for _, EquippedAsset in ipairs_(EquippedAssets) do
			Ryu_equippedSet[EquippedAsset] = true
		end

		local Ryu_groupedPets = {}

		for k, v in pairs(Ryu_saveDataSnapshot.Inventory) do
			if not Ryu_equippedSet[k] then
				local Ryu_findFusablePair_var1

				if AssetItems and type(AssetItems.Decode) == "function" then
					pcall(function()
						Ryu_findFusablePair_var1 = AssetItems.Decode(v)
					end)
				end

				Ryu_findFusablePair_var1 = Ryu_findFusablePair_var1 or v

				if type(Ryu_findFusablePair_var1) == "table" and not Ryu_findFusablePair_var1.InFuse and not Ryu_findFusablePair_var1.IsFavorite and Ryu_findFusablePair_var1.Category then
					local Ryu_petAssetDef = Directory[Ryu_findFusablePair_var1.Category]
					local DisplayName = Ryu_petAssetDef and Ryu_petAssetDef.Rarity and (Ryu_petAssetDef.Rarity.DisplayName or Ryu_petAssetDef.Rarity._id)
					local Ryu_rarityMatch = true

					if rarityFilter and #rarityFilter > 0 and not table.find(rarityFilter, "All") then
						Ryu_rarityMatch = DisplayName and table.find(rarityFilter, DisplayName) ~= nil
					end

					local Ryu_speciesMatch = true

					if speciesFilter and nameFilter and #nameFilter > 0 and not table.find(nameFilter, "All") then
						Ryu_speciesMatch = table.find(nameFilter, Ryu_findFusablePair_var1.Category) ~= nil or Ryu_petAssetDef and table.find(nameFilter, Ryu_petAssetDef.DisplayName) ~= nil
					end

					if Ryu_rarityMatch and Ryu_speciesMatch then
						Ryu_groupedPets[Ryu_findFusablePair_var1.Category] = Ryu_groupedPets[Ryu_findFusablePair_var1.Category] or {}
						table.insert(Ryu_groupedPets[Ryu_findFusablePair_var1.Category], {
							uid = k,
							d = Ryu_findFusablePair_var1
						})
					end
				end
			end
		end

		for _, v in pairs(Ryu_groupedPets) do
			if not (#v >= 3) then
				continue
			end

			return {
				v[1].uid,
				v[2].uid,
				v[3].uid
			}
		end

		return nil
	end

	local Ryu_petBarnActions = {
		equipBest = function()
			pcall(function()
				Remotes.Haul.WearBest:InvokeServer()
			end)
		end,
		claimOffline = function()
			local ok, result = pcall(function()
				return Remotes.AwayEarnings.FetchSummary:InvokeServer()
			end)

			if ok and type(result) == "table" then
				if (result.ClaimableAmount or 0) > 0 then
					pcall(function()
						Remotes.AwayEarnings.AskCollect:InvokeServer({
							Kind = "Claim"
						})
					end)
				end
			end
		end,
		favoriteSelected = function()
			local Ryu_saveForFavorite = (require(ReplicatedStorage.Shared.Save).Peek or require(ReplicatedStorage.Shared.Save).Get)()

			if not Ryu_saveForFavorite or type(Ryu_saveForFavorite.Inventory) ~= "table" then
				return 0
			end

			local AssetItems = require(ReplicatedStorage.Shared.Util.AssetItems)
			local Directory = require(ReplicatedStorage.Data.Assets).Directory
			local Ryu_favoriteSelected_var1 = 0

			for k, v in pairs(Ryu_saveForFavorite.Inventory) do
				local Ryu_favoriteSelected_var2

				if AssetItems and type(AssetItems.Decode) == "function" then
					pcall(function()
						Ryu_favoriteSelected_var2 = AssetItems.Decode(v)
					end)
				end

				Ryu_favoriteSelected_var2 = Ryu_favoriteSelected_var2 or v

				if type(Ryu_favoriteSelected_var2) == "table" then
					if not Ryu_favoriteSelected_var2.IsFavorite and Ryu_favoriteSelected_var2.Category then
						local Ryu_petAssetDefFav = Directory[Ryu_favoriteSelected_var2.Category]
						local DisplayName = Ryu_petAssetDefFav and Ryu_petAssetDefFav.Rarity and (Ryu_petAssetDefFav.Rarity.DisplayName or Ryu_petAssetDefFav.Rarity._id)
						local Ryu_favoriteMatch = false

						if senaV4Config.FavMode == "Species" then
							local FavSpecies = senaV4Config.FavSpecies or {}

							if table.find(FavSpecies, "All") or table.find(FavSpecies, Ryu_favoriteSelected_var2.Category) or Ryu_petAssetDefFav and table.find(FavSpecies, Ryu_petAssetDefFav.DisplayName) then
								Ryu_favoriteMatch = true
							end
						else
							local FavRarities = senaV4Config.FavRarities or {}

							if table.find(FavRarities, "All") or DisplayName and table.find(FavRarities, DisplayName) then
								Ryu_favoriteMatch = true
							end
						end

						if Ryu_favoriteMatch then
							pcall(function()
								Remotes.PetSatchel.WriteFavourite:FireServer(k, true)
							end)
							Ryu_favoriteSelected_var1 += 1

							if Ryu_favoriteSelected_var1 % 10 == 0 then
								task.wait(0.05)
							end
						end
					end
				end
			end

			return Ryu_favoriteSelected_var1
		end,
		unfavoriteAll = function()
			local Ryu_saveForUnfavorite = (require(ReplicatedStorage.Shared.Save).Peek or require(ReplicatedStorage.Shared.Save).Get)()

			if not Ryu_saveForUnfavorite or type(Ryu_saveForUnfavorite.Inventory) ~= "table" then
				return 0
			end

			local Ryu_unfavoriteAll_var1 = 0

			for k, v in pairs(Ryu_saveForUnfavorite.Inventory) do
				local Ryu_inventoryPet = v

				if type(Ryu_inventoryPet) == "table" and Ryu_inventoryPet.IsFavorite then
					pcall(function()
						Remotes.PetSatchel.WriteFavourite:FireServer(k, false)
					end)
					Ryu_unfavoriteAll_var1 += 1

					if Ryu_unfavoriteAll_var1 % 10 == 0 then
						task.wait(0.05)
					end
				end
			end

			return Ryu_unfavoriteAll_var1
		end,
		fuseOnePair = function()
			local Ryu_saveForFuse = (require(ReplicatedStorage.Shared.Save).Peek or require(ReplicatedStorage.Shared.Save).Get)()

			if not Ryu_saveForFuse then
				return false
			end

			if Ryu_saveForFuse.FusionLocked then
				return false, "Fusion locked"
			end

			local Ryu_fusablePair = Ryu_findFusablePair(senaV4Config.FuseSelectedOnly, senaV4Config.FuseSpecies, senaV4Config.FuseRarities)

			if not Ryu_fusablePair then
				return false, "No eligible group of 3"
			end

			pcall(function()
				Remotes.Fusery.ConfirmBriefing:InvokeServer()
			end)

			for _, v in ipairs(Ryu_fusablePair) do
				local ok, result = pcall(function()
					return Remotes.Fusery.LoadPet:InvokeServer(v)
				end)

				if ok and result then
					task.wait(0.02)

					continue
				end

				return false, "Failed to load pet"
			end

			local ok, result = pcall(function()
				return Remotes.Fusery.BeginFuse:InvokeServer()
			end)

			if not ok or not result then
				return false, "Failed to begin fuse"
			end

			task.wait(0.06)
			pcall(function()
				Remotes.Fusery.FinishReveal:InvokeServer()
			end)

			return true
		end
	}

	task.spawn(function()
		local Ryu_fuseOnePair_var1 = 0

		while Ryu_isCurrentSession() do
			local now = os.clock()

			if senaV4Config.AutoEquipBest and now - Ryu_fuseOnePair_var1 > 6 then
				Ryu_fuseOnePair_var1 = now
				pcall(Ryu_petBarnActions.equipBest)
			end

			if senaV4Config.AutoClaimOffline then
				pcall(Ryu_petBarnActions.claimOffline)
			end

			if senaV4Config.AutoFavorite then
				pcall(Ryu_petBarnActions.favoriteSelected)
			end

			if senaV4Config.AutoFusePets then
				pcall(Ryu_petBarnActions.fuseOnePair)
			end

			task.wait(2.5)
		end
	end)

	return Ryu_petBarnActions
end

genv.__oxioPetBarn = Ryu_petBarnFactory()

do
	local function Ryu_upgradesFactory()
		local Remotes = require(ReplicatedStorage.Shared.Remotes)
		local Ryu_baseUpgradeActions = {
			upgradeBase = function()
				local Ryu_saveForBase = (require(ReplicatedStorage.Shared.Save).Peek or require(ReplicatedStorage.Shared.Save).Get)()

				if not Ryu_saveForBase then
					return false
				end

				local Ryu_baseUpgradeLevel = tonumber(Ryu_saveForBase.BaseUpgradeLevel or 0) or 0
				local Bases = require(ReplicatedStorage.Data.Bases)
				local BASES = Bases and Bases.BASES and Bases.BASES[Ryu_baseUpgradeLevel + 1]

				if not BASES then
					return false, "Max level"
				end

				local Ryu_baseMoney = tonumber(Ryu_saveForBase.Money or 0) or 0

				if Ryu_baseMoney < (BASES.Cost or 0) then
					return false, "Not enough money"
				end

				local ok, result = pcall(function()
					return Remotes.Homestead.AskBaseTierRaise:InvokeServer()
				end)
				local Ryu_baseUpgradeOk = ok and result == true

				return Ryu_baseUpgradeOk, result
			end,
			claimAlmanac = function()
				local ok, result = pcall(function()
					return Remotes.Codex.AskRedeemAll:InvokeServer()
				end)

				return ok, result
			end
		}

		task.spawn(function()
			while Ryu_isCurrentSession() do
				if senaV4Config.AutoBaseUpgrade then
					pcall(Ryu_baseUpgradeActions.upgradeBase)
				end

				if senaV4Config.AutoClaimAlmanac then
					pcall(Ryu_baseUpgradeActions.claimAlmanac)
				end

				task.wait(3)
			end
		end)

		return Ryu_baseUpgradeActions
	end

	genv.__oxioUpgrades = Ryu_upgradesFactory()
end

local function Ryu_roamingFactory()
	local Ryu_roamingActions = {
		noclipConn = nil
	}

	Ryu_roamingActions.setNoclip = function(enabled)
		senaV4Config.Noclip = enabled == true

		if Ryu_roamingActions.noclipConn then
			pcall(function()
				Ryu_roamingActions.noclipConn:Disconnect()
			end)
			Ryu_roamingActions.noclipConn = nil
		end

		if senaV4Config.Noclip then
			Ryu_roamingActions.noclipConn = RunService.Stepped:Connect(function()
				if not senaV4Config.Noclip then
					return
				end

				local Character = LocalPlayer.Character

				if not Character then
					return
				end

				for _, descendant in ipairs(Character:GetDescendants()) do
					if descendant:IsA("BasePart") and descendant.CanCollide then
						descendant:SetAttribute("SenaNoclip", true)
						descendant.CanCollide = false
					end
				end
			end)

			return
		end

		local Character = LocalPlayer.Character

		if Character then
			for _, descendant in ipairs(Character:GetDescendants()) do
				if descendant:IsA("BasePart") and descendant:GetAttribute("SenaNoclip") then
					descendant.CanCollide = true
					descendant:SetAttribute("SenaNoclip", nil)
				end
			end
		end
	end
	Ryu_roamingActions.waypointList = function()
		local Ryu_waypointsList = { "Respawn Point" }
		local Ryu_worldRef9 = Ryu_getWorkspaceWorld()
		local Machines = Ryu_worldRef9 and Ryu_worldRef9:FindFirstChild("Machines")

		if Machines and Machines:FindFirstChild("FuseMachine") then
			table.insert(Ryu_waypointsList, "Fuse Machine")
		end

		local Areas = Ryu_worldRef9 and Ryu_worldRef9:FindFirstChild("Areas")
		local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")

		if GuardAreas then
			for _, child in ipairs(GuardAreas:GetChildren()) do
				table.insert(Ryu_waypointsList, child.Name)
			end
		end

		return Ryu_waypointsList
	end
	Ryu_roamingActions.teleportWaypoint = function(waypointName)
		local Character = LocalPlayer.Character
		local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")

		if not HumanoidRootPart then
			return false
		end

		local Position
		local Ryu_worldRef10 = Ryu_getWorkspaceWorld()

		if waypointName == "Respawn Point" then
			pcall(function()
				local PlotState2 = require(ReplicatedStorage.Client.PlotState)
				local ResolvePlot = PlotState2.ResolvePlot and PlotState2.ResolvePlot()

				if ResolvePlot and ResolvePlot.RespawnPointCFrame then
					Position = ResolvePlot.RespawnPointCFrame.Position
				elseif ResolvePlot and ResolvePlot.Model then
					if ResolvePlot.Model:FindFirstChild("Spawn") then
						Position = ResolvePlot.Model.Spawn.Position
					end
				end
			end)
		elseif waypointName == "Fuse Machine" then
			local Machines = Ryu_worldRef10 and Ryu_worldRef10:FindFirstChild("Machines")
			local FuseMachine = Machines and Machines:FindFirstChild("FuseMachine")
			local Machine = FuseMachine and (FuseMachine:FindFirstChild("Machine") or FuseMachine.PrimaryPart)

			if Machine then
				Position = Machine.Position
			end
		else
			local Areas = Ryu_worldRef10 and Ryu_worldRef10:FindFirstChild("Areas")
			local GuardAreas = Areas and Areas:FindFirstChild("GuardAreas")
			local Ryu_guardArea = GuardAreas and GuardAreas:FindFirstChild(waypointName)
			local Guard = Ryu_guardArea and Ryu_guardArea:FindFirstChild("Guard")

			if Guard and Guard:IsA("BasePart") then
				Position = Guard.Position
			end
		end

		if not Position then
			return false
		end

		HumanoidRootPart.CFrame = cFrameNew(Position + Vector3.new(0, 4, 0))
		HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero

		return true
	end
	Ryu_roamingActions.setBottingMode = function(enabled)
		senaV4Config.BottingMode = enabled == true

		local __oxioBottingOverlay = genv.__oxioBottingOverlay

		if __oxioBottingOverlay and __oxioBottingOverlay.Parent then
			pcall(function()
				__oxioBottingOverlay:Destroy()
			end)
		end

		genv.__oxioBottingOverlay = nil

		if not senaV4Config.BottingMode then
			pcall(function()
				RunService:Set3dRenderingEnabled(true)
			end)

			return
		end

		pcall(function()
			RunService:Set3dRenderingEnabled(false)
		end)

		local CoreGui

		pcall(function()
			CoreGui = game:GetService("CoreGui")
		end)
		CoreGui = CoreGui or LocalPlayer:FindFirstChildOfClass("PlayerGui")

		if not CoreGui then
			return
		end

		local ScreenGui = Instance.new("ScreenGui")

		ScreenGui.Name = "SenaBottingOverlay"
		ScreenGui.ResetOnSpawn = false
		ScreenGui.IgnoreGuiInset = true
		ScreenGui.DisplayOrder = -1
		ScreenGui.Parent = CoreGui

		local Frame = Instance.new("Frame")

		Frame.Name = "Blackscreen"
		Frame.Size = UDim2.new(1, 0, 1, 0)
		Frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		Frame.BorderSizePixel = 0
		Frame.Active = false
		Frame.Parent = ScreenGui
		genv.__oxioBottingOverlay = ScreenGui
	end
	task.spawn(function()
		while Ryu_isCurrentSession() do
			if senaV4Config.AntiCutscene then
				pcall(function()
					local PlayerGui = LocalPlayer:FindFirstChild("PlayerGui")

					if PlayerGui then
						for _, child in ipairs(PlayerGui:GetChildren()) do
							if child:IsA("ScreenGui") and (string.find(string.lower(child.Name), "cutscene") or child.Name == "Intro") and child.Enabled then
								child.Enabled = false
							end
						end
					end
				end)
			end

			task.wait(0.2)
		end
	end)

	return Ryu_roamingActions
end

genv.__oxioRoaming = Ryu_roamingFactory()

do
	local function Ryu_scrambleFactory()
		local Ryu_ScrambleRuntime = {
			snapAt = 0,
			snap = nil,
			status = "Idle",
			lastBuy = 0,
			doneLost = {},
			active = false,
			token = 0
		}

		local function Ryu_getScrambleRemotes()
			return require(ReplicatedStorage.Shared.Remotes).Scramble
		end

		Ryu_ScrambleRuntime.snapshot = function(forceRefresh)
			local now = os.clock()

			if not forceRefresh and Ryu_ScrambleRuntime.snap and now - Ryu_ScrambleRuntime.snapAt < 1.5 then
				return Ryu_ScrambleRuntime.snap
			end

			local ok, snap = pcall(function()
				return Ryu_getScrambleRemotes().Request:InvokeServer("Snapshot")
			end)

			if ok and type(snap) == "table" and snap.State then
				Ryu_ScrambleRuntime.snap = snap
				Ryu_ScrambleRuntime.snapAt = now
			end

			return Ryu_ScrambleRuntime.snap
		end
		Ryu_ScrambleRuntime.live = function()
			local Ryu_scrambleSnapshot = Ryu_ScrambleRuntime.snapshot()

			if not Ryu_scrambleSnapshot then
				return false
			end

			local Ryu_scrambleIsLive = Ryu_scrambleSnapshot.Ready == true and Ryu_scrambleSnapshot.Enabled == true and Ryu_scrambleSnapshot.WorldReady == true

			if Ryu_scrambleIsLive then
				Ryu_scrambleIsLive = workspace:GetServerTimeNow() < (Ryu_scrambleSnapshot.EventEndsAt or 0)
			end

			return Ryu_scrambleIsLive
		end
		Ryu_ScrambleRuntime.windowActive = function()
			local Ryu_scrambleWindowActive = Ryu_ScrambleRuntime.snapshot()

			return Ryu_scrambleWindowActive and Ryu_scrambleWindowActive.Window and Ryu_scrambleWindowActive.Window.Active == true or false
		end
		Ryu_ScrambleRuntime.progress = function()
			local Ryu_scrambleState = Ryu_ScrambleRuntime.snapshot()
			local State = Ryu_scrambleState and Ryu_scrambleState.State

			if State then
				return State.Samples or 0, State.TotalParts or 0, State.DroneParts or 0
			end

			return 0, 0, 0
		end
		Ryu_ScrambleRuntime.buyTick = function()
			local ScrambleBuyList = senaV4Config.ScrambleBuyList

			if not ScrambleBuyList or #ScrambleBuyList == 0 then
				return
			end

			if os.clock() - Ryu_ScrambleRuntime.lastBuy < 2 then
				return
			end

			local Ryu_scrambleShopSnapshot = Ryu_ScrambleRuntime.snapshot(true)

			if not Ryu_scrambleShopSnapshot or not Ryu_scrambleShopSnapshot.State or not Ryu_scrambleShopSnapshot.Shop then
				return
			end

			local Samples = Ryu_scrambleShopSnapshot.State.Samples or 0

			for _, v in pairs(Ryu_scrambleShopSnapshot.Shop) do
				if not senaV4Config.ScrambleAutoBuy then
					return
				end

				local Ryu_scrambleShopLabel = tostring(v.Label)
				local Ryu_scrambleShopMatched = false
				local Ryu_scrambleBuyIter, Ryu_scrambleBuyIterState, Ryu_scrambleBuyIterControl = ipairs(ScrambleBuyList)
				local Ryu_scrambleBuyIterator = geniter(Ryu_scrambleBuyIter, Ryu_scrambleBuyIterState, Ryu_scrambleBuyIterControl)
				local Ryu_scrambleBuyPack = table.pack(Ryu_scrambleBuyIterator())

				if Ryu_scrambleBuyPack[1] then
					local Ryu_scrambleBuyEntry = Ryu_scrambleBuyPack[3]

					while true do
						if tostring(Ryu_scrambleBuyEntry) == Ryu_scrambleShopLabel then
							Ryu_scrambleShopMatched = true

							break
						end

						local Ryu_scrambleBuyNextPack = table.pack(Ryu_scrambleBuyIterator())

						if not Ryu_scrambleBuyNextPack[1] then
							break
						end

						Ryu_scrambleBuyEntry = Ryu_scrambleBuyNextPack[3]
					end

					if not Ryu_scrambleShopMatched then
						continue
					end

					if not ((v.Price or 0) <= Samples) then
						continue
					end

					local Ryu_scrambleBuyPurchase = (Ryu_scrambleShopSnapshot.State.ShopPurchases or {})[v.Id]
					local Count = Ryu_scrambleBuyPurchase and Ryu_scrambleBuyPurchase.Period == Ryu_scrambleShopSnapshot.ShopPeriod and (Ryu_scrambleBuyPurchase.Count or 0) or 0

					if not v.PurchaseLimit then
						Ryu_ScrambleRuntime.lastBuy = os.clock()
						pcall(function()
							Ryu_getScrambleRemotes().Request:InvokeServer("Shop", v.Id, {
								Quote = v.Quote,
								Sequence = Ryu_scrambleShopSnapshot.State.ShopSequence
							})
						end)
						Ryu_ScrambleRuntime.status = "Bought " .. Ryu_scrambleShopLabel
						Ryu_ScrambleRuntime.snapshot(true)

						return
					end

					if not (Count + (v.Quantity or 1) <= v.PurchaseLimit) then
						continue
					end

					Ryu_ScrambleRuntime.lastBuy = os.clock()
					pcall(function()
						Ryu_getScrambleRemotes().Request:InvokeServer("Shop", v.Id, {
							Quote = v.Quote,
							Sequence = Ryu_scrambleShopSnapshot.State.ShopSequence
						})
					end)
					Ryu_ScrambleRuntime.status = "Bought " .. Ryu_scrambleShopLabel
					Ryu_ScrambleRuntime.snapshot(true)

					return
				end
			end
		end
		task.spawn(function()
			while Ryu_isCurrentSession() do
				Ryu_ScrambleRuntime.wantsCharacter = false
				Ryu_ScrambleRuntime.active = false

				if senaV4Config.ScrambleAutoBuy then
					pcall(function()
						if Ryu_ScrambleRuntime.live() then
							Ryu_ScrambleRuntime.buyTick()
						else
							Ryu_ScrambleRuntime.status = "Event not active"
						end
					end)
				end

				task.wait(senaV4Config.ScrambleAutoBuy and 0.5 or 1)
			end
		end)

		return Ryu_ScrambleRuntime
	end

	genv.__oxioScrambleRuntime = Ryu_scrambleFactory()
end

;(function() -- Auto Race (chili-based, integrated with sae_work)
local okRace, errRace = pcall(function()
	local RaceState = {
		status = "Idle",
		lastResult = "No race yet",
		driving = nil,
		joinTries = 0,
		joinTriedAt = 0,
		racedWindow = nil,
		claimAt = 0,
		buyAt = 0,
		equipAt = 0,
		portalWarned = false,
	}

	local RaceRally, RaceTrackPathMod, Save, Remotes
	pcall(function() RaceRally       = require(ReplicatedStorage.Data.RaceRally) end)
	pcall(function() RaceTrackPathMod= require(ReplicatedStorage.Shared.Modules.RaceTrackPath) end)
	pcall(function() Save            = require(ReplicatedStorage.Shared.Save) end)
	pcall(function() Remotes         = require(ReplicatedStorage.Shared.Remotes) end)

	local RaceRallyEligibility
	pcall(function() RaceRallyEligibility = require(ReplicatedStorage.Shared.Util.RaceRallyEligibility) end)

	local TRACK_NAME = (RaceRally and RaceRally.Track) or "RaceTrack"

	local function joinOpen()
		local t = workspace:GetAttribute("RaceRallyJoinEndsAt")
		return workspace:GetAttribute("RaceRallyRunning") == true
			and type(t) == "number"
			and workspace:GetServerTimeNow() < t
	end
	local function joinLeft()
		if not joinOpen() then return 0 end
		local t = workspace:GetAttribute("RaceRallyJoinEndsAt")
		return math.max(0, t - workspace:GetServerTimeNow())
	end
	local function windowId()
		return workspace:GetAttribute("RaceRallyWindow")
			or workspace:GetAttribute("RaceRallyJoinEndsAt")
	end
	local function getSave()
		if not Save then return nil end
		local ok, d = pcall(function() return Save.Peek() end)
		return ok and type(d) == "table" and d or nil
	end
	local function getRallyData()
		local d = getSave()
		return d and type(d.RaceRally) == "table" and d.RaceRally or nil
	end
	local function isEligible()
		if not RaceRallyEligibility or type(RaceRallyEligibility.IsEligible) ~= "function" then return true end
		local root = getSave()
		local sp = tonumber(root and root.SpeedPower) or 0
		local ok, res = pcall(RaceRallyEligibility.IsEligible, sp)
		return (not ok) or res == true
	end
	local function inRaceNow()
		local plr = Players.LocalPlayer
		return plr:GetAttribute("RaceId") ~= nil or plr:GetAttribute("RaceRallyQueued") == true
	end
	local function racedThisWindow()
		local w = windowId()
		if RaceState.racedWindow ~= nil and RaceState.racedWindow == w then return true end
		local d = getRallyData()
		return type(w) == "number" and d and d.LastRacedWindow == w
	end
	local function root()
		local c = LocalPlayer.Character
		return c and c:FindFirstChild("HumanoidRootPart")
	end
	local function findPortal()
		local world = workspace:FindFirstChild("World")
		return world and world:FindFirstChild("RaceRallyPortal")
	end
	local function portalHitbox(portal)
		if not portal then return nil end
		local hb = portal:FindFirstChild("Hitbox")
		if hb and hb:IsA("BasePart") then return hb end
		return portal:FindFirstChildWhichIsA("BasePart", true)
	end

	-- === Join ===
	local function touch(root_, hb)
		if not root_ or not hb or type(firetouchinterest) ~= "function" then return end
		pcall(firetouchinterest, root_, hb, 0)
		task.wait()
		pcall(firetouchinterest, root_, hb, 1)
	end
	local function firePrompt(portal, root_)
		if not portal or not root_ then return end
		local prompt = portal:FindFirstChildWhichIsA("ProximityPrompt", true)
		if not prompt or type(fireproximityprompt) ~= "function" then return end
		local model = prompt.Parent
		local pos
		if model:IsA("Model") then
			local ok, p = pcall(function() return model:GetPivot().Position end)
			if ok then pos = p end
		elseif model:IsA("BasePart") then
			pos = model.Position
		end
		if pos and (root_.Position - pos).Magnitude < 25 then
			pcall(fireproximityprompt, prompt)
		end
	end
	local function attemptJoin()
		if not joinOpen() or racedThisWindow() or not isEligible() then return false end
		local r = root()
		if not r then return false end
		local portal = findPortal()
		if not portal then
			if not RaceState.portalWarned then
				RaceState.portalWarned = true
				warn("[oxio][Race] portal not found")
			end
			return false
		end
		RaceState.portalWarned = false

		local egg = genv.__oxioEggRuntime
		if egg and not egg.destroyed and (egg.running or (egg.carry and egg.carry.active)) and joinLeft() > 10 then
			RaceState.status = "Waiting for egg to finish"
			return false
		end

		RaceState.status = "Joining race"
		RaceState.joinTries += 1
		RaceState.joinTriedAt = os.clock()

		local hb = portalHitbox(portal)
		-- Snap to portal
		local targetPos = (hb and hb.Position or portal:GetPivot().Position) + Vector3.new(0, 3, 0)
		pcall(function()
			r.CFrame = CFrame.new(targetPos) * r.CFrame.Rotation
			r.AssemblyLinearVelocity = Vector3.zero
			r.AssemblyAngularVelocity = Vector3.zero
		end)
		task.wait(0.15)
		touch(r, hb)
		firePrompt(portal, r)
		if inRaceNow() then
			RaceState.racedWindow = windowId()
			RaceState.status = "In race"
			return true
		end
		-- Retry
		for i = 1, 4 do
			if not joinOpen() or inRaceNow() then break end
			r = root()
			if not r then break end
			hb = portalHitbox(portal)
			if hb then
				local d = hb.Position + Vector3.new(0,3,0) - r.Position
				for _ = 1, 8 do
					if d.Magnitude < 3 then break end
					local step = d.Unit * math.min(d.Magnitude, 120)
					pcall(function()
						r.CFrame = CFrame.new(r.Position + step) * r.CFrame.Rotation
						r.AssemblyLinearVelocity = Vector3.zero
					end)
					touch(r, hb)
					task.wait(0.05)
					if inRaceNow() then break end
					d = hb.Position + Vector3.new(0,3,0) - r.Position
				end
			end
			task.wait(0.25)
			if inRaceNow() then
				RaceState.racedWindow = windowId()
				RaceState.status = "In race"
				return true
			end
		end
		return false
	end

	-- === Drive ===
	local Driving = nil
	local function findMount()
		if type(filtergc) == "function" then
			local ok, res = pcall(filtergc, "table",
				{ Keys = { "Holds", "Drive", "Align", "Push", "Heading", "TravelDirection" } }, false)
			if ok and type(res) == "table" then
				for _, t in ipairs(res) do
					if typeof(t.Drive) == "Instance" and t.Drive.Parent then return t end
				end
			end
		end
		if type(getgc) == "function" then
			local ok, all = pcall(getgc, true)
			if ok and type(all) == "table" then
				for _, t in ipairs(all) do
					if type(t) == "table"
						and rawget(t, "Holds") ~= nil
						and rawget(t, "Drive") ~= nil
						and rawget(t, "Align") ~= nil
						and typeof(t.Drive) == "Instance" and t.Drive.Parent
					then return t end
				end
			end
		end
		return nil
	end
	local function buildPath()
		if not RaceTrackPathMod then return nil end
		local track = workspace:FindFirstChild(TRACK_NAME)
		if not track then return nil end
		local att = track:FindFirstChild("AttachmentTrack")
		if not att then return nil end
		local ok, p = pcall(RaceTrackPathMod.new, att)
		return ok and p or nil
	end
	local function usePowerUp(r)
		if not Remotes then return end
		local remote = Remotes.MountRace and Remotes.MountRace.PowerUp
		if not remote then return end
		local plr = LocalPlayer
		local item = plr:GetAttribute("RacePowerUp")
		if type(item) == "string" and item ~= "" then
			local now = workspace:GetServerTimeNow()
			local roll = tonumber(plr:GetAttribute("RacePowerUpRollEndsAt")) or 0
			local eff  = tonumber(plr:GetAttribute("RacePowerUpEffectEndsAt")) or 0
			local stun = tonumber(plr:GetAttribute("RacePowerUpStunEndsAt")) or 0
			if not (now < roll) and not (now < eff) and not (now < stun) then
				local look = r.CFrame.LookVector
				if Driving and Driving.Path then
					local f = Driving.Path:FrameAt(Driving.Progress)
					if f then look = f.LookVector end
				end
				pcall(function() remote:FireServer("Use", r.Position, look) end)
			end
		end
	end
	local function startDriving()
		if Driving then return end
		local r = root()
		if not r then return end
		local path = buildPath()
		if not path then return end
		local half = path.Length / 2
		local ok, proj = pcall(function() return path:Project(r.Position, half, half, half) end)
		if not ok or type(proj) ~= "number" then return end
		local f = path:FrameAt(proj)
		if (r.Position - f.Position).Magnitude > 80 then return end
		local mount = findMount()
		if not mount then return end
		local speed = math.clamp(tonumber(senaV4Config.RaceSpeed) or 150, 100, 160)
		Driving = {
			Path = path,
			Progress = proj,
			Lift = math.max((r.Position - f.Position):Dot(f.UpVector), 2),
			Life = LocalPlayer.Character,
			Mount = mount,
			Speed = speed,
			LastPowerAt = 0,
		}
		RaceState.driving = Driving
		local driveRef = Driving
		game:GetService("RunService").Heartbeat:Connect(function(dt)
			if Driving ~= driveRef then return end
			if LocalPlayer.Character ~= driveRef.Life then return end
			driveRef.Progress = driveRef.Progress + driveRef.Speed * dt
			local cur = root()
			if not cur then return end
			local fr = driveRef.Path:FrameAt(driveRef.Progress)
			local target = fr.Position + fr.UpVector * driveRef.Lift
			if (cur.Position - target).Magnitude > 40 then
				local ok2, p2 = pcall(function() return driveRef.Path:Project(cur.Position, driveRef.Progress, 300, 300) end)
				if ok2 and type(p2) == "number" then
					driveRef.Progress = p2
					fr = driveRef.Path:FrameAt(driveRef.Progress)
					target = fr.Position + fr.UpVector * driveRef.Lift
				end
			end
			pcall(function()
				cur.CFrame = CFrame.new(target) * fr.Rotation
				cur.AssemblyLinearVelocity = fr.LookVector * driveRef.Speed
				cur.AssemblyAngularVelocity = Vector3.zero
			end)
			local now = os.clock()
			if now - driveRef.LastPowerAt >= 0.2 then
				driveRef.LastPowerAt = now
				usePowerUp(cur)
			end
		end)
	end
	local function stopDriving()
		Driving = nil
		RaceState.driving = nil
	end
	local function leaveRace()
		if Remotes then
			local remote = Remotes.MountRace and Remotes.MountRace.AskLeave
			if remote then pcall(function() remote:FireServer() end) end
		end
		stopDriving()
		RaceState.racedWindow = windowId()
	end
	local function claimRewards()
		if os.clock() - RaceState.claimAt < 5 then return end
		RaceState.claimAt = os.clock()
		local d = getRallyData()
		if type(d) ~= "table" or not RaceRally then return end
		local wins = tonumber(d.Wins) or 0
		local owned = type(d.Milestones) == "table" and d.Milestones or {}
		if not Remotes then return end
		local rf = Remotes.RaceRally and Remotes.RaceRally.AskClaimMilestone
		if not rf then return end
		for id, m in pairs(RaceRally.Milestones or {}) do
			if not owned[id] and wins >= (tonumber(m.Wins) or 0) then
				pcall(function() rf:InvokeServer(id) end)
			end
		end
		if RaceRally.RepeatsEarned and RaceRally.RepeatId then
			local ok, want = pcall(RaceRally.RepeatsEarned, wins)
			if ok and (tonumber(d.Repeats) or 0) < want then
				pcall(function() rf:InvokeServer(RaceRally.RepeatId) end)
			end
		end
	end
	local function equipBestRacer()
		local d = getRallyData()
		if type(d) ~= "table" or not RaceRally then return end
		local owned = type(d.Racers) == "table" and d.Racers or {}
		local bestId, bestOrder = RaceRally.DefaultRacer, -math.huge
		for id, isOwned in pairs(owned) do
			if isOwned == true then
				local def = RaceRally.Racers and RaceRally.Racers[id]
				local order = def and tonumber(def.Order) or 0
				if order > bestOrder then bestOrder = order; bestId = id end
			end
		end
		if not bestId or not Remotes then return end
		if tostring(d.EquippedRacer or "") ~= bestId then
			local rf = Remotes.RaceRally and Remotes.RaceRally.AskEquipRacer
			if rf then pcall(function() rf:InvokeServer(bestId) end) end
		end
	end
	local function buyFromShop()
		if os.clock() - RaceState.buyAt < 2 then return end
		RaceState.buyAt = os.clock()
		local d = getRallyData()
		if type(d) ~= "table" or not RaceRally or not Remotes then return end
		local tokens = tonumber(d.Tokens) or 0
		local list = senaV4Config.RaceBuyList or {}
		local want = {}
		for _, n in ipairs(list) do want[n] = true end
		if not next(want) then return end
		local offers = RaceRally.Shop or {}
		local purchases = type(d.Purchases) == "table" and d.Purchases or {}
		local rf = Remotes.RaceRally and Remotes.RaceRally.AskBuy
		if not rf then return end
		local BUYLIST = {
			{ Id="MutationToken", Name="Nitro Mutation" }, { Id="CashBooster",    Name="Cash Booster"    },
			{ Id="SpeedBoost",    Name="Speed Boost"    }, { Id="TreadmillBoost", Name="Treadmill Boost" },
			{ Id="RacingBat",     Name="Racing Bat"     },
		}
		for _, entry in ipairs(BUYLIST) do
			local offer = offers[entry.Id]
			if want[entry.Name] and offer then
				local price = tonumber(offer.Price) or 0
				if tokens >= price then
					local limit  = tonumber(offer.Limit) or 0
					local bought = purchases[entry.Id]
					local count  = bought and tonumber(bought.Count) or 0
					if limit == 0 or count < limit then
						pcall(function() rf:InvokeServer(entry.Id) end)
						tokens = tokens - price
					end
				end
			end
		end
	end

	-- === Main loop ===
	task.spawn(function()
		while Ryu_isCurrentSession() do
			if senaV4Config.RaceAuto == true then
				pcall(function()
					local plr = LocalPlayer
					local raceId = plr:GetAttribute("RaceId")
					if raceId ~= nil then
						RaceState.racedWindow = windowId()
						RaceState.status = string.format("Racing · lap %s · place %s",
							tostring(plr:GetAttribute("RaceLap") or "?"),
							tostring(plr:GetAttribute("RacePlace") or "?"))
						local place = plr:GetAttribute("RaceFinishPlace")
						if type(place) == "number" then
							RaceState.lastResult = string.format("Finished #%d", place)
							stopDriving()
							leaveRace()
						elseif tostring(raceId) == TRACK_NAME then
							startDriving()
						else
							stopDriving()
						end
					else
						if Driving then stopDriving() end
						local w = windowId()
						if type(w) == "number" and not joinOpen() and RaceState.racedWindow == w then
							RaceState.racedWindow = nil
						end
						if joinOpen() then
							local egg = genv.__oxioEggRuntime
							local eggBusy = egg and not egg.destroyed and (egg.running or (egg.carry and egg.carry.active))
							if racedThisWindow() then
								RaceState.status = "Already raced this window"
							elseif not isEligible() then
								RaceState.status = "Not eligible yet"
							elseif eggBusy and joinLeft() > 10 then
								RaceState.status = "Waiting for egg to finish"
							else
								attemptJoin()
							end
						else
							RaceState.status = "Idle"
						end
						if senaV4Config.RaceClaim then pcall(claimRewards) end
						if senaV4Config.RaceBuy   then pcall(buyFromShop)  end
						if senaV4Config.RaceClaim and os.clock() - RaceState.claimAt > 30 then
							pcall(equipBestRacer)
						end
					end
				end)
			else
				if Driving then stopDriving() end
				RaceState.status = "Disabled"
			end
			task.wait(0.5)
		end
	end)

	-- expose inRace/wantsJoin for StealPlayers guard
	RaceState.inRace    = inRaceNow
	RaceState.wantsJoin = function()
		return senaV4Config.RaceAuto == true and joinOpen() and not racedThisWindow()
	end

	Ryu_Blocker.register("race", {
		wants   = function() return senaV4Config.RaceAuto == true and (joinOpen() or inRaceNow()) end,
		active  = function() return inRaceNow() or Driving ~= nil end,
		enabled = function() return senaV4Config.RaceAuto == true end,
		status  = function() return RaceState.status end,
	})

	genv.__oxioRaceRuntime = RaceState
end)
if not okRace then warn("[oxio][Auto Race] failed: " .. tostring(errRace)) end
end)() -- akhir Auto Race

local function Ryu_butterflyFactory()
	local Ryu_BloomRuntime = {
