	local function Ryu_requirePath(root, ...)
		for _, v in ipairs({ ... }) do
			if not root then
				return nil
			end

			root = root:FindFirstChild(v)
		end

		return root
	end

	local Ryu_requirePath_var1

	local function Ryu_getButterflyModules()
		if Ryu_requirePath_var1 then
			return Ryu_requirePath_var1
		end

		local function Ryu_safeRequire(moduleScript)
			if not moduleScript then
				return nil
			end

			local ok, result = pcall(require, moduleScript)

			return ok and result or nil
		end

		local Ryu_butterflyModules = {
			Remotes = Ryu_safeRequire(Ryu_requirePath(ReplicatedStorage, "Shared", "Remotes")),
			Save = Ryu_safeRequire(Ryu_requirePath(ReplicatedStorage, "Shared", "Save")),
			Catalog = Ryu_safeRequire(Ryu_requirePath(ReplicatedStorage, "Shared", "Modules", "ButterflyCatalog")),
			Flags = Ryu_safeRequire(Ryu_requirePath(ReplicatedStorage, "Shared", "Flags", "ButterflyFlags")),
			Swarm = Ryu_safeRequire(Ryu_requirePath(ReplicatedStorage, "Controllers", "Game", "AdminAbuseClientController", "Events", "ButterflyBloom", "Swarm"))
		}

		if not Ryu_butterflyModules.Remotes or not Ryu_butterflyModules.Save or not Ryu_butterflyModules.Catalog then
			return nil
		end

		Ryu_requirePath_var1 = Ryu_butterflyModules

		return Ryu_butterflyModules
	end
	local function Ryu_readButterflyFlag(flagKey, defaultValue)
		local Ryu_butterflyFlags = Ryu_getButterflyModules()
		local Flags = Ryu_butterflyFlags and Ryu_butterflyFlags.Flags and Ryu_butterflyFlags.Flags[flagKey]

		if not Flags then
			return defaultValue
		end

		local ok, result = pcall(function()
			return Flags:Get()
		end)

		if not ok or result == nil then
			return defaultValue
		end

		return result
	end
	local function Ryu_callButterflyRemote(remoteCategory, remoteName, ...)
		local Ryu_butterflyModulesRef = Ryu_getButterflyModules()
		local Ryu_butterflyRemote = Ryu_butterflyModulesRef and Ryu_butterflyModulesRef.Remotes[remoteCategory] and Ryu_butterflyModulesRef.Remotes[remoteCategory][remoteName]

		if not Ryu_butterflyRemote then
			return false, remoteCategory .. "." .. remoteName .. " missing"
		end

		local Ryu_remoteCallResult = table.pack(pcall(Ryu_butterflyRemote.InvokeServer, Ryu_butterflyRemote, ...))

		if Ryu_remoteCallResult[1] then
			return Ryu_remoteCallResult[2] == true, type(Ryu_remoteCallResult[3]) == "string" and Ryu_remoteCallResult[3] or nil, Ryu_remoteCallResult[2]
		end

		return false, tostring(Ryu_remoteCallResult[2])
	end
	local function Ryu_canRetry(cooldownKey)
		return (Ryu_BloomRuntime.retryAt[cooldownKey] or 0) <= os.clock()
	end
	local function Ryu_markRetryAt(cooldownKey)
		Ryu_BloomRuntime.retryAt[cooldownKey] = os.clock() + 5
	end
	local function Ryu_getLocalRoot()
		local Character = LocalPlayer.Character

		return Character and Character:FindFirstChild("HumanoidRootPart") or nil
	end

	Ryu_BloomRuntime.bloomLeft = function()
		local Ryu_butterflyCatalog = Ryu_getButterflyModules()
		local attribute = workspace:GetAttribute(Ryu_butterflyCatalog and Ryu_butterflyCatalog.Catalog.EndsAtAttribute or "ButterflyBloomEndsAt")

		if typeof(attribute) == "number" then
			return math.max(0, attribute - workspace:GetServerTimeNow())
		end

		return 0
	end
	Ryu_BloomRuntime.nextBloom = function()
		local Ryu_bloomIntervalSeconds = tonumber(Ryu_readButterflyFlag("IntervalSeconds", 1800)) or 1800
		local Ryu_bloomOffsetSeconds = tonumber(Ryu_readButterflyFlag("OffsetSeconds", 900)) or 900
		local Ryu_bloomDurationSeconds = tonumber(Ryu_readButterflyFlag("DurationSeconds", 300)) or 300

		if Ryu_bloomIntervalSeconds <= 0 then
			return nil
		end

		local serverTimeNow = workspace:GetServerTimeNow()
		local Ryu_butterflyCatalog2 = Ryu_getButterflyModules()
		local attribute = workspace:GetAttribute(Ryu_butterflyCatalog2 and Ryu_butterflyCatalog2.Catalog.EndsAtAttribute or "ButterflyBloomEndsAt")
		local Ryu_nextBloomTime = typeof(attribute) == "number" and attribute - Ryu_bloomDurationSeconds or math.floor((serverTimeNow - Ryu_bloomOffsetSeconds) / Ryu_bloomIntervalSeconds) * Ryu_bloomIntervalSeconds + Ryu_bloomOffsetSeconds
		local Ryu_getLocalRoot_var1 = 0

		while Ryu_nextBloomTime <= serverTimeNow and Ryu_getLocalRoot_var1 < 64 do
			Ryu_nextBloomTime += Ryu_bloomIntervalSeconds
			Ryu_getLocalRoot_var1 += 1
		end

		return Ryu_nextBloomTime > serverTimeNow and Ryu_nextBloomTime - serverTimeNow or nil
	end

	local function Ryu_findButterflyNet(character)
		if not character then
			return nil
		end

		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Tool") and child:GetAttribute("ButterflyNet") == true then
				return child
			end
		end

		return nil
	end

	local Ryu_findButterflyNet_var1

	Ryu_BloomRuntime.tiers = function()
		if Ryu_findButterflyNet_var1 then
			return Ryu_findButterflyNet_var1
		end

		local Ryu_butterflyModules3 = Ryu_getButterflyModules()

		if not Ryu_butterflyModules3 then
			return nil
		end

		local Ryu_butterflyTiers = {}

		for i, v in ipairs(Ryu_BLOOM_TIERS) do
			local Tiers = Ryu_butterflyModules3.Catalog.Tiers and Ryu_butterflyModules3.Catalog.Tiers[v]

			Ryu_butterflyTiers[v] = {
				name = (Tiers and tostring(Tiers.DisplayName) or v):gsub("%s*Butterfly$", ""),
				color = Tiers and typeof(Tiers.Color) == "Color3" and Tiers.Color or Color3.new(1, 1, 1),
				trade = i < 4 and (tonumber(Ryu_readButterflyFlag(("%sTo%sCost"):format(v, Ryu_BLOOM_TIERS[i + 1]), 0)) or 0) or 0,
				essence = tonumber(Ryu_readButterflyFlag("Essence" .. v, 0)) or 0
			}
		end

		Ryu_findButterflyNet_var1 = Ryu_butterflyTiers

		return Ryu_butterflyTiers
	end
	Ryu_BloomRuntime.snapshot = function()
		local Ryu_butterflyModules4 = Ryu_getButterflyModules()
		local snap = Ryu_BloomRuntime.snap

		if not Ryu_butterflyModules4 then
			return snap
		end

		snap.left = Ryu_BloomRuntime.bloomLeft()
		snap.active = snap.left > 0
		snap.enabled = Ryu_readButterflyFlag("Enabled", true) ~= false
		snap.nextIn = not snap.active and Ryu_BloomRuntime.nextBloom() or nil

		local ok, result = pcall(Ryu_butterflyModules4.Save.Peek)
		local Ryu_saveSnapshot2 = ok and result or nil
		local Butterflies = Ryu_saveSnapshot2 and Ryu_saveSnapshot2.Butterflies

		snap.net = type(Butterflies) == "table" and Butterflies.NetClaimed == true
		snap.holding = Ryu_findButterflyNet(LocalPlayer.Character) ~= nil
		snap.inBag = Ryu_findButterflyNet(LocalPlayer:FindFirstChildOfClass("Backpack")) ~= nil
		snap.counts = snap.counts or {}

		for _, v in ipairs(Ryu_BLOOM_TIERS) do
			snap.counts[v] = type(Butterflies) == "table" and Butterflies.Counts and tonumber(Butterflies.Counts[v]) or 0
		end

		snap.essence = type(Butterflies) == "table" and tonumber(Butterflies.Essence) or 0
		snap.caught = type(Butterflies) == "table" and tonumber(Butterflies.TotalCaught) or 0
		snap.treeUnlocked = LocalPlayer:GetAttribute("EnchantedTreeUnlocked") == true

		return snap
	end
	Ryu_BloomRuntime.smartNext = function(tierCounts)
		local Ryu_butterflyTiers = Ryu_BloomRuntime.tiers()

		if not Ryu_butterflyTiers or not tierCounts then
			return nil
		end

		for i = 3, 1, -1 do
			local Ryu_butterflySourceTier = Ryu_BLOOM_TIERS[i]
			local Ryu_butterflyDestTier = Ryu_BLOOM_TIERS[i + 1]
			local trade = Ryu_butterflyTiers[Ryu_butterflySourceTier].trade

			if not (trade > 0) then
				continue
			end

			if not ((tierCounts[Ryu_butterflyDestTier] or 0) < Ryu_butterflyTiers[Ryu_butterflyDestTier].essence) then
				continue
			end

			if trade <= (tierCounts[Ryu_butterflySourceTier] or 0) - Ryu_butterflyTiers[Ryu_butterflySourceTier].essence then
				return Ryu_butterflySourceTier
			end
		end

		return nil
	end
	Ryu_BloomRuntime.canTrade = function()
		local snap = Ryu_BloomRuntime.snap
		local Ryu_butterflyTiers2 = Ryu_BloomRuntime.tiers()

		if not Ryu_butterflyTiers2 or not snap.counts then
			return false
		end

		local ButterflyTradeRecipe = senaV4Config.ButterflyTradeRecipe

		if ButterflyTradeRecipe == "Smart" then
			return Ryu_BloomRuntime.smartNext(snap.counts) ~= nil
		end

		for i = 1, 3 do
			local Ryu_butterflyTierEntry = Ryu_BLOOM_TIERS[i]

			if ButterflyTradeRecipe ~= nil and ButterflyTradeRecipe ~= "All" and ButterflyTradeRecipe ~= Ryu_butterflyTierEntry or not (Ryu_butterflyTiers2[Ryu_butterflyTierEntry].trade > 0) then
				continue
			end

			if Ryu_butterflyTiers2[Ryu_butterflyTierEntry].trade <= (snap.counts[Ryu_butterflyTierEntry] or 0) then
				return true
			end
		end

		return false
	end
	Ryu_BloomRuntime.canCraft = function()
		local snap = Ryu_BloomRuntime.snap
		local Ryu_butterflyTiers3 = Ryu_BloomRuntime.tiers()

		if not Ryu_butterflyTiers3 or not snap.counts then
			return false
		end

		for _, v in ipairs(Ryu_BLOOM_TIERS) do
			if not (Ryu_butterflyTiers3[v].essence > 0) then
				continue
			end

			if (snap.counts[v] or 0) < Ryu_butterflyTiers3[v].essence then
				return false, v
			end
		end

		return true
	end

	local function Ryu_getTierFilterSet()
