	local Ryu_bloomPad = {
		part = nil,
		y = 0
	}

	local function Ryu_cleanupBloomPad()
		if Ryu_bloomPad.part then
			pcall(function()
				Ryu_bloomPad.part:Destroy()
			end)
		end

		Ryu_bloomPad.part = nil
	end
	local function Ryu_updateBloomPad()
		local Ryu_localRoot = Ryu_getLocalRoot()

		if not Ryu_localRoot then
			return
		end

		if not Ryu_bloomPad.part or not Ryu_bloomPad.part.Parent then
			local Part = Instance.new("Part")

			Part.Name = "SenaBloomPad"
			Part.Anchored = true
			Part.CanCollide = true
			Part.CanTouch = false
			Part.CastShadow = false
			Part.Transparency = 1
			Part.Size = Vector3.new(24, 1, 24)
			Ryu_bloomPad.y = Ryu_localRoot.Position.Y - 3.5
			Part.CFrame = cFrameNew(Ryu_localRoot.Position.X, Ryu_bloomPad.y, Ryu_localRoot.Position.Z)
			Part.Parent = workspace
			Ryu_bloomPad.part = Part
		end

		local raycastParams = RaycastParams.new()

		raycastParams.FilterType = Enum.RaycastFilterType.Exclude
		raycastParams.FilterDescendantsInstances = {
			LocalPlayer.Character,
			Ryu_bloomPad.part
		}

		local hit = workspace:Raycast(Ryu_localRoot.Position + Vector3.new(0, 4, 0), Vector3.new(0, -80, 0), raycastParams)

		if not hit then
			return
		end

		Ryu_bloomPad.y += math.clamp(hit.Position.Y - 0.5 + 6 - Ryu_bloomPad.y, -2, 2)
		Ryu_bloomPad.part.CFrame = cFrameNew(Ryu_localRoot.Position.X, Ryu_bloomPad.y, Ryu_localRoot.Position.Z)
	end
	local function Ryu_travelToBloomZone(targetPos, timeoutSeconds)
		local Character = LocalPlayer.Character
		local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
		local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

		if not HumanoidRootPart or not Humanoid then
			return false
		end

		Ryu_cleanupBloomPad()

		local Ryu_travelTimeout = os.clock() + (timeoutSeconds or 30)

		local function Ryu_isTravelCancelled()
			if not Ryu_isCurrentSession() or Ryu_travelTimeout < os.clock() then
				return true
			end

			return Ryu_butterflyBlockers.blocker("butterfly") ~= nil
		end

		if Ryu_eggRuntime and HumanoidRootPart.Position.Y < 16000 and targetPos.Y < 16000 and (HumanoidRootPart.Position - targetPos).Magnitude > 600 and not Ryu_eggRuntime:_isInSafeArea(HumanoidRootPart) then
			local Ryu_safeCFrameToZone = Ryu_eggRuntime:_resolveSafeCFrame(HumanoidRootPart)

			if Ryu_safeCFrameToZone and (Ryu_safeCFrameToZone.Position - targetPos).Magnitude > 40 then
				local status = Ryu_BloomRuntime.status

				Ryu_BloomRuntime.status = "Heading to the safe zone first"
				pcall(Ryu_glideTo, HumanoidRootPart, Humanoid, Ryu_safeCFrameToZone, Ryu_isTravelCancelled)
				Ryu_BloomRuntime.status = status
				HumanoidRootPart = Ryu_getLocalRoot()

				if not HumanoidRootPart or Ryu_isTravelCancelled() or not Ryu_eggRuntime:_isInSafeArea(HumanoidRootPart) then
					return false
				end
			end
		end

		pcall(Ryu_glideTo, HumanoidRootPart, Humanoid, cFrameNew(targetPos) * HumanoidRootPart.CFrame.Rotation, Ryu_isTravelCancelled)

		local Ryu_localRootAfterTravel = Ryu_getLocalRoot()
		local Ryu_arrivedAtZone = Ryu_localRootAfterTravel ~= nil and (Ryu_localRootAfterTravel.Position - targetPos).Magnitude <= 12

		return Ryu_arrivedAtZone
	end
	local function Ryu_isInEnchantedTree()
		if LocalPlayer:GetAttribute("InEnchantedTree") == true then
			return true
		end

		local Ryu_localRootPos = Ryu_getLocalRoot()

		return Ryu_localRootPos ~= nil and Ryu_localRootPos.Position.Y > 16000
	end
	local function Ryu_firePrompt(prompt)
		if not prompt or not prompt:IsA("ProximityPrompt") or not prompt.Enabled then
			return false
		end

		local Ryu_promptHoldDuration = tonumber(prompt.HoldDuration) or 0

		pcall(function()
			prompt:InputHoldBegin()
			task.wait(Ryu_promptHoldDuration > 0 and Ryu_promptHoldDuration + 0.15 or 0.05)
			prompt:InputHoldEnd()
		end)

		if typeof(fireproximityprompt) == "function" then
			pcall(fireproximityprompt, prompt, Ryu_promptHoldDuration > 0 and Ryu_promptHoldDuration + 0.15 or 0)
		end

		return true
	end

	local EnchantedTreePrompt

	local function Ryu_enterEnchantedTree()
		if Ryu_isInEnchantedTree() then
			return nil
		end

		if LocalPlayer:GetAttribute("EnchantedTreeUnlocked") ~= true then
			return "Enchanted Tree is locked (finish the Wisp Event)"
		end

		if not EnchantedTreePrompt or not EnchantedTreePrompt.Parent then
			local world = Ryu_requirePath(workspace, "World", "Build", "EnchantedTreeInterior", "Markers", "EnterTrigger")

			EnchantedTreePrompt = world and world:FindFirstChild("EnchantedTreePrompt", true) or nil
		end

		local Parent = EnchantedTreePrompt and EnchantedTreePrompt.Parent
		local WorldPosition = Parent and (Parent:IsA("Attachment") and Parent.WorldPosition or Parent:IsA("BasePart") and Parent.Position)

		if not WorldPosition then
			return "tree entrance not found"
		end

		if Ryu_isNightPhase() then
			return "night - the forest is sealed"
		end

		Ryu_BloomRuntime.status = "Flying to the Enchanted Tree"

		if not Ryu_travelToBloomZone(WorldPosition + Vector3.new(0, 3, 0), 60) then
			return "could not reach the tree entrance"
		end

		Ryu_BloomRuntime.status = "Entering the tree"
		Ryu_firePrompt(EnchantedTreePrompt)

		local Ryu_enterTreeDeadline = os.clock() + 8

		while os.clock() < Ryu_enterTreeDeadline and not Ryu_isInEnchantedTree() do
			task.wait(0.05)
		end

		if Ryu_isInEnchantedTree() then
			return nil
		end

		return "entering the tree failed"
	end
	local function Ryu_exitEnchantedTree()
		if not Ryu_isInEnchantedTree() then
			return true
		end

		local world = Ryu_requirePath(workspace, "World", "Build", "EnchantedTreeInterior", "Markers", "ExitTrigger")

		if not world or typeof(firetouchinterest) ~= "function" then
			return false
		end

		Ryu_BloomRuntime.status = "Leaving the tree"

		local Ryu_exitTreeDeadline = os.clock() + 6

		while os.clock() < Ryu_exitTreeDeadline and Ryu_isInEnchantedTree() do
			local Ryu_localRootForExit = Ryu_getLocalRoot()

			if Ryu_localRootForExit then
				pcall(firetouchinterest, Ryu_localRootForExit, world, 0)
				pcall(firetouchinterest, Ryu_localRootForExit, world, 1)
			end

			task.wait(0.3)
		end

		return not Ryu_isInEnchantedTree()
	end
	local function Ryu_findButterflyStation(stationName)
		local world = Ryu_requirePath(workspace, "World", "Machines", "ButterflyStation", stationName, "Anchor")

		return world and world:IsA("BasePart") and world.Position or nil, world
	end
	local function Ryu_visitButterflyStation(stationName)
		local Ryu_stationAnchor = Ryu_findButterflyStation(stationName)

		if not Ryu_stationAnchor then
			return false, stationName .. " not found"
		end

		local Ryu_localRootForStation = Ryu_getLocalRoot()

		if Ryu_localRootForStation and (Ryu_localRootForStation.Position - Ryu_stationAnchor).Magnitude <= 10 then
			return true
		end

		local Ryu_stationEnterError = Ryu_enterEnchantedTree()

		if Ryu_stationEnterError then
			return false, Ryu_stationEnterError
		end

		Ryu_BloomRuntime.status = "Walking to the " .. stationName

		if Ryu_travelToBloomZone(Ryu_stationAnchor + Vector3.new(0, 3, 0), 15) then
			return true
		end

		return false, "could not reach the " .. stationName
	end
	local function Ryu_getBloomBounds()
		local world = Ryu_requirePath(workspace, "World", "Areas", "ButterflyBloom", "Bounds")

		return world and world:IsA("BasePart") and world or nil
	end
	local function Ryu_isInBloomZone()
		local Ryu_bloomBoundsPart = Ryu_getBloomBounds()
		local Ryu_localRootForBounds = Ryu_getLocalRoot()

		if not Ryu_bloomBoundsPart or not Ryu_localRootForBounds or Ryu_isInEnchantedTree() then
			return false
		end

		local Ryu_localPosInBounds = Ryu_bloomBoundsPart.CFrame:PointToObjectSpace(Ryu_localRootForBounds.Position)

		return math.abs(Ryu_localPosInBounds.X) <= Ryu_bloomBoundsPart.Size.X / 2 + 20 and math.abs(Ryu_localPosInBounds.Z) <= Ryu_bloomBoundsPart.Size.Z / 2 + 20
	end
	local function Ryu_getBloomZoneCenter()
		local Ryu_bloomBoundsPart2 = Ryu_getBloomBounds()

		return Ryu_bloomBoundsPart2 and Ryu_bloomBoundsPart2.Position + Vector3.new(0, 4, 0) or nil
	end
	local function Ryu_leaveTreadmill()
		local __oxioTreadmillManager = genv.__oxioTreadmillManager

		if not __oxioTreadmillManager or __oxioTreadmillManager.activeTreadmill == nil then
			return
		end

		Ryu_BloomRuntime.status = "Leaving the treadmill"

		local Ryu_leaveTreadmillDeadline = os.clock() + 5

		while __oxioTreadmillManager.activeTreadmill ~= nil and os.clock() < Ryu_leaveTreadmillDeadline do
			__oxioTreadmillManager:_requestUnequip()
			task.wait(0.3)
		end

		local Ryu_localRootForLeave = Ryu_getLocalRoot()

		if Ryu_localRootForLeave and Ryu_localRootForLeave.Anchored then
			pcall(function()
				Ryu_localRootForLeave.Anchored = false
			end)
		end
	end
	local function Ryu_resumeTreadmillIdle()
		local __oxioTreadmillManager = genv.__oxioTreadmillManager

		if not __oxioTreadmillManager or __oxioTreadmillManager.destroyed or not __oxioTreadmillManager.config.idleFarm then
			return false
		end

		if not __oxioTreadmillManager.busy and not __oxioTreadmillManager.idleRunning then
			task.defer(function()
				__oxioTreadmillManager:_startIdle()
			end)
		end

		return true
	end
	local function Ryu_returnToSafeArea()
		Ryu_cleanupBloomPad()

		if Ryu_isInEnchantedTree() then
			Ryu_exitEnchantedTree()
		end

		if Ryu_resumeTreadmillIdle() then
			return
		end

		local Ryu_localRootForReturn = Ryu_getLocalRoot()

		if not Ryu_localRootForReturn or not Ryu_eggRuntime or Ryu_eggRuntime:_isInSafeArea(Ryu_localRootForReturn) then
			return
		end

		local Ryu_safeCFrameForReturn = Ryu_eggRuntime:_resolveSafeCFrame(Ryu_localRootForReturn)

		if Ryu_safeCFrameForReturn then
			Ryu_BloomRuntime.status = "Back to the safe zone"
			Ryu_travelToBloomZone(Ryu_safeCFrameForReturn.Position, 60)
		end
	end

	Ryu_BloomRuntime.claimNet = function()
		local NetStand, Ryu_netClaimError = Ryu_visitButterflyStation("NetStand")

		if not NetStand then
			return false, Ryu_netClaimError
		end

		Ryu_BloomRuntime.status = "Claiming the net"

		local _, Ryu_netStandPart = Ryu_findButterflyStation("NetStand")
		local Butterflies, Ryu_netClaimErrorText

		if Ryu_netStandPart then
			local ProximityPrompt = Ryu_netStandPart:FindFirstChildWhichIsA("ProximityPrompt", true)

			if ProximityPrompt and ProximityPrompt.Enabled then
				Ryu_firePrompt(ProximityPrompt)

				local Ryu_netClaimDeadline = os.clock() + 2

				while true do
					if not (os.clock() < Ryu_netClaimDeadline) then
						Butterflies, Ryu_netClaimErrorText = Ryu_callButterflyRemote("Butterflies", "AskClaimNet")

						return Butterflies, Ryu_netClaimErrorText
					end

					if not Ryu_BloomRuntime.snapshot().net then
						task.wait(0.1)

						continue
					end

					break
				end

				return true
			end
		end

		Butterflies, Ryu_netClaimErrorText = Ryu_callButterflyRemote("Butterflies", "AskClaimNet")

		return Butterflies, Ryu_netClaimErrorText
	end
	Ryu_BloomRuntime.tradeUp = function()
		Ryu_BloomRuntime.snapshot()

		if not Ryu_BloomRuntime.canTrade() then
			return false, "nothing to trade up"
		end

		local ButterflyMachine, Ryu_butterflyMachineError = Ryu_visitButterflyStation("ButterflyMachine")

		if not ButterflyMachine then
			return false, Ryu_butterflyMachineError
		end

		local Ryu_butterflyTiersForTrade = Ryu_BloomRuntime.tiers()
		local ButterflyTradeRecipe = senaV4Config.ButterflyTradeRecipe
		local Ryu_returnToSafeArea_var1 = 0

		if ButterflyTradeRecipe == "Smart" then
			local Ryu_simulatedTierCounts = table.clone(Ryu_BloomRuntime.snap.counts)
			local Ryu_tradeUpError

			while true do
				if Ryu_returnToSafeArea_var1 < 50 then
					local Ryu_nextTradeTier = Ryu_BloomRuntime.smartNext(Ryu_simulatedTierCounts)

					if not Ryu_nextTradeTier then
						return true, Ryu_returnToSafeArea_var1
					end

					Ryu_BloomRuntime.status = "Trading up " .. Ryu_butterflyTiersForTrade[Ryu_nextTradeTier].name .. " for the essence"

					local Butterflies

					Butterflies, Ryu_tradeUpError = Ryu_callButterflyRemote("Butterflies", "AskTradeUp", Ryu_nextTradeTier)

					if not Butterflies then
						break
					end

					Ryu_returnToSafeArea_var1 += 1
					Ryu_simulatedTierCounts[Ryu_nextTradeTier] = (Ryu_simulatedTierCounts[Ryu_nextTradeTier] or 0) - Ryu_butterflyTiersForTrade[Ryu_nextTradeTier].trade

					local Ryu_nextTierAfterTrade = Ryu_BLOOM_TIERS[Ryu_butterflyTierOrder[Ryu_nextTradeTier] + 1]

					Ryu_simulatedTierCounts[Ryu_nextTierAfterTrade] = (Ryu_simulatedTierCounts[Ryu_nextTierAfterTrade] or 0) + 1
					task.wait(0.12)
				else
					return true, Ryu_returnToSafeArea_var1
				end
			end

			if Ryu_returnToSafeArea_var1 == 0 then
				return false, Ryu_tradeUpError or "the machine refused"
			end

			return true, Ryu_returnToSafeArea_var1
		end

		local Ryu_tradeRecipeError

		for i = 3, 1, -1 do
			local Ryu_butterflyTierForTrade = Ryu_BLOOM_TIERS[i]

			if ButterflyTradeRecipe ~= nil and ButterflyTradeRecipe ~= "All" and ButterflyTradeRecipe ~= Ryu_butterflyTierForTrade then
				continue
			end

			local Ryu_currentTierCount = Ryu_BloomRuntime.snap.counts[Ryu_butterflyTierForTrade] or 0
			local trade = Ryu_butterflyTiersForTrade[Ryu_butterflyTierForTrade].trade
			local exitTo

			while trade > 0 and trade <= Ryu_currentTierCount do
				Ryu_BloomRuntime.status = "Trading up " .. Ryu_butterflyTiersForTrade[Ryu_butterflyTierForTrade].name

				local Butterflies

				Butterflies, Ryu_tradeRecipeError = Ryu_callButterflyRemote("Butterflies", "AskTradeUp", Ryu_butterflyTierForTrade)

				if not Butterflies then
					exitTo = 1

					break
				end

				Ryu_returnToSafeArea_var1 += 1
				Ryu_currentTierCount -= trade
				task.wait(0.12)
			end

			if exitTo == 1 then
				if Ryu_returnToSafeArea_var1 == 0 then
					return false, Ryu_tradeRecipeError or "the machine refused"
				end
			end
		end

		return true, Ryu_returnToSafeArea_var1
	end
	Ryu_BloomRuntime.craft = function()
		Ryu_BloomRuntime.snapshot()

		local Ryu_canCraftResult, Ryu_craftMissingTier = Ryu_BloomRuntime.canCraft()

		if not Ryu_canCraftResult then
			local Ryu_butterflyTiersForCraft = Ryu_BloomRuntime.tiers()

			return false, "need more " .. tostring(Ryu_butterflyTiersForCraft and Ryu_butterflyTiersForCraft[Ryu_craftMissingTier] and Ryu_butterflyTiersForCraft[Ryu_craftMissingTier].name or Ryu_craftMissingTier)
		end

		local MutationShrine, Ryu_mutationShrineError = Ryu_visitButterflyStation("MutationShrine")

		if not MutationShrine then
			return false, Ryu_mutationShrineError
		end

		local Ryu_returnToSafeArea_var2 = 0
		local Ryu_craftErrorText

		while true do
			if Ryu_returnToSafeArea_var2 < 10 and Ryu_BloomRuntime.canCraft() then
				Ryu_BloomRuntime.status = "Crafting Enchanted Essence"

				local Butterflies

				Butterflies, Ryu_craftErrorText = Ryu_callButterflyRemote("Butterflies", "AskCraftEssence")

				if not Butterflies then
					break
				end

				Ryu_returnToSafeArea_var2 += 1
				task.wait(0.2)
				Ryu_BloomRuntime.snapshot()
			else
				return true, Ryu_returnToSafeArea_var2
			end
		end

		if Ryu_returnToSafeArea_var2 == 0 then
			return false, Ryu_craftErrorText or "the shrine refused"
		end

		return true, Ryu_returnToSafeArea_var2
	end
	Ryu_BloomRuntime.tierOptions = function()
		local Ryu_butterflyTiersForLabels = Ryu_BloomRuntime.tiers()
		local Ryu_bloomTierLabels = {}

		for i = #Ryu_BLOOM_TIERS, 1, -1 do
			local Ryu_tierForLabels = Ryu_BLOOM_TIERS[i]

			Ryu_bloomTierLabels[#Ryu_bloomTierLabels + 1] = Ryu_butterflyTiersForLabels and Ryu_butterflyTiersForLabels[Ryu_tierForLabels].name or Ryu_tierForLabels
		end

		return Ryu_bloomTierLabels
	end
	Ryu_BloomRuntime.tierFromLabel = function(tierLabel)
		local Ryu_butterflyTiersForLookup = Ryu_BloomRuntime.tiers()

		for _, v in ipairs(Ryu_BLOOM_TIERS) do
			if tierLabel == v or Ryu_butterflyTiersForLookup and Ryu_butterflyTiersForLookup[v].name == tierLabel then
				return v
			end
		end

		return nil
	end
	Ryu_BloomRuntime.setTiers = function(tierList)
		local butterflyTiers = {}
		local ipairs_ = ipairs
		local Ryu_tierLabelsToSet = type(tierList) == "table" and tierList or {}

		for _, v in ipairs_(Ryu_tierLabelsToSet) do
			local Ryu_resolvedTierKey = Ryu_BloomRuntime.tierFromLabel(tostring(v))

			if Ryu_resolvedTierKey then
				butterflyTiers[#butterflyTiers + 1] = Ryu_resolvedTierKey
			end
		end

		senaV4Config.ButterflyTiers = butterflyTiers
	end

	local Ryu_bloomRecipes = {
		"All Recipes",
		"For Essence (shortfall only)",
		"Emerald to Sapphire",
		"Sapphire to Amethyst",
		"Amethyst to Radiant"
	}
	local Ryu_bloomRecipeMap = {
		["For Essence (shortfall only)"] = "Smart",
		["Emerald to Sapphire"] = "Green",
		["Sapphire to Amethyst"] = "Blue",
		["Amethyst to Radiant"] = "Purple"
	}

	Ryu_BloomRuntime.recipeOptions = function()
		return Ryu_bloomRecipes
	end
	Ryu_BloomRuntime.setRecipe = function(recipeLabel)
		senaV4Config.ButterflyTradeRecipe = Ryu_bloomRecipeMap[tostring(recipeLabel)] or "All"
	end

	local Ryu_bloomModes = {
		"Tween to Butterfly",
		"Stand",
		"Zigzag",
		"Circle"
	}
	local Ryu_bloomModeMap = {
		["Tween to Butterfly"] = "Tween",
		Stand = "Stand",
		Zigzag = "Zigzag",
		Circle = "Circle"
	}

	Ryu_BloomRuntime.modeOptions = function()
		return Ryu_bloomModes
	end
	Ryu_BloomRuntime.setMode = function(modeLabel)
		senaV4Config.ButterflyCatchMode = Ryu_bloomModeMap[tostring(modeLabel)] or "Tween"
	end

	local Folder

	local function Ryu_clearBloomEsp()
		for k, card in pairs(Ryu_BloomRuntime.cards) do
			pcall(function()
				card.part:Destroy()
			end)
			Ryu_BloomRuntime.cards[k] = nil
		end

		if Folder then
			pcall(function()
				Folder:Destroy()
			end)
			Folder = nil
		end
	end
	local function Ryu_updateBloomEsp()
		local CurrentCamera = workspace.CurrentCamera

		if not CurrentCamera then
			return
		end

		if not Folder or not Folder.Parent then
			Folder = Instance.new("Folder")
			Folder.Name = "SenaBloomEsp"
			Folder.Parent = CurrentCamera
		end

		local Ryu_butterflyTiersForEsp = Ryu_BloomRuntime.tiers() or {}
		local Ryu_localRootForEsp = Ryu_getLocalRoot()
		local Ryu_activeCards = {}

		for _, v in ipairs(Ryu_getSwarmButterflies()) do
			local Ryu_bloomEspKey = ("%d_%d_%d"):format(v.pos.X, v.pos.Y, v.pos.Z)

			Ryu_activeCards[Ryu_bloomEspKey] = true

			local Ryu_bloomEspCard = Ryu_BloomRuntime.cards[Ryu_bloomEspKey]

			if not Ryu_bloomEspCard or not Ryu_bloomEspCard.part.Parent then
				local Part = Instance.new("Part")

				Part.Size = Vector3.new(0.2, 0.2, 0.2)
				Part.Anchored = true
				Part.CanCollide = false
				Part.CanQuery = false
				Part.CanTouch = false
				Part.Transparency = 1
				Part.Parent = Folder

				local BillboardGui = Instance.new("BillboardGui")

				BillboardGui.Adornee = Part
				BillboardGui.Size = UDim2.fromOffset(120, 20)
				BillboardGui.StudsOffsetWorldSpace = Vector3.new(0, 1.6, 0)
				BillboardGui.AlwaysOnTop = true
				BillboardGui.MaxDistance = 260
				BillboardGui.Parent = Part

				local TextLabel = Instance.new("TextLabel")

				TextLabel.Size = UDim2.fromScale(1, 1)
				TextLabel.BackgroundTransparency = 1
				TextLabel.Font = Enum.Font.GothamBold
				TextLabel.TextSize = 13
				TextLabel.TextStrokeTransparency = 0.35
				TextLabel.Parent = BillboardGui
				Ryu_bloomEspCard = {
					part = Part,
					label = TextLabel
				}
				Ryu_BloomRuntime.cards[Ryu_bloomEspKey] = Ryu_bloomEspCard
			end

			Ryu_bloomEspCard.part.CFrame = cFrameNew(v.pos)

			local Ryu_bloomTierData = Ryu_butterflyTiersForEsp[v.tier]

			Ryu_bloomEspCard.label.TextColor3 = Ryu_bloomTierData and Ryu_bloomTierData.color or Color3.new(1, 1, 1)

			local label = Ryu_bloomEspCard.label
			local Ryu_bloomEspLabel = Ryu_localRootForEsp

			if Ryu_bloomEspLabel then
				Ryu_bloomEspLabel = ("%s  %dm"):format(Ryu_bloomTierData and Ryu_bloomTierData.name or v.tier, math.floor((v.pos - Ryu_localRootForEsp.Position).Magnitude))
			end

			label.Text = Ryu_bloomEspLabel or Ryu_bloomTierData and Ryu_bloomTierData.name or v.tier
		end

		for k, card in pairs(Ryu_BloomRuntime.cards) do
			if not Ryu_activeCards[k] then
				pcall(function()
					card.part:Destroy()
				end)
				Ryu_BloomRuntime.cards[k] = nil
			end
		end
	end

	local Ryu_BloomCatcher

	Ryu_BloomCatcher = {
		target = nil,
		since = 0,
		swinging = false,
		skip = setmetatable({}, {
			__mode = "k"
		}),
		pos = function(model)
			if not model or not model.Parent then
				return nil
			end

			local ok, result = pcall(function()
				return model.PrimaryPart and model.PrimaryPart.Position or model:GetPivot().Position
			end)
			local Ryu_resolvedPos = ok and result or nil

			return Ryu_resolvedPos
		end,
		pick = function(originPos)
			local ButterflyBloomSwarm = workspace:FindFirstChild("ButterflyBloomSwarm")

			if not ButterflyBloomSwarm then
				return nil
			end

			local Ryu_activeTierFilter = Ryu_getTierFilterSet()
			local now = os.clock()
			local Ryu_bestButterfly
			local Ryu_bestButterflyScore

			for _, child in ipairs(ButterflyBloomSwarm:GetChildren()) do
				if child:IsA("Model") and Ryu_butterflyTierOrder[child.Name] and (not Ryu_activeTierFilter or Ryu_activeTierFilter[child.Name]) then
					if (Ryu_BloomCatcher.skip[child] or 0) <= now then
						local Ryu_butterflyPos = Ryu_BloomCatcher.pos(child)

						if Ryu_butterflyPos then
							local Ryu_butterflyScore = (Ryu_butterflyTierOrder[child.Name] == 4 and 1000000 or 0) - (Ryu_butterflyPos - originPos).Magnitude

							if not Ryu_bestButterflyScore or Ryu_bestButterflyScore < Ryu_butterflyScore then
								Ryu_bestButterfly = child
								Ryu_bestButterflyScore = Ryu_butterflyScore
							end
						end
					end
				end
			end

			return Ryu_bestButterfly
		end,
		gain = function()
			local ok, result = pcall(Ryu_getButterflyModules().Save.Peek)
			local Ryu_caughtDelta = ok and result and result.Butterflies and tonumber(result.Butterflies.TotalCaught)

			return Ryu_caughtDelta and Ryu_BloomRuntime.bloomBase and math.max(0, Ryu_caughtDelta - Ryu_BloomRuntime.bloomBase) or 0
		end
	}
	Ryu_BloomCatcher.swing = function(butterflyModel, originPos)
		if Ryu_BloomCatcher.swinging then
			return
		end

		local Ryu_swingCooldown = tonumber(Ryu_readButterflyFlag("SwingCooldownSeconds", 0.45)) or 0.45

		if os.clock() - Ryu_BloomRuntime.lastSwing < Ryu_swingCooldown then
			return
		end

		local Ryu_butterflySwarm = Ryu_getButterflyModules()

		if not Ryu_butterflySwarm or not Ryu_butterflySwarm.Swarm or not Ryu_butterflySwarm.Swarm.Nearest then
			return
		end

		local ok, result = pcall(Ryu_butterflySwarm.Swarm.Nearest, originPos, Vector3.new(0, 0, -1), 4)
		local Flight = ok and result and result.Flight

		if not Flight or not Flight.Id then
			return
		end

		if Flight.Tier ~= nil and tostring(Flight.Tier) ~= butterflyModel.Name then
			return
		end

		Ryu_BloomRuntime.lastSwing = os.clock()
		Ryu_BloomCatcher.swinging = true
		task.spawn(function()
			local _, _, Ryu_swingResult = Ryu_callButterflyRemote("Butterflies", "AskSwing", Flight.Id)

			Ryu_BloomCatcher.swinging = false

			if Ryu_swingResult ~= "Caught" and Ryu_swingResult ~= "Gone" then
				Ryu_BloomCatcher.skip[butterflyModel] = os.clock() + 1.5
			end

			if Ryu_BloomCatcher.target == butterflyModel then
				Ryu_BloomCatcher.target = nil
			end

			local Ryu_butterflyTiersForStatus = Ryu_BloomRuntime.tiers()

			Ryu_BloomRuntime.status = ("%s %s  ·  +%d this Bloom"):format(Ryu_swingResult == "Caught" and "Caught" or "Chasing", Ryu_butterflyTiersForStatus and Ryu_butterflyTiersForStatus[butterflyModel.Name] and Ryu_butterflyTiersForStatus[butterflyModel.Name].name or butterflyModel.Name, Ryu_BloomCatcher.gain())
		end)
	end
	Ryu_BloomCatcher.prepare = function()
		local Character = LocalPlayer.Character
		local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
		local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

		if not HumanoidRootPart or not Humanoid then
			return nil
		end

		Ryu_cleanupBloomPad()
		Ryu_purgeTrapsOnCharacter(Character)
		Ryu_startMovementLoop()
		Ryu_ensureHoverPad()

		local AutoRotate = Humanoid.AutoRotate

		Humanoid.AutoRotate = false

		return Character, HumanoidRootPart, Humanoid, AutoRotate
	end
	Ryu_BloomCatcher.release = function(rootPart, character, savedAutoRotate)
		Ryu_BloomCatcher.target = nil

		if character.Parent and savedAutoRotate ~= nil then
			character.AutoRotate = savedAutoRotate
		end

		rootPart.AssemblyLinearVelocity = Vector3.zero
		rootPart.AssemblyAngularVelocity = Vector3.zero
		Ryu_destroyHoverPad()
	end
	Ryu_BloomCatcher.keepGoing = function(rootPart, humanoid, mode)
		if not Ryu_isCurrentSession() or not senaV4Config.ButterflyAutoCatch or not (Ryu_BloomRuntime.bloomLeft() > 0) or not rootPart.Parent or not (humanoid.Health > 0) then
			return false
		end

		if (senaV4Config.ButterflyCatchMode or "Tween") == mode then
			return not (Ryu_BloomRuntime.manual or Ryu_isInEnchantedTree() or Ryu_isNightPhase() or Ryu_butterflyBlockers.blocker("butterfly") ~= nil)
		end

		return false
	end
	Ryu_BloomCatcher.moveStep = function(self, humanoid, rootPart, targetPos, lookAtPos, speed, dt)
		Ryu_setTargetWalkSpeed(self, speed * Ryu_CONFIG.HEADROOM)

		local Ryu_stealIntegrityState2 = Ryu_getEnv()[Ryu_CONFIG.INTEGRITY_KEY]
		local State = type(Ryu_stealIntegrityState2) == "table" and Ryu_stealIntegrityState2.State or nil

		if not Ryu_isOwnStateChecked(State, humanoid, rootPart) then
			rootPart.AssemblyLinearVelocity = Vector3.zero
			rootPart.AssemblyAngularVelocity = Vector3.zero
			Ryu_syncHoverPad(rootPart.Position)

			if Ryu_isOwnState(State, humanoid, rootPart) then
				Ryu_applyWalkSpeedToState(State, speed * Ryu_CONFIG.HEADROOM, Vector3.zero)
			else
				Ryu_installIntegritySpoof(humanoid, rootPart, speed)
			end

			return nil
		end

		local Position = rootPart.Position
		local Ryu_moveStepDelta = targetPos - Position
		local Ryu_moveStepDist = speed * dt
		local Ryu_moveStepNextPos = Ryu_moveStepDelta.Magnitude <= Ryu_moveStepDist and targetPos or Position + Ryu_moveStepDelta.Unit * Ryu_moveStepDist
		local Ryu_moveStepLookAt = (lookAtPos or targetPos) - Ryu_moveStepNextPos
		local vector32 = Vector3.new(Ryu_moveStepLookAt.X, 0, Ryu_moveStepLookAt.Z)

		if vector32.Magnitude <= 0.001 then
			vector32 = Vector3.new(Ryu_moveStepDelta.X, 0, Ryu_moveStepDelta.Z)
		end

		local Unit = vector32.Magnitude > 0.001 and vector32.Unit or rootPart.CFrame.LookVector
		local Ryu_moveStepVelocity = (Ryu_moveStepNextPos - Position) / dt

		Ryu_syncHoverPad(Ryu_moveStepNextPos)
		rootPart.CFrame = lookAt(Ryu_moveStepNextPos, Ryu_moveStepNextPos + Unit)
		rootPart.AssemblyLinearVelocity = Vector3.zero
		rootPart.AssemblyAngularVelocity = Vector3.zero

		if not Ryu_updateIntegritySpoof(humanoid, rootPart, speed, Ryu_moveStepVelocity) then
			Ryu_installIntegritySpoof(humanoid, rootPart, speed)
			Ryu_updateIntegritySpoof(humanoid, rootPart, speed, Ryu_moveStepVelocity)
		end

		return Ryu_moveStepNextPos
	end
	Ryu_BloomCatcher.nearest = function(originPos, maxDist)
		local ButterflyBloomSwarm = workspace:FindFirstChild("ButterflyBloomSwarm")

		if not ButterflyBloomSwarm then
			return nil
		end

		local Ryu_activeTierFilter2 = Ryu_getTierFilterSet()
		local now = os.clock()
		local Ryu_nearestButterfly
		local Ryu_nearestButterflyPos
		local Ryu_nearestSearchRadius = maxDist

		for _, child in ipairs(ButterflyBloomSwarm:GetChildren()) do
			if child:IsA("Model") and Ryu_butterflyTierOrder[child.Name] and (not Ryu_activeTierFilter2 or Ryu_activeTierFilter2[child.Name]) then
				if (Ryu_BloomCatcher.skip[child] or 0) <= now then
					local Ryu_butterflyPos2 = Ryu_BloomCatcher.pos(child)
					local Magnitude = Ryu_butterflyPos2 and (Ryu_butterflyPos2 - originPos).Magnitude

					if Magnitude and Magnitude <= Ryu_nearestSearchRadius then
						Ryu_nearestButterfly = child
						Ryu_nearestButterflyPos = Ryu_butterflyPos2
						Ryu_nearestSearchRadius = Magnitude
					end
				end
			end
		end

		return Ryu_nearestButterfly, Ryu_nearestButterflyPos
	end
	Ryu_BloomCatcher.cluster = function(originPos)
		local ButterflyBloomSwarm = workspace:FindFirstChild("ButterflyBloomSwarm")
		local Ryu_clusterPositions = {}
		local ipairs_ = ipairs
		local children = ButterflyBloomSwarm and ButterflyBloomSwarm:GetChildren() or {}

		for _, child in ipairs_(children) do
			if child:IsA("Model") and Ryu_butterflyTierOrder[child.Name] then
				local Ryu_clusterButterflyPos = Ryu_BloomCatcher.pos(child)

				if Ryu_clusterButterflyPos then
					Ryu_clusterPositions[#Ryu_clusterPositions + 1] = Ryu_clusterButterflyPos
				end
			end
		end

		if #Ryu_clusterPositions == 0 then
			return nil, 0, 0
		end

		local Ryu_gain_var1 = 0

		for _, v in ipairs(Ryu_clusterPositions) do
			if originPos and (v - originPos).Magnitude <= 24 then
				Ryu_gain_var1 += 1
			end
		end

		local Ryu_clusterBestCenter
		local Ryu_clusterBestScore

		for _, v in ipairs(Ryu_clusterPositions) do
			local vector32 = Vector3.zero
			local Ryu_gain_var2 = 0

			for _, Ryu_item in ipairs(Ryu_clusterPositions) do
				if (v - Ryu_item).Magnitude <= 24 then
					vector32 += Ryu_item
					Ryu_gain_var2 += 1
				end
			end

			local Ryu_clusterAvgPos = vector32 / Ryu_gain_var2
			local Ryu_clusterScore = Ryu_gain_var2 * 100 - (originPos and (Ryu_clusterAvgPos - originPos).Magnitude or 0)

			if not Ryu_clusterBestScore or Ryu_clusterBestScore < Ryu_clusterScore then
				Ryu_clusterBestCenter = Ryu_clusterAvgPos
				Ryu_clusterBestScore = Ryu_clusterScore
			end
		end

		return Ryu_clusterBestCenter, #Ryu_clusterPositions, Ryu_gain_var1
	end
	Ryu_BloomCatcher.route = function(mode, centerPos, elapsedTime)
		if mode == "Circle" then
			local Ryu_routeAngle = elapsedTime * 2.0833333333333335

			return centerPos + Vector3.new(math.cos(Ryu_routeAngle) * 24, 0, math.sin(Ryu_routeAngle) * 24)
		end

		local Ryu_routeBounds = Ryu_getBloomBounds()

		if not (mode == "Zigzag" and Ryu_routeBounds) then
			return centerPos
		end

		local Ryu_routeHalfWidth = math.max(Ryu_routeBounds.Size.X / 2 - 12, 20)
		local Ryu_routeHalfDepth = math.clamp(Ryu_routeBounds.Size.Z / 2 - 12, 8, 30)
		local Ryu_routePhase = elapsedTime * 80 / math.sqrt((2 * Ryu_routeHalfWidth / 8) ^ 2 + (2 * Ryu_routeHalfDepth) ^ 2) % 16
		local Ryu_routeSector = math.floor(Ryu_routePhase)
		local Ryu_routeSectorFrac = Ryu_routePhase - Ryu_routeSector
		local Ryu_routeSideA = Ryu_routeSector <= 8 and Ryu_routeSector or 16 - Ryu_routeSector
		local Ryu_routeSideB = Ryu_routeSector + 1 <= 8 and Ryu_routeSector + 1 or 16 - (Ryu_routeSector + 1)
		local Ryu_routeX = -Ryu_routeHalfWidth + Ryu_routeSideA * (2 * Ryu_routeHalfWidth / 8)
		local Ryu_routeZ = Ryu_routeSector % 2 == 0 and -Ryu_routeHalfDepth or Ryu_routeHalfDepth
		local Ryu_routeWorldOffset = Ryu_routeBounds.CFrame:VectorToWorldSpace(Vector3.new(Ryu_routeX + (-Ryu_routeHalfWidth + Ryu_routeSideB * (2 * Ryu_routeHalfWidth / 8) - Ryu_routeX) * Ryu_routeSectorFrac, 0, Ryu_routeZ + (((Ryu_routeSector + 1) % 2 == 0 and -Ryu_routeHalfDepth or Ryu_routeHalfDepth) - Ryu_routeZ) * Ryu_routeSectorFrac))

		return Vector3.new(Ryu_routeBounds.Position.X + Ryu_routeWorldOffset.X, centerPos.Y, Ryu_routeBounds.Position.Z + Ryu_routeWorldOffset.Z)
	end
	Ryu_BloomCatcher.patrol = function(mode)
		local Ryu_patrolSelf, Ryu_patrolRoot, Ryu_patrolHumanoid, Ryu_patrolAutoRotate = Ryu_BloomCatcher.prepare()

		if not Ryu_patrolSelf then
			return false
		end

		local Ryu_patrolNetReach = tonumber(Ryu_readButterflyFlag("NetReach", 14)) or 14
		local Ryu_patrolLabel = ({
			Stand = "Standing in the swarm",
			Zigzag = "Zigzag patrol",
			Circle = "Circling the swarm"
		})[mode] or mode
		local Ryu_patrolClusterCenter
		local Ryu_gain_var3 = 0
		local now = os.clock()
		local Ryu_patrolEmptySince
		local Ryu_patrolMoved = false
		local Ryu_gain_var4 = 0

		while Ryu_BloomCatcher.keepGoing(Ryu_patrolRoot, Ryu_patrolHumanoid, mode) do
			local Ryu_patrolFrameDelta = math.max(math.min(RunService.Heartbeat:Wait(), 0.15), 0.0041666666666666666)
			local now2 = os.clock()

			if Ryu_gain_var3 <= now2 then
				local Ryu_patrolClusterPos, Ryu_patrolClusterCount, Ryu_patrolClusterNearby = Ryu_BloomCatcher.cluster(Ryu_patrolClusterCenter)

				Ryu_gain_var3 = now2 + 1.5

				if Ryu_patrolClusterCount == 0 then
					Ryu_patrolEmptySince = Ryu_patrolEmptySince or now2
				else
					Ryu_patrolEmptySince = nil

					if mode == "Stand" then
						if not Ryu_patrolClusterCenter or Ryu_patrolClusterNearby < 3 then
							Ryu_patrolClusterCenter = Ryu_patrolClusterPos
						end
					else
						Ryu_patrolClusterCenter = Ryu_patrolClusterCenter and Ryu_patrolClusterCenter:Lerp(Ryu_patrolClusterPos, 0.5) or Ryu_patrolClusterPos
					end
				end
			end

			if Ryu_patrolEmptySince and now2 - Ryu_patrolEmptySince > 2 then
				break
			end

			if Ryu_patrolClusterCenter then
				Ryu_patrolMoved = true

				local Ryu_patrolRouteTarget = Ryu_BloomCatcher.route(mode, Ryu_patrolClusterCenter, now2 - now)
				local huge = (Ryu_patrolRouteTarget - Ryu_patrolRoot.Position).Magnitude > 40 and math.huge or mode == "Stand" and 60 or mode == "Circle" and 70 or 110
				local Ryu_patrolSpeed = math.clamp(math.min(Ryu_getTweenSpeed(), huge), Ryu_CONFIG.MIN_SPEED, Ryu_CONFIG.MAX_SPEED)
				local Ryu_patrolNearestButterfly, Ryu_patrolNearestPos = Ryu_BloomCatcher.nearest(Ryu_patrolRoot.Position, Ryu_patrolNetReach + 6)
				local Ryu_patrolMovedPos = Ryu_BloomCatcher.moveStep(Ryu_patrolSelf, Ryu_patrolHumanoid, Ryu_patrolRoot, Ryu_patrolRouteTarget, Ryu_patrolNearestPos, Ryu_patrolSpeed, Ryu_patrolFrameDelta)

				if Ryu_patrolMovedPos and Ryu_patrolNearestButterfly and (Ryu_patrolNearestPos - Ryu_patrolMovedPos).Magnitude <= Ryu_patrolNetReach - 1.5 then
					Ryu_BloomCatcher.swing(Ryu_patrolNearestButterfly, Ryu_patrolNearestPos)
				end

				if Ryu_gain_var4 <= now2 and not Ryu_BloomCatcher.swinging then
					Ryu_gain_var4 = now2 + 1
					Ryu_BloomRuntime.status = ("%s  ·  +%d this Bloom"):format(Ryu_patrolLabel, Ryu_BloomCatcher.gain())
				end
			else
				Ryu_patrolRoot.AssemblyLinearVelocity = Vector3.zero
				Ryu_patrolRoot.AssemblyAngularVelocity = Vector3.zero
				Ryu_syncHoverPad(Ryu_patrolRoot.Position)
			end
		end

		Ryu_BloomCatcher.release(Ryu_patrolRoot, Ryu_patrolHumanoid, Ryu_patrolAutoRotate)

		return Ryu_patrolMoved
	end
	Ryu_BloomCatcher.run = function()
		local Ryu_huntSelf, Ryu_huntRoot, Ryu_huntHumanoid, Ryu_huntAutoRotate = Ryu_BloomCatcher.prepare()

		if not Ryu_huntSelf then
			return false
		end

		local Ryu_huntNetReach = tonumber(Ryu_readButterflyFlag("NetReach", 14)) or 14
		local Ryu_huntDodgeRadius = math.min(Ryu_huntNetReach - 3, (tonumber(Ryu_readButterflyFlag("DodgeRadius", 9)) or 9) + 1)
		local now
		local Ryu_huntMoved = false

		while Ryu_BloomCatcher.keepGoing(Ryu_huntRoot, Ryu_huntHumanoid, "Tween") do
			local Ryu_huntFrameDelta = math.max(math.min(RunService.Heartbeat:Wait(), 0.15), 0.0041666666666666666)
			local target = Ryu_BloomCatcher.target
			local Ryu_huntTargetPos = Ryu_BloomCatcher.pos(target)

			if not Ryu_huntTargetPos or os.clock() - Ryu_BloomCatcher.since > 3 then
				if Ryu_huntTargetPos then
					Ryu_BloomCatcher.skip[target] = os.clock() + 2
				end

				target = Ryu_BloomCatcher.pick(Ryu_huntRoot.Position)

				local now2 = os.clock()

				Ryu_BloomCatcher.target = target
				Ryu_BloomCatcher.since = now2
				Ryu_huntTargetPos = Ryu_BloomCatcher.pos(target)

				if target then
					local Ryu_huntTiersForStatus = Ryu_BloomRuntime.tiers()

					Ryu_BloomRuntime.status = ("Chasing %s  ·  +%d this Bloom"):format(Ryu_huntTiersForStatus and Ryu_huntTiersForStatus[target.Name] and Ryu_huntTiersForStatus[target.Name].name or target.Name, Ryu_BloomCatcher.gain())
				end
			end

			if Ryu_huntTargetPos then
				now = nil
				Ryu_huntMoved = true

				local Ryu_huntSpeed = math.clamp(Ryu_getTweenSpeed(), Ryu_CONFIG.MIN_SPEED, Ryu_CONFIG.MAX_SPEED)
				local Ryu_huntDelta = Ryu_huntRoot.Position - Ryu_huntTargetPos
				local Ryu_huntMovedPos = Ryu_BloomCatcher.moveStep(Ryu_huntSelf, Ryu_huntHumanoid, Ryu_huntRoot, Ryu_huntDelta.Magnitude > 0.001 and Ryu_huntTargetPos + Ryu_huntDelta.Unit * Ryu_huntDodgeRadius or Ryu_huntTargetPos + Vector3.new(Ryu_huntDodgeRadius, 0, 0), Ryu_huntTargetPos, Ryu_huntSpeed, Ryu_huntFrameDelta)

				if Ryu_huntMovedPos and (Ryu_huntTargetPos - Ryu_huntMovedPos).Magnitude <= Ryu_huntNetReach - 1.5 then
					Ryu_BloomCatcher.swing(target, Ryu_huntTargetPos)
				end

				continue
			else
				now = now or os.clock()

				if not (os.clock() - now > 2) then
					Ryu_huntRoot.AssemblyLinearVelocity = Vector3.zero
					Ryu_huntRoot.AssemblyAngularVelocity = Vector3.zero
					Ryu_syncHoverPad(Ryu_huntRoot.Position)

					continue
				end
			end

			break
		end

		Ryu_BloomCatcher.release(Ryu_huntRoot, Ryu_huntHumanoid, Ryu_huntAutoRotate)

		return Ryu_huntMoved
	end

	local function Ryu_processBloomTick(snapshot)
		if Ryu_isInEnchantedTree() then
			Ryu_exitEnchantedTree()

			return
		end

		if not Ryu_isInBloomZone() then
			Ryu_cleanupBloomPad()

			if Ryu_isNightPhase() then
				Ryu_BloomRuntime.status = "Night - waiting to fly to the forest"

				return
			end

			if not Ryu_canRetry("area") then
				return
			end

			local Ryu_bloomZoneCenter = Ryu_getBloomZoneCenter()

			if not Ryu_bloomZoneCenter then
				Ryu_BloomRuntime.status = "Butterfly Bloom zone not found"
				Ryu_markRetryAt("area")

				return
			end

			Ryu_BloomRuntime.status = "Flying to the Butterfly Bloom"

			if not Ryu_travelToBloomZone(Ryu_bloomZoneCenter, 60) then
				Ryu_markRetryAt("area")
				Ryu_BloomRuntime.status = "Could not reach the Enchanted Forest"
			end

			return
		end

		local __oxioTreadmillManager = genv.__oxioTreadmillManager

		if __oxioTreadmillManager and __oxioTreadmillManager.activeTreadmill ~= nil then
			Ryu_leaveTreadmill()
		end

		if not snapshot.holding and not Ryu_equipNetTool() then
			Ryu_BloomRuntime.status = "Butterfly Net is not in your backpack"

			return
		end

		local ButterflyCatchMode = senaV4Config.ButterflyCatchMode or "Tween"
		local Ryu_huntResult

		if ButterflyCatchMode == "Tween" then
			Ryu_huntResult = Ryu_BloomCatcher.run()
		else
			Ryu_huntResult = Ryu_BloomCatcher.patrol(ButterflyCatchMode)
		end

		if not Ryu_huntResult then
			Ryu_updateBloomPad()
			Ryu_BloomRuntime.status = ("Waiting for butterflies  ·  +%d this Bloom"):format(Ryu_BloomCatcher.gain())
		end
	end
	local function Ryu_bloomStatusText(snapshot)
		if not snapshot.net then
			return snapshot.treeUnlocked and "No Butterfly Net yet" or "Enchanted Tree locked - finish the Wisp Event"
		end

		if snapshot.active then
			return "Bloom is live"
		end

		if snapshot.nextIn then
			return ("Next Bloom in %dm %02ds"):format(math.floor(snapshot.nextIn / 60), math.floor(snapshot.nextIn % 60))
		end

		return "Idle"
	end
	local function Ryu_processBloomState()
		if Ryu_BloomRuntime.manual then
			return
		end

		local Ryu_bloomSnapshot = Ryu_BloomRuntime.snapshot()

		if Ryu_bloomSnapshot.active then
			Ryu_BloomRuntime.bloomBase = Ryu_BloomRuntime.bloomBase or Ryu_bloomSnapshot.caught
		else
			Ryu_BloomRuntime.bloomBase = nil
		end

		if senaV4Config.ButterflyEsp and Ryu_bloomSnapshot.active then
			Ryu_updateBloomEsp()
		elseif next(Ryu_BloomRuntime.cards) or Folder then
			Ryu_clearBloomEsp()
		end

		local Ryu_task

		if senaV4Config.ButterflyAutoNet and not Ryu_bloomSnapshot.net and Ryu_bloomSnapshot.treeUnlocked and Ryu_canRetry("net") then
			Ryu_task = "net"
		elseif senaV4Config.ButterflyAutoCatch and Ryu_bloomSnapshot.active and Ryu_bloomSnapshot.net then
			Ryu_task = "catch"
		elseif not Ryu_bloomSnapshot.active and senaV4Config.ButterflyAutoTrade and Ryu_bloomSnapshot.net and Ryu_BloomRuntime.canTrade() and Ryu_canRetry("trade") then
			Ryu_task = "trade"
		elseif not Ryu_bloomSnapshot.active and senaV4Config.ButterflyAutoCraft and Ryu_bloomSnapshot.net and Ryu_BloomRuntime.canCraft() and Ryu_canRetry("craft") then
			Ryu_task = "craft"
		end

		Ryu_BloomRuntime.wantsCharacter = Ryu_task ~= nil

		local butterfly = Ryu_task and Ryu_butterflyBlockers.blocker("butterfly") or nil
		local butterfly2 = Ryu_task and not butterfly and Ryu_butterflyBlockers.holder("butterfly") or nil
		local active = Ryu_BloomRuntime.active

		Ryu_BloomRuntime.active = Ryu_task ~= nil and butterfly == nil and butterfly2 == nil

		if Ryu_task and not Ryu_BloomRuntime.active then
			Ryu_cleanupBloomPad()

			if butterfly and Ryu_isInEnchantedTree() then
				Ryu_BloomRuntime.status = "Leaving the tree for " .. Ryu_butterflyBlockers.TITLES[butterfly]
				Ryu_exitEnchantedTree()
			end

			Ryu_BloomRuntime.status = butterfly and "Yielding to " .. Ryu_butterflyBlockers.TITLES[butterfly] or "Waiting for " .. Ryu_butterflyBlockers.TITLES[butterfly2] .. " to hand over"

			return
		end

		if not Ryu_task then
			if active then
				Ryu_returnToSafeArea()
			end

			Ryu_cleanupBloomPad()
			Ryu_BloomRuntime.status = Ryu_bloomStatusText(Ryu_bloomSnapshot)

			return
		end

		if not active then
			Ryu_leaveTreadmill()
		end

		if Ryu_task == "net" then
			local Ryu_netClaimOk, Ryu_netClaimErr = Ryu_BloomRuntime.claimNet()
			local status = Ryu_netClaimOk and "Butterfly Net claimed"

			if not status then
				status = "Net: " .. tostring(Ryu_netClaimErr or "refused")
			end

			Ryu_BloomRuntime.status = status

			if not Ryu_netClaimOk then
				Ryu_markRetryAt("net")
			end
		elseif Ryu_task == "catch" then
			Ryu_processBloomTick(Ryu_bloomSnapshot)
		elseif Ryu_task == "trade" then
			local status, Ryu_tradeCount = Ryu_BloomRuntime.tradeUp()

			if status then
				status = ("Traded up %d time(s)"):format(tonumber(Ryu_tradeCount) or 0)
			end

			Ryu_BloomRuntime.status = status or "Trade: " .. tostring(Ryu_tradeCount)
			Ryu_markRetryAt("trade")
		elseif Ryu_task == "craft" then
			local status, Ryu_craftCount = Ryu_BloomRuntime.craft()

			if status then
				status = ("Crafted %d Enchanted Essence"):format(tonumber(Ryu_craftCount) or 0)
			end

			Ryu_BloomRuntime.status = status or "Craft: " .. tostring(Ryu_craftCount)
			Ryu_markRetryAt("craft")
		end
	end

	task.spawn(function()
		while Ryu_isCurrentSession() do
			local ok, result = pcall(Ryu_processBloomState)

			if not ok then
				Ryu_BloomRuntime.active = false
				Ryu_BloomRuntime.wantsCharacter = false
				Ryu_cleanupBloomPad()
				Ryu_BloomRuntime.status = "Error: " .. tostring(result)
				task.wait(1)
			end

			task.wait(0.2)
		end

		Ryu_cleanupBloomPad()
		Ryu_clearBloomEsp()
	end)
	genv.__oxioButterflyRuntime = Ryu_BloomRuntime
end

Ryu_butterflyFactory()

local function Ryu_getIsBatKeywords()
	local Ryu_getIsBatKeywords_var1

	local function Ryu_getBatKeywordSet()
		if Ryu_getIsBatKeywords_var1 then
			return Ryu_getIsBatKeywords_var1
		end

		local Ryu_batKeywords = {}

		pcall(function()
			for _, child in ipairs(ReplicatedStorage.Data.Gears.Configs:GetChildren()) do
				local ok, result = pcall(require, child)

				if ok and type(result) == "table" and type(result.BatControllerData) == "table" then
					for _, v in ipairs({
						child.Name,
						result._id,
						result.DisplayName,
						result.ToolModel
					}) do
						if type(v) == "string" then
							Ryu_batKeywords[v:lower()] = true
						end
					end
				end
			end
		end)

		if next(Ryu_batKeywords) then
			Ryu_getIsBatKeywords_var1 = Ryu_batKeywords
		end

		return Ryu_batKeywords
	end
	local function Ryu_isBatToolCheck(tool)
		if not tool or not tool:IsA("Tool") then
			return false
		end

		if tool:GetAttribute("IsBat") == true then
			return true
		end

		local attribute = tool:GetAttribute("ItemType")

		if attribute ~= nil and attribute ~= "Gear" then
			return false
		end

		local Ryu_batKeywordSet = Ryu_getBatKeywordSet()
		local Ryu_toolGearName = tostring(tool:GetAttribute("GearName") or ""):lower()
		local Ryu_toolCleanName = tostring(tool.Name or ""):gsub("%s*%[.-%]%s*$", ""):lower()

		if Ryu_batKeywordSet[Ryu_toolGearName] or Ryu_batKeywordSet[Ryu_toolCleanName] then
			return true
		end

		return attribute == "Gear" and (Ryu_toolGearName:find("bat", 1, true) ~= nil or Ryu_toolCleanName:find("bat", 1, true) ~= nil)
	end

	return Ryu_isBatToolCheck
end

genv.__oxioIsBatTool = Ryu_getIsBatKeywords()

do
	local Players2 = game:GetService("Players")
	local RunService2 = game:GetService("RunService")
	local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
	local LocalPlayer2 = Players2.LocalPlayer
	local Ryu_AutoCapture = {
		pinConn = nil,
		holding = false,
		status = "Idle"
	}

	local function Ryu_getEggStateModule()
		local ok, result = pcall(require, ReplicatedStorage2.Client.EggState)

		return ok and result or nil
	end
	local function Ryu_getRemotesModule()
		local ok, result = pcall(require, ReplicatedStorage2.Shared.Remotes)

		return ok and result or nil
	end
	local function Ryu_getAreaEggStates()
		local ok, result = pcall(require, ReplicatedStorage2.Shared.Types.AreaEggs)

		return ok and result and result.States or nil
	end
	local function Ryu_getCaptureRoot()
		local Character = LocalPlayer2.Character

		return Character and Character:FindFirstChild("HumanoidRootPart")
	end
	local function Ryu_getCaptureHumanoid()
		local Character = LocalPlayer2.Character

		return Character and Character:FindFirstChildOfClass("Humanoid")
	end
	local function Ryu_getCaptureEggUid()
		return workspace:GetAttribute("Event_CaptureTheEggUid")
	end
	local function Ryu_getCaptureRecord(uid)
		if not uid then
			return nil
		end

		local Ryu_eggStateModule = Ryu_getEggStateModule()

		if not Ryu_eggStateModule then
			return nil
		end

		local ok, result = pcall(Ryu_eggStateModule.ReadFieldEgg, uid)

		return ok and result or nil
	end
	local function Ryu_isEggCarriedByMe(uid, record)
		local Ryu_captureEggState = record or Ryu_getCaptureRecord(uid)
		local Ryu_captureEggStates = Ryu_getAreaEggStates()

		if Ryu_captureEggState and Ryu_captureEggStates then
			return Ryu_captureEggState.State == Ryu_captureEggStates.Carried and Ryu_captureEggState.CarrierUserId == LocalPlayer2.UserId
		end

		return false
	end
	local function Ryu_isEggSlotOrDropped(record)
		local Ryu_captureEggStates2 = Ryu_getAreaEggStates()

		if record and Ryu_captureEggStates2 then
			return record.State == Ryu_captureEggStates2.Slot or record.State == Ryu_captureEggStates2.Dropped
		end

		return false
	end
	local function Ryu_destroyCapturePlatform()
		local SenaCapturePlatform = workspace:FindFirstChild("SenaCapturePlatform")

		if SenaCapturePlatform then
			pcall(function()
				SenaCapturePlatform:Destroy()
			end)
		end
	end
	local function Ryu_updateCapturePlatform(rootPart)
		local Ryu_captureRootPos = rootPart or Ryu_getCaptureRoot()

		if not Ryu_captureRootPos then
			return
		end

		local SenaCapturePlatform = workspace:FindFirstChild("SenaCapturePlatform")

		if not SenaCapturePlatform then
			SenaCapturePlatform = Instance.new("Part")
			SenaCapturePlatform.Name = "SenaCapturePlatform"
			SenaCapturePlatform.Anchored = true
			SenaCapturePlatform.CanCollide = true
			SenaCapturePlatform.Size = Vector3.new(30, 1, 30)
			SenaCapturePlatform.Transparency = 0.5
			SenaCapturePlatform.Material = Enum.Material.Neon
			SenaCapturePlatform.Color = Color3.fromRGB(130, 90, 255)
			SenaCapturePlatform.TopSurface = Enum.SurfaceType.Smooth
			SenaCapturePlatform.BottomSurface = Enum.SurfaceType.Smooth
			SenaCapturePlatform.Parent = workspace
		end

		SenaCapturePlatform.CFrame = cFrameNew(Ryu_captureRootPos.Position.X, Ryu_captureRootPos.Position.Y - 3.4, Ryu_captureRootPos.Position.Z)
	end
	local function Ryu_startCapturePinLoop()
		if Ryu_AutoCapture.pinConn then
			return
		end

		Ryu_AutoCapture.pinConn = RunService2.PreSimulation:Connect(function()
			if not senaV4Config.AutoStealCapture then
				return
			end

			local Ryu_captureRootRef = Ryu_getCaptureRoot()

			if not Ryu_captureRootRef then
				return
			end

			if Ryu_captureRootRef.Position.Y < 89 then
				Ryu_captureRootRef.CFrame = cFrameNew(Ryu_captureRootRef.Position.X, 90, Ryu_captureRootRef.Position.Z) * Ryu_captureRootRef.CFrame.Rotation
			end

			Ryu_captureRootRef.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
			Ryu_captureRootRef.AssemblyAngularVelocity = Vector3.zero
			Ryu_updateCapturePlatform(Ryu_captureRootRef)
		end)
	end
	local function Ryu_stopCapturePin()
		if Ryu_AutoCapture.pinConn then
			pcall(function()
				Ryu_AutoCapture.pinConn:Disconnect()
			end)
			Ryu_AutoCapture.pinConn = nil
		end

		Ryu_destroyCapturePlatform()
	end
	local function Ryu_flyToCaptureEgg(uid, record)
		local Ryu_captureRoot = Ryu_getCaptureRoot()
		local Ryu_captureHumanoid = Ryu_getCaptureHumanoid()

		if not Ryu_captureRoot or not Ryu_captureHumanoid or not record or not record.BottomCFrame then
			return false
		end

		Ryu_stopCapturePin()

		local Ryu_captureEggPos = record.BottomCFrame.Position + Vector3.new(0, 3, 0)

		Ryu_AutoCapture.status = "Flying to capture egg"
		pcall(Ryu_glideTo, Ryu_captureRoot, Ryu_captureHumanoid, cFrameNew(Ryu_captureEggPos) * Ryu_captureRoot.CFrame.Rotation, function()
			return not senaV4Config.AutoStealCapture or Ryu_getCaptureEggUid() ~= uid or Ryu_isEggCarriedByMe(uid)
		end)

		local Ryu_captureRootAfterFly = Ryu_getCaptureRoot()

		if not Ryu_captureRootAfterFly then
			return false
		end

		pcall(function()
			Ryu_captureRootAfterFly.AssemblyLinearVelocity = Vector3.zero
			Ryu_captureRootAfterFly.AssemblyAngularVelocity = Vector3.zero
		end)

		local Ryu_captureRemotes = Ryu_getRemotesModule()

		if not Ryu_captureRemotes or not Ryu_captureRemotes.EggWorld or not Ryu_captureRemotes.EggWorld.AskFieldEggCarry then
			return false
		end

		Ryu_AutoCapture.status = "Grabbing capture egg"

		local ok, result = pcall(function()
			return Ryu_captureRemotes.EggWorld.AskFieldEggCarry:InvokeServer({
				Uid = uid
			})
		end)
		local Ryu_captureOk = ok and result == true

		return Ryu_captureOk
	end

	task.spawn(function()
		while Ryu_isCurrentSession() do
			if senaV4Config.AutoStealCapture then
				if not pcall(function()
					local Ryu_captureEggUid = Ryu_getCaptureEggUid()
					local Ryu_captureEggRecord = Ryu_getCaptureRecord(Ryu_captureEggUid)

					if Ryu_captureEggUid and Ryu_isEggCarriedByMe(Ryu_captureEggUid, Ryu_captureEggRecord) then
						Ryu_AutoCapture.holding = true
						Ryu_AutoCapture.status = "Holding capture egg"
						Ryu_startCapturePinLoop()
					elseif Ryu_captureEggUid and Ryu_isEggSlotOrDropped(Ryu_captureEggRecord) then
						Ryu_AutoCapture.holding = false
						Ryu_flyToCaptureEgg(Ryu_captureEggUid, Ryu_captureEggRecord)
					elseif not Ryu_captureEggUid then
						Ryu_AutoCapture.holding = false

						if Ryu_AutoCapture.pinConn or workspace:FindFirstChild("SenaCapturePlatform") then
							Ryu_stopCapturePin()
						end

						Ryu_AutoCapture.status = "No capture event"
					elseif Ryu_AutoCapture.holding then
						Ryu_startCapturePinLoop()
						Ryu_AutoCapture.status = "Egg taken - holding position"
					else
						if Ryu_AutoCapture.pinConn or workspace:FindFirstChild("SenaCapturePlatform") then
							Ryu_stopCapturePin()
						end

						Ryu_AutoCapture.status = "Waiting for capture egg"
					end
				end) then
					Ryu_stopCapturePin()
				end

				task.wait(0.3)
			else
				if Ryu_AutoCapture.pinConn or workspace:FindFirstChild("SenaCapturePlatform") then
					Ryu_stopCapturePin()
				end

				Ryu_AutoCapture.holding = false
				Ryu_AutoCapture.status = "Idle"
				task.wait(0.5)
			end
		end
	end)
	genv.__oxioAutoCapture = Ryu_AutoCapture
end

do
	local Players2 = game:GetService("Players")
	local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
	local LocalPlayer2 = Players2.LocalPlayer

	local function Ryu_getSaveModule()
		local ok, result = pcall(require, ReplicatedStorage2.Shared.Save)

		return ok and result or nil
	end
	local function Ryu_getAssetsDirectory()
		local ok, result = pcall(require, ReplicatedStorage2.Data.Assets)

		if ok then
			return result.Directory or result
		end

		return nil
	end
	local function Ryu_genVisualId(kind)
		return "SENAVIS_" .. kind .. "_" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1, 1000000))
	end

	local Ryu_VisualSAE = {
		held = {},
		categories = function(category)
			local Ryu_assetsDirectory = Ryu_getAssetsDirectory()
			local Ryu_categories_var1 = {}

			if not Ryu_assetsDirectory then
				return Ryu_categories_var1
			end

			for k, v in pairs(Ryu_assetsDirectory) do
				if type(k) == "string" and type(v) == "table" and (category == "Pet" or v.Egg ~= nil) then
					Ryu_categories_var1[#Ryu_categories_var1 + 1] = k
				end
			end

			table.sort(Ryu_categories_var1)

			return Ryu_categories_var1
		end,
		spawnEgg = function(eggCategory, size)
			local Ryu_saveModule = Ryu_getSaveModule()
			local Ryu_assetsDirectory2 = Ryu_getAssetsDirectory()

			if not Ryu_saveModule or not Ryu_assetsDirectory2 or not Ryu_assetsDirectory2[eggCategory] then
				return nil
			end

			local Ryu_visualEggId = Ryu_genVisualId("E")

			pcall(function()
				Ryu_saveModule.Amend("EggInventory", function(eggInventory)
					eggInventory[Ryu_visualEggId] = {
						AssetCategory = eggCategory,
						AssetScale = tonumber(size) or 50,
						AssetColorIndex = 1,
						AssetColorSeed = math.random(1, 2e9),
						AssetEyeColor = "ffffff",
						HasParasite = false,
						Mutations = {}
					}
				end)
			end)

			return Ryu_visualEggId
		end,
		spawnPet = function(petCategory, petSize)
			local Ryu_saveModuleForPet = Ryu_getSaveModule()
			local Ryu_assetsDirectoryForPet = Ryu_getAssetsDirectory()

			if not Ryu_saveModuleForPet or not Ryu_assetsDirectoryForPet or not Ryu_assetsDirectoryForPet[petCategory] then
				return nil
			end

			local Ryu_visualPetId = Ryu_genVisualId("P")

			pcall(function()
				Ryu_saveModuleForPet.Amend("Inventory", function(petInventory)
					petInventory[Ryu_visualPetId] = {
						Category = petCategory,
						Scale = tonumber(petSize) or 50,
						ColorIndex = 1,
						ColorSeed = math.random(1, 2e9),
						EyeColor = "ffffff",
						Gender = "Male",
						Personality = "Normal",
						InFuse = false,
						HasBeenFirstPlaced = false,
						Mutations = {}
					}
				end)
			end)

			return Ryu_visualPetId
		end
	}

	local function Ryu_findEggModel(eggCategory)
		local Assets = ReplicatedStorage2:FindFirstChild("Assets")
		local Models = Assets and Assets:FindFirstChild("Models")
		local Eggs = Models and Models:FindFirstChild("Eggs")

		return Eggs and Eggs:FindFirstChild(eggCategory)
	end
	local function Ryu_findAssetModel(assetCategory)
		local AssetModels = ReplicatedStorage2:FindFirstChild("AssetModels")

		return AssetModels and AssetModels:FindFirstChild(assetCategory)
	end
	local function Ryu_clearHeldVisuals()
		for _, v in ipairs(Ryu_VisualSAE.held) do
			pcall(function()
				v:Destroy()
			end)
		end

		Ryu_VisualSAE.held = {}

		for _, v in ipairs({
			LocalPlayer2.Character,
			LocalPlayer2:FindFirstChild("Backpack")
		}) do
			if v then
				for _, child in ipairs(v:GetChildren()) do
					if child:IsA("Tool") then
						if child.Name:sub(1, 8) == "SENAVIS_" then
							pcall(function()
								child:Destroy()
							end)
						end
					end
				end
			end
		end
	end

	Ryu_VisualSAE.hold = function(category, isEgg, visualSize)
		local Character = LocalPlayer2.Character

		if not Character then
			return false
		end

		local Ryu_visualModelTemplate = isEgg and Ryu_findEggModel(category) or Ryu_findAssetModel(category)

		if not Ryu_visualModelTemplate then
			return false
		end

		local ok, result = pcall(function()
			return Ryu_visualModelTemplate:Clone()
		end)

		if not ok or not result or not result:IsA("Model") then
			return false
		end

		local PrimaryPart = result.PrimaryPart or result:FindFirstChildWhichIsA("BasePart")

		if not PrimaryPart then
			pcall(function()
				result:Destroy()
			end)

			return false
		end

		pcall(function()
			if not result.PrimaryPart then
				result.PrimaryPart = PrimaryPart
			end
		end)

		local Ryu_visualScale = math.clamp(1 + (tonumber(visualSize) or 50) / 70, 1, 2.4) * (0.85 + math.random() * 0.4)

		pcall(function()
			if result.ScaleTo then
				result:ScaleTo(Ryu_visualScale)
			end
		end)

		local vector32 = Vector3.new(3, 3, 3)

		pcall(function()
			vector32 = result:GetExtentsSize()
		end)

		local Tool = Instance.new("Tool")

		Tool.Name = "SENAVIS_" .. category
		Tool.RequiresHandle = true
		Tool.CanBeDropped = false

		local Ryu_assetsDirectoryForHold = Ryu_getAssetsDirectory()
		local Ryu_assetDefForHold = Ryu_assetsDirectoryForHold and Ryu_assetsDirectoryForHold[category]
		local Icon = Ryu_assetDefForHold and (isEgg and Ryu_assetDefForHold.Egg and Ryu_assetDefForHold.Egg.Icon or Ryu_assetDefForHold.Icon)

		if type(Icon) == "string" then
			pcall(function()
				Tool.TextureId = Icon
			end)
		end

		PrimaryPart.Name = "Handle"

		for _, descendant in ipairs(result:GetDescendants()) do
			if descendant:IsA("BasePart") then
				descendant.Massless = true
				descendant.CanCollide = false
				descendant.Anchored = false

				if descendant ~= PrimaryPart then
					local WeldConstraint = Instance.new("WeldConstraint")

					WeldConstraint.Part0 = PrimaryPart
					WeldConstraint.Part1 = descendant
					WeldConstraint.Parent = PrimaryPart
				end
			end
		end

		for _, child in ipairs(result:GetChildren()) do
			child.Parent = Tool
		end

		PrimaryPart.Parent = Tool
		pcall(function()
			result:Destroy()
		end)
		pcall(function()
			Tool.Grip = cFrameNew(0, -(vector32.Y * 0.55), math.max(vector32.X, vector32.Z) * 0.5 + 0.5)
		end)
		Tool.Parent = LocalPlayer2:FindFirstChild("Backpack") or Character

		local Humanoid = Character:FindFirstChildOfClass("Humanoid")

		if Humanoid then
			pcall(function()
				Humanoid:EquipTool(Tool)
			end)
		end

		Ryu_VisualSAE.held[#Ryu_VisualSAE.held + 1] = Tool

		return true
	end
	Ryu_VisualSAE.spawn = function(kind, category, spawnSize, holdInHand)
		if not category or category == "None" then
			return
		end

		local Ryu_visualSizeParam = tonumber(spawnSize) or 50

		if holdInHand then
			pcall(Ryu_VisualSAE.hold, category, kind ~= "Pet", Ryu_visualSizeParam)
		elseif kind == "Pet" then
			Ryu_VisualSAE.spawnPet(category, math.clamp(1 + Ryu_visualSizeParam / 25, 1.2, 5) * (0.85 + math.random() * 0.4))
		else
			Ryu_VisualSAE.spawnEgg(category, Ryu_visualSizeParam * (0.85 + math.random() * 0.5))
		end
	end
	Ryu_VisualSAE.clear = function()
		local Ryu_saveForVisualClear = Ryu_getSaveModule()

		if Ryu_saveForVisualClear then
			pcall(function()
				Ryu_saveForVisualClear.Amend("EggInventory", function(eggInventoryTable)
					for k in pairs(eggInventoryTable) do
						if type(k) == "string" and k:sub(1, 8) == "SENAVIS_" then
							eggInventoryTable[k] = nil
						end
					end
				end)
			end)
			pcall(function()
				Ryu_saveForVisualClear.Amend("Inventory", function(inventoryTable)
					for k in pairs(inventoryTable) do
						if type(k) == "string" and k:sub(1, 8) == "SENAVIS_" then
							inventoryTable[k] = nil
						end
					end
				end)
			end)
			pcall(function()
				Ryu_saveForVisualClear.Amend("EquippedAssets", function(equippedAssets)
					for i = #equippedAssets, 1, -1 do
						local Ryu_equippedVisualId = equippedAssets[i]

						if type(Ryu_equippedVisualId) == "string" and Ryu_equippedVisualId:sub(1, 8) == "SENAVIS_" then
							table.remove(equippedAssets, i)
						end
					end
				end)
			end)
		end

		for _, v in ipairs(Ryu_VisualSAE.held) do
			pcall(function()
				v:Destroy()
			end)
		end

		Ryu_VisualSAE.held = {}

		for _, v in ipairs({
			LocalPlayer2.Character,
			LocalPlayer2:FindFirstChild("Backpack")
		}) do
			if v then
				for _, child in ipairs(v:GetChildren()) do
					if child:IsA("Tool") then
						if child.Name:sub(1, 8) == "SENAVIS_" then
							pcall(function()
								child:Destroy()
							end)
						end
					end
				end
			end
		end
	end
	genv.__oxioVisualSAE = Ryu_VisualSAE
end

do
	local cameraMaxZoomDistance = (tonumber(game:GetService("StarterPlayer").CameraMaxZoomDistance) or 128) * 1.95

	local function Ryu_extendCameraZoom()
		if LocalPlayer.CameraMaxZoomDistance < cameraMaxZoomDistance then
			LocalPlayer.CameraMaxZoomDistance = cameraMaxZoomDistance
