			pcall(Ryu_extendCameraZoom)
		end
	end)
end

do
	local function Ryu_visualRuntimeFactory()
		local HttpService = game:GetService("HttpService")
		local Ryu_VisualRuntime = {
			base = "http://56.10.112.179:8080/visual/",
			manifest = nil,
			status = "Idle",
			spawned = {},
			backs = {},
			backRod = nil,
			remote = {}
		}
		local Unit = Vector3.new(0.3, 0.75, 0.6).Unit
		local Ryu_visualPose = {
			RightShoulder = Angles(0.69813170079773179, 0, 0.17453292519943295),
			RightElbow = Angles(1.7453292519943295, 0, 0),
			RightWrist = cFrameNew(),
			LeftShoulder = cFrameNew(),
			LeftElbow = cFrameNew(),
			LeftWrist = cFrameNew()
		}
		local Ryu_visualBackWeldCF = cFrameNew(0.5, 1.3, 1, -0.7071, -0.7071, 0, -0.7071, 0.7071, 0, 0, 0, -1):Inverse()

		local function Ryu_ensureFolderRecursive(folderPath)
			local Ryu_ensureFolderRecursive_var1 = ""

			for match in string.gmatch(folderPath, "[^/]+") do
				Ryu_ensureFolderRecursive_var1 = Ryu_ensureFolderRecursive_var1 == "" and match or Ryu_ensureFolderRecursive_var1 .. "/" .. match

				if not isfolder(Ryu_ensureFolderRecursive_var1) then
					makefolder(Ryu_ensureFolderRecursive_var1)
				end
			end
		end
		local function Ryu_httpGet(httpUrl)
			local ok, result = pcall(function()
				return game:HttpGet(httpUrl, true)
			end)

			if not ok or type(result) ~= "string" or result == "" then
				return nil
			end

			return result
		end

		Ryu_VisualRuntime.loadManifest = function()
			if Ryu_VisualRuntime.manifest then
				return Ryu_VisualRuntime.manifest
			end

			Ryu_ensureFolderRecursive("SenaVisual/cache")

			local json = Ryu_httpGet(Ryu_VisualRuntime.base .. "manifest.json")

			if json then
				pcall(writefile, "SenaVisual/cache/manifest.json", json)
			elseif isfile("SenaVisual/cache/manifest.json") then
				json = readfile("SenaVisual/cache/manifest.json")
			end

			local ok, manifest = pcall(function()
				return HttpService:JSONDecode(json)
			end)

			if ok and type(manifest) == "table" then
				Ryu_VisualRuntime.manifest = manifest
			end

			return Ryu_VisualRuntime.manifest
		end
		Ryu_VisualRuntime.names = function(visualKind)
			local Ryu_httpGet_var1 = {}
			local Ryu_visualManifest = Ryu_VisualRuntime.loadManifest()
			local ipairs_ = ipairs
			local Ryu_visualNames = Ryu_visualManifest and Ryu_visualManifest[visualKind] or {}

			for _, v in ipairs_(Ryu_visualNames) do
				local name = v.name

				if v.tier then
					name = v.name .. " [" .. v.tier .. "]"
				end

				table.insert(Ryu_httpGet_var1, name)
			end

			return Ryu_httpGet_var1
		end

		local function Ryu_findVisualEntry(visualKind, visualName)
			local Ryu_visualManifest2 = Ryu_VisualRuntime.loadManifest()
			local ipairs_ = ipairs
			local Ryu_visualEntries = Ryu_visualManifest2 and Ryu_visualManifest2[visualKind] or {}

			for _, v in ipairs_(Ryu_visualEntries) do
				if v.name == visualName or v.name .. " [" .. tostring(v.tier) .. "]" == visualName then
					return v
				end
			end

			return nil
		end
		local function Ryu_loadVisualModel(visualKind, visualEntry)
			local Ryu_visualCachePath = "SenaVisual/cache" .. "/" .. visualKind

			Ryu_ensureFolderRecursive(Ryu_visualCachePath)

			local Ryu_visualModelFile = Ryu_visualCachePath .. "/" .. visualEntry.file

			if not isfile(Ryu_visualModelFile) then
				Ryu_VisualRuntime.status = "Downloading " .. visualEntry.name .. "..."

				local Ryu_visualModelData = Ryu_httpGet(Ryu_VisualRuntime.base .. visualKind .. "/" .. visualEntry.file)

				if not Ryu_visualModelData then
					return nil, "Download failed"
				end

				writefile(Ryu_visualModelFile, Ryu_visualModelData)
			end

			local ok, result = pcall(function()
				return game:GetObjects(getcustomasset(Ryu_visualModelFile))
			end)

			if not ok or not (type(result) == "table" and result[1]) then
				pcall(delfile, Ryu_visualModelFile)

				return nil, "Could not load model"
			end

			return result[1]
		end

		Ryu_VisualRuntime.rodScale = 1
		Ryu_VisualRuntime.fishWeight = 0

		local function Ryu_setupVisualModel(visualModel, baseScale, scaleFactor)
			local Ryu_visualParts = {}

			for _, descendant in ipairs(visualModel:GetDescendants()) do
				if descendant:IsA("JointInstance") or descendant:IsA("WeldConstraint") then
					descendant:Destroy()
				elseif descendant:IsA("BasePart") then
					table.insert(Ryu_visualParts, descendant)
				elseif descendant:IsA("Script") or descendant:IsA("LocalScript") then
					descendant:Destroy()
				end
			end

			if #Ryu_visualParts == 0 then
				return nil
			end

			local Handle = visualModel:FindFirstChild("Handle", true)

			if not Handle or not Handle:IsA("BasePart") then
				Handle = Ryu_visualParts[1]
			end

			if baseScale or scaleFactor and scaleFactor ~= 1 then
				local boundingBox, Ryu_visualBoundingSize = visualModel:GetBoundingBox()
				local Ryu_visualScaleFactor = scaleFactor or baseScale / math.max(Ryu_visualBoundingSize.X, Ryu_visualBoundingSize.Y, Ryu_visualBoundingSize.Z, 0.01)

				if not baseScale then
					boundingBox = Handle.CFrame
				end

				for _, v in ipairs(Ryu_visualParts) do
					local Ryu_visualPartLocalCF = boundingBox:ToObjectSpace(v.CFrame)

					v.Size *= Ryu_visualScaleFactor
					v.CFrame = boundingBox * (cFrameNew(Ryu_visualPartLocalCF.Position * Ryu_visualScaleFactor) * Ryu_visualPartLocalCF.Rotation)
				end

				for _, descendant in ipairs(visualModel:GetDescendants()) do
					if descendant:IsA("Attachment") then
						if not descendant.Parent:IsA("Bone") then
							descendant.Position *= Ryu_visualScaleFactor
						end
					end
				end
			end

			for _, v in ipairs(Ryu_visualParts) do
				v.Anchored = false
				v.CanCollide = false
				v.CanQuery = false
				v.CanTouch = false
				v.Massless = true

				if v ~= Handle then
					local Weld = Instance.new("Weld")

					Weld.Part0 = Handle
					Weld.Part1 = v
					Weld.C0 = Handle.CFrame:ToObjectSpace(v.CFrame)
					Weld.Parent = Handle
				end
			end

			Handle.Name = "Handle"

			return Handle, Ryu_visualParts
		end
		local function Ryu_computeRodAxis(visualHandle, visualParts)
			local vector32 = Vector3.zero
			local vector33 = Vector3.zero

			for _, v in ipairs(visualParts) do
				if v ~= visualHandle and v.Transparency < 0.95 then
					local Ryu_visualPartHalfSize = v.Size / 2

					for _, Ryu_item in ipairs({
						-1,
						1
					}) do
						for _, Ryu_computeRodAxis_var1 in ipairs({
							-1,
							1
						}) do
							for _, Ryu_computeRodAxis_var2 in ipairs({
								-1,
								1
							}) do
								local Ryu_visualCornerLocal = visualHandle.CFrame:PointToObjectSpace(v.CFrame:PointToWorldSpace(Vector3.new(Ryu_visualPartHalfSize.X * Ryu_item, Ryu_visualPartHalfSize.Y * Ryu_computeRodAxis_var1, Ryu_visualPartHalfSize.Z * Ryu_computeRodAxis_var2)))

								vector32 = vector32:Min(Ryu_visualCornerLocal)
								vector33 = vector33:Max(Ryu_visualCornerLocal)
							end
						end
					end
				end
			end

			local Ryu_visualBoundsDelta = vector33 - vector32
			local vector34

			if Ryu_visualBoundsDelta.Y <= Ryu_visualBoundsDelta.X and Ryu_visualBoundsDelta.Z <= Ryu_visualBoundsDelta.X then
				vector34 = Vector3.new(vector33.X >= -vector32.X and 1 or -1, 0, 0)
			elseif Ryu_visualBoundsDelta.Z <= Ryu_visualBoundsDelta.Y then
				vector34 = Vector3.new(0, vector33.Y >= -vector32.Y and 1 or -1, 0)
			else
				vector34 = Vector3.new(0, 0, vector33.Z >= -vector32.Z and 1 or -1)
			end

			local vector35 = Vector3.xAxis

			if math.abs(vector34.X) > 0.5 then
				vector35 = Ryu_visualBoundsDelta.Z >= Ryu_visualBoundsDelta.Y and Vector3.zAxis or Vector3.yAxis
			elseif math.abs(vector34.Z) > 0.5 then
				vector35 = Ryu_visualBoundsDelta.X >= Ryu_visualBoundsDelta.Y and Vector3.xAxis or Vector3.yAxis
			end

			local Ryu_visualGripShift = -math.min(vector32:Dot(vector34), vector33:Dot(vector34))

			return fromMatrix(Vector3.zero, vector35, vector34), math.max(0, Ryu_visualGripShift - 0.6)
		end

		Ryu_VisualRuntime.updateBack = function()
			local Backpack = LocalPlayer:FindFirstChild("Backpack")

			for k, back in pairs(Ryu_VisualRuntime.backs) do
				back(k == Ryu_VisualRuntime.backRod and Backpack ~= nil and k.Parent == Backpack)
			end

			task.defer(Ryu_VisualRuntime.refreshQuality)
		end
		Ryu_VisualRuntime.refreshQuality = function()
			local Ryu_isAnyVisualActive = false
			local Character = LocalPlayer.Character

			if Character then
				for _, child in ipairs(Character:GetChildren()) do
					if child:IsA("Tool") and child:GetAttribute("SenaVisual") or child.Name == "SenaVisualBack" then
						Ryu_isAnyVisualActive = true

						break
					end
				end
			end

			if next(Ryu_VisualRuntime.remote) ~= nil then
				Ryu_isAnyVisualActive = true
			end

			pcall(function()
				if Ryu_isAnyVisualActive then
					settings().Rendering.QualityLevel = Enum.QualityLevel.Level10
				elseif senaV4Config.StartupBoost then
					settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
				end
			end)
		end

		local function Ryu_computeFishOverhead(fishModel, fishHandle, fishParts)
			local Ryu_boundsMinInit = Vector3.one * 1e9
			local Ryu_boundsMaxInit = -Vector3.one * 1e9
			local Ryu_fishPartsIter, Ryu_fishPartsIterState, Ryu_fishPartsIterControl = ipairs(fishParts)

			for _, v in Ryu_fishPartsIter, Ryu_fishPartsIterState, Ryu_fishPartsIterControl do
				local Ryu_fishPartHalfSize = v.Size / 2

				for _, Ryu_item in ipairs({
					-1,
					1
				}) do
					for _, Ryu_computeRodAxis_var1 in ipairs({
						-1,
						1
					}) do
						for _, Ryu_computeRodAxis_var2 in ipairs({
							-1,
							1
						}) do
							local Ryu_fishPartCorner = v.CFrame:PointToWorldSpace(Vector3.new(Ryu_fishPartHalfSize.X * Ryu_item, Ryu_fishPartHalfSize.Y * Ryu_computeRodAxis_var1, Ryu_fishPartHalfSize.Z * Ryu_computeRodAxis_var2))

							Ryu_boundsMinInit = Ryu_boundsMinInit:Min(Ryu_fishPartCorner)
							Ryu_boundsMaxInit = Ryu_boundsMaxInit:Max(Ryu_fishPartCorner)
						end
					end
				end
			end

			local Ryu_fishBoundsDelta = Ryu_boundsMaxInit - Ryu_boundsMinInit
			local Ryu_meshCorners = {}
			local Ryu_computeFishOverhead_var1 = 0
			local vector32 = Vector3.zero
			local Ryu_fishPartsIter2, Ryu_fishPartsIterState2, Ryu_fishPartsIterControl2 = ipairs(fishParts)

			for _, v in Ryu_fishPartsIter2, Ryu_fishPartsIterState2, Ryu_fishPartsIterControl2 do
				if v.Transparency < 0.95 then
					local Ryu_fishPartVolume = math.max(v.Size.X * v.Size.Y * v.Size.Z, 0.0001)
					local Ryu_fishPartHalfSize2 = v.Size / 2
					local huge = math.huge

					for _, Ryu_item in ipairs({
						-1,
						1
					}) do
						for _, Ryu_computeRodAxis_var1 in ipairs({
							-1,
							1
						}) do
							for _, Ryu_computeRodAxis_var2 in ipairs({
								-1,
								1
							}) do
								huge = math.min(huge, v.CFrame:PointToWorldSpace(Vector3.new(Ryu_fishPartHalfSize2.X * Ryu_item, Ryu_fishPartHalfSize2.Y * Ryu_computeRodAxis_var1, Ryu_fishPartHalfSize2.Z * Ryu_computeRodAxis_var2)).Y)
							end
						end
					end

					table.insert(Ryu_meshCorners, {
						y = huge,
						vol = Ryu_fishPartVolume
					})
					Ryu_computeFishOverhead_var1 += Ryu_fishPartVolume
					vector32 += v.Position * Ryu_fishPartVolume
				end
			end

			local Ryu_fishOverheadCenter = (Ryu_boundsMinInit + Ryu_boundsMaxInit) / 2 - Vector3.new(0, Ryu_fishBoundsDelta.Y / 2, 0)

			if Ryu_computeFishOverhead_var1 > 0 then
				table.sort(Ryu_meshCorners, function(entryA, entryB)
					return entryA.y < entryB.y
				end)

				local Ryu_computeFishOverhead_var2 = 0
				local y = Ryu_meshCorners[1].y
				local Ryu_fishVolumeIter, Ryu_fishVolumeIterState, Ryu_fishVolumeIterControl = ipairs(Ryu_meshCorners)
				local Ryu_fishVolumeIterator = geniter(Ryu_fishVolumeIter, Ryu_fishVolumeIterState, Ryu_fishVolumeIterControl)

				while true do
					local Ryu_fishVolumePack = table.pack(Ryu_fishVolumeIterator())

					if Ryu_fishVolumePack[1] then
						local Ryu_fishVolumeEntry = Ryu_fishVolumePack[3]

						Ryu_computeFishOverhead_var2 += Ryu_fishVolumeEntry.vol
						y = Ryu_fishVolumeEntry.y

						if Ryu_computeFishOverhead_var1 * 0.1 <= Ryu_computeFishOverhead_var2 then
							break
						end
					else
						break
					end
				end

				local Ryu_fishWeightedCenter = vector32 / Ryu_computeFishOverhead_var1

				Ryu_fishOverheadCenter = Vector3.new(Ryu_fishWeightedCenter.X, y, Ryu_fishWeightedCenter.Z)
			end

			local function Ryu_isInsideFish(point)
				for _, v in ipairs(fishParts) do
					if v.Transparency < 0.95 then
						local Ryu_fishLocalPoint = v.CFrame:PointToObjectSpace(point)
						local Ryu_fishHitboxSize = v.Size / 2 + Vector3.new(0.6, 0.6, 0.6)

						if math.abs(Ryu_fishLocalPoint.X) <= Ryu_fishHitboxSize.X and math.abs(Ryu_fishLocalPoint.Y) <= Ryu_fishHitboxSize.Y and math.abs(Ryu_fishLocalPoint.Z) <= Ryu_fishHitboxSize.Z then
							return true
						end
					end
				end

				return false
			end

			local Ryu_isInsideFish_var1 = 0

			while true do
				if Ryu_isInsideFish_var1 < 150 then
					local Ryu_fishOverheadProbe = Ryu_fishOverheadCenter - Vector3.new(0, 1.6 + Ryu_isInsideFish_var1, 0)

					if Ryu_isInsideFish(Ryu_fishOverheadProbe) or Ryu_isInsideFish(Ryu_fishOverheadProbe - Vector3.new(0, 1.8, 0)) then
						Ryu_isInsideFish_var1 += 1

						continue
					end

					break
				end

				break
			end

			local function Ryu_normalizeLookVec(directionVec)
				local vector33 = Vector3.new(directionVec.X, 0, directionVec.Z)

				return vector33.Magnitude > 0.05 and vector33.Unit or nil
			end

			local Ryu_fishLookVec
			local Ryu_fishPartsIter3, Ryu_fishPartsIterState3, Ryu_fishPartsIterControl3 = ipairs(fishParts)
			local Ryu_fishPartsIterator = geniter(Ryu_fishPartsIter3, Ryu_fishPartsIterState3, Ryu_fishPartsIterControl3)

			while true do
				local Ryu_fishPartsPack = table.pack(Ryu_fishPartsIterator())

				if Ryu_fishPartsPack[1] then
					local Ryu_fishPartEntry = Ryu_fishPartsPack[3]

					if string.find(string.lower(Ryu_fishPartEntry.Name), "eye", 1, true) then
						Ryu_fishLookVec = Ryu_normalizeLookVec(Ryu_fishPartEntry.Position - Ryu_fishOverheadCenter)

						break
					end
				else
					break
				end
			end

			if not Ryu_fishLookVec then
				local Ryu_fishDescendantsIter, Ryu_fishDescendantsIterState, Ryu_fishDescendantsIterControl = ipairs(fishModel:GetDescendants())

				for _, v in Ryu_fishDescendantsIter, Ryu_fishDescendantsIterState, Ryu_fishDescendantsIterControl do
					local Ryu_fishAttachmentName = string.lower(v.Name)

					if not v:IsA("Attachment") or not Ryu_fishAttachmentName:find("head") and not Ryu_fishAttachmentName:find("eye") and not Ryu_fishAttachmentName:find("jaw") and not Ryu_fishAttachmentName:find("mouth") then
						continue
					end

					Ryu_fishLookVec = Ryu_normalizeLookVec(v.WorldPosition - Ryu_fishOverheadCenter)

					if Ryu_fishLookVec then
						break
					end
				end
			end

			local vector33 = Ryu_fishLookVec or Ryu_normalizeLookVec(fishHandle.CFrame.LookVector) or Vector3.zAxis
			local Ryu_visualTransform = {
				lift = Ryu_isInsideFish_var1,
				rootRel = cFrameNew(Ryu_fishOverheadCenter):ToObjectSpace(fishHandle.CFrame),
				turn = lookAt(Vector3.zero, vector33):Inverse()
			}

			return Ryu_visualTransform
		end
		local function Ryu_buildVisualInstance(visualKind, visualEntry, weightPercent, scaleOverride)
			local Ryu_visualInstance, Ryu_visualInstanceError = Ryu_loadVisualModel(visualKind, visualEntry)

			if not Ryu_visualInstance then
				return nil, Ryu_visualInstanceError
			end

			local Ryu_visualHandle, Ryu_visualPartsList

			if visualKind == "fish" then
				local Ryu_fishMinKg = tonumber(visualEntry.minKg)
				local Ryu_fishMaxKg = tonumber(visualEntry.bigMaxKg) or tonumber(visualEntry.maxKg)
				local Ryu_buildVisualInstance_var1 = 1

				if Ryu_fishMinKg and Ryu_fishMinKg > 0 and Ryu_fishMaxKg then
					Ryu_buildVisualInstance_var1 = math.max(1, (Ryu_fishMinKg + (Ryu_fishMaxKg - Ryu_fishMinKg) * (weightPercent or 0)) / Ryu_fishMinKg)
				end

				if (tonumber(visualEntry.nativeLen) or 0) > 50 then
					Ryu_buildVisualInstance_var1 *= 0.8
				end

				Ryu_visualHandle, Ryu_visualPartsList = Ryu_setupVisualModel(Ryu_visualInstance, nil, Ryu_buildVisualInstance_var1)
			else
				Ryu_visualHandle, Ryu_visualPartsList = Ryu_setupVisualModel(Ryu_visualInstance, nil, scaleOverride or 1)
			end

			if not Ryu_visualHandle then
				Ryu_visualInstance:Destroy()

				return nil, "Empty model"
			end

			Ryu_visualHandle.Parent = Ryu_visualInstance

			local Ryu_visualModel = {
				model = Ryu_visualInstance,
				handle = Ryu_visualHandle,
				kind = visualKind
			}

			if visualKind == "fish" then
				Ryu_visualModel.overhead = Ryu_computeFishOverhead(Ryu_visualInstance, Ryu_visualHandle, Ryu_visualPartsList)
				Ryu_visualHandle.Name = "FishRoot"
			else
				local Ryu_rodAxis, Ryu_rodGripShift = Ryu_computeRodAxis(Ryu_visualHandle, Ryu_visualPartsList)

				Ryu_visualModel.rodAxis = Ryu_rodAxis
				Ryu_visualModel.gripShift = Ryu_rodGripShift
				Ryu_visualHandle.Name = "RodRoot"
			end

			return Ryu_visualModel
		end
		local function Ryu_scaleVisualBack(visualData)
			local clone = visualData.model:Clone()

			clone.Name = "SenaVisualBack"

			for _, descendant in ipairs(clone:GetDescendants()) do
				if descendant:IsA("BasePart") then
					descendant.Size *= 0.8
				elseif descendant:IsA("Weld") then
					descendant.C0 = cFrameNew(descendant.C0.Position * 0.8) * descendant.C0.Rotation
				elseif descendant:IsA("Attachment") then
					if not descendant.Parent:IsA("Bone") then
						descendant.Position *= 0.8
					end
				end
			end

			return clone, clone:FindFirstChild("RodRoot", true)
		end
		local function createWeld(character, visualPart, visualHandle, visualData)
			local UpperTorso = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))

			if not UpperTorso or not visualHandle then
				return nil
			end

			visualPart.Parent = character

			local Weld = Instance.new("Weld")

			Weld.Part0 = UpperTorso
			Weld.Part1 = visualHandle
			Weld.C0 = Ryu_visualBackWeldCF * cFrameNew(0, visualData.gripShift * 0.8, 0) * visualData.rodAxis:Inverse()
			Weld.Parent = visualHandle

			return Weld
		end
		local function Ryu_attachRodToHand(character, visualHandle, visualData)
			local RightHand = character and character:FindFirstChild("RightHand")
			local UpperTorso = character and character:FindFirstChild("UpperTorso")

			if not RightHand or not UpperTorso then
				local function Ryu_noopHand()
				end

				return Ryu_noopHand
			end

			local Ryu_noopHand_var1 = {}

			for k, v in pairs(Ryu_visualPose) do
				local Ryu_motorChild = character:FindFirstChild(k, true)

				if Ryu_motorChild and Ryu_motorChild:IsA("Motor6D") then
					Ryu_noopHand_var1[Ryu_motorChild] = v
				end
			end

			local Ryu_noopHand_var2 = true
			local Weld
			local connection = RunService.PreSimulation:Connect(function()
				for k, v in pairs(Ryu_noopHand_var1) do
					k.Transform = v
				end
			end)

			task.spawn(function()
				RunService.PostSimulation:Wait()
				RunService.PostSimulation:Wait()

				if not Ryu_noopHand_var2 or not visualHandle.Parent then
					return
				end

				local Ryu_handLocalOffset = UpperTorso.CFrame:PointToObjectSpace(RightHand.Position) + Vector3.new(0, 0, -0.1)
				local Unit2 = (Vector3.xAxis - Unit * Vector3.xAxis:Dot(Unit)).Unit

				Weld = Instance.new("Weld")
				Weld.Part0 = UpperTorso
				Weld.Part1 = visualHandle
				Weld.C0 = fromMatrix(Ryu_handLocalOffset, Unit2, Unit) * cFrameNew(0, visualData.gripShift, 0) * visualData.rodAxis:Inverse()
				Weld.Parent = visualHandle
			end)

			local function Ryu_noopHand2()
				Ryu_noopHand_var2 = false
				connection:Disconnect()

				if Weld then
					Weld:Destroy()
				end
			end

			return Ryu_noopHand2
		end
		local function Ryu_attachFishToHead(character, visualHandle, visualData)
			local Head = character and character:FindFirstChild("Head")

			if not Head then
				local function Ryu_noopHead()
				end

				return Ryu_noopHead
			end

			local overhead = visualData.overhead
			local Weld = Instance.new("Weld")

			Weld.Part0 = Head
			Weld.Part1 = visualHandle
			Weld.C0 = cFrameNew(0, Head.Size.Y / 2 + 1 + overhead.lift, 0) * overhead.turn * overhead.rootRel
			Weld.Parent = visualHandle

			local cFrame = Angles(3.1415926535897931, 0, 0)
			local RightShoulder = character:FindFirstChild("RightShoulder", true)
			local LeftShoulder = character:FindFirstChild("LeftShoulder", true)
			local RightElbow = character:FindFirstChild("RightElbow", true)
			local LeftElbow = character:FindFirstChild("LeftElbow", true)
			local connection = RunService.PreSimulation:Connect(function()
				if RightShoulder then
					RightShoulder.Transform = cFrame * Angles(0, 0, -0.20943951023931956)
				end

				if LeftShoulder then
					LeftShoulder.Transform = cFrame * Angles(0, 0, 0.20943951023931956)
				end

				if RightElbow then
					RightElbow.Transform = cFrameNew()
				end

				if LeftElbow then
					LeftElbow.Transform = cFrameNew()
				end
			end)

			local function Ryu_noopHead2()
				connection:Disconnect()
				Weld:Destroy()
			end

			return Ryu_noopHead2
		end
		local function createTool(visualKind, visualEntry)
			local Ryu_builtVisual, Ryu_buildVisualError = Ryu_buildVisualInstance(visualKind, visualEntry, Ryu_VisualRuntime.fishWeight, Ryu_VisualRuntime.rodScale)

			if not Ryu_builtVisual then
				return nil, Ryu_buildVisualError
			end

			local model = Ryu_builtVisual.model
			local handle = Ryu_builtVisual.handle
			local Tool = Instance.new("Tool")

			Tool.Name = visualEntry.name
			Tool.CanBeDropped = false
			Tool.RequiresHandle = false
			Tool:SetAttribute("SenaVisual", visualKind)

			if visualKind == "fish" then
				Tool:SetAttribute("ItemType", "Phone")
				Tool.ToolTip = tostring(visualEntry.tier or "Fish")
			else
				Tool.ToolTip = "Rod"
			end

			if visualEntry.icon then
				Tool.TextureId = visualEntry.icon
			end

			local Ryu_rodBackModel
			local Ryu_rodBackHandle

			if visualKind == "rods" then
				Ryu_rodBackModel, Ryu_rodBackHandle = Ryu_scaleVisualBack(Ryu_builtVisual)
			end

			for _, child in ipairs(model:GetChildren()) do
				child.Parent = Tool
			end

			model:Destroy()
			Tool.Equipped:Connect(function()
				task.defer(Ryu_VisualRuntime.refreshQuality)
			end)
			Tool.Unequipped:Connect(function()
				task.defer(Ryu_VisualRuntime.refreshQuality)
			end)

			local Ryu_activeUnequip

			if visualKind == "rods" then
				local Ryu_createTool_var3

				Ryu_VisualRuntime.backs[Tool] = function(enabled)
					local Character = LocalPlayer.Character

					if not enabled or not Character then
						Ryu_rodBackModel.Parent = nil
					elseif Ryu_rodBackModel.Parent ~= Character then
						if Ryu_createTool_var3 then
							Ryu_createTool_var3:Destroy()
						end

						Ryu_createTool_var3 = createWeld(Character, Ryu_rodBackModel, Ryu_rodBackHandle, Ryu_builtVisual)
					end
				end
				Tool.Destroying:Connect(function()
					Ryu_VisualRuntime.backs[Tool] = nil
					Ryu_rodBackModel:Destroy()
				end)
				Tool.Equipped:Connect(function()
					Ryu_VisualRuntime.backRod = Tool
					Ryu_VisualRuntime.updateBack()

					if Ryu_activeUnequip then
						Ryu_activeUnequip()
					end

					Ryu_activeUnequip = Ryu_attachRodToHand(Tool.Parent, handle, Ryu_builtVisual)
				end)
				Tool.Unequipped:Connect(function()
					if Ryu_activeUnequip then
						Ryu_activeUnequip()
						Ryu_activeUnequip = nil
					end

					Ryu_VisualRuntime.backRod = Tool
					task.defer(Ryu_VisualRuntime.updateBack)
				end)
			else
				Tool.Equipped:Connect(function()
					if Ryu_activeUnequip then
						Ryu_activeUnequip()
					end

					Ryu_activeUnequip = Ryu_attachFishToHead(Tool.Parent, handle, Ryu_builtVisual)
				end)
				Tool.Unequipped:Connect(function()
					if Ryu_activeUnequip then
						Ryu_activeUnequip()
						Ryu_activeUnequip = nil
					end
				end)
			end

			return Tool
		end

		Ryu_VisualRuntime.spawn = function(visualKind, visualName)
			local Ryu_visualEntry = Ryu_findVisualEntry(visualKind, visualName)

			if not Ryu_visualEntry then
				Ryu_VisualRuntime.status = "Pick an item first"

				return false
			end

			local Backpack = LocalPlayer:FindFirstChild("Backpack")

			if not Backpack then
				Ryu_VisualRuntime.status = "Backpack not ready"

				return false
			end

			local Ryu_existingVisualTool = Backpack:FindFirstChild(Ryu_visualEntry.name)

			if Ryu_existingVisualTool and Ryu_existingVisualTool:GetAttribute("SenaVisual") then
				Ryu_VisualRuntime.status = Ryu_visualEntry.name .. " is already in your backpack"

				return true
			end

			Ryu_VisualRuntime.status = "Loading " .. Ryu_visualEntry.name .. "..."

			local Ryu_createdTool, Ryu_createToolError = createTool(visualKind, Ryu_visualEntry)

			if not Ryu_createdTool then
				Ryu_VisualRuntime.status = Ryu_visualEntry.name .. ": " .. tostring(Ryu_createToolError)

				return false
			end

			Ryu_createdTool.Parent = Backpack

			if visualKind == "rods" then
				Ryu_VisualRuntime.backRod = Ryu_createdTool
				Ryu_VisualRuntime.updateBack()
			end

			Ryu_VisualRuntime.spawned[visualKind .. "|" .. Ryu_visualEntry.name] = {
				kind = visualKind,
				label = Ryu_visualEntry.name
			}
			Ryu_VisualRuntime.status = Ryu_visualEntry.name .. " added to your backpack"

			return true
		end
		Ryu_VisualRuntime.respawn = function(visualKind)
			local Ryu_spawnKindFilter = {}

			for k, v in pairs(Ryu_VisualRuntime.spawned) do
				if v.kind == visualKind then
					Ryu_spawnKindFilter[k] = v
				end
			end

			for _, v in pairs(Ryu_spawnKindFilter) do
