		for i = 1, 3 do
			local ok, result = pcall(function()
				local Ryu_serverListUrl = ("https://games.roblox.com/Ryu_resolveThumbnail_var1/games/%d/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"):format(game.PlaceId)

