			end) then
				local now = os.clock()

				while not Ryu_ServerHop.hopFailed and os.clock() - now < 6 do
					task.wait(0.25)
				end

				if not Ryu_ServerHop.hopFailed then
					return true
				end
			end

			task.wait(0.3)
