	Ryu_ServerHop.findPrivateTargets = function()
		local Ryu_privateMaxPlayers = Ryu_ServerHop.privateMax()
		local Ryu_publicServerList = Ryu_ServerHop.collectServers(nil)

		if #Ryu_publicServerList == 0 then
			return nil
		end

		local Ryu_privateTargets = {}

		for _, v in ipairs(Ryu_publicServerList) do
			if v.playing + 1 <= Ryu_privateMaxPlayers then
				Ryu_privateTargets[#Ryu_privateTargets + 1] = v
			end
		end

		local Ryu_targetServers = Ryu_privateTargets

		if #Ryu_targetServers == 0 then
			local playing = Ryu_publicServerList[1].playing

			for _, v in ipairs(Ryu_publicServerList) do
