		while #Ryu_targetServers > 0 and #Ryu_applyRemoteVisual_var6 < 5 do
			Ryu_applyRemoteVisual_var6[#Ryu_applyRemoteVisual_var6 + 1] = table.remove(Ryu_targetServers, math.random(1, #Ryu_targetServers))
		end

		return Ryu_applyRemoteVisual_var6
