	Ryu_ServerHop.hopPrivateOnce = function()
		local Ryu_privateMaxCheck = Ryu_ServerHop.privateMax()
		local Ryu_currentPlayerCount = #Players:GetPlayers()

		if Ryu_currentPlayerCount <= Ryu_privateMaxCheck then
			Ryu_ServerHop.privateStatus = "This server is good (" .. Ryu_currentPlayerCount .. " player(s), max " .. Ryu_privateMaxCheck .. ")."

			return false
		end

		if Ryu_ServerHop.hubBusy() then
			Ryu_ServerHop.privateStatus = "Waiting until you finish stealing..."

			return false
		end

		Ryu_ServerHop.privateStatus = "Searching for a quieter server..."

		local Ryu_privateTargetServers = Ryu_ServerHop.findPrivateTargets()

		if not Ryu_privateTargetServers or #Ryu_privateTargetServers == 0 then
			Ryu_ServerHop.privateStatus = "Could not load the server list. Try again."

			return false
		end

		Ryu_ServerHop.privateStatus = "Teleporting..."
		Ryu_ServerHop.lastHopAt = os.clock()

		if Ryu_ServerHop.hopToList(Ryu_privateTargetServers) then
			return true
