			end)
			local Ryu_tradeInRemotes = ok and result or nil

			return Ryu_tradeInRemotes
		end
		local function Ryu_isTradeInActive()
			return senaV4Config.ScrambleTradeInTrade or senaV4Config.ScrambleTradeInReroll
		end
		local function Ryu_normalizeTradeName(nameInput)
			return ((tostring(nameInput or ""):lower():match("^%s*(.-)%s*$") or ""):gsub("%s*egg$", ""))
		end
		local function matches(nameA, nameB)
			local Ryu_normalizedA = Ryu_normalizeTradeName(nameA)
			local Ryu_normalizedB = Ryu_normalizeTradeName(nameB)

			if Ryu_normalizedA == "" or Ryu_normalizedB == "" then
				return false
			end

			if Ryu_normalizedA == Ryu_normalizedB then
				return true
			end

			if not Directory or Directory[nameA] then
				return false
			end

			local Ryu_tradeAssetDef = Directory[nameB]

			return type(Ryu_tradeAssetDef) == "table" and type(Ryu_tradeAssetDef.DisplayName) == "string" and Ryu_normalizeTradeName(Ryu_tradeAssetDef.DisplayName) == Ryu_normalizedA
		end

		Ryu_ScrambleTradeIn.matches = matches

		local function Ryu_getTradeDisplayName(nameInput)
			local Ryu_tradeAssetDefB = Directory and Directory[nameInput]
			local DisplayName = type(Ryu_tradeAssetDefB) == "table" and Ryu_tradeAssetDefB.DisplayName

			return type(DisplayName) == "string" and DisplayName ~= "" and DisplayName or tostring(nameInput)
		end
		local function Ryu_joinTradeNames(namesList, separator)
			local Ryu_petNameList = {}

			for i, v in ipairs(namesList) do
