		local function Ryu_submitTradeIn(requirementsList, selectedPets)
			local Ryu_tradeInRemotes2 = Ryu_getTradeInRemotes()

			if not Ryu_tradeInRemotes2 or not Ryu_tradeInRemotes2.AskTradeIn then
				return false, "Trade remote unavailable"
			end

			local Ryu_submitTradeIn_var1 = {}

			for i = 1, #requirementsList do
				local Ryu_petSlotEntry = selectedPets[i]

				if Ryu_petSlotEntry then
					Ryu_submitTradeIn_var1[#Ryu_submitTradeIn_var1 + 1] = Ryu_petSlotEntry.uid

					continue
				end

				return false, "Requirements incomplete"
			end

			Ryu_ScrambleTradeIn.status = "Trading pets into Dr Scramble"

			local ok, result = pcall(function()
				return Ryu_tradeInRemotes2.AskTradeIn:InvokeServer(Ryu_submitTradeIn_var1)
			end)

			if (not ok or result == false) and teleport() then
				task.wait(0.3)
				ok, result = pcall(function()
					return Ryu_tradeInRemotes2.AskTradeIn:InvokeServer(Ryu_submitTradeIn_var1)
				end)
			end

			if not ok or result == false then
				local Ryu_tradeFailed = false
				local tostring_ = tostring
				local Ryu_tradeErrorMessage = result or "Trade rejected"

				return Ryu_tradeFailed, tostring_(Ryu_tradeErrorMessage)
			end

			pcall(function()
				if Ryu_tradeInRemotes2.AskFinishReveal then
					Ryu_tradeInRemotes2.AskFinishReveal:InvokeServer()
				end
			end)
			Ryu_ScrambleTradeIn.trades += 1
			Ryu_ScrambleTradeIn.state(true)

			return true
		end

		Ryu_ScrambleTradeIn.tradeOnce = function()
			local Ryu_tradeRequirements = Ryu_getTradeRequirements(Ryu_ScrambleTradeIn.state(true))

			if #Ryu_tradeRequirements < 3 then
				return false, "Cannot read the recipe"
			end

			local Ryu_selectedPets, Ryu_missingRequirements = selectPets(Ryu_tradeRequirements, Ryu_getTradeSaveData())

			if #Ryu_missingRequirements > 0 then
				return false, "Missing: " .. Ryu_joinTradeNames(Ryu_missingRequirements, ", ")
			end

			return Ryu_submitTradeIn(Ryu_tradeRequirements, Ryu_selectedPets)
		end
		Ryu_ScrambleTradeIn.reroll = function()
			local Ryu_tradeInState = Ryu_ScrambleTradeIn.state(false)

			if (tonumber(Ryu_tradeInState and Ryu_tradeInState.FreeRefreshesRemaining) or 0) <= 0 then
				return false, "No free rerolls left"
			end

			local Ryu_tradeInRemotes3 = Ryu_getTradeInRemotes()

			if not Ryu_tradeInRemotes3 or not Ryu_tradeInRemotes3.AskRefresh then
				return false, "Refresh remote unavailable"
			end

			if not pcall(function()
				return Ryu_tradeInRemotes3.AskRefresh:InvokeServer()
			end) then
				return false, "Reroll failed"
			end

			Ryu_ScrambleTradeIn.state(true)

			return true
		end
		Ryu_ScrambleTradeIn.tick = function()
			local Ryu_tradeInSnapshot = Ryu_ScrambleTradeIn.state(false)

			if not Ryu_tradeInSnapshot then
				Ryu_ScrambleTradeIn.status = "Trade-In state unavailable"

				return
			end

			if Ryu_tradeInSnapshot.Unlocked == false then
				Ryu_ScrambleTradeIn.status = "Dr Scramble Trade-In is locked"

				return
			end

			Ryu_ScrambleTradeIn.banner = tostring(Ryu_tradeInSnapshot.BannerDisplayName or Ryu_tradeInSnapshot.BannerId or "Unknown")
			Ryu_ScrambleTradeIn.rotation = math.max(0, math.floor(tonumber(Ryu_tradeInSnapshot.SecondsUntilRotation) or 0))
			Ryu_ScrambleTradeIn.pity = tonumber(Ryu_tradeInSnapshot.PityCount) or 0
			Ryu_ScrambleTradeIn.pityMax = tonumber(Ryu_tradeInSnapshot.PityThreshold) or 100
			Ryu_ScrambleTradeIn.free = tonumber(Ryu_tradeInSnapshot.FreeRefreshesRemaining) or 0

			if Ryu_tradeInSnapshot.PendingReward then
				Ryu_ScrambleTradeIn.status = "Finishing reward"

				local Ryu_tradeInRemotes4 = Ryu_getTradeInRemotes()

				pcall(function()
					if Ryu_tradeInRemotes4 and Ryu_tradeInRemotes4.AskFinishReveal then
						Ryu_tradeInRemotes4.AskFinishReveal:InvokeServer()
					end
				end)
				Ryu_ScrambleTradeIn.cache = nil

				return
			end

			if not Ryu_isBannerMatched(Ryu_tradeInSnapshot) then
				Ryu_ScrambleTradeIn.status = "Waiting for banner (now: " .. Ryu_ScrambleTradeIn.banner .. ")"
				Ryu_ScrambleTradeIn.demands = "-"
				Ryu_ScrambleTradeIn.stock = "-"
				Ryu_ScrambleTradeIn.ready = 0
				Ryu_ScrambleTradeIn.missing = "None"

