			end

			local Ryu_tradeRequirementsList = Ryu_getTradeRequirements(Ryu_tradeInSnapshot)

			Ryu_ScrambleTradeIn.total = #Ryu_tradeRequirementsList
			Ryu_ScrambleTradeIn.demands = #Ryu_tradeRequirementsList > 0 and Ryu_joinTradeNames(Ryu_tradeRequirementsList, " / ") or "-"

			if #Ryu_tradeRequirementsList < 3 then
				Ryu_ScrambleTradeIn.status = "Waiting for requirements"

				return
			end

			local Ryu_tradeSaveData = Ryu_getTradeSaveData()
			local Ryu_selectedPets2, Ryu_missingPets2, Ryu_allPets2 = selectPets(Ryu_tradeRequirementsList, Ryu_tradeSaveData)

			Ryu_ScrambleTradeIn.stock = Ryu_formatStockText(Ryu_tradeRequirementsList, Ryu_tradeSaveData, Ryu_allPets2)
			Ryu_ScrambleTradeIn.ready = #Ryu_tradeRequirementsList - #Ryu_missingPets2
			Ryu_ScrambleTradeIn.missing = #Ryu_missingPets2 > 0 and Ryu_joinTradeNames(Ryu_missingPets2, ", ") or "None"

			if #Ryu_missingPets2 == 0 then
				if senaV4Config.ScrambleTradeInTrade then
					Ryu_ScrambleTradeIn.status = "Requirements complete, submitting"

					local Ryu_tradeOk, Ryu_tradeErr = Ryu_submitTradeIn(Ryu_tradeRequirementsList, Ryu_selectedPets2)

					Ryu_ScrambleTradeIn.status = Ryu_tradeOk and "Trade complete" or "Trade: " .. tostring(Ryu_tradeErr)
				else
					Ryu_ScrambleTradeIn.status = "Ready to trade (Auto Trade-In is off)"
				end

				return
			end

			if senaV4Config.ScrambleTradeInReroll and Ryu_ScrambleTradeIn.free > 0 and os.clock() - Ryu_ScrambleTradeIn.lastReroll > 3 then
				Ryu_ScrambleTradeIn.lastReroll = os.clock()
				Ryu_ScrambleTradeIn.status = "Rerolling the recipe"
				Ryu_ScrambleTradeIn.reroll()

				return
			end

			Ryu_ScrambleTradeIn.status = #Ryu_missingPets2 > 0 and "Waiting for " .. Ryu_ScrambleTradeIn.missing or Ryu_ScrambleTradeIn.status
		end
		task.spawn(function()
			while Ryu_isCurrentSession() do
				if Ryu_isTradeInActive() then
					local ok, result = pcall(Ryu_ScrambleTradeIn.tick)

					if not ok then
