				elseif Ryu_ScrambleTradeIn.status ~= "Disabled" then
					Ryu_ScrambleTradeIn.status = "Disabled"
				end

				task.wait(1)
			end
		end)
		genv.__oxioScrambleTradeIn = Ryu_ScrambleTradeIn
	end

