		local function Ryu_findBossTarget(arena)
			local Ryu_scramblePlayerRoot4 = Ryu_getScramblePlayerParts()

			if not Ryu_scramblePlayerRoot4 then
				return nil
			end

			local Ryu_findBossTarget_var1
			local Ryu_findBossTarget_var2
			local Ryu_findBossTarget_var3

			local function Ryu_considerBossTarget(targetPart, priority)
				local Ryu_bossHitbox = Ryu_resolveBossHitbox(targetPart)

				if not Ryu_bossHitbox then
					return
				end

				local Magnitude = (Ryu_bossHitbox.Position - Ryu_scramblePlayerRoot4.Position).Magnitude

				if not Ryu_findBossTarget_var2 or priority < Ryu_findBossTarget_var2 or priority == Ryu_findBossTarget_var2 and Magnitude < Ryu_findBossTarget_var3 then
					Ryu_findBossTarget_var1 = Ryu_bossHitbox
					Ryu_findBossTarget_var2 = priority
					Ryu_findBossTarget_var3 = Magnitude
				end
