			for _, child in ipairs(arena:GetChildren()) do
				if not Ryu_swingBatAt_var1[child.Name] and child:IsA("Model") and child.Name ~= "Mech" and child:FindFirstChildOfClass("Humanoid") then
					Ryu_considerBossTarget(child, 1)
