			end

			local Ryu_moveDelta = targetPos - Ryu_scramblePlayerRoot5.Position
			local Magnitude = Ryu_moveDelta.Magnitude

			if Magnitude < 0.5 then
				return
			end

			Ryu_scramblePlayerRoot5.CFrame = cFrameNew(Ryu_scramblePlayerRoot5.Position + Ryu_moveDelta.Unit * math.min(Magnitude, maxDist or 40))
			Ryu_scramblePlayerRoot5.AssemblyLinearVelocity = Vector3.zero
		end
		local function Ryu_stepTowardsPos(targetPos)
			local Ryu_scramblePlayerRoot6 = Ryu_getScramblePlayerParts()

			if not Ryu_scramblePlayerRoot6 then
				return
			end

			local Position = Ryu_scramblePlayerRoot6.Position
			local Ryu_stepCount = math.max(1, math.ceil((targetPos - Position).Magnitude / 140))

			for i = 1, Ryu_stepCount do
				local Ryu_scramblePlayerRoot7 = Ryu_getScramblePlayerParts()

				if not Ryu_scramblePlayerRoot7 then
					return
				end

				Ryu_scramblePlayerRoot7.CFrame = cFrameNew(Position:Lerp(targetPos, i / Ryu_stepCount))
				Ryu_scramblePlayerRoot7.AssemblyLinearVelocity = Vector3.zero
				task.wait(0.08)
			end
		end
