			local Ryu_scrambleArena3 = Ryu_getScrambleArena()

			if not Ryu_scrambleArena3 then
				return false
			end

			local Ryu_scramblePlayerRoot8 = Ryu_getScramblePlayerParts()

			if not Ryu_scramblePlayerRoot8 then
				return false
			end

			local LeaveTeleport = Ryu_scrambleArena3:FindFirstChild("LeaveTeleport")
			local isBasePart = LeaveTeleport and (LeaveTeleport:IsA("BasePart") and LeaveTeleport or LeaveTeleport:FindFirstChildWhichIsA("BasePart", true))

			if not isBasePart then
