		Ryu_scrambleBossFactory_var1.leaveArena = leaveArena

		local Ryu_leaveArena_var1 = 0

		task.spawn(function()
			while Ryu_isCurrentSession() do
				if not senaV4Config.ScrambleBossAuto or Ryu_isAutoStealActive() then
					if senaV4Config.ScrambleBossAuto and Ryu_isAutoStealActive() then
						Ryu_scrambleBossFactory_var1.status = "Yielding to Auto Steal"

						if amInArena() and os.clock() - Ryu_leaveArena_var1 > 3 then
							Ryu_leaveArena_var1 = os.clock()
