				else
					local Ryu_scrambleArena4 = Ryu_getScrambleArena()

					if amInArena() then
						Ryu_scrambleBossFactory_var1.inArena = true

						local serverTimeNow = workspace:GetServerTimeNow()

						if Ryu_tryDodgeHazard(serverTimeNow) then
