						else
							Ryu_getOrEquipBat()

							local Ryu_bossTarget = Ryu_findBossTarget(Ryu_scrambleArena4)

							if Ryu_bossTarget then
								local Ryu_scramblePlayerRoot9 = Ryu_getScramblePlayerParts()

								if Ryu_scramblePlayerRoot9 and (Ryu_scramblePlayerRoot9.Position - Ryu_bossTarget.Position).Magnitude > 12 then
