						Ryu_scrambleBossFactory_var1.status = "Boss up - joining"

						local Ryu_scramblePortalPart = Ryu_getScramblePortal()
						local Position = Ryu_scramblePortalPart and (Ryu_scramblePortalPart:IsA("Model") and select(1, Ryu_scramblePortalPart:GetPivot()).Position or Ryu_scramblePortalPart.Position)

						if Position then
