							if Ryu_scramblePlayerRoot10 and Ryu_eggRuntime and (Ryu_scramblePlayerRoot10.Position - Position).Magnitude > 600 and not Ryu_eggRuntime:_isInSafeArea(Ryu_scramblePlayerRoot10) then
								local Ryu_safeCFForArena = Ryu_eggRuntime:_resolveSafeCFrame(Ryu_scramblePlayerRoot10)

