		local function Ryu_formatCompactShort(value)
			local Ryu_compactAbsValue = tonumber(value) or 0

			if Ryu_compactAbsValue >= 1e12 then
				return string.format("%.2fT", Ryu_compactAbsValue / 1e12)
			end

			if Ryu_compactAbsValue >= 1e9 then
