		local function Ryu_refreshBoardRarityChips()
			Ryu_applyElevatedIdentity()

			for k, v in pairs(Ryu_createLogHeaderLabel_var2) do
				local Ryu_isBoardChipActive = k == Ryu_createLogHeaderLabel_var1

				v.BackgroundColor3 = Ryu_isBoardChipActive and Ryu_uiTheme.accent or Color3.fromRGB(255, 255, 255)
				v.BackgroundTransparency = Ryu_isBoardChipActive and 0.15 or 0.88
