				local UIStroke = v:FindFirstChildOfClass("UIStroke")

				if UIStroke then
					UIStroke.Transparency = Ryu_isBoardChipActive and 0 or 1
				end
			end
		end

		Ryu_refreshEggBoard = function()
			Ryu_applyElevatedIdentity()

			if not Ryu_createLogHeaderLabel_var4 then
				return
			end

			for _, child in ipairs(Ryu_createLogHeaderLabel_var4:GetChildren()) do
				if child:IsA("Frame") then
					child:Destroy()
				end
			end

			local ok, result = pcall(function()
				return EggState2.ReadOwnerEggs(LocalPlayer.UserId)
			end)

			if not ok or type(result) ~= "table" then
				if TextLabel3 then
					TextLabel3.Text = "Total: 0  ON: 0"
				end

				return
			end

			local Ryu_boardRows = {}
			local Ryu_refreshEggBoard_var1 = 0

			for k, v in pairs(result) do
				if v.Placement == nil then
					local Ryu_boardEggRank, Ryu_boardEggRarity, Ryu_boardEggColor = Ryu_resolveRarityInfo(v.AssetCategory)

					if Ryu_createLogHeaderLabel_var1 == "All" or Ryu_boardEggRarity == Ryu_createLogHeaderLabel_var1 then
						local Ryu_boardEggEnabled = Ryu_createLogHeaderLabel_var3[k] ~= false

						if Ryu_boardEggEnabled then
							Ryu_refreshEggBoard_var1 += 1
						end

						local Directory2 = Assets.Directory and Assets.Directory[v.AssetCategory]

						table.insert(Ryu_boardRows, {
							uid = k,
							name = Directory2 and Directory2.DisplayName or v.AssetCategory or tostring(k):sub(1, 8),
							rarity = Ryu_boardEggRarity,
							rnum = Ryu_boardEggRank,
							color = Ryu_boardEggColor,
							image = Ryu_findIconUrl(v.AssetCategory),
							enabled = Ryu_boardEggEnabled
						})
					end
				end
			end

			table.sort(Ryu_boardRows, function(entryA, entryB)
				if entryA.rnum == entryB.rnum then
					return entryA.name < entryB.name
				end

				return (entryA.rnum or 0) > (entryB.rnum or 0)
			end)

			for i, v in ipairs(Ryu_boardRows) do
