			local toggleAll = createTextButton("Toggle All", 80, Color3.fromRGB(60, 70, 95), 1)

			toggleAll.Parent = Frame3
			toggleAll.MouseButton1Click:Connect(function()
				local ok, result = pcall(function()
					return EggState2.ReadOwnerEggs(LocalPlayer.UserId)
				end)

				if not ok or type(result) ~= "table" then
					return
				end

				local Ryu_allEggsEnabled = false
				local Ryu_pairsIter, Ryu_pairsIterState, Ryu_pairsIterControl = pairs(result)
				local Ryu_pairsIterator = geniter(Ryu_pairsIter, Ryu_pairsIterState, Ryu_pairsIterControl)

				while true do
					local Ryu_pairsPack = table.pack(Ryu_pairsIterator())

					if Ryu_pairsPack[1] then
						if (Ryu_pairsPack[3]).Placement == nil and Ryu_createLogHeaderLabel_var3[Ryu_pairsPack[2]] == false then
							Ryu_allEggsEnabled = true

							break
						end
					else
						break
					end
