		Ryu_EggCheckerUI.scan = function()
			local Ryu_createInvHeaderLabel_var5

			pcall(function()
				Ryu_createInvHeaderLabel_var5 = EggState2.ReadFieldEggs()
			end)

			local Ryu_checkerRows = {}
			local ipairs_ = ipairs
			local Records = Ryu_createInvHeaderLabel_var5 and Ryu_createInvHeaderLabel_var5.Records or {}

			for _, Record in ipairs_(Records) do
				if Record.State ~= "Claimed" and Record.State ~= "Carried" and not Record.CarrierUserId and Record.BottomCFrame then
					if not tostring(Record.Uid):find("FirstAreaEgg") then
						local AssetCategory = Record.AssetCategory
						local Directory2 = AssetCategory and Assets.Directory and Assets.Directory[AssetCategory]
						local Ryu_checkerEggRank, Ryu_checkerEggRarity, Ryu_checkerEggColor = Ryu_resolveRarityInfo(AssetCategory)
						local Ryu_checkerEggRate = Ryu_computeAreaEggValue({
							AssetCategory = AssetCategory,
							Category = AssetCategory,
							AssetScale = Record.AssetScale or Record.Scale or 1,
							Scale = Record.AssetScale or Record.Scale or 1,
							Mutations = Record.Mutations or {}
						})
						local Ryu_checkerEggWeight = Ryu_computeEggWeight(Record)
						local Ryu_checkerRowIndex = #Ryu_checkerRows + 1
						local Ryu_checkerRow = {
							rec = Record,
							uid = Record.Uid
						}
						local DisplayName = Directory2 and Directory2.DisplayName

						if not DisplayName then
							DisplayName = tostring(AssetCategory or "Egg")
						end

						Ryu_checkerRow.name = DisplayName
						Ryu_checkerRow.rarity = Ryu_checkerEggRarity
						Ryu_checkerRow.rnum = Ryu_checkerEggRank
						Ryu_checkerRow.color = Ryu_checkerEggColor
						Ryu_checkerRow.area = tostring(Record.AreaId or "?")
						Ryu_checkerRow.rate = Ryu_checkerEggRate
						Ryu_checkerRow.kg = Ryu_checkerEggWeight
						Ryu_checkerRow.icon = Ryu_findIconUrl(AssetCategory)
						Ryu_checkerRows[Ryu_checkerRowIndex] = Ryu_checkerRow
					end
				end
			end

			if Ryu_EggCheckerUI.rarity ~= "All" then
				local Ryu_createInvHeaderLabel_var3 = {}

				for _, v in ipairs(Ryu_checkerRows) do
					if v.rarity == Ryu_EggCheckerUI.rarity then
						Ryu_createInvHeaderLabel_var3[#Ryu_createInvHeaderLabel_var3 + 1] = v
					end
				end

				Ryu_checkerRows = Ryu_createInvHeaderLabel_var3
			end

			table.sort(Ryu_checkerRows, function(entryA, entryB)
				if Ryu_EggCheckerUI.sort == "rarity" then
					if entryA.rnum == entryB.rnum then
						return (entryA.rate or 0) > (entryB.rate or 0)
					end

					return (entryA.rnum or 0) > (entryB.rnum or 0)
				end

				if entryA.rate == entryB.rate then
					return (entryA.rnum or 0) > (entryB.rnum or 0)
				end

				return (entryA.rate or 0) > (entryB.rate or 0)
			end)

			return Ryu_checkerRows
		end
		Ryu_EggCheckerUI.paintChips = function()
			for k, chip in pairs(Ryu_EggCheckerUI.chips) do
				local Ryu_isRarityChipActive = k == Ryu_EggCheckerUI.rarity

				chip.BackgroundTransparency = Ryu_isRarityChipActive and 0.1 or 0.9
				chip.TextColor3 = Ryu_isRarityChipActive and Color3.fromRGB(255, 255, 255) or chip:GetAttribute("chipColor") and Color3.fromHex(chip:GetAttribute("chipColor")) or Ryu_uiTheme.btnText

				local UIStroke = chip:FindFirstChildOfClass("UIStroke")

				if UIStroke then
					UIStroke.Transparency = Ryu_isRarityChipActive and 0 or 0.65
				end
			end

			for k, sortBtn in pairs(Ryu_EggCheckerUI.sortBtns) do
				local Ryu_isSortChipActive = k == Ryu_EggCheckerUI.sort

				sortBtn.BackgroundColor3 = Ryu_isSortChipActive and Ryu_uiTheme.accent or Color3.fromRGB(255, 255, 255)
				sortBtn.BackgroundTransparency = Ryu_isSortChipActive and 0.12 or 0.9
				sortBtn.TextColor3 = Ryu_isSortChipActive and Color3.fromRGB(255, 255, 255) or Ryu_uiTheme.btnText
			end

			local __oxioStealMode = genv.__oxioStealMode or "Fly"
			local pairs_2 = pairs
			local modeBtns = Ryu_EggCheckerUI.modeBtns or {}

			for k, modeBtn in pairs_2(modeBtns) do
				local Ryu_isModeChipActive = __oxioStealMode == k

				modeBtn.BackgroundColor3 = Ryu_isModeChipActive and Ryu_uiTheme.accent or Color3.fromRGB(255, 255, 255)
				modeBtn.BackgroundTransparency = Ryu_isModeChipActive and 0.12 or 0.9
				modeBtn.TextColor3 = Ryu_isModeChipActive and Color3.fromRGB(255, 255, 255) or Ryu_uiTheme.btnText

				local UIStroke = modeBtn:FindFirstChildOfClass("UIStroke")

				if UIStroke then
					UIStroke.Transparency = Ryu_isModeChipActive and 0 or 0.7
				end
			end
		end
		Ryu_EggCheckerUI.paintRows = function()
			local Ryu_createInvHeaderLabel_var1 = 0

			for _, row in ipairs(Ryu_EggCheckerUI.rows) do
				local Ryu_isRowPicked = Ryu_EggCheckerUI.picked[tostring(row.uid)] == true

				if Ryu_isRowPicked then
					Ryu_createInvHeaderLabel_var1 += 1
				end

				row.frame.BackgroundTransparency = Ryu_isRowPicked and 0.02 or 0.14

				local UIStroke = row.frame:FindFirstChildOfClass("UIStroke")

				if UIStroke then
					UIStroke.Transparency = Ryu_isRowPicked and 0 or 0.78
				end

				if row.tick then
					row.tick.BackgroundTransparency = Ryu_isRowPicked and 0.05 or 0.86
					row.tick.Text = Ryu_isRowPicked and "OK" or ""
				end
			end

			if Ryu_EggCheckerUI.statusBtn and not Ryu_EggCheckerUI.running then
				Ryu_EggCheckerUI.statusBtn.Text = Ryu_createInvHeaderLabel_var1 > 0 and "Steal Selected (" .. Ryu_createInvHeaderLabel_var1 .. ")" or "Steal Selected"
