		local function Ryu_normalizePetNameKey(petName)
			if not petName or type(petName) ~= "string" then
				return "unknown"
			end

			local Ryu_normalizePetKey = petName:lower()

			if Ryu_normalizePetKey:find("kong") or Ryu_normalizePetKey:find("gorilla") then
				return "gorillaking"
			end

			if Ryu_normalizePetKey:find("phoenix") then
				return "phoenix"
			end

			if Ryu_normalizePetKey:find("lunar") or Ryu_normalizePetKey:find("dragon.-lunar") then
				return "lunardragon"
			end

			if Ryu_normalizePetKey:find("mosa") then
				return "mosasaurus"
			end

			if Ryu_normalizePetKey:find("tiger") or Ryu_normalizePetKey:find("oni") then
				return "onitiger"
			end

			if Ryu_normalizePetKey:find("kitsune") then
				return "kitsune"
			end

			if Ryu_normalizePetKey:find("unicorn") then
				return "unicorn"
			end

			if Ryu_normalizePetKey:find("godzilla") then
				return "godzilla"
			end

			if Ryu_normalizePetKey:find("pegasus") then
				return "pegasus"
			end

			if Ryu_normalizePetKey:find("archangel") then
				return "archangel"
			end

			if Ryu_normalizePetKey:find("ice.-dragon") then
				return "icedragon"
			end

			if Ryu_normalizePetKey:find("lava.-dragon") or Ryu_normalizePetKey:find("dragon") then
				return "lavadragon"
			end

			if Ryu_normalizePetKey:find("cosmic.-dragon") or Ryu_normalizePetKey:find("ember") then
				return "cosmicdragon"
			end

			if Ryu_normalizePetKey:find("trex") or Ryu_normalizePetKey:find("tyranno") or Ryu_normalizePetKey:find("t%-rex") then
				return "trex"
			end

			if Ryu_normalizePetKey:find("gargoyle") then
				return "gargoyle"
			end

			if Ryu_normalizePetKey:find("cerberus") then
				return "cerberus"
			end

			if Ryu_normalizePetKey:find("yeti") then
				return "yeti"
			end

			if Ryu_normalizePetKey:find("dreadscale") then
				return "dreadscale"
			end

			if Ryu_normalizePetKey:find("el.-maja") then
				return "elmaja"
			end

			return (Ryu_normalizePetKey:gsub("eternal", ""):gsub("ascended", ""):gsub("vermilion", ""):gsub("divine", ""):gsub("secret", ""):gsub("egg", ""):gsub("[^%a%d]", ""))
		end
		local function Ryu_roundToCycle(cycleSeconds)
			if not cycleSeconds or cycleSeconds <= 0 then
				return 0
			end

			return math.floor((cycleSeconds + 150) / 300) * 300
		end
		local function Ryu_formatTimestamp(timestamp, showSeconds)
			if not timestamp or timestamp <= 0 then
				return "--:--"
			end

			local now = os.time()
