			elseif Ryu_targetTimeTable.year == Ryu_nowTimeTable.year and Ryu_targetTimeTable.yday == Ryu_nowTimeTable.yday - 1 then
				Ryu_formatTimestamp_var1 = "Yesterday"
			elseif Ryu_targetTimeTable.year == Ryu_nowTimeTable.year and Ryu_targetTimeTable.yday == Ryu_nowTimeTable.yday + 1 then
				Ryu_formatTimestamp_var1 = "Tomorrow"
			else
				Ryu_formatTimestamp_var1 = string.format("%02d/%02d", Ryu_targetTimeTable.month, Ryu_targetTimeTable.day)
			end

			if showSeconds then
				return string.format("%s %02d:%02d:%02d", Ryu_formatTimestamp_var1, Ryu_targetTimeTable.hour, Ryu_targetTimeTable.min, Ryu_targetTimeTable.sec)
			end

