		local function Ryu_formatRelativeTime(timestamp)
			if not timestamp or timestamp <= 0 then
				return ""
			end

			local Ryu_ageSeconds = os.time() - timestamp

			if Ryu_ageSeconds < 0 then
				local Ryu_ageSecondsAbs = -Ryu_ageSeconds

				if Ryu_ageSecondsAbs < 60 then
					return "in <1m"
				end

				if Ryu_ageSecondsAbs < 3600 then
					return string.format("in %dm", math.floor(Ryu_ageSecondsAbs / 60))
				end

				return string.format("in %.1fh", Ryu_ageSecondsAbs / 3600)
			end

			if Ryu_ageSeconds < 60 then
				return "Just now"
			end

			if Ryu_ageSeconds < 3600 then
				return string.format("%dm ago", math.floor(Ryu_ageSeconds / 60))
			end

			if Ryu_ageSeconds < 86400 then
				return string.format("%.1fh ago", Ryu_ageSeconds / 3600)
			end

			return string.format("%.1fd ago", Ryu_ageSeconds / 86400)
		end
		local function Ryu_formatWindowRange(startTime, endTime)
			local Ryu_windowStartRounded = Ryu_roundToCycle(startTime)
			local Ryu_windowEndRounded = Ryu_roundToCycle(endTime)
			local now = os.time()
			local Ryu_nowTimeTable2 = os.date("*t", now)
			local Ryu_startTimeTable = os.date("*t", Ryu_windowStartRounded)
