				end

				if timeTable.year == Ryu_nowTimeTable2.year and timeTable.yday == Ryu_nowTimeTable2.yday - 1 then
					return "Yesterday"
				end

				return string.format("%02d/%02d", timeTable.month, timeTable.day)
			end

			local Ryu_startDayLabel = Ryu_getDayLabel(Ryu_startTimeTable)
			local Ryu_endDayLabel = Ryu_getDayLabel(Ryu_endTimeTable)

			if Ryu_startDayLabel == Ryu_endDayLabel then
				return string.format("%s %02d:%02d - %02d:%02d", Ryu_startDayLabel, Ryu_startTimeTable.hour, Ryu_startTimeTable.min, Ryu_endTimeTable.hour, Ryu_endTimeTable.min)
			end

			return string.format("%s %02d:%02d - %s %02d:%02d", Ryu_startDayLabel, Ryu_startTimeTable.hour, Ryu_startTimeTable.min, Ryu_endDayLabel, Ryu_endTimeTable.hour, Ryu_endTimeTable.min)
