		local function Ryu_recordEggSpawn(spawnData)
			if not spawnData or not spawnData.name then
				return false
			end

			local now = tonumber(spawnData.ts) or os.time()

			spawnData.ts = now

			local Ryu_rarityLower = (spawnData.rarity or ""):lower()

			if Ryu_rarityLower ~= "eternal" and Ryu_rarityLower ~= "divine" then
				return false
			end

			local Ryu_petKeyNorm = Ryu_normalizePetNameKey(spawnData.name)

			for _, v in ipairs(Ryu_EggDataUI.history) do
				if v.uid and spawnData.uid and v.uid == spawnData.uid then
					return false
				end

				if Ryu_normalizePetNameKey(v.name) ~= Ryu_petKeyNorm then
					continue
				end

				if not (math.abs((v.ts or 0) - now) < 600) then
					continue
				end

				return false
			end

			table.insert(Ryu_EggDataUI.history, spawnData)
			table.sort(Ryu_EggDataUI.history, function(entryA, entryB)
				return (entryA.ts or 0) > (entryB.ts or 0)
			end)

			if Ryu_rarityLower == "eternal" then
				if not Ryu_EggDataUI.lastEternal then
					Ryu_EggDataUI.lastEternal = spawnData
				elseif (Ryu_EggDataUI.lastEternal.ts or 0) <= now then
					Ryu_EggDataUI.lastEternal = spawnData

					return true
				end
			elseif Ryu_rarityLower == "divine" then
				if not Ryu_EggDataUI.lastDivine then
					Ryu_EggDataUI.lastDivine = spawnData
				elseif (Ryu_EggDataUI.lastDivine.ts or 0) <= now then
					Ryu_EggDataUI.lastDivine = spawnData

					return true
				end
			end

			return true
		end

