				end

				if not candidateNames or not (#candidateNames > 0) then
					return v
				end

				local Ryu_petKeyNorm2 = Ryu_normalizePetNameKey(v.name)

				for _, Ryu_item in ipairs(candidateNames) do
					if Ryu_normalizePetNameKey(Ryu_item.name) == Ryu_petKeyNorm2 then
						return v
					end
				end
			end

			return nil
		end

