		local function Ryu_parseSpawnMessage(message)
			if not message or type(message) ~= "string" then
				return nil
			end

			if not message:find("spawned in") then
				return nil
			end

			local Ryu_cleanedSpawnText = message:gsub("<[^>]+>", ""):gsub("[%c]", "")
			local match, match2, Ryu_spawnAreaMatch = Ryu_cleanedSpawnText:match("A%s+(%a+)%s+(.-)%s+Egg%s+spawned%s+in%s+([^!]+)")

			if not match or not match2 or not Ryu_spawnAreaMatch then
				match2, match, Ryu_spawnAreaMatch = Ryu_cleanedSpawnText:match("([%w%s]+)%s*%((%a+)%)%s+has%s+spawned%s+in%s+([^!]+)")
			end

			if not match or not match2 or not Ryu_spawnAreaMatch then
				return nil
			end

			local Ryu_spawnArea = Ryu_spawnAreaMatch:gsub("%s+$", ""):gsub("^%s+", "")
			local Ryu_spawnRarity = match2:gsub("%s+$", ""):gsub("^%s+", "")

			return match:gsub("%s+$", ""):gsub("^%s+", ""), Ryu_spawnRarity, Ryu_spawnArea
		end
		local function Ryu_processSpawnMessage(message)
			local Ryu_spawnRarity2, Ryu_spawnPetName, Ryu_spawnArea2 = Ryu_parseSpawnMessage(message)

			if not Ryu_spawnRarity2 or not Ryu_spawnPetName or not Ryu_spawnArea2 then
				return
			end

			local now = os.time()
			local Ryu_spawnPetKey = Ryu_normalizePetNameKey(Ryu_spawnPetName)
			local Ryu_spawnAlertBucket = math.floor(now / 300)
			local Ryu_spawnAlertKey = string.format("alert_%s_%s_%d", Ryu_spawnPetKey, Ryu_spawnArea2:lower(), Ryu_spawnAlertBucket)

			if Ryu_EggDataUI.reportedUids[Ryu_spawnAlertKey] then
				return
			end

			Ryu_EggDataUI.reportedUids[Ryu_spawnAlertKey] = now
			Ryu_EggDataUI.lastAlert = {
				pet = Ryu_spawnPetName,
				area = Ryu_spawnArea2,
				rarity = Ryu_spawnRarity2,
				ts = now,
				norm = Ryu_spawnPetKey
			}

			if Ryu_recordEggSpawn({
				uid = Ryu_spawnAlertKey,
				name = Ryu_spawnPetName,
				area = Ryu_spawnArea2,
				rarity = Ryu_spawnRarity2,
				ts = now,
				reporter = "Server Alert"
			}) then
				pcall(Ryu_EggDataUI.paint)
			end
		end

		Ryu_EggDataUI.reportSpawn = function(uid, petName, area, rarity, timestamp)
			if not uid or Ryu_EggDataUI.reportedUids[uid] then
				return
			end

			local now = os.time()
			local Ryu_spawnReportTs = tonumber(timestamp) or now

			if now - Ryu_EggDataUI.lastReportTime < 3 then
				return
			end

			Ryu_EggDataUI.reportedUids[uid] = Ryu_spawnReportTs
			Ryu_EggDataUI.lastReportTime = now

			local Name = LocalPlayer and LocalPlayer.Name or "Player"

			if Ryu_recordEggSpawn({
				uid = tostring(uid),
				name = petName,
				area = area,
				rarity = rarity,
				ts = Ryu_spawnReportTs,
				reporter = Name
			}) then
				pcall(Ryu_EggDataUI.paint)
			end
		end
		Ryu_EggDataUI.syncBackend = function()
			local now = os.time()

			if now - Ryu_EggDataUI.lastSync < 10 then
				return
			end

			Ryu_EggDataUI.lastSync = now
			task.spawn(function()
				local SenaBackend = getgenv and getgenv().SenaBackend or {}
				local Api = SenaBackend.Api or "http://56.10.112.179:8080"
				local Key = SenaBackend.Key or ""
				local Ryu_localUserId = LocalPlayer and tostring(LocalPlayer.UserId) or "0"
				local Ryu_eggSyncResponse = Ryu_httpRequest({
					Url = Api .. "/egg/latest?key=" .. tostring(Key) .. "&uid=" .. tostring(Ryu_localUserId) .. "&t=" .. tostring(now),
					Method = "GET"
				})

				if Ryu_eggSyncResponse and (Ryu_eggSyncResponse.StatusCode == 200 or Ryu_eggSyncResponse.Status == 200) and Ryu_eggSyncResponse.Body then
					local HttpService2 = game:GetService("HttpService")
					local ok, result = pcall(function()
						return HttpService2:JSONDecode(Ryu_eggSyncResponse.Body)
					end)

					if ok and type(result) == "table" and result.ok then
						if result.last_eternal and type(result.last_eternal) == "table" and result.last_eternal.name then
							Ryu_recordEggSpawn(result.last_eternal)
						end

						if result.last_divine and type(result.last_divine) == "table" and result.last_divine.name then
							Ryu_recordEggSpawn(result.last_divine)
						end

						if type(result.recent_spawns) == "table" then
							for _, recentSpawn in ipairs(result.recent_spawns) do
								Ryu_recordEggSpawn(recentSpawn)
							end
						end

						pcall(Ryu_EggDataUI.paint)
					end
				end
			end)
		end
		Ryu_EggDataUI.scanField = function()
			local Ryu_processSpawnMessage_var2

			pcall(function()
				Ryu_processSpawnMessage_var2 = EggState2.ReadFieldEggs()
			end)

			if not Ryu_processSpawnMessage_var2 or not Ryu_processSpawnMessage_var2.Records then
				return
			end

			local now = os.time()

			if not Ryu_EggDataUI._fieldInitialized then
				Ryu_EggDataUI._fieldInitialized = true

				for _, record in ipairs(Ryu_processSpawnMessage_var2.Records) do
					if record.Uid then
						Ryu_EggDataUI.knownFieldUids[record.Uid] = true
					end
				end

				return
			end

			for _, record in ipairs(Ryu_processSpawnMessage_var2.Records) do
				if record.Uid and not Ryu_EggDataUI.knownFieldUids[record.Uid] then
					Ryu_EggDataUI.knownFieldUids[record.Uid] = true

					if record.State ~= "Claimed" and record.BottomCFrame then
						local AssetCategory = record.AssetCategory
						local _, Ryu_fieldEggRarity = Ryu_resolveRarityInfo(AssetCategory)

						if Ryu_fieldEggRarity == "Divine" or Ryu_fieldEggRarity == "Eternal" then
							local Ryu_fieldEggNameAliased = AssetCategory == "King Kong" and "Gorilla King" or AssetCategory == "Ascended Vermilion Phoenix" and "Phoenix" or AssetCategory
							local ts = now

							if Ryu_EggDataUI.lastAlert then
								if now - (Ryu_EggDataUI.lastAlert.ts or 0) <= 60 and Ryu_normalizePetNameKey(Ryu_EggDataUI.lastAlert.pet) == Ryu_normalizePetNameKey(Ryu_fieldEggNameAliased) then
									if Ryu_EggDataUI.lastAlert.area:lower() == (record.AreaId or ""):lower() then
										ts = Ryu_EggDataUI.lastAlert.ts
									end
								end
							end

							Ryu_EggDataUI.reportSpawn(record.Uid, Ryu_fieldEggNameAliased, record.AreaId or "Field", Ryu_fieldEggRarity, ts)
						end
					end
				end
			end
		end
