							while Ryu_windowMinSec * 0.75 < now - Ryu_windowEnd do
								Ryu_windowStart = Ryu_windowEnd + Ryu_windowMinSec
								Ryu_windowEnd = Ryu_windowStart + Ryu_windowRangeSec
							end
						end

						local Ryu_windowStartRounded2 = Ryu_roundToCycle(Ryu_windowStart)
						local Ryu_windowEndRounded2 = Ryu_roundToCycle(Ryu_windowEnd)
