		local function Ryu_openPanelWindow(panelKey)
			Ryu_applyElevatedIdentity()

			local Ryu_panelConfig = Ryu_uiPanels[panelKey]

			if not Ryu_panelConfig then
				return
			end

			local name = "__SNE_Panel_" .. panelKey

			local function Ryu_getPlayerGui()
				local ok, result = pcall(function()
					return LocalPlayer:FindFirstChild("PlayerGui")
				end)
				local Ryu_playerGui = ok and result or nil

				return Ryu_playerGui
			end

			for _, v in ipairs({
				game:GetService("CoreGui"),
				Ryu_getPlayerGui()
			}) do
				if v then
					pcall(function()
						for _, descendant in ipairs(v:GetDescendants()) do
							if descendant.Name == name and descendant:IsA("ScreenGui") then
								pcall(function()
									descendant:Destroy()
								end)
							end
						end
					end)
				end
			end

			local Ryu_guiHost = Ryu_getUiHost()
			local ScreenGui = Instance.new("ScreenGui")

			ScreenGui.Name = name
			ScreenGui.ResetOnSpawn = false
			ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			ScreenGui.DisplayOrder = 99999
			ScreenGui.Parent = Ryu_guiHost

			local Ryu_getPlayerGui_var1 = 0

			for i, v in ipairs(Ryu_uiTabs) do
				if v == panelKey then
					Ryu_getPlayerGui_var1 = i - 1
				end
			end

			local Frame = Instance.new("Frame")

			Frame.AnchorPoint = Vector2.new(0.5, 0.5)
			Frame.Size = UDim2.fromOffset(Ryu_panelConfig.w, Ryu_panelConfig.h)
			Frame.BackgroundTransparency = 1
			Frame.Active = true
			Frame.Parent = ScreenGui

			local UIScale = Instance.new("UIScale")

			UIScale.Name = "WindowScale"
			UIScale.Scale = 1
			UIScale.Parent = Frame

			local UserInputService = game:GetService("UserInputService")

			local function Ryu_fitPanelToViewport(initialLayout)
				local CurrentCamera = workspace.CurrentCamera
				local ViewportSize = CurrentCamera and CurrentCamera.ViewportSize or Vector2.new(1024, 768)

				if ViewportSize.X <= 0 or ViewportSize.Y <= 0 then
					return
				end

				local Ryu_isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled or ViewportSize.Y < 550
				local Ryu_fitScale = math.min(1, ViewportSize.X * (Ryu_isMobile and 0.86 or 0.94) / Ryu_panelConfig.w, ViewportSize.Y * (Ryu_isMobile and 0.88 or 0.92) / Ryu_panelConfig.h)

				if Ryu_isMobile and Ryu_fitScale > 0.82 then
					Ryu_fitScale = 0.82
				end

				UIScale.Scale = math.clamp(Ryu_fitScale, 0.48, 1)

				local Scale = UIScale.Scale
				local Ryu_scaledWidth = Ryu_panelConfig.w * Scale
				local Ryu_scaledHeight = Ryu_panelConfig.h * Scale

				if initialLayout then
					if Ryu_isMobile then
						local Ryu_mobileX = ViewportSize.X - math.floor(Ryu_scaledWidth / 2) - 14
						local Ryu_mobileY = math.floor(ViewportSize.Y / 2)

						Frame.Position = UDim2.fromOffset(Ryu_mobileX, Ryu_mobileY)
					else
						local Ryu_desktopYOffset = Ryu_getPlayerGui_var1 * 20

						Frame.Position = UDim2.fromOffset(math.floor(ViewportSize.X / 2 + Ryu_getPlayerGui_var1 * 24), math.floor(ViewportSize.Y / 2 + Ryu_desktopYOffset))
					end
				end

				local Ryu_halfScaledW = Ryu_scaledWidth / 2
				local Ryu_halfScaledH = Ryu_scaledHeight / 2
				local Ryu_clampXMin = math.min(Ryu_halfScaledW + 8, ViewportSize.X / 2)
				local Ryu_clampXMax = math.max(ViewportSize.X - Ryu_halfScaledW - 8, ViewportSize.X / 2)
				local Ryu_clampYMin = math.min(Ryu_halfScaledH + 8, ViewportSize.Y / 2)
				local Ryu_clampYMax = math.max(ViewportSize.Y - Ryu_halfScaledH - 8, ViewportSize.Y / 2)
				local Ryu_panelAbsoluteY = Frame.Position.Y.Scale * ViewportSize.Y + Frame.Position.Y.Offset
				local floor = math.floor

				Frame.Position = UDim2.fromOffset(math.floor(math.clamp(Frame.Position.X.Scale * ViewportSize.X + Frame.Position.X.Offset, Ryu_clampXMin, Ryu_clampXMax)), floor(math.clamp(Ryu_panelAbsoluteY, Ryu_clampYMin, Ryu_clampYMax)))
			end

