			local TextLabel7 = Instance.new("TextLabel")

			TextLabel7.BackgroundTransparency = 1
			TextLabel7.Position = UDim2.fromOffset(24, 0)
			TextLabel7.Size = UDim2.new(1, -28, 1, 0)
			TextLabel7.Font = Enum.Font.GothamBold
