			local TextButton2 = Instance.new("TextButton")

			TextButton2.Position = UDim2.new(1, -36, 0, 8)
			TextButton2.Size = UDim2.fromOffset(26, 26)
			TextButton2.BackgroundColor3 = Ryu_buildAllUI_var1.btnBg
			TextButton2.BackgroundTransparency = 0.15
			TextButton2.AutoButtonColor = false
			TextButton2.Font = Enum.Font.GothamBold
			TextButton2.TextSize = 13
			TextButton2.TextColor3 = Ryu_buildAllUI_var1.btnText
			TextButton2.Text = "X"
			TextButton2.ZIndex = 5
			TextButton2.Parent = Frame2
			Instance.new("UICorner", TextButton2).CornerRadius = UDim.new(0, 4)

			local UIStroke4 = Instance.new("UIStroke", TextButton2)

			UIStroke4.Color = Ryu_buildAllUI_var1.strokeCol
			UIStroke4.Thickness = 1
			UIStroke4.Transparency = 0.6
			TextButton2.MouseButton1Click:Connect(function()
				Ryu_applyElevatedIdentity()
				ScreenGui.Enabled = false
			end)

			local Frame4 = Instance.new("Frame")

			Frame4.Position = UDim2.fromOffset(0, 72)
			Frame4.Size = UDim2.new(1, 0, 1, -120)
			Frame4.BackgroundTransparency = 1
			Frame4.BorderSizePixel = 0
			Frame4.Parent = Frame2

			local Ryu_fitPanelToViewport_var1 = false
			local Position
			local Position2

			local function Ryu_onDragStart(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					Ryu_fitPanelToViewport_var1 = true
					Position = input.Position
					Position2 = Frame.Position
				end
			end

			TextLabel5.InputBegan:Connect(Ryu_onDragStart)
			Frame3.InputBegan:Connect(Ryu_onDragStart)
			Frame2.InputBegan:Connect(function(input)
				if input.Position.Y - Frame.AbsolutePosition.Y <= 44 * (UIScale and UIScale.Scale or 1) then
					Ryu_onDragStart(input)
				end
			end)
			UserInputService.InputChanged:Connect(function(input)
				if Ryu_fitPanelToViewport_var1 and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
					local Ryu_dragDelta = input.Position - Position

					Frame.Position = UDim2.new(Position2.X.Scale, Position2.X.Offset + Ryu_dragDelta.X, Position2.Y.Scale, Position2.Y.Offset + Ryu_dragDelta.Y)
				end
			end)
			UserInputService.InputEnded:Connect(function(input)
				if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) and Ryu_fitPanelToViewport_var1 then
					Ryu_fitPanelToViewport_var1 = false
					pcall(Ryu_fitPanelToViewport, false)
				end
			end)
			Ryu_fitPanelToViewport(true)

			local CurrentCamera = workspace.CurrentCamera

			if CurrentCamera then
				CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
					if ScreenGui and ScreenGui.Parent and ScreenGui.Enabled then
						pcall(Ryu_fitPanelToViewport, false)
					end
				end)
			end

