				gui = ScreenGui,
				page = Frame4,
				holder = Frame,
				fitScale = Ryu_fitPanelToViewport
			}
			pcall(function()
				Ryu_panelConfig.build(Frame4)
			end)
			pcall(function()
				Ryu_refreshPanelByKey(panelKey)
			end)
		end
		local function Ryu_openOrCreatePanel(panelKey)
			Ryu_applyElevatedIdentity()

			local Ryu_panelKey = panelKey or "logs"
			local Ryu_existingPanel = windows[Ryu_panelKey]

			if not Ryu_existingPanel or not Ryu_existingPanel.gui or not Ryu_existingPanel.gui.Parent then
				Ryu_openPanelWindow(Ryu_panelKey)

				return
			end

			Ryu_existingPanel.gui.Enabled = true

			if Ryu_existingPanel.fitScale then
				pcall(Ryu_existingPanel.fitScale, false)
			end

			pcall(function()
				Ryu_refreshPanelByKey(Ryu_panelKey)
			end)
		end
		local function Ryu_openAllPanels()
			for _, v in ipairs(Ryu_uiTabs) do
				Ryu_openOrCreatePanel(v)
			end
		end
		local function Ryu_closeAllPanels()
			for _, window in pairs(windows) do
				if window and window.gui then
					window.gui.Enabled = false
				end
			end
		end

		task.spawn(function()
			while Ryu_isCurrentSession() do
				pcall(function()
					local Ryu_fieldEggSnapshot2 = EggState2.ReadFieldEggs()

					if Ryu_fieldEggSnapshot2 and Ryu_fieldEggSnapshot2.Records then
						for _, record in ipairs(Ryu_fieldEggSnapshot2.Records) do
							Ryu_incrementEggLog(record)
						end
					end
				end)
				pcall(function()
					if Ryu_EggDataUI and type(Ryu_EggDataUI.scanField) == "function" then
						Ryu_EggDataUI.scanField()
					end
				end)

				for _, v in ipairs({
					"logs",
					"eggs",
					"inventory",
					"checker",
					"eggdata"
				}) do
					if Ryu_isWindowOpen(v) then
						pcall(Ryu_refreshPanelByKey, v)
					end
				end

				task.wait(2)
			end
		end)
		senaPanels.windows = windows
		senaPanels.openLogs = function()
			Ryu_openOrCreatePanel("logs")
		end
		senaPanels.openBoard = function()
			Ryu_openOrCreatePanel("eggs")
		end
		senaPanels.openInventory = function()
			Ryu_openOrCreatePanel("inventory")
		end
		senaPanels.openChecker = function()
			Ryu_openOrCreatePanel("checker")
		end
		senaPanels.openAnalyst = function()
			Ryu_openOrCreatePanel("eggdata")
		end
		senaPanels.openAll = function()
			Ryu_openAllPanels()
		end
		senaPanels.closeAll = function()
			Ryu_closeAllPanels()
		end
		pcall(function()
			getgenv().SenaPanels = senaPanels
		end)
	end

	Ryu_buildAllUI()

	-- ============================================================
-- PREDICTOR WINDOW (compact)
-- ============================================================
do
	local P = { window = nil, eggCards = {}, fuseSlots = {}, filter = "All", sortKey = "Value", search = "" }
	genv.__oxioPredictor = P

	local function C3(hex) return Color3.fromHex(hex) end
	local function new(cls, props, parent)
		local i = Instance.new(cls)
		for k, v in pairs(props or {}) do i[k] = v end
		if parent then i.Parent = parent end
		return i
	end
	local function compactNum(n)
		n = tonumber(n) or 0
		if n >= 1e9 then return string.format("%.1fB", n/1e9) end
		if n >= 1e6 then return string.format("%.1fM", n/1e6) end
		if n >= 1e3 then return string.format("%.0fK", n/1e3) end
		return string.format("%d", math.floor(n+0.5))
	end
	local function clockStr(s)
		s = math.max(math.floor(tonumber(s) or 0), 0)
		if s >= 3600 then return string.format("%dh%02dm", s//3600, s%3600//60) end
		return string.format("%dm%02ds", s//60, s%60)
	end
	local function rarGradient(rarity)
		local ok, Assets = pcall(require, ReplicatedStorage.Data.Assets)
		if not ok then return ColorSequence.new(C3("#8F98A8"), C3("#E6EAF2")) end
		local grad = Assets.UI and Assets.UI.RarityGradients and Assets.UI.RarityGradients:FindFirstChild(rarity)
		local g = grad and (grad:IsA("UIGradient") and grad or grad:FindFirstChildWhichIsA("UIGradient", true))
		return g and g.Color or ColorSequence.new(C3("#8F98A8"), C3("#E6EAF2"))
	end
	local function rarColor(rarity)
		local ok, Assets = pcall(require, ReplicatedStorage.Data.Assets)
		if not ok then return C3("#FFFFFF") end
		for _, v in pairs(Assets.Directory or {}) do
			if v.Rarity and (v.Rarity.DisplayName or v.Rarity._id) == rarity then
				return v.Rarity.Color or C3("#FFFFFF")
			end
		end
		return C3("#FFFFFF")
	end

	local function readEggs()
		local out = {}
		pcall(function()
			local EggState   = require(ReplicatedStorage.Client.EggState)
			local Assets     = require(ReplicatedStorage.Data.Assets)
			local EggRecords = require(ReplicatedStorage.Shared.Util.EggRecords)
			local AE; pcall(function() AE = require(ReplicatedStorage.Shared.Util.AssetEarnings) end)
			local owned = EggState.ReadOwnerEggs(LocalPlayer.UserId)
			if type(owned) ~= "table" then return end
			local now = workspace:GetServerTimeNow()
			for uid, rec in pairs(owned) do
				if type(rec) ~= "table" then continue end
				local def     = Assets.Directory[rec.AssetCategory]
				local rarity  = def and def.Rarity and (def.Rarity.DisplayName or def.Rarity._id) or "Unknown"
				local name    = def and (def.DisplayName or def._id) or tostring(rec.AssetCategory)
				local scale   = tonumber(rec.AssetScale) or 0
				local income  = 0
				if AE and AE.LiveRatePerSecond then
					pcall(function() income = AE.LiveRatePerSecond(rec) or 0 end)
				end
				local status, remaining, percent = "Inventory", math.huge, 0
				if rec.Placement ~= nil then
					local ready = false
					pcall(function() ready = EggState.IsReadyToHatch(uid) end)
					if ready then
						status, remaining, percent = "Ready", 0, 100
					else
						status = "Growing"
						pcall(function()
							local mult = EggRecords.GrowthSpeedMultiplier and EggRecords.GrowthSpeedMultiplier(rec) or 1
							remaining  = EggRecords.GrowthSecondsRemaining and EggRecords.GrowthSecondsRemaining(rec, now, mult) or 0
							local dur  = EggRecords.GrowthDuration and EggRecords.GrowthDuration(rec) or 0
							if dur > 0 then percent = math.clamp(math.floor((1 - remaining/dur)*100), 0, 100) end
						end)
					end
				end
				local mutations = type(rec.Mutations) == "table" and rec.Mutations or {}
				local mutTxt = ""
				if #mutations > 0 then
					local names = {}
					for _, m in ipairs(mutations) do names[#names+1] = tostring(m) end
					mutTxt = table.concat(names, "+")
				end
				local icon = ""
				pcall(function()
					if EggRecords.EggIcon then icon = EggRecords.EggIcon(rec) or "" end
				end)
				if icon == "" and def then
					if def.Egg and def.Egg.Icon then icon = tostring(def.Egg.Icon)
					elseif def.Icon then icon = tostring(def.Icon) end
				end
				local rank = 0; pcall(function() rank = Ryu_catalog.rarityRank(rarity) end)
				out[#out+1] = {
					uid=uid, name=name, rarity=rarity, rank=rank,
					scale=scale, income=income, status=status,
					remaining=remaining, percent=percent,
					mutationText=mutTxt, icon=icon,
				}
			end
		end)
		return out
	end

	local function sortEggs(list, key)
		table.sort(list, function(a, b)
			if key == "Rarity" and a.rank ~= b.rank then return a.rank > b.rank end
			if key == "Time Left" and a.remaining ~= b.remaining then return a.remaining < b.remaining end
			if a.income ~= b.income then return a.income > b.income end
			return tostring(a.uid) < tostring(b.uid)
		end)
	end

	-- Compact card: 120x170
	local function makeCard(parent, lo)
		local card = new("Frame", {
			Size = UDim2.fromOffset(120, 170),
			BackgroundColor3 = C3("#0E0E14"),
			BackgroundTransparency = 0.06,
			BorderSizePixel = 0,
			LayoutOrder = lo,
		}, parent)
		new("UICorner", { CornerRadius = UDim.new(0.07, 0) }, card)
		new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Transparency = 0.5 }, card)

		local iconBox = new("Frame", {
			Position = UDim2.fromScale(0.05, 0.04),
			Size = UDim2.new(0.9, 0, 0.38, 0),
			BackgroundColor3 = C3("#050509"),
			BackgroundTransparency = 0.3,
			BorderSizePixel = 0,
		}, card)
		new("UICorner", { CornerRadius = UDim.new(0.1, 0) }, iconBox)
		local icon = new("ImageLabel", {
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(0.88, 0.88),
			Position = UDim2.fromScale(0.06, 0.06),
			ScaleType = Enum.ScaleType.Fit,
			Image = "",
		}, iconBox)
		icon.Name = "Icon"
		local edge = new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Transparency = 0.55 }, iconBox)
		edge.Name = "Edge"

		local nameLbl = new("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromScale(0.05, 0.445),
			Size = UDim2.new(0.9, 0, 0.09, 0),
			Font = Enum.Font.GothamBold,
			TextSize = 11,
			TextColor3 = C3("#FFFFFF"),
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = "Egg",
		}, card)
		nameLbl.Name = "Name"

		local rarityLbl = new("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromScale(0.05, 0.535),
			Size = UDim2.new(0.9, 0, 0.07, 0),
			Font = Enum.Font.GothamBold,
			TextSize = 9,
			TextColor3 = C3("#FFFFFF"),
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = "COMMON",
		}, card)
		rarityLbl.Name = "Rarity"
		new("UIGradient", { Name = "RarityPaint", Rotation = 90 }, rarityLbl)

		local valueLbl = new("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromScale(0.05, 0.605),
			Size = UDim2.new(0.9, 0, 0.09, 0),
			Font = Enum.Font.GothamBold,
			TextSize = 11,
			TextColor3 = C3("#7BE38E"),
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = "$0/s",
		}, card)
		valueLbl.Name = "Value"

		local scaleLbl = new("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromScale(0.05, 0.695),
			Size = UDim2.new(0.9, 0, 0.07, 0),
			Font = Enum.Font.Gotham,
			TextSize = 9,
			TextColor3 = C3("#C9D1E0"),
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = "x1.00",
		}, card)
		scaleLbl.Name = "Scale"

		local prog = new("Frame", {
			Position = UDim2.fromScale(0.05, 0.83),
			Size = UDim2.new(0.9, 0, 0.085, 0),
			BackgroundColor3 = C3("#050509"),
			BackgroundTransparency = 0.15,
			BorderSizePixel = 0,
			ClipsDescendants = true,
		}, card)
		new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, prog)
		new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Transparency = 0.4 }, prog)
		local fill = new("Frame", { Size = UDim2.fromScale(0,1), BackgroundColor3 = C3("#FFFFFF"), BorderSizePixel = 0 }, prog)
		new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, fill)
		new("UIGradient", { Color = ColorSequence.new(C3("#5BE873"), C3("#A3E635")), Rotation = 0 }, fill)
		local progText = new("TextLabel", {
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1,1),
			Font = Enum.Font.GothamBold,
			TextSize = 9,
			TextColor3 = C3("#FFFFFF"),
			Text = "IN BAG",
			ZIndex = 3,
		}, prog)
		new("UIStroke", { Color = C3("#000000"), Thickness = 1.2 }, progText)

		return { frame=card, icon=icon, edge=edge, name=nameLbl, rarity=rarityLbl,
		         value=valueLbl, scale=scaleLbl, fill=fill, progressText=progText }
	end

	local function updateCard(card, egg)
		card.name.Text  = egg.name
		card.rarity.Text = string.upper(egg.rarity)
		local paint = card.rarity:FindFirstChild("RarityPaint")
		if paint then paint.Color = rarGradient(egg.rarity) end
		local rc = rarColor(egg.rarity)
		card.edge.Color = rc
		card.rarity.TextColor3 = rc
		card.value.Text = "$"..compactNum(egg.income).."/s"
		card.scale.Text = string.format("x%.2f", egg.scale)
		card.icon.Image = egg.icon or ""
		local st = "IN BAG"
		if egg.status == "Ready" then st = "READY"
		elseif egg.status == "Growing" then
			st = egg.remaining == math.huge and "GROWING" or (clockStr(egg.remaining).." "..egg.percent.."%")
		end
		card.progressText.Text = st
		card.fill.Size = UDim2.fromScale(
			egg.status == "Growing" and math.clamp(egg.percent/100, 0.04, 1) or 1, 1)
	end

	local function buildEggTab(parent)
		-- Thin filter bar
		local filterRow = new("Frame", {
			Position = UDim2.fromOffset(8, 6),
			Size = UDim2.new(1,-16, 0, 24),
			BackgroundTransparency = 1,
		}, parent)
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0,4), VerticalAlignment = Enum.VerticalAlignment.Center }, filterRow)

		local filterBtns = {}
		local function refreshFilter()
			for k, btn in pairs(filterBtns) do
				local act = k == P.filter
				btn.BackgroundColor3 = act and C3("#FFFFFF") or C3("#0E0E14")
				btn.BackgroundTransparency = act and 0 or 0.1
				btn.TextColor3 = act and C3("#000000") or C3("#FFFFFF")
			end
		end
		for _, def in ipairs({
			{key="All",label="ALL"},{key="Ready",label="READY"},{key="Growing",label="GROWING"},{key="Inventory",label="BAG"},
		}) do
			local btn = new("TextButton", {
				Size = UDim2.fromOffset(68, 24),
				BackgroundColor3 = C3("#0E0E14"), BackgroundTransparency = 0.1,
				Font = Enum.Font.GothamBold, TextSize = 10,
				TextColor3 = C3("#FFFFFF"), Text = def.label, AutoButtonColor = false,
			}, filterRow)
			new("UICorner", { CornerRadius = UDim.new(1,0) }, btn)
			new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.1, Transparency = 0.55 }, btn)
			btn.MouseButton1Click:Connect(function() P.filter = def.key; refreshFilter(); pcall(P.refreshEggs) end)
			filterBtns[def.key] = btn
		end
		refreshFilter()

		-- Sort + Search row
		local sortRow = new("Frame", {
			Position = UDim2.fromOffset(8, 36),
			Size = UDim2.new(1,-16, 0, 24),
			BackgroundTransparency = 1,
		}, parent)
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0,4), VerticalAlignment = Enum.VerticalAlignment.Center }, sortRow)
		local sortBtns = {}
		local function refreshSort()
			for k, btn in pairs(sortBtns) do
				local act = k == P.sortKey
				btn.BackgroundColor3 = act and C3("#FFFFFF") or C3("#0E0E14")
				btn.BackgroundTransparency = act and 0 or 0.1
				btn.TextColor3 = act and C3("#000000") or C3("#FFFFFF")
			end
		end
		for _, def in ipairs({
			{key="Value",label="VALUE"},{key="Rarity",label="RARITY"},{key="Time Left",label="TIME"},
		}) do
			local btn = new("TextButton", {
				Size = UDim2.fromOffset(72, 24),
				BackgroundColor3 = C3("#0E0E14"), BackgroundTransparency = 0.1,
				Font = Enum.Font.GothamBold, TextSize = 10,
				TextColor3 = C3("#FFFFFF"), Text = def.label, AutoButtonColor = false,
			}, sortRow)
			new("UICorner", { CornerRadius = UDim.new(1,0) }, btn)
			new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.1, Transparency = 0.55 }, btn)
			btn.MouseButton1Click:Connect(function() P.sortKey = def.key; refreshSort(); pcall(P.refreshEggs) end)
			sortBtns[def.key] = btn
		end
		refreshSort()

		local searchBox = new("TextBox", {
			Position = UDim2.fromOffset(8, 66),
			Size = UDim2.new(1,-16, 0, 22),
			BackgroundColor3 = C3("#050509"), BackgroundTransparency = 0.2,
			Font = Enum.Font.Gotham, TextSize = 11,
			TextColor3 = C3("#FFFFFF"), PlaceholderText = "Search...",
			PlaceholderColor3 = C3("#8A8FA3"), Text = "", ClearTextOnFocus = false,
		}, parent)
		new("UICorner", { CornerRadius = UDim.new(0,5) }, searchBox)
		new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1, Transparency = 0.6 }, searchBox)
		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			P.search = searchBox.Text or ""; pcall(P.refreshEggs)
		end)

		local scroll = new("ScrollingFrame", {
			Position = UDim2.fromOffset(8, 94),
			Size = UDim2.new(1,-16, 1, -100),
			BackgroundTransparency = 1, BorderSizePixel = 0,
			ScrollBarThickness = 3, ScrollBarImageColor3 = C3("#FFFFFF"),
			CanvasSize = UDim2.new(0,0,0,0),
		}, parent)
		new("UIGridLayout", {
			CellSize = UDim2.fromOffset(120, 170),
			CellPadding = UDim2.fromOffset(6, 6),
			SortOrder = Enum.SortOrder.LayoutOrder,
		}, scroll)

		P.eggScroll = scroll
		P.eggCards = {}

		P.refreshEggs = function()
			if not scroll or not scroll.Parent then return end
			for _, c in ipairs(scroll:GetChildren()) do
				if c:IsA("Frame") then c:Destroy() end
			end
			P.eggCards = {}
			local list = readEggs()
			sortEggs(list, P.sortKey)
			local q = (P.search or ""):lower()
			local shown = 0
			for _, e in ipairs(list) do
				if P.filter ~= "All" and e.status ~= P.filter then continue end
				if q ~= "" then
					local hay = (e.name.." "..e.rarity.." "..e.status.." "..e.mutationText):lower()
					if not hay:find(q, 1, true) then continue end
				end
				shown = shown + 1
				local card = makeCard(scroll, shown)
				updateCard(card, e)
				P.eggCards[#P.eggCards+1] = card
			end
			local cols = math.max(1, math.floor((scroll.AbsoluteSize.X + 6) / 126))
			local rows = math.ceil(shown / cols)
			scroll.CanvasSize = UDim2.new(0, 0, 0, rows * 176 + 6)
		end
		P.refreshEggs()
	end

	function P.open()
		if P.window and P.window.Gui and P.window.Gui.Parent then
			P.window.Gui.Enabled = true; return
		end
		local StarHubUI = genv.__oxioStarHubUI
		if not StarHubUI then warn("[oxio][Predictor] StarHubUI not ready"); return end

		local W = StarHubUI:CreateWindow({
			Title = "oxio predictor",
			SubTitle = "egg viewer",
			Size = UDim2.new(0, 580, 0, 380),
			ToggleKey = Enum.KeyCode.RightShift,
			Logo = "rbxassetid://118755181202304",
		})
		P.window = W

		local eggTab = W:CreateTab({ Title = "Eggs", LayoutOrder = 1 })

		local function findFrame(tab)
			for _, name in ipairs({"Page","Container","Content","Holder","Frame","Root","Body"}) do
				local f = rawget(tab, name)
				if typeof(f) == "Instance" then return f end
			end
			local host = W.Gui or W.Holder
			if host then
				for _, d in ipairs(host:GetDescendants()) do
					if d:IsA("Frame") and d.AbsoluteSize.X > 200 and d.AbsoluteSize.Y > 200 then return d end
				end
			end
			return nil
		end

		local eggFrame = findFrame(eggTab)
		if eggFrame then
			buildEggTab(eggFrame)
		else
			-- fallback overlay
			local CoreGui = game:GetService("CoreGui")
			local ov = new("ScreenGui", {
				Name = "OxioPredictorOverlay", ResetOnSpawn = false,
				DisplayOrder = 99998, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			}, CoreGui)
			P.overlay = ov
			local page = new("Frame", {
				Size = UDim2.new(0, 580, 0, 380),
				Position = UDim2.fromScale(0.5, 0.5),
				AnchorPoint = Vector2.new(0.5, 0.5),
				BackgroundColor3 = C3("#08080C"), BorderSizePixel = 0,
			}, ov)
			new("UICorner", { CornerRadius = UDim.new(0.015, 0) }, page)
			new("UIStroke", { Color = C3("#FFFFFF"), Thickness = 1.4, Transparency = 0.45 }, page)
			buildEggTab(page)
		end

		task.spawn(function()
			while P.window and P.window.Gui and P.window.Gui.Parent do
				pcall(P.refreshEggs)
				task.wait(3)
			end
		end)
	end

	function P.close()
		if P.window and P.window.Gui then
			pcall(function() P.window.Gui.Enabled = false end)
		end
		if P.overlay then
			pcall(function() P.overlay.Enabled = false end)
		end
	end
end

local function Ryu_buildMainWindow()
		pcall(function()
			local ChloeX_Instance = genv.ChloeX_Instance

			if type(ChloeX_Instance) == "table" and type(ChloeX_Instance.DestroyGui) == "function" then
				ChloeX_Instance:DestroyGui()
			end
		end)
		genv.ChloeX_Running = nil
		genv.ChloeX_ReopenPrompt = nil
		genv.ChloeX_Instance = nil

		local StarHubUI

		do
			local ok, result = pcall(function()
				return loadstring(game:HttpGet("https://raw.githubusercontent.com/STARLARP/StarHub-UI/main/StarHubUI.lua"))()
			end)

			StarHubUI = ok and result or nil
		end

		genv.__oxioStarHubUI = StarHubUI

		if not StarHubUI then
			warn("[oxio] StarHub UI gagal dimuat")

			return
		end
		-- ============================================================
		-- Branding & tema oxio (dijalankan SEBELUM window dibuat)
		-- Ikon asli StarHub: Logo, Search, Close, Minimize, Settings, ChevronDown, Palette,
		-- Save, Skull, Dashboard, Combat, Visuals, Teleport, Refresh, Server, Copy, Sound,
		-- SoundMute, Bell, Info, Check, Zap.
		-- ============================================================
		local OXIO_LOGO = "rbxassetid://118755181202304"

		do
			-- Tema: ubah semua warna aksen jadi putih (tabel tema dipakai library by-reference)
			local WHITE = Color3.fromRGB(255, 255, 255)
			local SOFT  = Color3.fromRGB(226, 229, 238)
			pcall(function()
				for _, th in pairs(StarHubUI.Themes or {}) do
					if type(th) == "table" then
						th.Grad1 = WHITE
						th.Grad2 = SOFT
						th.Accent = WHITE
						th.AccentLight = SOFT
					end
				end
			end)
			-- Logo default library (juga dipakai tombol melayang) -> logo oxio
			pcall(function()
				if type(StarHubUI.Settings) == "table" then
					StarHubUI.Settings.CustomLogoUrl = OXIO_LOGO
				end
			end)
		end

		-- ============================================================
		-- Icons: pakai nama ikon asli library. Nama yang tidak ada dipetakan ke yang terdekat.
		-- ============================================================
		local Icons
		do
			local raw = StarHubUI.Icons
			local alias = {
				flame = "Combat", home = "Dashboard", users = "Server", user = "Server",
				eye = "Visuals", chat = "Info", star = "Zap", gear = "Settings",
				house = "Dashboard", fire = "Combat", message = "Info", notification = "Bell",
			}
			local function norm(v)
				if type(v) == "number" then return "rbxassetid://" .. tostring(math.floor(v)) end
				if type(v) == "string" and v:match("^%d+$") then return "rbxassetid://" .. v end
				return v
			end
			Icons = setmetatable({}, {
				__index = function(_, name)
					local rawTbl = type(raw) == "table" and raw or {}
					local v = rawTbl[name]
					if v == nil then
						local key = tostring(name):lower()
						for k, val in pairs(rawTbl) do
							if type(k) == "string" and k:lower() == key then v = val; break end
						end
						if v == nil and alias[key] then v = rawTbl[alias[key]] end
						if v == nil then v = rawTbl.Zap or rawTbl.Logo end
					end
					return norm(v)
				end,
			})
		end

		-- ============================================================
		-- Branding: ganti nama "StarHub" dan logo bawaan library jadi oxio (teks + gambar)
		-- ============================================================
		local function findHost()
			local roots = {}
			pcall(function() if type(gethui) == "function" then roots[#roots + 1] = gethui() end end)
			pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
			pcall(function() roots[#roots + 1] = LocalPlayer:FindFirstChildOfClass("PlayerGui") end)
			for _, r in ipairs(roots) do
				if r then
					local h = r:FindFirstChild("StarHubUI_Host")
					if h then return h end
				end
			end
			return nil
		end

		local function brandInstance(d)
			if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
				local t = d.Text
				if type(t) == "string" and t ~= "" then
					local nt = t
					nt = (nt:gsub("STARHUB UI", "OXIO HUB"))
					nt = (nt:gsub("STARHUB", "OXIO HUB"))
					nt = (nt:gsub("StarHub UI", "oxio hub"))
					nt = (nt:gsub("StarHub", "oxio hub"))
					nt = (nt:gsub("Starhub", "oxio hub"))
					if nt ~= t then d.Text = nt end
				end
			elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then
				local img = tostring(d.Image)
				if img == "rbxassetid://10709819149" or img:find("starhub_custom_logo", 1, true) then
					d.Image = OXIO_LOGO
				end
			end
		end

		local function BrandSweep()
			local host
			for _ = 1, 40 do
				host = findHost()
				if host then break end
				task.wait(0.25)
			end
			if not host then return end
			for _, d in ipairs(host:GetDescendants()) do pcall(brandInstance, d) end
			host.DescendantAdded:Connect(function(d)
				task.defer(function() pcall(brandInstance, d) end)
			end)
		end

		-- ============================================================
		-- Logo: kotak rounded (sudut membulat, tidak tajam) + outline putih
		-- ============================================================
		local function StyleLogo()
			local function findLogos()
				local found = {}
				local host = findHost()
				if not host then return found end
				for _, d in ipairs(host:GetDescendants()) do
					if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and tostring(d.Image):find("118755181202304", 1, true) then
						found[#found + 1] = d
					end
				end
				return found
			end

			local function squareAndWhite(obj)
				for _, ch in ipairs(obj:GetChildren()) do
					if ch:IsA("UICorner") then
						ch.CornerRadius = UDim.new(0.22, 0)
					elseif ch:IsA("UIStroke") then
						ch.Color = Color3.new(1, 1, 1)
						ch.Enabled = true
						local g = ch:FindFirstChildOfClass("UIGradient")
						if g then g.Color = ColorSequence.new(Color3.new(1, 1, 1)) end
					end
				end
			end

			local function apply(logo)
				-- wadah logo terluar yang ukurannya masih seukuran logo (<= 120px)
				local top = logo
				local p = logo.Parent
				for _ = 1, 3 do
					if p and p:IsA("GuiObject") and p.AbsoluteSize.X <= 120 and p.AbsoluteSize.Y <= 120 then
						top = p
						p = p.Parent
					else
						break
					end
				end
				squareAndWhite(top)
				if not top:FindFirstChildOfClass("UICorner") then
					local rc = Instance.new("UICorner")
					rc.CornerRadius = UDim.new(0.22, 0)
					rc.Parent = top
				end
				for _, d in ipairs(top:GetDescendants()) do
					if d:IsA("GuiObject") then squareAndWhite(d) end
				end
				local hasStroke = false
				for _, ch in ipairs(top:GetChildren()) do
					if ch:IsA("UIStroke") then hasStroke = true end
				end
				if not hasStroke then
					local st = Instance.new("UIStroke")
					st.Color = Color3.new(1, 1, 1)
					st.Thickness = 1.5
					st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
					st.Parent = top
				end
			end

			local logos
			for _ = 1, 40 do
				logos = findLogos()
				if #logos > 0 then break end
				task.wait(0.25)
			end
			if not logos or #logos == 0 then
				warn("[oxio] logo tidak ditemukan untuk di-style")
				return
			end
			for _, wait in ipairs({ 0, 0.5, 1.5, 3, 6 }) do
				if wait > 0 then task.wait(wait) end
				for _, l in ipairs(findLogos()) do pcall(apply, l) end
			end
		end

		-- Callback dropdown satu pilihan: pastikan nilai yang masuk berupa string pilihan
		-- (bukan tabel / nomor urut) karena handler lama mengharapkan string.
		local function Sel(cb, options)
			return function(v)
				if type(v) == "table" then v = v[1] end
				if type(v) == "number" and type(options) == "table" and options[v] ~= nil then v = options[v] end
				if type(cb) == "function" then return cb(v) end
			end
		end
		-- ============================================================
		-- Helper: ubah teks baris (ActionRow) StarHub dengan aman.
		-- Nama method setter belum bisa diverifikasi, jadi dicoba beberapa nama umum.
		-- ============================================================
		local function SetRowText(ctrl, text)
			if type(ctrl) ~= "table" then return end
			for _, m in ipairs({ "SetContent", "SetDescription", "SetSubtitle", "SetDesc", "SetText" }) do
				if type(ctrl[m]) == "function" then
					local ok = pcall(ctrl[m], ctrl, text)
					if ok then return end
				end
			end
		end

		-- ============================================================
		-- MULTI-SELECT DROPDOWN untuk StarHub UI
		-- ============================================================
		local UITheme = {
			bg      = Color3.fromRGB(18, 18, 24),
			panel   = Color3.fromRGB(24, 24, 32),
			row     = Color3.fromRGB(32, 32, 42),
			accent  = Color3.fromRGB(26, 147, 250),
			text    = Color3.fromRGB(235, 236, 245),
			muted   = Color3.fromRGB(150, 152, 170),
			stroke  = Color3.fromRGB(60, 60, 80),
		}

		local function AddMultiDropdown(box, title, desc, options, default, callback)
			local selected = {}
			if type(default) == "table" then
				for _, v in ipairs(default) do selected[v] = true end
			end

			local function list()
				local t = {}
				for _, v in ipairs(options) do
					if selected[v] then table.insert(t, v) end
				end
				return t
			end
			local function summary()
				local l = list()
				if #l == 0 then return "(kosong)" end
				if #l <= 2 then return table.concat(l, ", ") end
				return l[1] .. ", " .. l[2] .. " +" .. (#l - 2)
			end
			local function subtitleText()
				return desc and (desc .. "  ➜  " .. summary()) or summary()
			end

			local rowCtrl

			rowCtrl = box:AddActionRow(title, subtitleText(), Icons.Zap, function()
				local CoreGui = game:GetService("CoreGui")
				local sg = Instance.new("ScreenGui")
				sg.Name = "OxioMultiSelect"
				sg.ResetOnSpawn = false
				sg.DisplayOrder = 99999
				sg.IgnoreGuiInset = true
				sg.Parent = CoreGui

				local main = Instance.new("Frame")
				main.AnchorPoint = Vector2.new(0.5, 0.5)
				main.Position = UDim2.fromScale(0.5, 0.5)
				main.Size = UDim2.fromOffset(340, 460)
				main.BackgroundColor3 = UITheme.bg
				main.BorderSizePixel = 0
				main.Active = true
				main.Parent = sg
				Instance.new("UICorner", main).CornerRadius = UDim.new(0, 10)
				local stroke = Instance.new("UIStroke", main)
				stroke.Color = UITheme.stroke

				local head = Instance.new("TextLabel")
				head.Position = UDim2.fromOffset(14, 12)
				head.Size = UDim2.new(1, -52, 0, 22)
				head.BackgroundTransparency = 1
				head.Font = Enum.Font.GothamBold
				head.TextSize = 14
				head.TextColor3 = UITheme.text
				head.TextXAlignment = Enum.TextXAlignment.Left
				head.TextTruncate = Enum.TextTruncate.AtEnd
				head.Text = title
				head.Parent = main

				local closeBtn = Instance.new("TextButton")
				closeBtn.Position = UDim2.new(1, -38, 0, 10)
				closeBtn.Size = UDim2.fromOffset(28, 28)
				closeBtn.BackgroundColor3 = UITheme.row
				closeBtn.BorderSizePixel = 0
				closeBtn.Font = Enum.Font.GothamBold
				closeBtn.TextSize = 13
				closeBtn.TextColor3 = UITheme.text
				closeBtn.Text = "X"
				closeBtn.Parent = main
				Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0, 6)

				local search = Instance.new("TextBox")
				search.Position = UDim2.fromOffset(14, 42)
				search.Size = UDim2.new(1, -28, 0, 30)
				search.BackgroundColor3 = UITheme.panel
				search.BorderSizePixel = 0
				search.Font = Enum.Font.Gotham
				search.TextSize = 12
				search.TextColor3 = UITheme.text
				search.PlaceholderText = "Cari..."
				search.PlaceholderColor3 = UITheme.muted
				search.Text = ""
				search.ClearTextOnFocus = false
				search.Parent = main
				Instance.new("UICorner", search).CornerRadius = UDim.new(0, 6)

				local scroll = Instance.new("ScrollingFrame")
				scroll.Position = UDim2.fromOffset(14, 80)
				scroll.Size = UDim2.new(1, -28, 1, -180)
				scroll.BackgroundColor3 = UITheme.panel
				scroll.BorderSizePixel = 0
				scroll.ScrollBarThickness = 4
				scroll.ScrollBarImageColor3 = UITheme.accent
				scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
				scroll.Parent = main
				Instance.new("UICorner", scroll).CornerRadius = UDim.new(0, 6)
				local layout = Instance.new("UIListLayout", scroll)
				layout.Padding = UDim.new(0, 3)
				layout.SortOrder = Enum.SortOrder.LayoutOrder

				local rowH = 28
				local filterText = ""

				local function rebuild()
					for _, c in ipairs(scroll:GetChildren()) do
						if c:IsA("TextButton") then c:Destroy() end
					end
					local visCount = 0
					local f = filterText:lower()
					for i, opt in ipairs(options) do
						local label = tostring(opt)
						if f == "" or label:lower():find(f, 1, true) then
							visCount += 1
							local btn = Instance.new("TextButton")
							btn.Size = UDim2.new(1, -6, 0, rowH)
							btn.BackgroundColor3 = selected[opt] and UITheme.accent or UITheme.row
							btn.BorderSizePixel = 0
							btn.Font = Enum.Font.GothamBold
							btn.TextSize = 12
							btn.TextColor3 = UITheme.text
							btn.Text = (selected[opt] and "[✓] " or "[   ] ") .. label
							btn.TextXAlignment = Enum.TextXAlignment.Left
							btn.LayoutOrder = i
							btn.Parent = scroll
							Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)
							btn.MouseButton1Click:Connect(function()
								selected[opt] = not selected[opt] or nil
								rebuild()
							end)
						end
					end
					scroll.CanvasSize = UDim2.new(0, 0, 0, visCount * (rowH + 3) + 6)
				end
				rebuild()

				search:GetPropertyChangedSignal("Text"):Connect(function()
					filterText = search.Text
					rebuild()
				end)

				local applyBtn = Instance.new("TextButton")
				applyBtn.Position = UDim2.new(0, 14, 1, -96)
				applyBtn.Size = UDim2.new(1, -28, 0, 34)
				applyBtn.BackgroundColor3 = UITheme.accent
				applyBtn.BorderSizePixel = 0
				applyBtn.Font = Enum.Font.GothamBold
				applyBtn.TextSize = 13
				applyBtn.TextColor3 = Color3.new(1, 1, 1)
				applyBtn.Text = "Simpan"
				applyBtn.Parent = main
				Instance.new("UICorner", applyBtn).CornerRadius = UDim.new(0, 6)

				local selBtn = Instance.new("TextButton")
				selBtn.Position = UDim2.new(0, 14, 1, -58)
				selBtn.Size = UDim2.new(0.5, -19, 0, 30)
				selBtn.BackgroundColor3 = UITheme.row
				selBtn.BorderSizePixel = 0
				selBtn.Font = Enum.Font.GothamBold
				selBtn.TextSize = 12
				selBtn.TextColor3 = UITheme.text
				selBtn.Text = "Pilih Semua"
				selBtn.Parent = main
				Instance.new("UICorner", selBtn).CornerRadius = UDim.new(0, 6)

				local clrBtn = Instance.new("TextButton")
				clrBtn.Position = UDim2.new(0.5, 5, 1, -58)
				clrBtn.Size = UDim2.new(0.5, -19, 0, 30)
				clrBtn.BackgroundColor3 = UITheme.row
				clrBtn.BorderSizePixel = 0
				clrBtn.Font = Enum.Font.GothamBold
				clrBtn.TextSize = 12
				clrBtn.TextColor3 = UITheme.text
				clrBtn.Text = "Kosongkan"
				clrBtn.Parent = main
				Instance.new("UICorner", clrBtn).CornerRadius = UDim.new(0, 6)

				closeBtn.MouseButton1Click:Connect(function() sg:Destroy() end)
				selBtn.MouseButton1Click:Connect(function()
					for _, opt in ipairs(options) do selected[opt] = true end
					rebuild()
				end)
				clrBtn.MouseButton1Click:Connect(function()
					selected = {}
					rebuild()
				end)
				applyBtn.MouseButton1Click:Connect(function()
					SetRowText(rowCtrl, subtitleText())
					if callback then
						local ok, err = pcall(callback, list())
						if not ok then warn("[oxio][dropdown] " .. tostring(err)) end
					end
					sg:Destroy()
				end)
			end)

			return {
				GetValue = list,
				Set = function(l)
					selected = {}
					for _, v in ipairs(l or {}) do selected[v] = true end
					SetRowText(rowCtrl, subtitleText())
					if callback then callback(list()) end
				end,
			}
		end

		local function Ryu_cleanList(list)
			local Ryu_cleanList_var1 = {}
			local ipairs_ = ipairs
			local Ryu_listToClean = type(list) == "table" and list or {}

			for _, v in ipairs_(Ryu_listToClean) do
				if v ~= "None" and v ~= "" then
					Ryu_cleanList_var1[#Ryu_cleanList_var1 + 1] = v
				end
			end

			return Ryu_cleanList_var1
		end
		local function Ryu_getAllRarities()
			local Ryu_getAllRarities_var1 = {}

			pcall(function()
				for _, v in ipairs(Ryu_catalog.getRarities()) do
					Ryu_getAllRarities_var1[#Ryu_getAllRarities_var1 + 1] = v
				end
			end)

			if #Ryu_getAllRarities_var1 == 0 then
				Ryu_getAllRarities_var1 = {
					"Common",
					"Uncommon",
					"Rare",
					"Epic",
					"Legendary",
					"Mythic",
					"Cosmic",
					"Secret",
					"Eternal",
					"Divine"
				}
			end

			return Ryu_getAllRarities_var1
		end
		local function Ryu_prependAll(list)
			local Ryu_prependAll_var3 = { "All" }

			for _, v in ipairs(list) do
				if v ~= "All" then
					Ryu_prependAll_var3[#Ryu_prependAll_var3 + 1] = v
				end
			end

			return Ryu_prependAll_var3
		end

		local Ryu_mutationOptions = {}

		pcall(function()
			for _, v in ipairs(Ryu_catalog.getMutations()) do
				Ryu_mutationOptions[#Ryu_mutationOptions + 1] = v
			end
		end)

		if #Ryu_mutationOptions == 0 then
			Ryu_mutationOptions = {
				"Golden",
				"Rainbow",
				"Shocked",
				"Frozen",
				"Burnt",
				"Boss"
			}
		end

		local Ryu_rarityOptionsAll = { "None" }

		if not pcall(function()
			local Directory = require(game:GetService("ReplicatedStorage").Data.Areas).Directory
			local ok, result = pcall(function()
				return require(game:GetService("ReplicatedStorage").Data.Assets)
			end)

			if ok and result and result.Directory then
				local Directory2 = result.Directory
				local Ryu_prependAll_var4 = {}

				for _, v in pairs(Directory) do
					if type(v) == "table" and type(v.DropTable) == "table" then
						for _, Ryu_item in ipairs(v.DropTable) do
							local Ryu_dropEntry = Ryu_item[1]

							if type(Ryu_dropEntry) == "string" and not Ryu_prependAll_var4[Ryu_dropEntry] then
								Ryu_prependAll_var4[Ryu_dropEntry] = true

								local Ryu_dropAssetDef = Directory2[Ryu_dropEntry]

								Ryu_rarityOptionsAll[#Ryu_rarityOptionsAll + 1] = Ryu_dropAssetDef and Ryu_dropAssetDef.DisplayName or Ryu_dropEntry
							end
						end
					end
				end
			end
		end) or #Ryu_rarityOptionsAll <= 1 then
			Ryu_rarityOptionsAll = { "None" }
		end

		table.sort(Ryu_rarityOptionsAll, function(entryA, entryB)
			if entryA == "None" then
				return true
			end

			if entryB == "None" then
				return false
			end

			return entryA < entryB
		end)

		local Ryu_areaOptions = { "None" }

		do
			local Ryu_knownAreas = {
				"Lake",
				"Jungle",
				"Desert",
				"Snow",
				"Volcano",
				"Abyss Ocean",
				"Prehistoric",
				"Cosmic",
				"Cherry Blossom",
				"Titan Temple"
			}
			local Ryu_areaSet = {}

			if not pcall(function()
				for k, v in pairs(require(game:GetService("ReplicatedStorage").Data.Areas).Directory) do
					if type(v) == "table" and type(v.DropTable) == "table" then
						Ryu_areaSet[k] = true
					end
				end
			end) or next(Ryu_areaSet) == nil then
				for _, v in ipairs(Ryu_knownAreas) do
					Ryu_areaSet[v] = true
				end
			end

			local Ryu_excludedAreas = {
				None = true,
				Forest = true,
				["Titan Temple"] = true
			}

			for _, v in ipairs(Ryu_knownAreas) do
				if v ~= "Titan Temple" and Ryu_areaSet[v] then
					table.insert(Ryu_areaOptions, v)
					Ryu_excludedAreas[v] = true
				end
			end

			local Ryu_otherAreas = {}

			for k in pairs(Ryu_areaSet) do
				if not Ryu_excludedAreas[k] then
					table.insert(Ryu_otherAreas, k)
				end
			end

			table.sort(Ryu_otherAreas)

			for _, v in ipairs(Ryu_otherAreas) do
				table.insert(Ryu_areaOptions, v)
			end

			if Ryu_areaSet["Titan Temple"] then
				table.insert(Ryu_areaOptions, "Titan Temple")
			end
		end

		Ryu_AutoLoops.AutoPlaceLoop = function()
			if senaV4Config.IsAutoPlaceWorkerRunning then
				return
			end

			senaV4Config.IsAutoPlaceWorkerRunning = true

			while senaV4Config.AutoPlace and Ryu_isCurrentSession() do
				task.wait(1.5)

				local ok, result = pcall(function()
					if senaV4Config.IsStealing then
						return
					end

					local ReplicatedStorage2 = game:GetService("ReplicatedStorage")

					game:GetService("HttpService")

					local EggState2 = require(ReplicatedStorage2.Client.EggState)
					local Assets = require(ReplicatedStorage2.Data.Assets)
					local Ryu_localPlot
					local Plots = workspace:FindFirstChild("Plots")

					if Plots then
						local Ryu_plotsIter, Ryu_plotsIterState, Ryu_plotsIterControl = ipairs(Plots:GetChildren())
						local Ryu_plotsIterator = geniter(Ryu_plotsIter, Ryu_plotsIterState, Ryu_plotsIterControl)

						while true do
							local Ryu_plotsPack = table.pack(Ryu_plotsIterator())

							if not Ryu_plotsPack[1] then
								break
							end

							local Ryu_plotChild = Ryu_plotsPack[3]
							local PlotSign = Ryu_plotChild:FindFirstChild("PlotSign")

							if PlotSign then
								local PlayerPlotSign = PlotSign:FindFirstChild("PlayerPlotSign")

								if PlayerPlotSign and PlayerPlotSign:FindFirstChild("Frame") then
									if PlayerPlotSign.Frame:FindFirstChild("PlayerName") then
										local Ryu_plotPlayerName = string.gsub(PlayerPlotSign.Frame.PlayerName.Text, "<[^>]+>", "")

										if string.find(string.lower(Ryu_plotPlayerName), string.lower(LocalPlayer.Name)) or string.find(string.lower(Ryu_plotPlayerName), string.lower(LocalPlayer.DisplayName)) then
											Ryu_localPlot = Ryu_plotChild

											break
										end
									end
								end
							end
						end
					end

					if not Ryu_localPlot then
						return
					end

					local ToUpdate = Ryu_localPlot:FindFirstChild("ToUpdate")
					local PetArea = ToUpdate and ToUpdate:FindFirstChild("PetArea")
					local CenterPoint = Ryu_localPlot:FindFirstChild("CenterPoint") or PetArea

					if not PetArea then
						return
					end

					local Ryu_prependAll_var5 = {}
					local Ryu_ownedEggsList = EggState2.GetOwnerRuntimeRecords(LocalPlayer.UserId)
					local Ryu_prependAll_var1 = 0

					if type(Ryu_ownedEggsList) == "table" then
						local Ryu_ownedEggsIter, Ryu_ownedEggsIterState, Ryu_ownedEggsIterControl = pairs(Ryu_ownedEggsList)

						for k, v in Ryu_ownedEggsIter, Ryu_ownedEggsIterState, Ryu_ownedEggsIterControl do
							if v.Placement == nil then
								local AssetCategory = v.AssetCategory
								local Ryu_ownedEggAssetDef = AssetCategory and Assets.Directory[AssetCategory]
								local Ryu_prependAll_var2 = "Unknown"

								if Ryu_ownedEggAssetDef and Ryu_ownedEggAssetDef.Rarity then
									local Rarity = Ryu_ownedEggAssetDef.Rarity

									Ryu_prependAll_var2 = Rarity.DisplayName or Rarity._id or Rarity.Name or "Unknown"
								end

								local Ryu_placeRarityMatch

								if #senaV4Config.PlaceRarities == 0 or table.find(senaV4Config.PlaceRarities, "None") or table.find(senaV4Config.PlaceRarities, "All") then
									Ryu_placeRarityMatch = true
								else
									Ryu_placeRarityMatch = table.find(senaV4Config.PlaceRarities, Ryu_prependAll_var2) ~= nil
								end

								local Ryu_ownedEggWeightRaw = tonumber(v.Kg) or tonumber(v.Weight) or tonumber(v.kg)

								if not Ryu_ownedEggWeightRaw and Ryu_ownedEggAssetDef then
									Ryu_ownedEggWeightRaw = tonumber(Ryu_ownedEggAssetDef.Kg) or tonumber(Ryu_ownedEggAssetDef.Weight) or tonumber(Ryu_ownedEggAssetDef.kg)
								end

								local Ryu_ownedEggWeightKg = Ryu_ownedEggWeightRaw or 0

								if Ryu_placeRarityMatch then
									table.insert(Ryu_prependAll_var5, {
										Uid = k,
										Rarity = Ryu_prependAll_var2,
										Kg = Ryu_ownedEggWeightKg
									})
								end
							else
								Ryu_prependAll_var1 += 1
							end
						end
					end

					table.sort(Ryu_prependAll_var5, function(entryA, entryB)
						return entryA.Kg > entryB.Kg
					end)

					local Character = LocalPlayer.Character

					if Character then
