					local Remotes = require(ReplicatedStorage2.Shared.Remotes)
					local LocalPlayer2 = game:GetService("Players").LocalPlayer

					local function Ryu_getOwnedEggSet()
						local ok, result = pcall(function()
							return AssetRoster.ReadOwnerPen(LocalPlayer2.UserId)
						end)

						if not ok or type(result) ~= "table" then
							return nil
						end

						local Ryu_getOwnedEggSet_var1 = {}

						for k, v in pairs(result) do
							if type(k) == "string" then
								Ryu_getOwnedEggSet_var1[k] = true
							end

							if type(v) == "table" and v.UID then
								Ryu_getOwnedEggSet_var1[v.UID] = true
							end
						end

						return Ryu_getOwnedEggSet_var1
					end
					local function Ryu_canSellPet(petEntry, placedSet)
						if not senaV4Config.AutoSell then
							return false, "toggle Auto Sell Pet udah OFF", "global"
						end

						if not Ryu_isSafeToSteal() then
							return false, "Auto Steal lagi megang kendali", "global"
						end

						local Ryu_sellNameFilter = Ryu_logDisconnect_var3(Ryu_petNameFilterRef)
						local Ryu_sellRarityFilter = Ryu_logDisconnect_var3(Ryu_petRarityFilterRef)

						if not Ryu_sellNameFilter or not Ryu_sellRarityFilter then
							return false, "filter dropdown gak bisa dibaca", "global"
						end

						if type(placedSet) ~= "table" then
							return false, "status pet dipajang gak bisa diverifikasi", "global"
						end

						if placedSet[petEntry.uid] then
							return false, "pet ini dipajang di plot", "pet"
						end

						if not Ryu_isFilterMatch(petEntry.petName, petEntry.rarity, Ryu_sellNameFilter, Ryu_sellRarityFilter) then
							return false, "pet ini udah gak match filter yang sekarang", "pet"
						end

						local Ryu_saveDataForSell = (Save.Peek or Save.Get)()
						local Inventory = Ryu_saveDataForSell and Ryu_saveDataForSell.Inventory and Ryu_saveDataForSell.Inventory[petEntry.uid]

						if Inventory == nil then
							return false, "pet ini udah gak ada di inventory", "pet"
						end

						local SellPetMaxRate = senaV4Config.SellPetMaxRate or 0

						if SellPetMaxRate > 0 then
							if SellPetMaxRate < Ryu_getRatePerSecond({
								Category = Inventory.Category or Inventory.AssetCategory,
								Scale = Inventory.Scale or Inventory.AssetScale or 1,
								Mutations = Inventory.Mutations or {}
							}) then
								return false, "money/s pet ini di atas batas value", "pet"
							end
						end

						if Inventory.IsFavorite == true then
							return false, "pet ini di-favorite", "pet"
						end

						if Inventory.InFuse == true then
							return false, "pet ini sedang di-fuse", "pet"
						end

						if table.find(Ryu_saveDataForSell.EquippedAssets or {}, petEntry.uid) == nil then
							return true
						end

						return false, "pet ini sedang dipasang", "pet"
					end

					while senaV4Config.AutoSell and Ryu_isCurrentSession() do
						local ok, result = pcall(function()
							if not Ryu_isSafeToSteal() then
								return
							end

							local Ryu_sellNameFilter2 = Ryu_logDisconnect_var3(Ryu_petNameFilterRef)
							local Ryu_sellRarityFilter2 = Ryu_logDisconnect_var3(Ryu_petRarityFilterRef)

							if not Ryu_sellNameFilter2 or not Ryu_sellRarityFilter2 then
								warn("[AutoSell] Filter dropdown gak bisa dibaca - ronde ini di-SKIP, gak ada yang dijual. Kalau ini terus-terusan, matiin Auto Sell Pet dan lapor.")

								return
							end

							local Ryu_saveDataForSell2 = (Save.Peek or Save.Get)()
							local Inventory = Ryu_saveDataForSell2 and Ryu_saveDataForSell2.Inventory or {}
							local Ryu_ownedEggSet = Ryu_getOwnedEggSet()

							if not Ryu_ownedEggSet then
								warn("[AutoSell] Status pet yang dipajang gak bisa diverifikasi - ronde ini di-SKIP, gak ada yang dijual.")

								return
							end

							local Ryu_canSellPet_var2 = {}
							local Ryu_canSellPet_var1 = 0

							if type(Inventory) == "table" then
								for k, v in pairs(Inventory) do
									Ryu_canSellPet_var1 += 1

									if Ryu_canSellPet_var1 % 250 == 0 then
										RunService.Heartbeat:Wait()

										if not senaV4Config.AutoSell then
											return
										end
									end

									if type(v) == "table" then
										local Ryu_isPlaced = Ryu_ownedEggSet[k] == true
										local Ryu_isFavorite = v.IsFavorite == true or v["Jadikan Favorit"] == true or v.Favorite == true
										local Ryu_isEquipped = table.find(Ryu_saveDataForSell2.EquippedAssets or {}, k) ~= nil
										local Ryu_isInFuse = v.InFuse == true
										local Category = v.Category or v.id or v.AssetCategory or v.ItemId
										local Ryu_petAssetDefForSell = Category and Assets.Directory[Category]
										local DisplayName = Ryu_petAssetDefForSell and (Ryu_petAssetDefForSell.DisplayName or Ryu_petAssetDefForSell._id or Ryu_petAssetDefForSell.Name) or "Unknown"
										local Rarity = Ryu_petAssetDefForSell and Ryu_petAssetDefForSell.Rarity
										local DisplayName2 = Rarity and (Rarity.DisplayName or Rarity._id or Rarity.Name) or "Unknown"
										local Ryu_petMatchesSellFilter = Ryu_isFilterMatch(DisplayName, DisplayName2, Ryu_sellNameFilter2, Ryu_sellRarityFilter2)
										local Ryu_petUnderMaxRate = true
										local SellPetMaxRate = senaV4Config.SellPetMaxRate or 0

										if SellPetMaxRate > 0 then
											Ryu_petUnderMaxRate = Ryu_getRatePerSecond({
												Category = Category,
												Scale = v.Scale or v.AssetScale or 1,
												Mutations = v.Mutations or {}
											}) <= SellPetMaxRate
										end

										if Ryu_petMatchesSellFilter and Ryu_petUnderMaxRate and not Ryu_isFavorite and not Ryu_isPlaced and not Ryu_isEquipped and not Ryu_isInFuse then
											table.insert(Ryu_canSellPet_var2, {
												uid = k,
												petName = DisplayName,
												rarity = DisplayName2
											})
										end
									end
								end
							end

							if #Ryu_canSellPet_var2 > 0 then
								for _, v in ipairs(Ryu_canSellPet_var2) do
									local Ryu_ownedEggSet2 = Ryu_getOwnedEggSet()
									local Ryu_petSellOk, Ryu_petSellError, Ryu_petSellScope = Ryu_canSellPet(v, Ryu_ownedEggSet2)

									if not Ryu_petSellOk then
										warn("[AutoSell] Gak jual " .. tostring(v.petName) .. " - " .. tostring(Ryu_petSellError))

										if Ryu_petSellScope ~= "global" then
											continue
										end
									elseif Ryu_isSafeToSteal() then
										local Character = LocalPlayer2.Character
										local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
										local Ryu_petTool

										for _, Ryu_item in ipairs({
											LocalPlayer2.Backpack,
											Character
										}) do
											if Ryu_item then
												for _, child in ipairs(Ryu_item:GetChildren()) do
													if child:IsA("Tool") and child:GetAttribute("UID") == v.uid then
														Ryu_petTool = child

														break
													end
												end
											end

											if Ryu_petTool then
												break
											end
										end

										if not Ryu_petTool or not Humanoid then
											continue
										end

										Humanoid:EquipTool(Ryu_petTool)
										task.wait(0.2)

										if Ryu_isSafeToSteal() then
											local Ryu_ownedEggSet3 = Ryu_getOwnedEggSet()
											local Ryu_petSellOk2, Ryu_petSellError2, Ryu_petSellScope2 = Ryu_canSellPet(v, Ryu_ownedEggSet3)

											if Ryu_petSellOk2 then
												Remotes.PetSatchel.SellPet:FireServer({ v.uid })
												task.wait(0.05)

												continue
											else
												warn("[AutoSell] Batal di detik terakhir, gak jual " .. tostring(v.petName) .. " - " .. tostring(Ryu_petSellError2))

												if Ryu_petSellScope2 ~= "global" then
													continue
												end
											end
										end
									end

									break
								end
							end
						end)

						if not ok then
							warn("Auto Sell Error:", result)
						end

						task.wait(1.5)
					end

					Ryu_parseValueInput_var2 = false
				end)
			end

			local Ryu_canSellPet_var3 = false
			local Ryu_canSellPet_var4 = false

			local function Ryu_hasAnyEggToSell()
				if not senaV4Config.AutoSellEgg then
					return false
				end

				local Ryu_eggRarityFilter2 = Ryu_logDisconnect_var3(Ryu_eggRarityFilterRef)

				if not Ryu_eggRarityFilter2 or #Ryu_eggRarityFilter2 == 0 or table.find(Ryu_eggRarityFilter2, "None") then
					return false
				end

				local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
				local ok, result = pcall(function()
					return require(ReplicatedStorage2.Shared.Save)
				end)

				if not ok or not result then
					return false
				end

				local Ryu_saveDataForEggSell = (result.Peek or result.Get)()
				local EggInventory = Ryu_saveDataForEggSell and Ryu_saveDataForEggSell.EggInventory

				if type(EggInventory) ~= "table" then
					return false
				end

				local ok2, result2 = pcall(function()
					return require(ReplicatedStorage2.Data.Assets)
				end)
				local Directory = ok2 and result2 and result2.Directory

				if not Directory then
					return false
				end

				for _, v in pairs(EggInventory) do
					local Ryu_eggAssetDefForSell = type(v) == "table" and Directory[v.AssetCategory]
					local DisplayName = Ryu_eggAssetDefForSell and Ryu_eggAssetDefForSell.Rarity and (Ryu_eggAssetDefForSell.Rarity.DisplayName or Ryu_eggAssetDefForSell.Rarity._id)
					local Ryu_eggUnderMaxRate = true
					local SellEggMaxRate = senaV4Config.SellEggMaxRate or 0

					if SellEggMaxRate > 0 and type(v) == "table" then
						Ryu_eggUnderMaxRate = Ryu_getRatePerSecond({
							Category = v.AssetCategory,
							Scale = v.AssetScale or 1,
							Mutations = v.Mutations or {}
						}) <= SellEggMaxRate
					end

					if v.Placement == nil and Ryu_eggUnderMaxRate then
						if not Ryu_isRarityInList(DisplayName or "Unknown", Ryu_eggRarityFilter2) then
							continue
						end

						return true
					end
				end

				return false
			end

			genv.__oxioIsAutoSellEggBusy = function()
				return Ryu_canSellPet_var4 or Ryu_hasAnyEggToSell()
			end
			Ryu_AutoLoops.startAutoSellEggLoop = function()
				if not Ryu_canSellPet_var3 then
					Ryu_canSellPet_var3 = true
					task.spawn(function()
						local ReplicatedStorage2 = game:GetService("ReplicatedStorage")
						local Directory = require(ReplicatedStorage2.Data.Assets).Directory
						local EggState2 = require(ReplicatedStorage2.Client.EggState)
						local Remotes = require(ReplicatedStorage2.Shared.Remotes)
						local Save = require(ReplicatedStorage2.Shared.Save)

						while senaV4Config.AutoSellEgg and Ryu_isCurrentSession() do
							local Ryu_eggRarityFilter3 = Ryu_logDisconnect_var3(Ryu_eggRarityFilterRef)
							local Ryu_saveDataForEggSell2 = (Save.Peek or Save.Get)()
							local EggInventory = Ryu_saveDataForEggSell2 and Ryu_saveDataForEggSell2.EggInventory

							if Ryu_eggRarityFilter3 and type(EggInventory) == "table" and Ryu_isSafeToSteal() then
								for k, v in pairs(EggInventory) do
									if senaV4Config.AutoSellEgg and Ryu_isSafeToSteal() then
										local Ryu_eggAssetDefForSell2 = type(v) == "table" and Directory[v.AssetCategory]
										local DisplayName = Ryu_eggAssetDefForSell2 and Ryu_eggAssetDefForSell2.Rarity and (Ryu_eggAssetDefForSell2.Rarity.DisplayName or Ryu_eggAssetDefForSell2.Rarity._id)
										local Ryu_eggUnderMaxRate2 = true
										local SellEggMaxRate = senaV4Config.SellEggMaxRate or 0

										if SellEggMaxRate > 0 and type(v) == "table" then
											Ryu_eggUnderMaxRate2 = Ryu_getRatePerSecond({
												Category = v.AssetCategory,
												Scale = v.AssetScale or 1,
												Mutations = v.Mutations or {}
											}) <= SellEggMaxRate
										end

										if not (v.Placement == nil and Ryu_eggUnderMaxRate2) then
											continue
										end

										if not Ryu_isRarityInList(DisplayName or "Unknown", Ryu_eggRarityFilter3) then
											continue
										end

										if Ryu_isSafeToSteal() then
											Ryu_canSellPet_var4 = true

											if genv.__oxioTreadmillManager and genv.__oxioTreadmillManager.activeTreadmill ~= nil then
												genv.__oxioTreadmillManager:_cancelIdle(true)
												task.wait(0.25)
											end

											if not EggState2.WearEggTool(k) then
												continue
											end

											task.wait(0.2)

											if Ryu_isSafeToSteal() then
												local Ryu_saveDataForEggSell3 = (Save.Peek or Save.Get)()
												local EggInventory2 = Ryu_saveDataForEggSell3 and Ryu_saveDataForEggSell3.EggInventory and Ryu_saveDataForEggSell3.EggInventory[k]

												if EggInventory2 and EggInventory2.Placement == nil then
													Remotes.PetSatchel.SellPet:FireServer({ k })
													task.wait(0.25)
												end

												continue
											end
										end
									end

									break
								end
							end

							Ryu_canSellPet_var4 = false
							task.wait(0.5)
						end

						Ryu_canSellPet_var4 = false
						Ryu_canSellPet_var3 = false
					end)

					return
				end
			end

			local Ryu_allNames = {
				"None",
				"All"
			}

			pcall(function()
				local Ryu_dedupNames = {}

				for _, v in pairs(require(game:GetService("ReplicatedStorage").Data.Assets).Directory) do
					if type(v) == "table" and (v.DisplayName or v._id or v.Name) then
						local DisplayName = v.DisplayName or v._id or v.Name

						if not Ryu_dedupNames[DisplayName] then
							Ryu_dedupNames[DisplayName] = true
							table.insert(Ryu_allNames, DisplayName)
						end
					end
				end

				table.sort(Ryu_allNames, function(entryA, entryB)
					if entryA == "None" then
						return true
					end

					if entryB == "None" then
						return false
					end

					if entryA == "All" then
						return true
					end

					if entryB == "All" then
						return false
					end

					return entryA < entryB
				end)
			end)
			Ryu_nameFilterOptions = Ryu_cleanList(Ryu_rarityOptionsAll)
			Ryu_areaFilterOptions = Ryu_cleanList(Ryu_areaOptions)
			Ryu_rarityFilterOptions = Ryu_getAllRarities()
			Ryu_petNameOptions = Ryu_prependAll(Ryu_cleanList(Ryu_allNames))
			Ryu_setAutoSteal = function(enabled)
				senaV4Config.AutoSteal = enabled == true

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setEnabled(senaV4Config.AutoSteal)
				end

				if type(genv.__oxioSetStealDeclutter) == "function" then
					pcall(genv.__oxioSetStealDeclutter, senaV4Config.AutoSteal)
				end
			end
			Ryu_setStealHold = function(holdSeconds)
				senaV4Config.StealHoldSeconds = math.clamp(math.floor((tonumber(holdSeconds) or 5) + 0.5), 1, 10)
				
				-- Boost walk speed immediately untuk chase egg
				task.spawn(function()
					if LocalPlayer and LocalPlayer.Character then
						local Humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
						if Humanoid then
							local multiplier = senaV4Config.StealHoldSeconds or 5
							local baseWalkSpeed = 50
							Humanoid.WalkSpeed = baseWalkSpeed * multiplier
						end
					end
				end)
			end
			Ryu_setGodMode = function(enabled)
				senaV4Config.GodMode = enabled == true

				if Ryu_godMode then
					Ryu_godMode:setEnabled(senaV4Config.GodMode)
				end
			end

			local function Ryu_getTreadmillManager()
				return genv.__oxioTreadmillManager
			end

			Ryu_setAutoTreadmillIdle = function(enabled)
				senaV4Config.AutoTreadmillIdle = enabled == true

				local Ryu_treadmillManagerForIdle = Ryu_getTreadmillManager()

				if Ryu_treadmillManagerForIdle then
					Ryu_treadmillManagerForIdle:setIdleFarm(senaV4Config.AutoTreadmillIdle and not senaV4Config.AntiTreadmill)
				end
			end
			Ryu_setAntiTreadmill = function(enabled)
				senaV4Config.AntiTreadmill = enabled == true

				local Ryu_treadmillManagerForAnti = Ryu_getTreadmillManager()

				if senaV4Config.AntiTreadmill then
					if Ryu_treadmillManagerForAnti then
						Ryu_treadmillManagerForAnti:setIdleFarm(false)
					end

					Ryu_ServerHop.startAntiTreadmillLoop()
				elseif Ryu_treadmillManagerForAnti then
					Ryu_treadmillManagerForAnti:setIdleFarm(senaV4Config.AutoTreadmillIdle)
				end
			end
			Ryu_setHopNoMatch = function(enabled)
				senaV4Config.HopNoMatch = enabled == true

				if senaV4Config.HopNoMatch then
					Ryu_ServerHop.startHopLoop()
				end
			end
			Ryu_setPrivateServerMax = function(maxPlayers)
				if type(maxPlayers) == "table" then
					maxPlayers = maxPlayers[1]
				end

				senaV4Config.PrivateServerMax = tostring(maxPlayers or "2")
			end
			Ryu_setPrivateServerAuto = function(enabled)
				senaV4Config.PrivateServerAuto = enabled == true

				if senaV4Config.PrivateServerAuto then
					Ryu_ServerHop.startPrivateAutoHop()
				end
			end
			Ryu_setHopCooldown = function(cooldown)
				senaV4Config.HopCooldown = math.max(1, math.floor(tonumber(cooldown) or 5))
			end
			Ryu_setAutoTreadmillUpgrade = function(enabled)
				senaV4Config.AutoTreadmillUpgrade = enabled == true

				local Ryu_treadmillManagerForUpgrade = Ryu_getTreadmillManager()

				if Ryu_treadmillManagerForUpgrade then
					Ryu_treadmillManagerForUpgrade:setAutoUpgrade(senaV4Config.AutoTreadmillUpgrade)
				end
			end
			Ryu_setStealMode = function(modeString)
				local Ryu_stealModeString = type(modeString) == "string" and modeString or ""
				local stealMode = (Ryu_stealModeString:find("Fly") or Ryu_stealModeString:find("High")) and "Fly" or "Instant"
				local flyAerial = stealMode == "Fly" and (Ryu_stealModeString:find("%(Fly%)") ~= nil or Ryu_stealModeString:lower():find("aerial") ~= nil)

				senaV4Config.StealMode = stealMode
				senaV4Config.FlyAerial = flyAerial

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setStealMode(stealMode, flyAerial)
				end
			end
			Ryu_setTweenSpeedSlider = function(speedInput)
				local Ryu_clampedSpeedSlider = math.floor(math.clamp(math.floor((tonumber(speedInput) or 600) + 0.5), 500, 1000) / 10 + 0.5)

				Ryu_setTweenSpeedMultiplier(Ryu_clampedSpeedSlider)

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setSpeed(Ryu_clampedSpeedSlider)
					
					-- Boost walk/fly speed saat mulai chase
					task.spawn(function()
						if LocalPlayer and LocalPlayer.Character then
							local Humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
							if Humanoid then
								local holdMultiplier = tonumber(senaV4Config.StealHoldSeconds) or 5
								local baseSpeed = 50
								Humanoid.WalkSpeed = baseSpeed * holdMultiplier
							end
						end
					end)
				end
			end
			Ryu_setStealFilter = function(filterKey, filterEnabled, valueList)
				local Ryu_cleanedFilterList = Ryu_cleanList(valueList)

				if filterKey == "names" then
					senaV4Config.StealNamesFilter = Ryu_cleanedFilterList
				elseif filterKey == "areas" then
					senaV4Config.StealAreas = Ryu_cleanedFilterList
				elseif filterKey == "rarities" then
					senaV4Config.StealRarities = Ryu_cleanedFilterList
				end

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setFilter(filterKey, Ryu_cleanedFilterList)
					Ryu_eggRuntime:setFilterEnabled(filterEnabled, #Ryu_cleanedFilterList > 0)
				end
			end
			Ryu_setStealValue = function(valueInput)
				senaV4Config:applyStealValueInput(valueInput)

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setMinValuePerSec(senaV4Config.StealMinValue or 0)
				end
			end
			Ryu_setStealMutations = function(valueList)
				local Ryu_cleanedMutationList = Ryu_cleanList(valueList)

				senaV4Config.StealMutations = Ryu_cleanedMutationList

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setFilter("mutations", Ryu_cleanedMutationList)
					Ryu_eggRuntime:setFilterEnabled("mutation", #Ryu_cleanedMutationList > 0)
				end
			end
			Ryu_setStealWeight = function(valueInput)
				local tonumber_ = tonumber
				local Ryu_cleanedWeightInput = tostring(valueInput or ""):gsub("[^%d%.]", "")
				local stealMinWeight = tonumber_(Ryu_cleanedWeightInput) or 0

				senaV4Config.StealMinWeight = stealMinWeight

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setMinWeightKg(stealMinWeight)
				end
			end
			Ryu_setStealPriority = function(priority)
				senaV4Config.StealPriority = tostring(priority or "Rarity")

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setHighestValueFirst(senaV4Config.StealPriority == "Highest Value")
					Ryu_eggRuntime:setHeaviestFirst(senaV4Config.StealPriority == "Heaviest")
				end
			end
			Ryu_setEggEsp = function(enabled)
				senaV4Config.EggESP = enabled == true

				if Ryu_eggRuntime then
					Ryu_eggRuntime:setEggEsp(senaV4Config.EggESP)
				end
			end
			Ryu_setEspDetails = function(detailList)
				local Ryu_cleanedEspDetails = Ryu_cleanList(detailList)

				senaV4Config.EspDetails = Ryu_cleanedEspDetails

				if not Ryu_eggRuntime then
					return
				end

				local Ryu_espDetailsMap = {}

				for _, v in ipairs(Ryu_cleanedEspDetails) do
					Ryu_espDetailsMap[v] = true
				end

				Ryu_eggRuntime:setEspOption("name", Ryu_espDetailsMap.Name == true)
				Ryu_eggRuntime:setEspOption("rarity", Ryu_espDetailsMap.Rarity == true)
				Ryu_eggRuntime:setEspOption("value", Ryu_espDetailsMap.Value == true)
