				end

				genv.__oxioAdminBoostSpeedGen = (genv.__oxioAdminBoostSpeedGen or 0) + 1

				local __oxioAdminBoostSpeedGen = genv.__oxioAdminBoostSpeedGen

				if enabled == true then
					task.spawn(function()
						local RunService2 = game:GetService("RunService")
						local Ryu_baseWalkSpeed
						local Ryu_appliedWalkSpeed

						while genv.__oxioAdminBoostSpeedGen == __oxioAdminBoostSpeedGen and Ryu_isCurrentSession() do
							local Character = LocalPlayer.Character
							local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

							if Humanoid then
								local WalkSpeed = Humanoid.WalkSpeed

								if Ryu_baseWalkSpeed == nil or Ryu_appliedWalkSpeed == nil or math.abs(WalkSpeed - Ryu_appliedWalkSpeed) > 0.5 then
									Ryu_baseWalkSpeed = WalkSpeed > 900 and WalkSpeed / 10 or WalkSpeed
								end

								if Ryu_baseWalkSpeed and Ryu_baseWalkSpeed > 0 then
									local walkSpeed = Ryu_baseWalkSpeed * 10

									Humanoid.WalkSpeed = walkSpeed
									Ryu_appliedWalkSpeed = walkSpeed
								end
							else
								Ryu_baseWalkSpeed = nil
								Ryu_appliedWalkSpeed = nil
							end

							RunService2.Heartbeat:Wait()
						end
					end)
