			local function Ryu_parseValueInput2(valueInput)
				local Ryu_cleanedValueInput2 = string.lower(tostring(valueInput or "")):gsub("[%s,]", "")

				if Ryu_cleanedValueInput2 == "" then
					return 0
				end

				local Ryu_parsedValueNum2, Ryu_parsedValueUnit2 = string.match(Ryu_cleanedValueInput2, "^([%d]+%.?[%d]*)([kmb]?)$")
				local Ryu_parsedValueRaw2 = tonumber(Ryu_parsedValueNum2)

				if not Ryu_parsedValueRaw2 then
					return 0
				end

				if Ryu_parsedValueUnit2 == "k" then
					return Ryu_parsedValueRaw2 * 1000
				end

				if Ryu_parsedValueUnit2 == "m" then
					return Ryu_parsedValueRaw2 * 1000000
				end

				if Ryu_parsedValueUnit2 == "b" then
					return Ryu_parsedValueRaw2 * 1e9
				end

				return Ryu_parsedValueRaw2
			end

