			local function Ryu_wrapControlSetter(control)
				if type(control) ~= "table" then
					return control
				end

				if rawget(control, "__senaElevated") then
					return control
				end

				for _, v in ipairs(Ryu_setWebhookMinValue_var1) do
					local value = rawget(control, v)

					if type(value) == "function" then
						rawset(control, v, function(...)
							Ryu_applyElevatedIdentityFn()

							return value(...)
						end)
					end
				end

				rawset(control, "__senaElevated", true)

				return control
			end

			local Ryu_wrapControlSetter_var1 = {
				"AddToggle",
				"AddSlider",
				"AddDropdown",
				"AddInput",
				"AddButton",
				"AddParagraph",
				"AddKeybind",
