			local function Ryu_wrapControlFactory(control)
				if type(control) ~= "table" then
					return control
				end

				Ryu_wrapControlSetter(control)

				if rawget(control, "__senaFactoryGuarded") then
					return control
				end

				for _, v in ipairs(Ryu_wrapControlSetter_var1) do
					local value = rawget(control, v)

					if type(value) == "function" then
						rawset(control, v, function(...)
							Ryu_applyElevatedIdentityFn()

							local Ryu_wrappedResult = table.pack(value(...))

							if Ryu_wrappedResult.n > 0 then
								Ryu_wrappedResult[1] = Ryu_wrapControlFactory(Ryu_wrappedResult[1])
							end

							return table.unpack(Ryu_wrappedResult, 1, Ryu_wrappedResult.n)
						end)
					end
				end

				rawset(control, "__senaFactoryGuarded", true)

				return control
			end

