local __oxioButterflyRuntime = genv.__oxioButterflyRuntime
local bloomL = EventsTab:CreateGroupBox("Left", "BUTTERFLY BLOOM", "EVENT", Icons.Zap)
local bloomR = EventsTab:CreateGroupBox("Right", "BUTTERFLY BLOOM", "EVENT", Icons.Zap)
