Ryu_uiRefs.bloomAutoCraft = bloomR:AddToggle("Auto Craft Essence", "Auto craft essence.", false, Ryu_safeInvoke(function(s) senaV4Config.ButterflyAutoCraft = s == true end))

local function bloomAction(name, desc, fn, msg)
    bloomR:AddActionRow(name, desc, Icons.Zap, Ryu_safeInvoke(function()
        if not __oxioButterflyRuntime then return end
        task.spawn(function()
            __oxioButterflyRuntime.manual = true
            local ok, res, err = pcall(fn)
            __oxioButterflyRuntime.manual = false
            if not ok then res, err = false, res end
            local msgTxt = res and msg(res) or tostring(err or "Gagal")
            StarHubUI:Notify({Title="Butterfly Bloom", Content=msgTxt, Duration=4})
        end)
    end))
end
bloomAction("Claim Net Now", "Klaim net sekarang.", function() return __oxioButterflyRuntime.claimNet() end, function() return "Net di-klaim" end)
bloomAction("Trade Up Now", "Trade sekali.", function() return __oxioButterflyRuntime.tradeUp() end, function(n) return ("Trade %d kali"):format(tonumber(n) or 0) end)
bloomAction("Craft Now", "Craft essence.", function() return __oxioButterflyRuntime.craft() end, function(n) return ("Craft %d essence"):format(tonumber(n) or 0) end)
			task.spawn(function()
				while Ryu_isCurrentSession() do
					if __oxioButterflyRuntime then
						pcall(function()
							local snap = __oxioButterflyRuntime.snap
							local Ryu_butterflyTiersForDisplay = __oxioButterflyRuntime.tiers() or {}
							local Ryu_bloomStatusText2

							if snap.active then
								local Ryu_bloomRemainingSec = math.floor(snap.left or 0)

								Ryu_bloomStatusText2 = ("LIVE - ends in %dm %02ds"):format(math.floor(Ryu_bloomRemainingSec / 60), Ryu_bloomRemainingSec % 60)
							elseif snap.enabled == false then
								Ryu_bloomStatusText2 = "Disabled on this server"
							elseif snap.nextIn then
								local Ryu_bloomNextInSec = math.floor(snap.nextIn)

								Ryu_bloomStatusText2 = ("Next in %dm %02ds"):format(math.floor(Ryu_bloomNextInSec / 60), Ryu_bloomNextInSec % 60)
							else
								Ryu_bloomStatusText2 = "Not running"
							end

							local Ryu_bloomAction_var1 = {}

							for _, v in ipairs({
								"Golden",
								"Purple",
								"Blue",
								"Green"
							}) do
								Ryu_bloomAction_var1[#Ryu_bloomAction_var1 + 1] = ("%s %d"):format(Ryu_butterflyTiersForDisplay[v] and Ryu_butterflyTiersForDisplay[v].name or v, snap.counts and snap.counts[v] or 0)
							end

							Ryu_bloomStatusRow:SetContent(("%s\n%s  ·  Essence %d  ·  Caught %d\n%s\n%s"):format(Ryu_bloomStatusText2, snap.net and (snap.holding and "Net equipped" or "Net owned") or "No Butterfly Net", snap.essence or 0, snap.caught or 0, table.concat(Ryu_bloomAction_var1, "  ·  "), tostring(__oxioButterflyRuntime.status or "Idle")))
						end)
					end

					task.wait(1)
				end
			end)

