			Ryu_applySavedConfigFn(Ryu_uiRefs.antiHitGuard, Ryu_setAntiHitGuard)
			Ryu_applySavedConfigFn(Ryu_uiRefs.flyForCapture, Ryu_setFlyForCapture)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoStealCapture, Ryu_setAutoStealCapture)
            Ryu_applySavedConfigFn(Ryu_uiRefs.instantStealV2, function(v)
	senaV4Config.InstantStealV2 = v == true
end)
Ryu_applySavedConfigFn(Ryu_uiRefs.instantV3, function(v)
	senaV4Config.InstantV3 = v == true
end)
Ryu_applySavedConfigFn(Ryu_uiRefs.instantCarryMode, function(v)
	senaV4Config.InstantCarry = v
end)
Ryu_applySavedConfigFn(Ryu_uiRefs.instantApproach, function(v)
	senaV4Config.InstantApproach = v
end)
Ryu_applySavedConfigFn(Ryu_uiRefs.instantCamHide, function(v)
	senaV4Config.InstantHideCamera = v == true
end)
			Ryu_applySavedConfigFn(Ryu_uiRefs.instantGrab, Ryu_setInstantGrab)
			Ryu_applySavedConfigFn(Ryu_uiRefs.infiniteJump, Ryu_setInfiniteJump)
			Ryu_applySavedConfigFn(Ryu_uiRefs.uncapFps, Ryu_setFpsCap)
			Ryu_applySavedConfigFn(Ryu_uiRefs.startupBoost, Ryu_setStartupBoost)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoPlace, Ryu_setAutoPlace)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoHatch, Ryu_setAutoHatch)
			Ryu_applySavedConfigFn(Ryu_uiRefs.mutationChoice, Ryu_setMutationChoice)
			Ryu_applySavedConfigFn(Ryu_uiRefs.mutationSpecies, Ryu_setMutationSpecies)
			Ryu_applySavedConfigFn(Ryu_uiRefs.mutationRarity, Ryu_setMutationRarities)
			Ryu_applySavedConfigFn(Ryu_uiRefs.mutationRetry, Ryu_setMutationRetry)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoMutation, Ryu_setAutoMutation)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoRingEvent, Ryu_setAutoRingEvent)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoSell, Ryu_setAutoSell)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoSellEgg, Ryu_setAutoSellEgg)
			Ryu_applySavedConfigFn(Ryu_uiRefs.stealPlayerRarities, Ryu_setStealPlayerRarities)
			Ryu_applySavedConfigFn(Ryu_uiRefs.stealPlayerValue, Ryu_setStealPlayerMinValue)
			Ryu_applySavedConfigFn(Ryu_uiRefs.webhookUrl, Ryu_setWebhookUrl)
			Ryu_applySavedConfigFn(Ryu_uiRefs.webhookRarities, Ryu_setWebhookRarities)
			Ryu_applySavedConfigFn(Ryu_uiRefs.webhookValue, Ryu_setWebhookMinValue)
			Ryu_applySavedConfigFn(Ryu_uiRefs.webhookEnabled, Ryu_setWebhookEnabled)
			Ryu_applySavedConfigFn(Ryu_uiRefs.helpFriend, function(Ryu_applySavedConfigFn_var19)
				senaV4Config.HelpFriend = Ryu_applySavedConfigFn_var19 == true
			end)
			Ryu_applySavedConfigFn(Ryu_uiRefs.autoSteal, Ryu_setAutoSteal)
			Ryu_applySavedConfigFn(Ryu_uiRefs.stealPlayers, Ryu_setStealPlayers)

			-- StarHub: control belum tentu punya .Value, jadi nilai default diterapkan manual
			-- (toggle default ON & dropdown/slider dengan default). Aman dipanggil dobel.
			do
				local function applyDefault(ctrl, cb, value)
					if type(ctrl) == "table" and rawget(ctrl, "Value") ~= nil then return end
					if type(cb) == "function" then pcall(cb, value) end
				end
				applyDefault(Ryu_uiRefs.startupBoost, Ryu_setStartupBoost, true)
				applyDefault(Ryu_uiRefs.uncapFps, Ryu_setFpsCap, true)
				applyDefault(Ryu_uiRefs.antiGuardKnockback, Ryu_setAntiGuardKnockback, true)
				applyDefault(Ryu_uiRefs.antiAfk, Ryu_setAntiAfk, true)
				applyDefault(Ryu_uiRefs.autoReconnect, Ryu_setAutoReconnect, true)
				applyDefault(Ryu_uiRefs.mutationRetry, Ryu_setMutationRetry, true)
				applyDefault(Ryu_uiRefs.stealMode, Ryu_setStealMode, "High Speed User")
				applyDefault(Ryu_uiRefs.stealHold, Ryu_setStealHold, 5)
				applyDefault(Ryu_uiRefs.priority, Ryu_setStealPriority, "Rarity")
				applyDefault(Ryu_uiRefs.mutationChoice, Ryu_setMutationChoice, "Scrambled")
				applyDefault(Ryu_uiRefs.privateServerMax, Ryu_setPrivateServerMax, "2")
				applyDefault(Ryu_uiRefs.hopCooldown, Ryu_setHopCooldown, 5)
				applyDefault(Ryu_uiRefs.favoriteRule, Ryu_setFavoriteRule, "Rarity")
				applyDefault(Ryu_uiRefs.espDetails, Ryu_setEspDetails, { "Name", "Rarity", "Value" })
				applyDefault(Ryu_uiRefs.fuseRule, Ryu_setFuseRule, "Any Species")
			end
		end

		do
			genv.__oxioHubShutdown = function()
				if __oxioPlayerSteal then
					pcall(__oxioPlayerSteal.setEnabled, __oxioPlayerSteal, false)
				end

				for _, v in ipairs({
					"AutoSteal",
					"AutoPlace",
					"AutoHatch",
					"AutoMutation",
					"AutoRingEvent",
					"AutoSell",
					"AutoSellEgg",
					"StealPlayers",
					"ScrambleBossAuto",
					"RaceAuto",
					"RaceClaim",
					"RaceBuy",
					"ButterflyAutoCatch",
					"ButterflyAutoNet",
					"ButterflyAutoTrade",
					"ButterflyAutoCraft"
				}) do
					senaV4Config[v] = false
				end

				if Ryu_eggRuntime then
					pcall(Ryu_eggRuntime.setEnabled, Ryu_eggRuntime, false)
				end
			end
		end
	end

	Ryu_buildMainWindow()

	-- ============================================================
	-- Bikin tombol melayang StarHubUI bisa di-drag
	-- ============================================================
	task.spawn(function()
		local UIS = game:GetService("UserInputService")

		local function roots()
			local t = {}
			pcall(function() if gethui then t[#t+1] = gethui() end end)
			pcall(function() t[#t+1] = game:GetService("CoreGui") end)
			pcall(function() t[#t+1] = LocalPlayer:FindFirstChildOfClass("PlayerGui") end)
			return t
		end

		local function findFloatingButton()
			for _, r in ipairs(roots()) do
				if r then
					local host = r:FindFirstChild("StarHubUI_Host")
					if host then
						for _, d in ipairs(host:GetDescendants()) do
							if d:IsA("GuiObject") and (d:IsA("ImageButton") or d:IsA("TextButton")) then
								local sz = d.AbsoluteSize
								-- tombol melayang biasanya kecil (< 90px) & persegi
								if sz.X > 0 and sz.X <= 90 and sz.Y <= 90 and math.abs(sz.X - sz.Y) < 12 then
									return d
								end
							end
						end
					end
				end
			end
			return nil
		end

		local button
		for _ = 1, 60 do
			button = findFloatingButton()
			if button then break end
			task.wait(0.25)
		end

		if not button then
			warn("[oxio] tombol melayang StarHubUI tidak ditemukan — drag tidak diaktifkan")
			return
		end

		-- Simpan posisi default agar tidak lompat saat drag
		local dragging   = false
		local dragStart  = nil
		local startPos   = nil

		button.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
				dragging   = true
				dragStart  = input.Position
				startPos   = button.Position
			end
		end)

		UIS.InputChanged:Connect(function(input)
			if not dragging then return end
			if input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch then
				local delta = input.Position - dragStart
				button.Position = UDim2.new(
					startPos.X.Scale,
					startPos.X.Offset + delta.X,
					startPos.Y.Scale,
					startPos.Y.Offset + delta.Y
				)
			end
		end)

		UIS.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
				dragging = false
			end
		end)

		-- Naikkan sedikit z-index biar tidak ketutup UI lain saat drag
		pcall(function()
			if button.ZIndex < 50 then button.ZIndex = 50 end
		end)
	end)
end
